// Global variables
size_t batchSize = 1024;
char *inputFile = NULL;
static regex_t pattern[32]; // Maximum number of patterns
int patternCount = 0;
pthread_mutex_t logMutex;

void* processLines(void *arg);
void initRegexPatterns(const char *patternStr, size_t patternIndex);
void printUsage();
void logMessage(const char *msg);

int main(int argc, char **argv) {
    int opt;
    while ((opt = getopt(argc, argv, "b:p:")) != -1) {
        switch (opt) {
            case 'b':
                batchSize = atoi(optarg);
                break;
            case 'p':
                initRegexPatterns(optarg, patternCount++);
                break;
            default:
                printUsage();
        }
    }

    if (inputFile == NULL) {
        printUsage();
        return EXIT_FAILURE;
    }

    pthread_t threads[32]; // Maximum number of patterns + 1 for main thread
    FILE *fp = fopen(inputFile, "r");
    if (!fp) {
        perror("Error opening input file");
        return EXIT_FAILURE;
    }

    size_t threadCount = patternCount + 1;
    pthread_mutex_init(&logMutex, NULL);

    for (int i = 0; i < threadCount; ++i) {
        void *arg = malloc(sizeof(struct lineData));
        struct lineData *data = arg;

        data->lineNum = 0;
        data->lineBuffer = calloc(batchSize, sizeof(char));
        data->patternIndex = i < patternCount ? i : -1;

        if (pthread_create(&threads[i], NULL, processLines, arg)) {
            perror("Error creating thread");
            return EXIT_FAILURE;
        }
    }

    size_t lineSize;
    char lineBuffer[batchSize];
    while ((lineSize = fread(lineBuffer, sizeof(char), batchSize - 1, fp)) > 0) {
        lineBuffer[lineSize] = '\0';

        for (int i = 0; i < threadCount; ++i) {
            struct lineData *data = (struct lineData*) threads[i];
            if (data->patternIndex >= 0 && regexec(&pattern[data->patternIndex], lineBuffer, 0, NULL, REG_NOTEOL | REG_NEWLINE)) {
                ++(data->lineNum);
            }
            if (feof(fp)) break;
            pthread_t &target = threads[i];
            pthread_kill(target, SIGCONT);
        }
    }

    for (int i = 0; i < threadCount; ++i) {
        void *arg = malloc(sizeof(struct lineData));
        struct lineData *data = arg;
        data->lineNum = 0;
        pthread_join(threads[i], NULL);
        free(arg);
    }

    fclose(fp);
    return EXIT_SUCCESS;
}

// Define lineData and regex initialization functions, logMessage, etc. here...
