#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

#define MAX_INPUT 1000
#define MIN_VALUE -10000
#define MAX_VALUE 10000

void log(const char* msg) {
    time_t now;
    struct tm* timeinfo;
    char buff[80];

    time(&now);
    timeinfo = localtime(&now);

    strftime(buff, sizeof(buff), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s: %s\n", buff, msg);
}

int* read_and_store_integers(bool* success) {
    int size = MAX_INPUT;
    int* array = NULL;
    int num_inputs = 0;
    int index = 0;

    while (index < size && num_inputs < MAX_INPUT) {
        if (!(array = realloc(array, sizeof(int)*size))) {
            log("Failed to allocate memory. Reducing limit.");
            size /= 2;
            continue;
        }

        scanf("%d", &array[index]);

        if (array[index] < MIN_VALUE || array[index] > MAX_VALUE) {
            log("Invalid integer discarded.");
            continue;
        }

        index++;
        num_inputs++;
    }

    *success = true;
    return array;
}

int find_max(const int* arr, size_t len) {
    int max = arr[0];

    for (size_t i = 1; i < len; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    return max;
}

void print_max(const char* message, const int* arr, size_t len) {
    int max = find_max(arr, len);

    printf("%s: %d\n", message, max);
}

int main() {
    bool success;
    int* data = read_and_store_integers(&success);

    if (success) {
        print_max("Largest integer:", data, sizeof(data)/sizeof(data[0]));
        free(data);
    }

    return 0;
}
```

