#include <memory>

namespace bpo = boost::program_options;
using namespace std;

enum Severity { DEBUG, INFO, WARN, ERROR, FATAL };
typedef function<void(const string&)> LoggerFunc;

class LogQueue {
public:
    void enqueue(const string& msg, Severity severity) {
        unique_lock<mutex> lock(m_);
        queue_.emplace([this, msg, severity]() mutable { processMessage(msg, severity); });
        cond_.notify_one();
    }

    void processMessages() {
        while (!queue_.empty()) {
            auto task = move(queue_.front());
            queue_.pop();
            task();
        }
    }

private:
    void processMessage(const string& msg, Severity severity) {
        for (auto& logger : loggers_[severity])
            logger(msg);
    }

    mutex m_;
    queue<function<void()>> queue_;
    condition_variable cond_;
    map<Severity, vector<LoggerFunc>> loggers_;
};

class LogConfig {
public:
    void load(istream& is) {
        // Load logging settings from the input stream.
    }

