    desc.add_options()
        ( "config", bpo::value<string>(), "Configuration file" )
    ;
    bpo::variables_map vm;
    store(parse_command_line(argc, argv, desc), vm);
    notify(vm);

    ifstream configFile(vm["config"].as<string>());
    LogConfig config;
    config.load(configFile);

    // Initialize logger functions for each severity level.
    vector<LoggerFunc> loggers = {logToConsole, logToThirdPartyService};

    // Create a logging queue instance and start processing log messages.
