    {
        _redis = ConnectionMultiplexer.Connect("localhost");
        _cacheDb = _redis.GetDatabase();
    }

    public async Task<T> LoadAsync<T>()
    {
        var key = typeof(T).Name;
        if (_cacheDb.KeyExists(key))
        {
            return JsonConvert.DeserializeObject<T>(_cacheDb.StringGet(key));
        }

        var configJson = await LoadFromFileAsync<T>();
        _cacheDb.StringSet(key, JsonConvert.SerializeObject(configJson), TimeSpan.FromDays(7));
        return configJson;
    }

    private async Task<T> LoadFromFileAsync<T>()
    {
        try
        {
            using var fileStream = File.OpenRead("config.json");
            using var reader = new StreamReader(fileStream);
            var jsonText = await reader.ReadToEndAsync();
            return JsonConvert.DeserializeObject<T>(jsonText);
