    private static readonly ObjectCache _cache = MemoryCache.Default;
    private const int CacheDurationMinutes = 10;

    public static XmlNode GetFirstElementByXPath(string filePath, string xpath)
    {
        string cacheKey = $"Config_{filePath}_{xpath}";
        object cachedResult = _cache.Get(cacheKey);

        if (cachedResult != null) return (XmlNode)cachedResult;

        try
        {
            using (var reader = XmlReader.Create(filePath))
            {
                var xmlDoc = new XmlDocument();
                xmlDoc.Load(reader);
                return xmlDoc.SelectSingleNode(xpath);
            }
        }
        catch (Exception ex) when (ex is FileNotFoundException || ex is XPathExpressionException)
        {
            // Handle exceptions, e.g., log error details
        }

        _cache.Add(cacheKey, null, CacheItemPolicy.AbsoluteExpiration(DateTimeOffset.UtcNow.AddMinutes(CacheDurationMinutes)));
        return null;
    }
}
