```rust
use std::env;
use std::fs::{self, File};
use std::path::{Path, PathBuf};
use std::sync::Mutex;

static ENV_VAR: Mutex<Option<String>> = Mutex::new(None);

fn create_dir_with_env(dir_name: &str) {
    let dir_path = env::current_dir().unwrap().join(dir_name);

    if !fs::metadata(dir_path).is_err() {
        println!("Directory already exists.");
        return;
    }

    fs::create_dir_all(&dir_path)?;

    *ENV_VAR.lock().unwrap() = Some(dir_path.to_str().unwrap().to_string());

    env::set_var("MY_DIR", &dir_path.to_str().unwrap());

    println!("Directory created successfully: {}", dir_path.display());
}
```

