public class FileUtil {
    private static final String CACHE_ROOT = "path/to/cache";
    private static final long THEME_BITMAP_TIMEOUT = TimeUnit.MINUTES.toMillis(1);
    private static ScheduledExecutorService themeBitmapRecycler = Executors.newSingleThreadScheduledExecutor();
    private static ConcurrentHashMap<String, BufferedImage> themeCache;

    static {
        Path cacheRootPath = Paths.get(CACHE_ROOT);
        if (!Files.exists(cacheRootPath)) {
            try {
                Files.createDirectory(cacheRootPath);
            } catch (Exception e) {
                // Handle exception and log it
            }
        }
        themeCache = new ConcurrentHashMap<>();
        themeBitmapRecycler.scheduleWithFixedDelay(() -> {
            themeCache.values().removeIf(bi -> System.currentTimeMillis() - bi.timestamp > THEME_BITMAP_TIMEOUT);
        }, 0, THEME_BITMAP_TIMEOUT, TimeUnit.MILLISECONDS);
    }

    public static MoSTState loadStateFromFile(String fileName) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(fileName))) {
            return (MoSTState) ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            // Handle exception and log it
            return null;
        } finally {
            // Properly close the ObjectInputStream
        }
    }

    public static BufferedImage getThemeBitmap(String themeName) {
        BufferedImage bi = themeCache.get(themeName);
        if (bi == null) {
            synchronized (themeCache) {
                bi = themeCache.get(themeName);
                if (bi == null) {
                    try {
                        Path pngPath = Paths.get(CACHE_ROOT, themeName + ".png");
                        if (!Files.exists(pngPath)) {
                            // Download the PNG file from an external API or third-party service
                        }
                        bi = ImageIO.read(pngPath);
                        bi.timestamp = System.currentTimeMillis();
                        themeCache.putIfAbsent(themeName, bi);
                    } catch (IOException e) {
                        // Handle exception and log it
                        return null;
                    }
                }
            }
        }
        return bi;
    }
}
