["```javascript
class DomCollector {
  constructor(api) {
    this.api = api;
    this._results = [];
    this._callback = null;
  }

  collect(filter, limit, callback) {
    this._callback = callback;
    this._traverse(document.body, filter);
    if (limit) this._results.length = limit;
    this._callback(this._results);
  }

  _traverse(node, filter) {
    if (!node) return;

    if (filter.id && node.id === filter.id) this._results.push(node.cloneNode(true));
    if (filter.class && Array.from(node.classList).includes(filter.class)) this._results.push(node.cloneNode(true));

    let positionFilter = filter.position;
    const children = Array.from(node.children);
    let index = 0;
    if (positionFilter === 'first') {
      if (children.length > 0) this._results.push(children[0].cloneNode(true));
      return;
    }
    if (positionFilter === 'last') {
      const lastChildIndex = children.length - 1;
      if (lastChildIndex >= 0) this._results.push(children[lastChildIndex].cloneNode(true));
      return;
    }

    for (let i = 0; i < children.length; i++) {
      this._traverse(children[i], filter);
      if (this._results.length === limit) break;
      index++;
    }
  }

  async fetchMetadata(elements) {
    for (let elem of elements) {
      try {
        const metadata = await this.api.getMetadata(elem.id);
        Object.assign(elem, metadata);
      } catch (err) {
        console.error(`Error fetching metadata for element ${elem.id}:`, err);
      }
    }
  }
}
```

