const axios = require('axios');
const fs = require('fs');
const Bluebird = require('bluebird');
const log4js = require('log4js');
const retry = require('async-retry');

const log = log4js.getLogger('generateCertificateFromOAuthRequest');

function generateCertificateFromOAuthRequest(req) {
  const { access_token, privateKeyUrl, certificateUrl } = req;

  let privateKeyData = [];
  let certificateData = [];

  const processChunk = Bluebird.coroutine(function* (chunk) {
    if (!privateKeyData.length) {
      privateKeyData.push(chunk);
    } else if (!certificateData.length) {
      certificateData.push(chunk);
    }
  });

  const fetchPrivateKey = Bluebird.coroutine(function* () {
    let isResumed = false;
    const resumer = (options) => {
      options.signal.abort(); // Abort current request when resuming
      isResumed = true;
    };

    return yield retry(function* () {
      const response = yield axios.get(privateKeyUrl, {
        signal: axios.CancelToken.source(),
        responseType: 'arraybuffer',
        onDownloadProgress: processChunk,
        resumer,
      });

      if (!isResumed) {
        fs.writeFileSync(`temp/private_key`, Buffer.from(response.data));
      }
    }, { retries: 3, retryFactor: 2 });
  });

  const fetchCertificate = Bluebird.coroutine(function* () {
    let isResumed = false;
    const resumer = (options) => {
      options.signal.abort(); // Abort current request when resuming
      isResumed = true;
    };

    return yield retry(function* () {
      const response = yield axios.get(certificateUrl, {
        signal: axios.CancelToken.source(),
        responseType: 'arraybuffer',
        onDownloadProgress: processChunk,
        resumer,
      });

      if (!isResumed) {
        fs.writeFileSync(`temp/certificate`, Buffer.from(response.data));
      }
    }, { retries: 3, retryFactor: 2 });
  });

  log.info(`Fetching private key from ${privateKeyUrl}`);
  yield fetchPrivateKey();

  log.info(`Fetching certificate from ${certificateUrl}`);
  yield fetchCertificate();

  // Generate the PEM format for the certificate and private key
  const generatePem = (data, fileName) => {
    let pem = '';
    for (const chunk of data) {
      pem += chunk.toString('hex') + '\n';
    }
    return `-----BEGIN CERTIFICATE-----\n${pem}-----END CERTIFICATE-----\n`;
  };

  const privateKeyPem = generatePem(privateKeyData, 'private_key.pem');
  const certificatePem = generatePem(certificateData, 'certificate.pem');

  // Concatenate the PEM strings and return them
  return `${privateKeyPem}\n${certificatePem}`;
}
