#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    double quality_score;
    time_t timestamp;
} SensorEvent;

typedef struct {
    int window_size;
    int max_events;
    pthread_mutex_t mutex;
    SensorEvent *buffer;
    int head, tail;
    double avg_quality_score;
    int total_valid_events;
    double max_quality_score;
} Processor;

void init_processor(Processor *p, int window_size, int max_events) {
    p->window_size = window_size;
    p->max_events = max_events;
    p->buffer = malloc(max_events * sizeof(SensorEvent));
    p->head = 0;
    p->tail = 0;
    p->mutex = PTHREAD_MUTEX_INITIALIZER;
}

void process_sensor_event(Processor *p, const SensorEvent *se) {
    pthread_mutex_lock(&p->mutex);

    while ((p->tail - p->head + 1) >= p->window_size) {
        // slide window forward
        p->head = (p->head + 1) % p->max_events;
        p->total_valid_events--;
    }

    if(se->quality_score > p->max_quality_score){
        p->max_quality_score = se->quality_score;
    }

    p->buffer[p->tail] = *se;
    p->tail = (p->tail + 1) % p->max_events;
    p->total_valid_events++;
    p->avg_quality_score = ((double)(p->total_valid_events)*p->total_valid_events - p->head + p->tail) / (2.0 * p->window_size);

    pthread_mutex_unlock(&p->mutex);
}

// Function for handling external configuration parameters and system health indicators to dynamically change the window size
void set_window_size(Processor *p, int new_window_size) {
    if (new_window_size <= 0 || new_window_size > p->max_events) return;
    p->window_size = new_window_size;
}

// Implement a function to handle failures in external data sources gracefully, for example by replacing missing values with a default value or ignoring the event
