std::unordered_map<int, std::pair<std::chrono::steady_clock::time_point, int>> attacks = {
    {1, std::make_pair(std::chrono::steady_clock::now(), 3)},
    {2, std::make_pair(std::chrono::steady_clock::now(), 7)},
    {3, std::make_pair(std::chrono::steady_clock::now(), 10)}
};

int energy = 20;
const int cost[] = {5, 8, 12};

static std::mutex mtx;

void waitForCooldown(int id) {
    auto it = attacks.find(id);
    if (it != attacks.end()) {
        auto now = std::chrono::steady_clock::now();
        auto diff = now - it->second.first;
        auto remaining = it->second.second - static_cast<decltype(it->second.second)>(diff.count());
        if (remaining > 0) {
            std::this_thread::sleep_for(std::chrono::seconds(remaining));
        }
        it->second.first = now;
    }
}

void regenerateEnergy() {
    // Implement your energy regeneration logic here
}

void performAttack(int id) {
    if (energy >= cost[id - 1]) {
        energy -= cost[id - 1];
        waitForCooldown(id);
        std::cout << "Attack " << id << " performed.\n";
    } else {
        std::cout << "Insufficient energy to perform attack. Waiting..." << std::endl;
    }
}

void gameLoop() {
    while (true) {
        regenerateEnergy(); // Regenerate energy here

        for (auto& [id, data] : attacks) {
            waitForCooldown(id);
        }

        int nextAttackId = 0;
        mtx.lock();
        for (int id = 1; id <= 3; ++id) {
            if (energy >= cost[id - 1] && attacks[id].second == 0) {
                nextAttackId = id;
                break;
            }
        }
        mtx.unlock();

        if (nextAttackId != 0) {
            performAttack(nextAttackId);
        }
    }
