using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public class DynamicRangeManager<T> where T : struct, IComparable<T>
{
    private readonly ConcurrentDictionary<T, Range<T>> _ranges = new ConcurrentDictionary<T, Range<T>>();

    public void AddRange(T min, T max, bool isInclusive)
    {
        if (max.CompareTo(min) < 0)
            throw new ArgumentException("Maximum value must be greater than or equal to minimum value.");

        _ranges[CreateKey(min, max, isInclusive)] = new Range<T>(min, max, isInclusive);
    }

    public void UpdateRange(T min, T max, bool isInclusive)
    {
        if (_ranges.TryRemove(CreateKey(min, max, isInclusive), out var oldRange))
        {
            if (oldRange.IsValid())
            {
                AddRange(min, max, isInclusive);
            }
        }
    }

    public void RemoveRange(T min, T max)
    {
        _ranges.TryRemove(CreateKey(min, max), out _);
    }

    public T[] GetRandomValues(int count)
    {
        return Enumerable.Range(0, count).Select(_ => GetRandomValue()).ToArray();
    }

    private T GetRandomValue()
    {
        if (_ranges.Count == 0)
            throw new InvalidOperationException("No ranges available for generating random values.");

        var combinedRange = MergeRanges().FirstOrDefault();
        return combinedRange != null ? combinedRange.Value.GetRandomValue(combinedRange.Key, combinedRange.Value.IsInclusive) : default;
    }

    private KeyValuePair<T, Range<T>>[] MergeRanges()
    {
        var sortedRanges = _ranges.OrderBy(x => x.Key).ToList();

        for (int i = 1; i < sortedRanges.Count; i++)
        {
            if (sortedRanges[i - 1].Value.IsEnd && sortedRanges[i].Value.IsStart)
                sortedRanges[i - 1] = MergeRange(sortedRanges[i - 1], sortedRanges[i]);
        }

        return sortedRanges;
    }

    private KeyValuePair<T, Range<T>> MergeRange(KeyValuePair<T, Range<T>> range1, KeyValuePair<T, Range<T>> range2)
    {
        if (range1.Value.IsEnd && range2.Value.IsStart)
            return new KeyValuePair<T, Range<T>>(range1.Key, MergeRange(range1.Value, range2.Value));

        if (!range1.Value.IsEnd || !range2.Value.IsStart)
            throw new InvalidOperationException("Ranges cannot be merged if one or both are not completely defined.");

        return new KeyValuePair<T, Range<T>>(range1.Key, MergeRange(range1.Value, range2.Value));
    }

    private static Range<T> MergeRange(Range<T> range1, Range<T> range2)
    {
        if (range1.IsEnd && range2.IsStart)
            return range1;

        var newMin = Math.Min(range1.Min, range2.Min);
        var newMax = Math.Max(range1.Max, range2.Max);
        return new Range<T>(newMin, newMax, range1.IsInclusive && range2.IsInclusive);
    }

    private static bool RangeKeyEquals(KeyValuePair<T, Range<T>> key1, KeyValuePair<T, Range<T>> key2)
        => key1.Key == key2.Key && key1.Value.Equals(key2.Value);

    private static Tuple<T, bool> CreateKey(T min, T max, bool isInclusive)
        => new Tuple<T, bool>(min, (isInclusive ? min <= max : min < max));

    public override string ToString()
    {
        var result = new List<string>();

        foreach (var range in _ranges.Values)
            result.Add($"{range}");

        return string.Join("\n", result);
    }
}

public struct Range<T> where T : struct, IComparable<T>
{
    public Range(T min, T max, bool isInclusive)
    {
        Min = min;
        Max = max;
        IsInclusive = isInclusive;
    }

    public bool IsStart => IsInclusive && !IsEnd;
    public bool IsEnd => !IsInclusive && IsEmpty;
    public bool IsValid() => !(IsEmpty || (IsStart && IsEnd));

    public T GetRandomValue(T start, bool isInclusive)
    {
        if (start.CompareTo(Min) < 0)
            throw new ArgumentOutOfRangeException("start", "Start value must be greater than or equal to the minimum value of this range.");

        var end = IsEnd ? Max : GetNextValue();
        return isInclusive ? start + (end - start) * Random.Shared.NextDouble() : start + (end - start).Floor() + Random.Shared.NextDouble().CeilingTo(1);
    }

    private T GetNextValue() => IsInclusive ? Min + 1 : Min;

    public override bool Equals(object obj)
        => obj is Range<T> other && Equals(other);

    public bool Equals(Range<T> other)
        => EqualityComparer<T>.Default.Equals(Min, other.Min) && EqualityComparer<T>.Default.Equals(Max, other.Max)
           && IsInclusive == other.IsInclusive;

    public override int GetHashCode() => HashCode.Combine(Min, Max, IsInclusive);

    public T Min { get; }
    public T Max { get; }
    public bool IsInclusive { get; }
}
```
This code block provides a DynamicRangeManager class that handles multiple ranges of both integer and floating-point values. It includes methods for adding, updating, and removing ranges as well as generating random values within these ranges. Additionally, it merges overlapping or adjacent ranges into a single range to optimize storage and retrieval. The class is designed with concurrent access control in mind using `ConcurrentDictionary`. It also supports extension to other data types in the future and provides mechanisms for validating range integrity upon updates. The provided `ToString` method returns a clear, concise summary of all active ranges and their current configurations.']

