const axios = require('axios');
const { promisify } = require('util');
const asyncReduce = (arr, initialValue, callback, concurrencyLimit = 5) => {
  let accumulator = initialValue;
  let pendingRequests = 0;
  const worker = async (index) => {
    if (index >= arr.length) return;

    const url = arr[index];
    pendingRequests++;

    try {
      const response = await axios.get(url, { timeout: 5000 });
      accumulator = callback(accumulator, response.data);
      pendingRequests--;
      if (pendingRequests === 0) return;
    } catch (error) {
      if (error.isAxiosError && error.config.url === url) {
        if (--attempts > 0) {
          setTimeout(() => worker(index), Math.min(100 + index * 5, 1000));
        } else {
          console.error(`Failed to fetch data from ${url}`);
          pendingRequests--;
          if (pendingRequests === 0) return;
        }
      }
    }

    setTimeout(() => worker(index + 1), Math.min(100 + index * 5, 1000));
  };

  worker(0);
  return new Promise((resolve) => {
    setTimeout(() => resolve(accumulator), 60000); // Timeout after 60 seconds if no more requests are pending
  });
};

// Usage example:
const numbersArray = [
  'https://api.example.com/num1',
  'https://api.example.com/num2',
  'https://api.example.com/num3'
];

asyncReduce(numbersArray, 0, (acc, num) => acc + num, 3)
  .then((result) => console.log(`Result: ${result}`))
  .catch((error) => console.error(error));
