["```javascript
const MAX_LENGTH = 10;

function appendSlashIfNeeded(str) {
  return str.length < MAX_LENGTH ? (str + '/') : null;
}

async function collectElements(document, selector) {
  let elements = [];

  const visitNode = (node) => {
    if (!node || node.nodeType !== Node.ELEMENT_NODE) return;

    if (node.matches && node.matches(selector)) {
      elements.push(node);
    }

    Array.from(node.children).forEach((child) => visitNode(child));
  };

  visitNode(document);

  // Wait for all scripts and async data to load before proceeding
  await new Promise((resolve) => {
    const onScriptLoad = () => {
      document.removeEventListener('DOMContentLoaded', onScriptLoad);
      resolve();
    };

    document.addEventListener('DOMContentLoaded', onScriptLoad);

    // Handle asynchronous data loading
    const scripts = Array.from(document.getElementsByTagName('script'));
    const promises = [];

    scripts.forEach((script) => {
      if (script.async || script.defer) {
        promises.push(new Promise((resolve) => {
          script.onload = resolve;
        }));
      }
    });

    if (promises.length > 0) {
      await Promise.all(promises);
    }
  });

  return elements.map((el) => el.toString());
}

// Module exports
module.exports = {
  collectElements,
  appendSlashIfNeeded,
};
