#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <dirent.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>

#define THEME_FILE "/path/to/your/config_file"
#define CACHE_ROOT "/path/to/cache/root"
#define DEFAULT_DIR "./default_theme_dir" // Set this to your desired default directory path

typedef struct {
    int id;
    char *dir;
    char *png;
    double avg;
} Theme;

Theme* read_theme(char *line) {
    char *token;
    Theme *theme = malloc(sizeof(Theme));

    token = strtok(line, ",");
    theme->id = atoi(token);
    token = strtok(NULL, ",");
    theme->dir = strdup(token);
    theme->dir = getenv("THEME_DIR") ? getenv("THEME_DIR") : DEFAULT_DIR;
    if (chdir(theme->dir) != 0) {
        perror("Failed to change directory");
        free(theme->dir);
        free(theme);
        return NULL;
    }
    token = strtok(NULL, ",");
    theme->png = strdup(token);
    theme->avg = -1.0; // Fallback value for averages that aren't calculated yet

    return theme;
}

double calculate_average(Theme *theme) {
    int count = 0, sum = 0;
    DIR *dir;
    struct dirent *entry;
    char pattern[256];
    snprintf(pattern, sizeof(pattern), "%s/%s", theme->dir, theme->png);
    dir = opendir(CACHE_ROOT);

    if (dir != NULL) {
        while ((entry = readdir(dir)) != NULL) {
            if (strstr(entry->d_name, pattern) && sscanf(entry->d_name, "%*[^_]_%d_%*[^_]_%d", &count, &sum) == 2) {
                theme->avg = (double)(sum + count * theme->avg) / (count + 1);
                break;
            }
        }
        closedir(dir);
    }

    return theme->avg;
}

void print_theme(Theme *theme) {
    printf("%d,%s,%s,%f\n", theme->id, theme->dir, theme->png, theme->avg);
}

int main() {
    FILE *file;
    char line[4096];
    Theme *theme;

    file = fopen(THEME_FILE, "r");
    if (file == NULL) {
        perror("Failed to open configuration file");
        return 1;
    }

    while (fgets(line, sizeof(line), file)) {
        theme = read_theme(line);
        if (theme != NULL) {
            calculate_average(theme);
            print_theme(theme);
            free(theme->dir);
            free(theme->png);
            free(theme);
        }
    }

    fclose(file);
    return 0;
}
```
