['1. AES-256-CBC cipher initialization function (using OpenSSL library):

```c
#include <openssl/aes.h>
#include <openssl/pbkdf2.h>
#include <openssl/sha.h>
#include <openssl/rand.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    AES_KEY key;
    unsigned char iv[AES_BLOCK_SIZE];
} aes_context;

aes_context* aes_init(const char *password) {
    const int password_len = strlen(password);
    unsigned char salt[SHA256_DIGEST_LENGTH];
    RAND_bytes(salt, sizeof(salt));

    // Derive key and IV using PBKDF2 with SHA256
    uint8_t prk[EVP_MAX_KEY_LENGTH];
    size_t key_len = EVP_PBE_keyderivation(NULL, prk, EVP_PBE_SHA256, NULL, 1000, password, password_len, salt);

    unsigned char k[AES_KEYSIZE_256/8];
    memcpy(k, prk, AES_KEYSIZE_256/8);

    EVP_derive_init(NULL);
    EVP_derive_update(NULL, NULL, 0, key_len);
    EVP_derive_final(k, k, prk, password_len + SHA256_DIGEST_LENGTH);
    AES_set_encrypt_key(k, AES_KEYSIZE_256, &aes_context->key);

    // Derive IV from password and salt using PBKDF2 with SHA256
    unsigned char iv[AES_BLOCK_SIZE];
    size_t iv_len = EVP_PBE_keyderivation(iv, sizeof(iv), NULL, NULL, 1000, password, password_len, salt);
    memcpy(aes_context->iv, iv, AES_BLOCK_SIZE);

    return aes_context;
}

void aes_cleanup(aes_context *ctx) {
    free(ctx);
}
```

