using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Logging;

public class WebServerManager
{
    private readonly IWebHostBuilder _webHostBuilder;
    private readonly ILogger<WebServerManager> _logger;

    public WebServerManager(IWebHostBuilder webHostBuilder, ILogger<WebServerManager> logger)
    {
        _webHostBuilder = webHostBuilder;
        _logger = logger;
    }

    public async Task AddSiteAsync(string directoryPath, string siteName)
    {
        var webConfigPath = Path.Combine(directoryPath, "web.config");

        if (!File.Exists(webConfigPath))
        {
            _logger.LogError($"Missing web.config file in directory: {directoryPath}");
            return;
        }

        var siteDirectory = new DirectoryInfo(directoryPath);
        if (!siteDirectory.Exists || !siteDirectory.IsReadable || !siteDirectory.IsWritable)
        {
            _logger.LogError($"Invalid permissions for directory: {directoryPath}");
            return;
        }

        var siteLockPath = Path.Combine(directoryPath, $"{siteName}.lock");
        if (File.Exists(siteLockPath))
        {
            _logger.LogError($"Site {siteName} is currently being added or managed in directory: {directoryPath}");
            return;
        }

        using var lockFile = File.Create(siteLockPath);

        try
        {
            using var cancellationTokenSource = new CancellationTokenSource();

            Task.Run(async () =>
            {
                await StartupShutdownGuardAsync(directoryPath, siteName, cancellationTokenSource.Token);

                _logger.LogInformation($"Starting web server for site: {siteName}");

                var host = _webHostBuilder
                    .SetContentRoot(directoryPath)
                    .UseIISIntegration()
                    .UseUrls($"https://localhost:{port}")
                    .UseStartup<Startup>()
                    .Build();

                await host.RunAsync(cancellationTokenSource.Token);
            }, cancellationTokenSource.Token);
        }
        catch (Exception ex)
        {
            _logger.LogError($"Failed to start web server for site: {siteName}. Error: {ex.Message}");
        }
        finally
        {
            lockFile.Dispose();
        }
    }

    private async Task StartupShutdownGuardAsync(string directoryPath, string siteName, CancellationToken cancellationToken)
    {
        var siteLockPath = Path.Combine(directoryPath, $"{siteName}.lock");

        while (File.Exists(siteLockPath))
        {
            if (cancellationToken.IsCancellationRequested)
                return;

            await Task.Delay(TimeSpan.FromMilliseconds(100), cancellationToken);
        }
    }
}
```

