        using var memoryStream = new MemoryStream(data);
        var converter = new WordprocessingDocument(memoryStream, WordprocessingDocumentType.DocumentTemplate12);
        return WordConvertToImage(converter.MainDocumentPart.Worddocument, ImageFormat.Jpeg);
    }

    private byte[] ConvertXlsxToPdf(byte[] data)
    {
        using var memoryStream = new MemoryStream(data);
        var converter = new ExcelPackage(memoryStream);
        return WorkbookConvertToImage(converter, ImageFormat.Jpeg);
    }

    private byte[] WorkbookConvertToImage(ExcelWorkbook workbook, ImageFormat format)
    {
        using (var memoryStream = new MemoryStream())
        {
            foreach (var worksheet in workbook.Worksheets)
            {
                worksheet.PrintArea = worksheet.Dimension.Address;
                worksheet.PrintOptions.Copies = 1;
                worksheet.PrintOptions.PrinterName = "Microsoft Print to PDF";
                worksheet.Print();

                using var img = Image.FromFile(Path.GetTempFileName() + ".pdf");
                img.Save(memoryStream, format);
            }

            return memoryStream.ToArray();
        }
    }

    private byte[] WordConvertToImage(WordprocessingDocument wordDoc, ImageFormat format)
    {
        using (var memoryStream = new MemoryStream())
        {
            wordDoc.SaveAs(memoryStream, FormatSchemeType.Pdf);
            return memoryStream.ToArray();
        }
    }

    private async Task<IEnumerable<Image>> ProcessImagesAsync(Stream input)
    {
        var images = new List<Image>();

        using (var reader = new PdfReader(input))
        {
            for (int i = 1; i <= reader.NumberOfPages; i++)
            {
                var image = await ProcessPageAsync(reader, i);
                images.Add(image);
            }
        }

        return images;
    }

    private async Task<Image> ProcessPageAsync(PdfReader reader, int pageNumber)
    {
        using (var memoryStream = new MemoryStream())
        {
            await reader.ExtractPage(pageNumber, memoryStream);
            var image = Image.FromStream(memoryStream);
            // Perform any additional processing or optimization on the image here
            return image;
        }
    }

    private MemoryStream MergeImagesToPdf(IEnumerable<Image> images)
    {
        using (var memoryStream = new MemoryStream())
        {
            var pdfToolInfo = new ProcessStartInfo(_pdfToolPath, string.Join(" ", images.Select(img => img.ToArgbString())));
            pdfToolInfo.RedirectStandardOutput = true;
            pdfToolInfo.UseShellExecute = false;
            pdfToolInfo.CreateNoWindow = true;

            using (var process = new Process())
            {
                process.StartInfo = pdfToolInfo;
                process.Start();
                process.StandardOutput.BaseStream.CopyTo(memoryStream);
                process.WaitForExit();
            }

            return memoryStream;
        }
    }

    private async Task ConvertAndSaveBatchAsync(IEnumerable<string> ids)
    {
        var tasks = ids.Select(id => ConvertAndSavePdfAsync(id, await _container.GetItemAsync<byte[]>(id)));
        await Task.WhenAll(tasks);
    }
}
