    private BlockingCollection<string> _inputQueue = new BlockingCollection<string>();
    private ConcurrentQueue<Task> _tasks = new ConcurrentQueue<Task>();
    private SemaphoreSlim _semaphore = new SemaphoreS base>(_maxWorkerCount, _maxWorkerCount);

    public DecryptionService(ILogger<DecryptionService> logger, string errorLogFileName, byte[] key, byte[] iv)
    {
