                _tasks.Enqueue(Task.Run(() => AddToResults(decryptedMessage)));
            }
            finally
            {
                _semaphore.Release();
            }
        }
        else
        {
            _tasks.Enqueue(Task.Run(() => _inputQueue.TryTake(out var message) && AddToResults(message)));
        }
    }

    private void AddToResults(string decryptedMessage)
    {
        // Add the decrypted message to a collection or publish an event for further processing
    }

    private void CompleteAllDecryptionTasks(ConcurrentTaskPair<string, string>[] tasks)
    {
        foreach (var task in tasks)
        {
            if (!task.Item1.IsCompleted && !task.Item2.IsFaulted)
            {
                task.Item2.Complete();
            }
        }
    }

    private void LogError(Exception ex)
    {
        _logger.LogError(ex, "Decryption failed.");

        if (!string.IsNullOrWhiteSpace(_errorLogFileName))
        {
            using var file = File.AppendText(_errorLogFileName);
