    public class FileHasher
    {
        private readonly ConcurrentDictionary<string, byte[]> _fileDataCache = new ConcurrentDictionary<string, byte[]>();

        public async Task<ConcurrentDictionary<string, string>> HashFilesAsync(IEnumerable<string> filePaths)
        {
            var fileHashes = new ConcurrentDictionary<string, string>();

            var tasks = filePaths.Select(ProcessFileAsync);

            await Task.WhenAll(tasks);

            return fileHashes;
        }

        private async Task ProcessFileAsync(string filePath)
        {
            if (_fileDataCache.TryGetValue(filePath, out var fileData))
            {
                ComputeHash(fileData, out _); // Hash the existing data in memory.
                fileHashes[filePath] = BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
                return;
            }

            try
            {
                using var stream = File.OpenRead(filePath);
                var bufferSize = 4096; // Optimize buffer size for performance and memory usage.
                byte[] buffer = new byte[bufferSize];

                int bytesRead;
                while ((bytesRead = await stream.ReadAsync(buffer, 0, bufferSize)) > 0)
                {
                    _fileDataCache.AddOrUpdate(filePath, fileData => buffer.Take(fileData.Length).Concat(buffer).ToArray(), (_, oldValue) => oldValue);
                }
            }
            catch (Exception ex) // Handle potential exceptions when reading files or accessing the network.
            {
                Console.WriteLine($"Error processing file: {filePath}, Exception: {ex}");
            }

            if (_fileDataCache.TryGetValue(filePath, out var fileData))
            {
                ComputeHash(fileData, out var hashBytes); // Hash the collected data in memory.
                fileHashes[filePath] = BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
            }
        }

        private void ComputeHash(byte[] data, out byte[] hashBytes)
        {
            using (SHA256 sha256 = SHA256.Create())
            {
                hashBytes = sha256.ComputeHash(data);
            }
        }
    }
}
