using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using log4net;

namespace DataProcessingLibrary
{
    public class DataProcessingService
    {
        private readonly ILog _log = LogManager.GetLogger(typeof(DataProcessingService));
        private const int BufferSizeLimit = 1024 * 64; // 64KB buffer size limit for memory efficiency

        public async Task ProcessDataAsync(Stream inputStream, Stream outputStream)
        {
            var hmac = new HMACSHA256();
            var dataBuffer = new byte[BufferSizeLimit];
            int bytesRead;

            try
            {
                while ((bytesRead = await inputStream.ReadAsync(dataBuffer, 0, dataBuffer.Length)) > 0)
                {
                    using (var aes = Aes.Create())
                    {
                        var encryptionOperation = aes.CreateEncryptor();

                        // Encrypt and write encrypted data to output stream
                        var encryptedData = TransformData(dataBuffer, 0, bytesRead, encryptionOperation);
                        await outputStream.WriteAsync(encryptedData, 0, encryptedData.Length);

                        // Update HMAC SHA-256 hash using the encrypted data
                        hmac.TransformBlock(encryptedData, 0, encryptedData.Length, null, 0);
                    }
                }
            }
            catch (Exception ex)
            {
                _log.Error($"Error occurred while processing data: {ex.Message}", ex);
                throw;
            }

            // Complete HMAC hash calculation and verify its integrity
            var hmacResult = hmac.Hash;

            using (var sha256 = SHA256.Create())
            {
                var finalDataHash = sha256.ComputeHash(inputStream);
                _log.Info($"Final data hash: {BitConverter.ToString(finalDataHash).Replace("-", string.Empty)}");

                if (!hmacResult.SequenceEqual(finalDataHash))
                {
                    throw new InvalidDataException("The integrity of the processed data could not be verified.");
                }
            }
        }

        private byte[] TransformData(byte[] buffer, int offset, int count, ICryptoTransform transform)
        {
            var encryptedData = transform.TransformFinalBlock(buffer, offset, count);

            // Padding if necessary (assuming PKCS7 padding is used here)
            var paddingLength = BufferSizeLimit - (encryptedData.Length % BufferSizeLimit);
            Array.Resize<byte>(ref encryptedData, encryptedData.Length + paddingLength);
            for (var i = encryptedData.Length - 1; i > encryptedData.Length - paddingLength; --i)
                encryptedData[i] = paddingLength;

            return encryptedData;
        }
    }
}
```

