using System;
using System.IO;
using System.IO.Compression;
using System.Runtime.Serialization.Formatters.Binary;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using MemoryMappedFiles = System.IO.MemoryMappedFiles;

namespace CompressedDataLoader
{
    public class FileType
    {
        public string Name { get; set; }
        public Func<Stream, object> DeserializeFunc { get; set; }
    }

    public class CompressionStrategy
    {
        public FileType FileType { get; set; }
        public Func<Stream, Stream> CompressFunc { get; set; }
        public Func<Stream, Stream> DecompressFunc { get; set; }
    }

    public class Loader
    {
        private readonly Dictionary<string, CompressionStrategy> _compressionStrategies;
        private readonly BinaryFormatter _serializer = new BinaryFormatter();

        public Loader(IEnumerable<CompressionStrategy> compressionStrategies)
        {
            _compressionStrategies = compressionStrategies.ToDictionary(cs => cs.FileType.Name);
        }

        public async Task<T> LoadAsync<T>(string filePath)
        {
            var fileType = _compressionStrategies.FirstOrDefault(ct => ct.Key == Path.GetExtension(filePath));

            if (fileType.Equals(default))
                throw new Exception($"Unsupported file format: '{Path.GetExtension(filePath)}'");

            using var fileStream = File.OpenRead(filePath);
            Stream inputStream, outputStream;

            if (fileStream.Length > MemoryMappedFiles.SystemMemoryMappedFile.MaximumSize)
                inputStream = fileStream;
            else
                (inputStream, outputStream) = MemoryMappedFiles.CreateFromFile(filePath, FileMode.Open, fileStream.Length);

            await Task.Run(() => DecompressAsync(inputStream, outputStream));

            if (outputStream is MemoryStream memoryStream)
                return _serializer.Deserialize<T>(memoryStream);

            using var deserializedStream = new FileStream(filePath + ".temp", FileMode.Create, FileAccess.Write, FileShare.None);
            _serializer.Serialize(deserializedStream, File.ReadAllBytes(filePath));
            File.Delete(filePath);
            File.Move(filePath + ".temp", filePath);

            return default;
        }

        private void DecompressAsync(Stream inputStream, Stream outputStream)
        {
            if (inputStream is MemoryStream memoryInputStream && outputStream is MemoryStream memoryOutputStream)
            {
                var compressedStream = _compressionStrategies[Path.GetExtension(memoryInputStream.Name)].DecompressFunc(memoryInputStream);
                memoryOutputStream.CopyFromAsync(compressedStream, 0, Convert.ToInt64(compressedStream.Length), 0, null);
            }
            else
            {
                using var gzipStream = new GzipStream(inputStream, CompressionMode.Decompress);
                outputStream.CopyFromAsync(gzipStream, 0, Convert.ToInt64(gzipStream.Length), 0, null);
            }
        }
    }
}
```
