using boost::adjacency_list;
using namespace std;

class Vertex {
public:
    explicit Vertex(int id) : id(id), properties() {}
    int id;
    any properties;
};

typedef adjacency_list<Vertex, vecS> Graph;

class InterfaceTable {
public:
    virtual void addVertex(const Vertex& vertex) = 0;
    virtual void addEdge(int fromId, int toId) = 0;
};

class TestInterfaceTable : public InterfaceTable {
public:
    MOCK_METHOD1(addVertex, void(const Vertex&));
    MOCK_METHOD2(addEdge, void(int, int));
};

void addVerticesAndEdges(InterfaceTable& table, int numVertices, int numEdges) {
    random_device rd;
    mt19937 gen(rd());
    uniform_int_distribution<> dist6(0, numVertices - 1);

    for (int i = 0; i < numVertices; ++i) {
        Vertex v(i);
        table.addVertex(v);
    }

    for (int i = 0; i < numEdges; ++i) {
        int fromId = dist6(gen), toId = dist6(gen);
        if (fromId != toId)
            table.addEdge(fromId, toId);
    }
}

void addVerticesAndEdgesParallelized(InterfaceTable& table, int numVertices, int numEdges, int numThreads) {
    random_device rd;
    mt19937 gen(rd());
    uniform_int_distribution<> dist6(0, numVertices - 1);

    priority_queue<future<void>> tasks;

    for (int i = 0; i < numThreads; ++i) {
        Vertex v(i * (numVertices / numThreads));
        auto func = bind(&InterfaceTable::addVertex, ref(table), _1);
        tasks.push(async(launch::async, func, v));
    }

    for (int i = 0; i < numEdges; ++i) {
        int fromId = dist6(gen), toId = dist6(gen);
        if (fromId != toId) {
            auto func = bind(&InterfaceTable::addEdge, ref(table), fromId, toId);
            tasks.push(async(launch::async, func));
        }
    }

    while (!tasks.empty()) {
        tasks.top().wait();
        tasks.pop();
    }
}

