class MemMonitor {
public:
    MemMonitor() : start(getpagesize()), end(0), current(start) {}

    void logMemUsage() {
        long size = (end - current) / getpagesize();
        std::cout << "Current memory usage: " << size << " MB" << std::endl;
        current = mmap(nullptr, getpagesize(), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    }
private:
    long start, end, current;
};

