std::vector<int> keys;
std::vector<Record> records;
MemMonitor memMon;

void* process_records(void*) {
    // Integrate with the external data processing library here.
    ...
}

void readRecords() {
    std::string line;
    int key, value;
    long offset = 0;

    while (std::getline(std::cin, line)) {
        std::istringstream iss(line);
        if (!(iss >> key >> value)) {
            std::cerr << "Invalid input: " << line << std::endl;
            continue;
        }

        keys.push_back(key);
        records.emplace_back(Record{value});
        records.back().prev = (offset == 0) ? nullptr : records[--offset];
        records.back().next = (offset + 1 >= records.size()) ? nullptr : &records[++offset];
        offsets.push_back(offset);
    }
}

int main() {
    pthread_t threads[NUM_THREADS];
    std::atomic<bool> running(true);

    readRecords();

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], nullptr, process_records, nullptr);
    }

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], nullptr);
    }

    running.store(false);

    // Resize arrays if necessary
    ...

    memMon.logMemUsage();
}
