    private readonly IService _service;
    private readonly IDatabase _redisDatabase;
    private readonly XmlSchemaSet _schema;
    private readonly TimeSpan _rateLimitWindow = TimeSpan.FromMinutes(1);
    private readonly int _maxRetries = 3;
    private readonly TimeSpan _retryBackoff = TimeSpan.FromSeconds(2);
    private readonly INotificationService _notificationService;

    public UpdateElementContent(IService service, IDatabase redisDatabase, XmlSchemaSet schema, INotificationService notificationService)
    {
        _service = service;
        _redisDatabase = redisDatabase;
        _schema = schema;
        _notificationService = notificationService;
    }

    public async Task UpdateElementAsync(string sectionId, string elementId, string content)
    {
        var cacheKey = GenerateCacheKey(sectionId, elementId);

        // Rate limit using Redis
        if (IsRateLimited(cacheKey)) return;

        // Validate HTML content against schema
        if (!ValidateContent(content)) throw new Exception("Invalid or malformed HTML content");

        // Update the element's HTML content using the service class
        await _service.UpdateElementAsync(sectionId, elementId, content);

        // Log the change with a timestamp for auditing purposes
        var timestamp = DateTimeOffset.UtcNow;
        LogChange(cacheKey, timestamp, content);

        // Notify when significant changes are detected in the HTML content (optional)
        if (_notificationService != null && DetectSignificantChange(content)) _notificationService.Notify();

        // Retry logic for service failures up to three times with exponential backoff
        for (int i = 0; i < _maxRetries; i++)
        {
            try
            {
                await _service.UpdateElementAsync(sectionId, elementId, content);
                break;
            }
            catch (Exception)
            {
                if (i >= _maxRetries - 1) throw;
                Thread.Sleep((long)_retryBackoff.TotalMilliseconds);
            }
        }
    }

    private string GenerateCacheKey(string sectionId, string elementId) => $"{sectionId}:{elementId}";

