#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <limits.h>
#include <iconv.h>

char* generate_new_filename(const char *input) {
    const size_t max_len = 255;
    size_t input_len = strlen(input);

    // Truncate the filename if it exceeds 255 characters
    if (input_len > max_len) {
        input[max_len - 1] = '\0';
    }

    // Extract base name and extension
    size_t last_dot = strlen(input) == 0 ? UINT_MAX : strrchr(input, '.') - input;
    const size_t base_name_len = last_dot < UINT_MAX ? last_dot : strlen(input);
    size_t extension_len = input_len - base_name_len;
    char base_name[129] = {0};
    char extension[5] = {0};

    // Extract the base name and extension
    if (last_dot != UINT_MAX) {
        strncpy(base_name, input, base_name_len);
        strncpy(extension, input + last_dot, extension_len);
    } else {
        strncpy(base_name, input, base_name_len > 128 ? 128 : base_name_len);
        base_name[base_name_len] = '\0'; // Ensure null termination
    }

    // Determine new extension
    size_t base_name_length = strlen(base_name);
    int digits = base_name_length < 3 ? 2 : 1;
    char file_type[4] = {base_name[base_name_length - 2], base_name[base_name_length - 1], '\0', '\0'};

    // Handle edge case: if less than two characters, set file type to 'txt'
    if (strlen(file_type) < 2) {
        strcpy(file_type, "txt");
    }

    // Construct new extension
    snprintf(extension, sizeof(extension), "%0*d%s", digits, base_name[base_name_length - 1] - '0', file_type);

    // Handle invalid characters in the base name
    size_t valid_chars = 0;
    for (size_t i = 0; i < base_name_length; ++i) {
        if (isalnum(base_name[i]) || base_name[i] == '_' || base_name[i] == '-') {
            valid_chars++;
        } else {
            break;
        }
    }

    // If there are invalid characters, trim them from the end of the base name
    if (valid_chars < base_name_length) {
        base_name[valid_chars] = '\0';
        size_t trimmed_len = strlen(base_name);
        if (trimmed_len > 32) {
            trimmed_len = 32;
        }
        // Append invalid characters to the end of the new filename in reverse order
        for (size_t i = valid_chars; i < base_name_length; ++i) {
            if (!isalnum(base_name[i]) && base_name[i] != '_' && base_name[i] != '-') {
                strcat(base_name + trimmed_len, &base_name[i]);
                trimmed_len++;
            }
            if (trimmed_len == 32) break;
        }
    }

    // Construct the new filename by concatenating the base name and extension
    char* output = malloc(strlen(base_name) + strlen(extension) + 1);
    strcpy(output, base_name);
    strcat(output, ".");
    strcat(output, extension);

    return output;
}
