['```c
#include <openssl/aes.h>
#include <openssl/gcm.h>
#include <openssl/pbkdf2.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

#define KEY_SIZE 16
#define SALT_SIZE 8
#define PBKDF2_ITERATIONS_MIN 1000
#define PBKDF2_ITERATIONS_MAX 1000000

typedef struct {
    AES_KEY aes;
    GCm_ECB8_ctx *gcm_ctx;
} AES128GCM_ctx;

void init_aes128gcm(AES128GCM_ctx* ctx, const uint8_t* password, size_t password_len) {
    uint8_t key[KEY_SIZE];
    uint8_t salt[SALT_SIZE];

    // Derive the key using PBKDF2 with a suitable iteration count based on expected workload and dataset size.
    size_t iterations = PBKDF2_ITERATIONS_MIN + (size_t)(password_len * password_len) / (sizeof(uint8_t) * 10);
    if (iterations > PBKDF2_ITERATIONS_MAX) {
        iterations = PBKDF2_ITERATIONS_MAX;
    }
    PKCS5_PBKDF2_HMAC((const EVP_CIPHER*)EVPaes128_GCM(), password, password_len, salt, SALT_SIZE, iterations, key);

    // Initialize the AES-128-GCM cipher.
    AES_set_encrypt_key(key, 128, &ctx->aes.ctx);
    ctx->gcm_ctx = GCm_ECB8_init(&ctx->aes);
}

void encrypt_aes128gcm(AES128GCM_ctx* ctx, const uint8_t* in, size_t inlen, uint8_t* out) {
    GCm_ECB8_update(ctx->gcm_ctx, in, inlen);
    GCm_ECB8_final(ctx->gcm_ctx, out, NULL);
}

void decrypt_aes128gcm(AES128GCM_ctx* ctx, const uint8_t* in, size_t inlen, uint8_t* out) {
    GCm_ECB8_update(ctx->gcm_ctx, in, inlen);
    GCm_ECB8_final(ctx->gcm_ctx, out, NULL);
}

void cleanup_aes128gcm(AES128GCM_ctx* ctx) {
    GCm_ECB8_cleanup(ctx->gcm_ctx);
}
```
