#include <stdio.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <dirent.h>
#include <stdlib.h>
#include <sys/stat.h>
#include <unistd.h>
#include <openssl/sha.h>

size_t hash_first_8_chars(const char *filename) {
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_Init(&hash);
    SHA256_Update(&hash, filename, 8);
    SHA256_Final(hash, &hash);
    return hash[0] | (hash[1] << 8) | (hash[2] << 16) | (hash[3] << 24);
}

char* generate_unique_filename(const char *original_filename) {
    size_t hash_id = hash_first_8_chars(original_filename);
    time_t rawtime;
    struct tm * timeinfo;
    char timestamp[29]; // 29 characters to account for -1 null character and potential overflow in formatting

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    char *new_filename = malloc(256);
    snprintf(new_filename, 256, "%lu%s%s", hash_id, timestamp, strrchr(original_filename, '.'));

    if (strlen(new_filename) > 255) {
        size_t last_dot = strlen(strrchr(new_filename, '.')) - 1;
        size_t hash_len = strlen(strrchr(new_filename, '/')) + strlen("hash_") + last_dot;
        memmove(new_filename + hash_len, new_filename + last_dot, strlen(new_filename + last_dot));
        strncpy(new_filename, "hash_", hash_len);
    }

    return new_filename;
}

int rename_file(const char *original_filename, const char *new_filename) {
    DIR *dir = opendir(".");
    if (!dir) return -1;

    struct stat st;
    if (stat(original_filename, &st) < 0 || S_ISDIR(st.st_mode)) {
        closedir(dir);
        return -1;
    }

    int result = rename(original_filename, new_filename);
    closedir(dir);

    return result == 0 ? 0 : -1;
}

int main() {
    const char *original_filename = "/path/to/yourfile.txt";
    char *new_filename = generate_unique_filename(original_filename);
    if (rename_file(original_filename, new_filename)) {
        perror("Failed to rename file");
        free(new_filename);
        return -1;
    }
    printf("File successfully renamed: %s\n", new_filename);
    free(new_filename);
    return 0;
}
```']

