struct DynamicArray* create_dynamic_array(size_t initial_capacity) {
    struct DynamicArray* array = malloc(sizeof(struct DynamicArray));
    if (!array) {
        perror("Failed to allocate memory for dynamic array");
        return NULL;
    }

    array->records = calloc(initial_capacity, sizeof(Record));
    if (!array->records) {
        free(array);
        perror("Failed to allocate memory for records");
        return NULL;
    }

    array->capacity = initial_capacity;
    array->length = 0;

    return array;
}

void resize_dynamic_array(struct DynamicArray* array) {
    double heuristic_factor = 1.5; // Adjust this value to optimize for throughput and latency
    size_t new_capacity = (array->length > 0) ? (array->capacity * heuristic_factor) : heuristic_factor;

    Record* temp_records = realloc(array->records, new_capacity * sizeof(Record));
    if (!temp_records) {
        perror("Failed to reallocate memory for records");
        return;
    }

    array->records = temp_records;
    array->capacity = new_capacity;
}

void initialize_dynamic_array(struct DynamicArray* array, int min_key, int max_key) {
    for (size_t i = 0; i < array->length; ++i) {
        array->records[i].key = rand() % (max_key - min_key + 1) + min_key;
        array->records[i].offset = rand(); // Replace this with your logic for generating the offset values
    }
}

void process_batch(struct DynamicArray* array, void (*process_function)(Record)) {
    double start_time = get_current_time();

    for (size_t i = 0; i < array->length; ++i) {
        process_function(array->records[i]);
    }

    log_performance("Batch Processing", get_current_time() - start_time);
}

void destroy_dynamic_array(struct DynamicArray* array) {
    free(array->records);
    free(array);
}
