record* init_arrays(size_t *offsets, size_t num_offsets,
                    int *keys, size_t num_keys, record **records,
                    size_t *num_records) {
    *offsets = malloc(num_offsets * sizeof(long));
    if (!*offsets) {
        perror("malloc: ");
        exit(EXIT_FAILURE);
    }
    *keys = malloc(num_keys * sizeof(int));
    if (!*keys) {
        free(*offsets);
        perror("malloc: ");
        exit(EXIT_FAILURE);
    }
    *records = calloc(num_records, sizeof(record));
    if (!*records) {
        free(*keys);
        free(*offsets);
        perror("calloc: ");
        exit(EXIT_FAILURE);
    }

    record *current = *records;
    for (size_t i = 0; i < num_offsets; ++i) {
        (*offsets)[i] = i + 1;
    }
    for (size_t i = 0; i < num_keys; ++i) {
        (*keys)[i] = i + 1;
