    // Set the value of each record's int field to a random value within [1, 100]
    for (size_t i = 0; i < num_records; ++i) {
        current[i].value = rand() % 100 + 1;
        if (i != num_records - 1)
            current = current->next = calloc(1, sizeof(record));
