#include <archive_entry.h>

void serialize(const char *filename, record *records, size_t num_records) {
    struct archive *a;
    struct archive_entry *entry;
    int rc;

    a = archive_write_new();
    rc = archive_write_open_filename(a, filename, MAR_ZLIB);
    if (rc != ARCHIVE_OK) {
        perror("archive_write_open_filename: ");
        exit(EXIT_FAILURE);
    }

    entry = archive_entry_new();
    entry->type = AE_IF_REG;
    entry->size = num_records * sizeof(record);

