    if (rc != ARCHIVE_OK) {
        perror("archive_write_header: ");
        exit(EXIT_FAILURE);
    }

    record *current = records;
    for (size_t i = 0; i < num_records; ++i, current++) {
        archive_write_data(a, current, sizeof(record));
    }

    archive_write_finish(a, NULL);
    archive_free(a);
}

void deserialize(const char *filename, record **records, size_t *num_records) {
    struct archive *a;
    int rc;

    a = archive_read_new();
    rc = archive_read_open_filename(a, filename, MAR_ZLIB);
    if (rc != ARCHIVE_OK) {
        perror("archive_read_open_filename: ");
        exit(EXIT_FAILURE);
    }

    record *current = NULL;
    rc = archive_read_next_header(a, &entry);
    while (rc == ARCHIVE_OK && !archive_entry_has_errors(entry)) {
        if (rc != ARCHIVE_SKIP_LOOP) {
            *num_records = entry->size / sizeof(record);
            *records = malloc(*num_records * sizeof(record));
            current = *records;
        }
        rc = archive_read_data(a, current++, sizeof(record));
    }
    if (rc != ARCHIVE_EOF) {
        perror("archive_read_data: ");
        exit(EXIT_FAILURE);
    }

    archive_free(a);
}
```

