constexpr auto BATCH_SIZE_DEFAULT = 1000;
using ErrorCodeID = int;
std::map<ErrorCodeID, size_t> errorCodesCount;
size_t totalLogs = 0;
double averageProcessingTime = 0.0;

void parseLog(const fs::path& filePath) {
    std::ifstream file(filePath);
    if (!file) {
        PCLI_LOG_ERROR("Could not open file {}", filePath);
        return;
    }

    size_t batchCount = 0;
    auto startTime = std::chrono::steady_clock::now();
    std::string line;
    while (std::getline(file, line)) {
        if (batchCount >= BATCH_SIZE) {
            processBatch(startTime);
            batchCount = 0;
        }

        // Parse log entry and increment error code count if applicable
        // ...

        ++batchCount;
    }
    processBatch(startTime);
}

void processBatch(const std::chrono::steady_clock::time_point& startTime) {
    auto endTime = std::chrono::steady_clock::now();
    double elapsedSeconds = std::chrono::duration_cast<std::chrono::seconds>(endTime - startTime).count();
    averageProcessingTime = (averageProcessingTime * totalLogs + elapsedSeconds) / (totalLogs + 1);
    ++totalLogs;
}

