        ("batch_size", po::value<int>()->default_value(BATCH_SIZE_DEFAULT), "Batch size for processing log entries");

    po::variables_map vm;
    po::store(po::parse_command_line(argc, argv, desc), vm);
    po::notify(vm);

    if (vm.count("help")) {
        std::cout << desc;
        return 0;
    }

    auto outputPath = vm["output"].as<std::string>();
    int batchSize = vm["batch_size"].as<int>();

    // Process the specified directory recursively, handling edge cases such as empty directories or missing headers in log files
    // ...

    PCLI_LOG_INFO("Generating report...");
    std::ofstream reportFile(outputPath);
    reportFile << "Total Logs Processed: " << totalLogs << "\n";
    reportFile << "Error Code Frequencies:\n";
    for (const auto& [code, count] : errorCodesCount) {
        reportFile << code << ": " << count << "\n";
    }
    reportFile << "Average Processing Time per Batch: " << averageProcessingTime << " seconds\n";

    return 0;
}
