typedef struct Record {
    int value;
    size_t offset;
    unsigned long key;
    struct Record *next;
} Record;

typedef struct Node {
    Record *head;
    sem_t *sem;
    size_t capacity;
    size_t size;
    char *data; // Cache for efficient data processing
} Node;

Node *create_node(size_t capacity) {
    Node *node = (Node *)malloc(sizeof(Node));
    if (!node) return NULL;
    node->head = NULL;
    node->sem = sem_init(1, 0, 1);
    node->capacity = capacity;
    node->size = 0;
    node->data = NULL;
    return node;
}

Record *create_record(int value, size_t offset, unsigned long key) {
    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) return NULL;
    record->value = value;
    record->offset = offset;
    record->key = key;
    record->next = NULL;
    return record;
}

void add_to_list(Node *node, Record *record) {
    sem_wait(node->sem);
    record->next = node->head;
    node->head = record;
    sem_post(node->sem);
}

Record *get_from_list(Node *node) {
    Record *temp = NULL;
    sem_wait(node->sem);
    temp = node->head;
    if (temp) node->head = temp->next;
    sem_post(node->sem);
    return temp;
}

