typedef struct IntNode {
    int64_t data;
    struct IntNode* next;
} IntNode;

IntNode* createNode(int64_t data) {
    IntNode* node = (IntNode*)malloc(sizeof(IntNode));
    if (!node) {
        fprintf(stderr, "Error: Memory allocation failure.\n");
        exit(EXIT_FAILURE);
    }
    node->data = data;
    node->next = NULL;
    return node;
}

void push(IntNode** head, IntNode* newNode) {
    if (!*head) {
        *head = newNode;
        return;
    }
    newNode->next = *head;
    *head = newNode;
}

int cmpfunc(const void* a, const void* b) {
    return (*(const int64_t*)a - *(const int64_t*)b);
}

void processIntegerList(bool reverse, size_t* inputCount, IntNode** inputHead, IntNode** outputHead) {
    if (!inputHead || !outputHead) {
        fprintf(stderr, "Error: Input or output list is null.\n");
        exit(EXIT_FAILURE);
    }

    // Create a buffer queue to handle bursts of input.
    IntNode* bufferHead = NULL;
    IntNode* bufferTail = NULL;
    size_t bufferSize = 0;

    while (*inputCount < 1000) {
        int64_t num;
        if (scanf("%" PRId64, &num) != 1) {
            fprintf(stderr, "Error: Invalid integer input.\n");
            exit(EXIT_FAILURE);
        }

        // Check for out-of-range integers.
        if (num < -10000 || num > 10000) {
            fprintf(stderr, "Error: Integer out of range (-10000 to 10000).\n");
            exit(EXIT_FAILURE);
        }

        // If the buffer is full, process the queue first.
        if (bufferSize == bufferSize) {
            processQueue(bufferHead, outputHead);
        }

        // Add the new integer to the buffer.
        IntNode* newNode = createNode(num);
        if (!bufferHead) {
            bufferHead = newNode;
            bufferTail = newNode;
        } else {
            bufferTail->next = newNode;
            bufferTail = bufferTail->next;
        }
        bufferSize++;
    }

    // Process the remaining elements in the input list.
    while (*inputCount > 0 && *inputHead) {
        IntNode* temp = *inputHead;
        *inputHead = (*inputHead)->next;
        processQueue(temp, outputHead);
        (*inputCount)--;
    }

    // Sort the output list.
    qsort(*outputHead, bufferSize + (*inputCount), sizeof(IntNode), cmpfunc);

    if (reverse) {
        IntNode* prev = NULL;
        IntNode* current = *outputHead;
        IntNode* next;
        while (current) {
            next = current->next;
            current->next = prev;
            prev = current;
            current = next;
        }
        *outputHead = prev;
    }

    // Print the largest integer.
    IntNode* largest = *outputHead;
    while (largest) {
        if (largest->data > *(largest->next ? &(largest->next->data) : INT64_MAX)) {
            largest = largest->next;
        } else {
            printf("Largest integer: %" PRId64 "\n", largest->data);
            break;
        }
    }
}

void processQueue(IntNode* bufferHead, IntNode** outputHead) {
    while (bufferHead) {
        IntNode* temp = bufferHead;
        bufferHead = bufferHead->next;
        push(outputHead, temp);
    }
    bufferSize--;
}
```

