#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <sys/types.h>
#include <semaphore.h>
#include <unistd.h>

#define BUFFER_SIZE (100000)  // Maximum number of entries in the buffer
#define FLUSH_INTERVAL (10)    // Flush interval in seconds
#define THREAD_SAFE

struct circular_buffer {
    void *data[BUFFER_SIZE];
    size_t head, tail;
    pthread_mutex_t lock;
    sem_t space_sem, full_sem;
};

void cb_init(struct circular_buffer* cb) {
    cb->head = cb->tail = 0;
    pthread_mutex_init(&cb->lock, NULL);
    sem_init(&cb->space_sem, 0, BUFFER_SIZE);
    sem_init(&cb->full_sem, 0, 0);
}

void cb_append(struct circular_buffer* cb, void *data) {
    pthread_mutex_lock(&cb->lock);

    while (true) {
        if (sem_wait(&cb->space_sem) < 0) {
            perror("Semaphore wait failed");
            break;
        }

        size_t next = cb->head + 1 == BUFFER_SIZE ? 0 : cb->head + 1;

        if (next != cb->tail) {
            cb->data[cb->head] = data;
            cb->head = next;
            sem_post(&cb->full_sem);
            break;
        } else {
            // Buffer is full, potentially drop new entry.
            if (pthread_self() == pthread_self(pthread_self())) {
                printf("Dropping entry due to buffer overflow\n");
            }
        }
    }

    pthread_mutex_unlock(&cb->lock);
}

void cb_flush(struct circular_buffer* cb) {
    time_t last_flush = 0;

    pthread_mutex_lock(&cb->lock);

    while (time(NULL) - last_flush >= FLUSH_INTERVAL) {
        size_t buffer_size = cb->head - cb->tail;

        // Adjust flush interval based on current buffer occupancy and system resources.
        if (buffer_size > BUFFER_SIZE * 0.8) {
            FLUSH_INTERVAL *= 2;
        } else if (buffer_size < BUFFER_SIZE * 0.2) {
            FLUSH_INTERVAL /= 2;
        }

        size_t i;
        for (i = cb->tail; i != cb->head; i = (i + 1) % BUFFER_SIZE) {
            // Perform data transformation, filtering, and logging here.
            void *data = cb->data[i];
            // ...
            // Logging with variable argument lists using snprintf and va_start/va_end.
            char log_buf[256];
            int size = snprintf(log_buf, sizeof(log_buf), "[%lu] Flushing entry %p (avg_size: %.2f, buffer_occupancy: %.2f%%, last_flush: %ld)\n",
                                (unsigned long)getpid(), data, average_size, buffer_occupancy * 100, last_flush);
            // Log the message.
            fputs(log_buf, stderr);
            free(data);
        }

        cb->tail = i;
        last_flush = time(NULL);
    }

    pthread_mutex_unlock(&cb->lock);
