['```python
import os
import time
import requests
import shutil
from dotenv import load_dotenv
import docker
import yaml
from concurrent.futures import ThreadPoolExecutor

load_dotenv()
API_URL = os.getenv("API_URL")
REGISTRY = os.getenv("REGISTRY")
CI = os.getenv("CI", False)
BACKUP_SKIP = os.getenv("BACKUP_SKIP", False)
BACKUP_DIR = os.getenv("BACKUP_DIR", "./backups")

def fetch_spec():
    try:
        response = requests.get(API_URL)
        if response.status_code == 200:
            return yaml.safe_load(response.content)
    except Exception as e:
        print(f"Error fetching specifications from API: {e}")
        return None

def backup_dockerfile(dockerfile):
    if not BACKUP_SKIP:
        shutil.copy2(dockerfile, f"{BACKUP_DIR}/{os.path.basename(dockerfile)}")

def build_image(spec):
    docker.utils.setup_logging()
    client = docker.from_env()

    backup_dockerfile(spec["dockerfile"])

    image = client.images.build(path=os.getcwd(), tag=spec["tag"], rm=True, dockerfile=spec["dockerfile"])
    return image

def push_image(image):
    client = docker.from_env()
    client.login(username=REGISTRY_USER, password=REGISTRY_PASS)
    client.images.push(image, registry=REGISTRY)

def main():
    spec = fetch_spec() or {"dockerfile": "Dockerfile", "tag": "latest"}

    if not spec:
        print("Failed to fetch specifications, using default configuration.")

    image = build_image(spec)

    if image:
        push_image(image)

def parallel_build():
    specs = fetch_spec() or []

    with ThreadPoolExecutor() as executor:
        results = list(executor.map(build_and_push, specs))

def build_and_push(spec):
    image = build_image(spec)

    if image:
        push_image(image)

if __name__ == "__main__":
    main()
elif "CI" in os.environ:
    parallel_build()
else:
    print("This script should be run as a standalone or via CI/CD.")
```

This code provides a basic structure for managing Docker images with automatic building, tagging, and pushing to a container registry. It fetches the latest build specifications from an external API, handles errors gracefully, backs up the original Dockerfile before modification (optional), and supports both single builds and parallel processing using threads.

