uint32_t maxValue(const Container& container) {
    return *std::max_element(container.begin(), container.end());
}

void process_and_integrate_numbers(std::vector<int>& numbers, int target, int insert) {
    // Use an unordered map to quickly find the position of 'target'
    std::map<int, uint32_t> positions;
    for (size_t i = 0; i < numbers.size(); ++i) {
        positions[numbers[i]] = i;
    }

    auto it = positions.find(target);
    if (it != positions.end()) {
        // Insert 'insert' after the first occurrence of 'target'
        numbers.insert(it->second + 1, insert);
    } else {
        // Append 'insert' at the end if 'target' is not present
        numbers.push_back(insert);
    }

    // Sort the vector in non-decreasing order
    std::sort(numbers.begin(), numbers.end());

    // Determine maximum integer and validate it does not exceed 1023
    uint32_t max = maxValue(numbers);
    if (max > 1023) {
        std::cerr << "Error: The maximum number in the updated vector (" << max << ") exceeds 1023." << std::endl;
        return;
    }

    // Seed the random number generator using the maximum value
    static std::random_device rd;
    static std::mt19937 gen(rd());
    std::uniform_int_distribution<> distr(0, max);

