        executor.scheduleAtFixedRate(() -> {
            try {
                executeCommandInternal(command);
            } catch (Exception e) {
                logger.error("Error while executing command: {}", e.getMessage());
            }
        }, 0, rateLimit, TimeUnit.MILLISECONDS);
    }

    private void executeCommandInternal(String command) throws IOException {
        // Connection pool to handle multiple concurrent requests
