                boost::log::trivial::add_filter("MyApplication", boost::log::trivial::severity >= boost::log::trivial::info);

                // Add your desired sinks here. For a high-throughput web application, consider using asynchronous sinks.
                boost::log::trivial::add_sink(boost::log::sources::get_severity_filter("MyApplication").add_sink(
                    boost::log::sinks::async_frontend<boost::log::sinks::rolling_file_sink_frontend>(
                        boost::log::keywords::file_name = "application.log",
                        boost::log::keywords::rotation_size = 10 * (1UL << 20), // 10 MB
                        boost::log::keywords::time_based_rotation = boost::log::sinks::schedule_rolling_time<boost::posix_time::hours>(48)
                    )
                ).add_filter(boost::log::trivial::severity >= boost::log::trivial::trace).flush_size(1 << 20)); // 1 MB

                // Custom log message formatting using Boost.Log's attributes and format functions.
                boost::log::expressions::stream auto expr = boost::log::expressions::expr("{Severity} [{}]: {}");
                expr % boost::log::expressions::format_attr<boost::log::attributes::severity_level>("Severity") % boost::log::expressions::attr("Thread ID") % boost::log::expressions::attr("Message");
                boost::log::trivial::set_formatter(expr);
            }

            ~LoggingSystem() {
                // Cleanup and finalize the logging system here.
            }
    };
