async function getFromCache(key) {
  const cachedValue = await new Promise((resolve, reject) => {
    redisClient.get(key, (err, value) => {
      if (err) return reject(err);
      resolve(JSON.parse(value));
    });
  });
  return cachedValue;
}
async function setInCache(key, value) {
