  // Process each file format separately
  for (const file of files) {
    let parsedData;

    switch (file.mimetype) {
      case 'application/pdf':
        parsedData = await processPDF(file.path);
        break;
      case 'application/vnd.openxmlformats-officedocument.wordprocessingml.document':
        parsedData = await processWordDocument(file.path);
        break;
      // Add more file formats as needed
      default:
        parsedData = { textContent: file.buffer.toString('utf8') };
    }

    // Combine metadata, keywords, and user-provided tags to generate a unique identifier
    const documentId = combineIdentifier(file.filename, parsedData);

    // Check if the processed data is in cache and serve it if available
    const cachedParsedData = await getFromCache(documentId);
    if (cachedParsedData) {
      res.json(cachedParsedData);
      continue;
    }

    // Apply user-defined filters to the parsed data and save the result in MongoDB with proper metadata
    const filteredData = applyFilters(parsedData, /* user-provided filter parameters */);
    await Document.create({ ...file, parsedData: filteredData });

    // Save the processed data to cache for future requests
    await setInCache(documentId, filteredData);

    // Notify clients of changes using Socket.IO
    io.emit('document-updated', documentId, filteredData);
  }

  next();
}

