class Extractor:
    def __init__(self, config: Config, data_source: Union[str, Callable] = None):
        self.config = config
        self.data_source = data_source if data_source else lambda: None  # Replace this with your external data source function or URL

    def extract(self, json_data: Dict[str, Any]) -> Dict[str, Any]:
        extracted_data = {}

        def recurse(json_obj, path):
            for key, rule in self.config.config.items():
                if isinstance(rule, list) and len(rule) > 1:  # Supports nested rules
                    for sub_rule in rule:
                        new_path = path + [sub_rule]
                        if new_path in json_obj:
                            recurse(json_obj[new_path], new_path)
                else:
                    full_path = path + [key]
                    if full_path in json_obj:
                        extracted_data[rule] = json_obj[full_path]

        recurse(json_data, [])
        return extracted_data

    def load(self):
