struct ThemeCache {
    char path[256];
    sem_t cleanup_sem;
    size_t bitmap_count;
    size_t max_bitmap_count;
};

struct Bitmap {
    JSAMPARRAY data;
    struct ThemeCache* cache;
};

// Function prototypes
void log(const char*, ...);
int validate_cache_directory(char*);
void cleanup_bitmaps(struct ThemeCache*);
void verify_themes(struct ThemeCache*);
void fetch_theme(struct ThemeCache*, const char*, int);
void* convert_to_pdf(void*);

// Global variables
struct ThemeCache theme_cache;
sem_t g_cleanup_sem;

int convertAndCacheTheme(const char* src, const char* dest, int fetch) {
    if (!validate_cache_directory(theme_cache.path)) {
        strcpy(theme_cache.path, dest);
        sem_init(&theme_cache.cleanup_sem, 0, 0);
        theme_cache.bitmap_count = 0;
        theme_cache.max_bitmap_count = 1000; // Update this value based on your requirements
    }

    JPEG jpeg;
    FILE* file = fopen(src, "rb");
    if (!file) {
        log("Failed to open source theme file: %s\n", src);
        return 1;
    }

    jpeg_read_header(&jpeg, file, TRUE);

    // Validate dimensions and aspect ratio
    ...

    struct Bitmap bitmap = { NULL, &theme_cache };
    JSAMPROW row_pointer[1];

    bitmap.data = malloc(jpeg.output_width * jpeg.output_components);
    if (!bitmap.data) {
        log("Failed to allocate memory for bitmap data\n");
        fclose(file);
        return 1;
    }

    while (jpeg.output_scanline < jpeg.output_height) {
        row_pointer[0] = &bitmap.data[(jpeg.output_scanline * jpeg.output_width + jpeg.output_components * jpeg.output_width)];
        jpeg_read_scanlines(&jpeg, row_pointer, 1);
    }

    fclose(file);

    // Cache the bitmap and log metrics
    ...

    if (fetch) {
        pthread_t thread;
        if (pthread_create(&thread, NULL, convert_to_pdf, &bitmap) != 0) {
            log("Failed to create conversion thread\n");
            cleanup_bitmaps(&theme_cache);
            return 1;
        }
    }

    return 0;
}
