class HashTable {
private:
    static const unsigned int BUCKET_COUNT = 1024;
    unordered_map<unsigned long, DataNode*> buckets;

    unsigned long hash(const std::string& key) const {
        unsigned long hash = 5381;
        for (char c : key) hash = ((hash << 5) + hash) + c;
        return hash % BUCKET_COUNT;
