// Custom memory pool for reducing fragmentation
struct mem_pool {
    void *memory;
    size_t allocated;
    size_t capacity;
};

void mem_pool_init(struct mem_pool *pool, size_t initial_capacity) {
    pool->memory = malloc(initial_capacity);
    if (!pool->memory) {
        fprintf(stderr, "Error: Out of memory!\n");
        exit(EXIT_FAILURE);
    }
    pool->allocated = 0;
    pool->capacity = initial_capacity;
}

void *mem_pool_alloc(struct mem_pool *pool, size_t size) {
    if (pool->allocated + size > pool->capacity) {
        pool->memory = realloc(pool->memory, pool->allocated + size + POOL_GROWTH);
        if (!pool->memory) {
            fprintf(stderr, "Error: Out of memory!\n");
            exit(EXIT_FAILURE);
        }
        pool->capacity += POOL_GROWTH;
    }
    void *result = pool->memory + pool->allocated;
    pool->allocated += size;
    return result;
}

void mem_pool_free(struct mem_pool *pool, void *ptr) {
    if (ptr >= pool->memory && ptr < (pool->memory + pool->capacity)) {
        pool->allocated -= sizeof(*ptr);
    } else {
        fprintf(stderr, "Error: Invalid memory address!\n");
        exit(EXIT_FAILURE);
    }
}

