#define MAX_TOTAL_LENGTH 1000

typedef struct {
    char identifier[64];
    float value;
    char *description;
} data_entry;

enum ErrorCodes {
    NO_ERROR = 0,
    MEMORY_ALLOCATION_FAILURE = 1,
    INVALID_INPUT = 2,
    OUT_OF_MEMORY = 3,
    DESCRIPTION_OVERFLOW = 4
};

int init_data_collection(int *source_counts, const char **source_ids, int *source_lengths, char **output, int total_length) {
    int min_entries = INT32_MAX;
    int total_entries = 0;
    int i, j;

    // Check for invalid input and prevent overflow
    for (i = 0; i < *source_counts; ++i) {
        if (*source_counts <= 0 || *source_lengths[i] <= 0 || *source_ids[i] == NULL || total_length <= 0)
            return INVALID_INPUT;

        min_entries = (min_entries > source_counts[i]) ? source_counts[i] : min_entries;
        total_entries += source_counts[i];
    }

    data_entry *data = malloc(min_entries * sizeof(data_entry));
    if (data == NULL)
        return MEMORY_ALLOCATION_FAILURE;

    char template[] = "Entry #%d: %s - %.2f";
    char temp_str[MAX_TOTAL_LENGTH];

    // Allocate and initialize memory for descriptions, considering total length constraint
    int description_length = 0;
    for (i = 0; i < *source_counts; ++i) {
        if (*source_ids[i][*source_lengths[i] - 1] == '\0')
            source_ids[i][*source_lengths[i]] = '\0';

        // Check for length violation and handle overflow gracefully
        if (*source_lengths[i] > MAX_TOTAL_LENGTH || strlen(source_ids[i]) + strlen(template) * (*source_counts - 1) + description_length >= MAX_TOTAL_LENGTH)
            return DESCRIPTION_OVERFLOW;

        strcpy(temp_str, template);
        for (j = 0; j < i; ++j)
            sprintf(temp_str + strlen(source_ids[i]) + strlen(template), ", %.2f", source_values[j]);
        strcat(temp_str + strlen(source_ids[i]), source_ids[i]);
        data_entry *current = &data[i];
        current->description = malloc((strlen(temp_str) + 1) * sizeof(char));
        if (current->description == NULL) {
            free(data);
            return OUT_OF_MEMORY;
        }
        strcpy(current->description, temp_str);
        description_length += strlen(current->description);
    }

    // Handle memory allocation failures gracefully and clean up in case of errors
    if (description_length + total_entries * sizeof(data_entry) > total_length) {
        for (i = 0; i < min_entries; ++i) {
            free(data[i].description);
        }
        free(data);
        return DESCRIPTION_OVERFLOW;
    }

    // Copy data to output and return success
    for (i = 0; i < min_entries; ++i) {
        strcpy(output[total_entries - min_entries + i], data[i].description);
    }

    return NO_ERROR;
}
