typedef struct {
    int value;
} record;

typedef struct HashNode {
    int key;
    uint64_t count;
    struct HashNode* next;
} HashNode;

struct MemoryPool {
    void* memory;
    size_t allocated, free;
};

// Custom memory pool
void* mem_pool_alloc(struct MemoryPool* pool, size_t size) {
    if (pool->free > size) {
        pool->free -= size;
        return pool->memory + pool->allocated - pool->free;
    }
    return realloc(pool->memory, pool->allocated + size);
}

// Memory cleanup function for custom memory pool
void mem_cleanup(struct MemoryPool* pool) {
    if (pool->memory) {
        free(pool->memory);
        pool->memory = NULL;
        pool->allocated = 0;
        pool->free = 0;
    }
}

// Function to handle user input and validation
void handle_input(size_t* offsets, size_t* keys, int* limit) {
    if (*offsets > (1ull << 20)) *offsets = (1ull << 20);
    if (*keys > (1ull << 16)) *keys = (1ull << 16);
    if (*limit < 0 || *limit > (1000 * *offsets)) *limit = 1000 * *offsets;
}

// Function to initialize hash table with given keys
HashNode* init_hash(size_t size) {
    HashNode* table = (HashNode*)mem_pool_alloc(sizeof(HashNode) * size);
    memset(table, 0, sizeof(HashNode) * size);
    return table;
}

// Function to compute hash and handle collisions for given key
uint64_t hash(int key, size_t table_size) {
    uint64_t hash = key ^ (key >> 21);
    hash += (hash << 14);
    hash ^= (hash >> 18);
    hash += (hash << 32);
    hash ^= (hash >> 39);
    return hash % table_size;
}

// Main function to implement the programming task
void* work(void* arg) {
    size_t offsets = *(size_t*)arg, keys, limit;
    record* records = NULL;
    HashNode* hash_table = init_hash(100000);

    handle_input(&offsets, &keys, &limit);

    if (offsets > keys) offsets = keys;

    records = mem_pool_alloc(sizeof(record) * offsets);

    for (size_t i = 0; i < offsets; ++i) {
        records[i].value = rand() % 1001;

        uint64_t hash_key = hash(records[i].value, 100000);
        HashNode* current = hash_table[hash_key];

        while (current != NULL && current->key == records[i].value) {
            ++current->count;
            break;
        }

        if (current == NULL || current->key != records[i].value) {
            current = malloc(sizeof(HashNode));
            current->key = records[i].value;
            current->count = 1;
            current->next = hash_table[hash_key];
            hash_table[hash_key] = current;
        }
    }

    uint64_t sum = 0;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    #pragma omp parallel for reduced(+:sum) shared(records, offsets, hash_table, limit, &lock)
    for (size_t i = 0; i < offsets; ++i) {
        sum += records[i].value;
        // Perform atomic operation to add value to sum without locking
        #pragma omp atomic update
        if (sum > limit && sum - records[i].value <= limit) sum -= records[i].value;
    }

    mem_cleanup(hash_table);
    free(records);

    return NULL;
}

int main() {
    size_t offsets, keys, limit;
    scanf("%lu %lu %d", &offsets, &keys, &limit);

    pthread_t threads[128];
    for (size_t i = 0; i < offsets / 128 + 1; ++i) {
        int rc = pthread_create(&threads[i], NULL, work, (void*)&offsets);
        if (rc) {
            fprintf(stderr, "Error: unable to create thread\n");
            return 1;
        }
    }

    for (size_t i = 0; i < offsets / 128 + 1; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

