    // Add measurement to measurement_results array
    ctx->measurement_results[ctx->num_cars] = measurement;
    ctx->num_cars++;
    pthread_mutex_unlock(&ctx->lock);
}

// Function to remove a carrier aggregation from the context based on its index
void remove_ca(lte_ue_context_t *ctx, size_t idx) {
    pthread_mutex_lock(&ctx->lock);
    // Shift elements in measurement_results array and decrement num_cars if necessary
    if (idx < ctx->num_cars) {
        memmove(&(ctx->measurement_results[idx]), &(ctx->measurement_results[idx+1]), sizeof(measurement_t) * (ctx->num_cars - idx));
        ctx->num_cars--;
    }
    pthread_mutex_unlock(&ctx->lock);
}

// Function to dynamically resize the measurement_results array based on user-specified parameters
void resize_ca(lte_ue_context_t *ctx, size_t new_size) {
    sem_wait(&ctx->resize_sem);
    measurement_t *temp = realloc(ctx->measurement_results, new_size * sizeof(measurement_t));
    if (temp == NULL) {
        // Handle memory allocation failure here
    } else {
        ctx->measurement_results = temp;
    }
    sem_post(&ctx->resize_sem);
}
