    for (i, filename) in filenames.into_iter().enumerate() {
        let data = filename.as_bytes();
        let addr = Box::into_raw(Box::new(data));

        records.push((mem::abs(thread_rng().gen_range(-max - min, max + 1) + min), addr as *const _));
        offsets[i] = i as i64;
    }

    // Set the value of each record's int field to a random value within the specified range.
    for rec in records.iter_mut() {
        *rec.0 = mem::abs(thread_rng().gen_range(-max - min, max + 1) + min);
    }

    // Free memory no longer needed for filenames.
    drop(filenames);

    // Write the records to output files with unique names.
    write_records("output_files", &records).await?;

    Ok(())
}

async fn load_filenames(filename: &str, file_list: &mut Vec<String>) -> Result<(), Error> {
    let mut file = match TokioFile::open(filename).await {
        Ok(file) => file,
        Err(err) => return Err(Error::Io(err)),
    };

    let reader = BufReader::new(file);
    let mut unique_filenames: Vec<String> = Vec::new();

    tokio::task::spawn_blocking(move || {
        for line in reader.lines() {
            match line {
                Ok(filename) => {
                    if !unique_filenames.contains(&filename) {
                        unique_filenames.push(filename);
                    } else {
                        eprintln!("Error: Duplicate filename {}", filename);
                        std::process::exit(1);
                    }
                }
                Err(err) => eprintln!("Error reading file: {} (ignoring)", err),
            }
        }

        unique_filenames.into_iter().for_each(|filename| {
            file_list.push(filename);
        });
    })
    .await?;

    Ok(())
}

async fn write_records<P: AsRef<Path>>(prefix: P, records: &[Record]) -> Result<(), Error> {
    for (i, rec) in records.iter().enumerate() {
        let filename = format!("{}_{}.txt", prefix.as_ref().file_name().unwrap().to_str().unwrap(), i);
        write_to_file(filename, &rec).await?;
    }

    Ok(())
}

async fn write_to_file<P: AsRef<Path>>(filename: P, rec: &Record) -> Result<(), Error> {
    let mut file = OpenOptions::new()
        .create(true)
        .write(true)
        .open(filename)
        .await?;

    writeln!(file, "{} {} {}", rec.0, rec.1 as usize, filename).unwrap();

    Ok(())
}
```

