    return 0;
}

void resolve_domain(struct resolver_ctx *ctx, const char *domain, struct ip_addr *ips, size_t ips_size) {
    struct domain *found = NULL;
    struct timespec now;
    double elapsed;
    int i;

    clock_gettime(CLOCK_MONOTONIC, &now);

    sem_wait(&ctx->config->domains_mutex);
    for (i = 0; i < config->num_domains; ++i) {
        if (strcmp(domain, config->allowed_domains[i]) == 0) {
            found = &config->allowed_domains[i];
            break;
        }
    }
    sem_post(&ctx->config->domains_mutex);

    if (!found) return -1; // Domain not allowed

    elapsed = compare_time(now, found->last_query, TIME_LIMIT);

    if (elapsed > 0 && ++found->ref_count >= RATE_LIMIT) {
        usleep((TIME_LIMIT / RATE_LIMIT - elapsed) * 1e6);
    }

    sem_wait(&found->query_sem);

    getaddrinfo_wrapper(domain, NULL, socktype, protocol, &res);

    if (res != NULL) {
        // Fill the ips array with IP addresses from res...

        freeaddrinfo(res);
    }

    found->last_query = now;
    found->ref_count--;
    sem_post(&found->query_sem);
}

int compare_time(struct timespec now, struct timespec then, double time_limit) {
    return (now.tv_sec - then.tv_sec > time_limit) || (now.tv_nsec - then.tv_nsec >= 1e9 * time_limit);
}

void log_query(struct resolver_ctx *ctx, const char *domain, int success) {
    sem_wait(&ctx->log_mutex);

    if (ctx->log_file != NULL) {
        fprintf(ctx->log_file, "%s %d\n", domain, success);
        fflush(ctx->log_file);
    }

    sem_post(&ctx->log_mutex);
}

// External getaddrinfo implementation that wraps the system's getaddrinfo...
