```cpp
#include <iostream>
#include <vector>
#include <list>
#include <mutex>
#include <deque>
#include <memory>
#include <stdexcept>
#include <external_processing_library>
#include <boost/asio/io_service.hpp>
#include <boost/thread/mutex.hpp>
#include <boost/serialization/access.hpp>
#include <boost/archive/text_iarchiver.hpp>
#include <boost/archive/xml_oarchive.hpp>

struct Record {
    int value;
    size_t offset;
    std::string key;
};

class ProcessRecords {
public:
    explicit ProcessRecords(size_t numThreads) : mtx(), data(), inputQueue() {
        for (size_t i = 0; i < numThreads; ++i)
            workers.emplace_back([this] { this->processData(); });
    }

    void process_records(std::istream& is) {
        std::unique_ptr<Record, decltype(&free)> record(static_cast<Record*>(malloc(sizeof(Record))));
        if (!record) throw std::bad_alloc();

        if (!(is >> record->value >> record->offset >> record->key))
            throw std::invalid_argument("Invalid input format");

        std::unique_ptr<Record> newRecord(new Record(*record));
        {
            std::lock_guard<std::mutex> lock(mtx);
            data.push_back(std::move(newRecord));
        }
        inputQueue.push_back(std::move(record));
    }

    void run() {
        boost::asio::io_service ioService;
        for (auto& worker : workers)
            worker.thread = std::thread([this, &ioService] { worker.task(ioService); });

        boost::asio::io_service::work work(ioService);
        ioService.run();
    }

private:
    void processData() {
        std::unique_ptr<Record> record;
        {
            std::lock_guard<std::mutex> lock(mtx);
            if (!inputQueue.empty())
                record = std::move(inputQueue.front());
                inputQueue.pop_front();
        }
        if (record) {
            external_processing_library::process(*record);
            delete record.release();
        }
    }

    std::mutex mtx;
    std::vector<std::deque<std::unique_ptr<Record>>> data;
    std::deque<std::unique_ptr<Record>> inputQueue;
    std::vector<std::thread> workers;
};
```

