use std::collections::HashMap;
use std::fs::{OpenOptions, Write, WriteAll};
use std::io::{BufRead, BufReader, Error};
use std::sync::{Arc, Mutex};
use tokio::prelude::*;
use tokio::runtime::RuntimeExecutor;
use external_processing_library::{Process, Record};

struct ProcessRecords {
    data: Arc<Mutex<HashMap<i32, (i32, String)>>>,
    input_queue: Arc<Mutex<Vec<Record>>>,
}

impl ProcessRecords {
    async fn new(num_threads: usize) -> Self {
        let data = Arc::new(Mutex::new(HashMap::new()));
        let input_queue = Arc::new(Mutex::new(Vec::new()));
        let mut executor = RuntimeExecutor::new().expect("Failed to create executor");
        (0..num_threads).map(|_| {
            executor.spawn(async move { self::process_data(&data, &input_queue).await })
        }).for_each(|_| Ok(())).expect("Failed to start threads");
        Self { data, input_queue }
    }

    async fn process_records<R: BufRead>(reader: R) {
        let mut record = Record::new();
        if let Ok(_) = reader.read_line(&mut record.value) {
            if let Ok(_) = reader.read_line(&mut record.offset) {
                if let Ok(_) = reader.read_line(&mut record.key) {
                    self::process_data(&Self::data, &Self::input_queue).await;
                    external_processing_library::process(record.clone()).expect("Failed to process record");
                } else {
                    return Err(Error::new(ErrorKind::InvalidInput, "Invalid key format"));
                }
            } else {
                return Err(Error::new(ErrorKind::InvalidInput, "Invalid offset format"));
            }
        } else {
            return Err(Error::new(ErrorKind::InvalidInput, "Invalid value format"));
        }
    }

    async fn process_data<D: AsRef<[u8]>>(data: &Arc<Mutex<HashMap<i32, (i32, String)>>>, input_queue: &Arc<Mutex<Vec<Record>>>) {
        let mut data = data.lock().await;
        let mut input_queue = input_queue.lock().await;
        if !input_queue.is_empty() {
            let record = input_queue.remove(0);
            data.insert(record.value, (record.offset, record.key));
        }
    }
}

#[tokio::main]
