        .arg(clap::Arg::with_name("num_threads")
            .help("Number of worker threads to use"))
        .get_matches();
    let num_threads: usize = matches.value_of("num_threads").unwrap_or("1").parse::<usize>().expect("Invalid number of threads");
    let process_records = ProcessRecords::new(num_threads).await?;
    // Read records from standard input and process them
