#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#define MAX_FRAMES 1024

typedef struct {
    NFAPI_RX_FRAME_TAG tag;
    int signal_strength;
} NFAPI_RX_FRAME_INFO_T;

struct frame_queue {
    NFAPI_RX_FRAME_INFO_T frames[MAX_FRAMES];
    size_t head;
    size_t tail;
    pthread_mutex_t mutex;
};

void init_frame_queue(struct frame_queue* queue) {
    queue->head = 0;
    queue->tail = 0;
    pthread_mutex_init(&queue->mutex, NULL);
}

bool enqueue(struct frame_queue* queue, const NFAPI_RX_FRAME_INFO_T* frame) {
    pthread_mutex_lock(&queue->mutex);
    if ((queue->tail + 1) % MAX_FRAMES == queue->head) {
        pthread_mutex_unlock(&queue->mutex);
        return false; // queue is full, cannot enqueue
    }
    queue->frames[queue->tail] = *frame;
    queue->tail = (queue->tail + 1) % MAX_FRAMES;
    pthread_mutex_unlock(&queue->mutex);
    return true;
}

bool dequeue(struct frame_queue* queue, NFAPI_RX_FRAME_INFO_T* frame) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->head == queue->tail) {
        pthread_mutex_unlock(&queue->mutex);
        return false; // queue is empty, cannot dequeue
    }
    *frame = queue->frames[queue->head];
    queue->head = (queue->head + 1) % MAX_FRAMES;
    pthread_mutex_unlock(&queue->mutex);
    return true;
}

void get_queue_stats(const struct frame_queue* queue, size_t* num_frames, int* total_signal_strength) {
    *num_frames = (queue->tail >= queue->head) ? (queue->tail - queue->head) : ((size_t)(MAX_FRAMES - queue->head) + queue->tail);
    *total_signal_strength = 0;
    pthread_mutex_lock(&queue->mutex);
    for (size_t i = queue->head; i != queue->tail; i = (i + 1) % MAX_FRAMES) {
        *total_signal_strength += queue->frames[i].signal_strength;
    }
    pthread_mutex_unlock(&queue->mutex);
}
```

This function uses a circular buffer (array) to manage the frames. The use of a mutex ensures thread-safety. A linked list would require more memory overhead and could potentially have slower access times due to pointer dereferencing, which may not be suitable for your real-time processing needs. This implementation is easy to integrate with an external pipeline as you can simply copy the data from the array when needed. The function handles potential data inconsistencies by ensuring that frames are only added or removed when the mutex is locked. Robust error handling is implemented in the enqueue and dequeue functions, which return false if the operation cannot be performed (e.g., queue is full or empty).']

