using System;
using System.Collections.Generic;
using System.Linq;
using System.Runtime.CompilerServices;
using System.Text;
using Newtonsoft.Json;

namespace DynamicValueGenerator
{
    public class ValueRange
    {
        public enum RangeInclusivity { Inclusive, Exclusive }

        public double Min { get; set; }
        public double Max { get; set; }
        public RangeInclusivity InclusionType { get; set; }
        public double StepSize { get; set; } = 1.0;
        public double Precision { get; set; } = double.MaxValue;
        public string ExternalSource { get; set; }

        [JsonIgnore]
        private bool IsActive => (Min <= Max && (InclusionType == RangeInclusivity.Inclusive || InclusionType == RangeInclusivity.Exclusive)) && !string.IsNullOrEmpty(ExternalSource) || string.IsNullOrEmpty(ExternalSource) && DateTime.Now > LastUpdateTime;

        public DateTime LastUpdateTime { get; set; }
    }

    [JsonObject(MemberSerialization = MemberSerialization.OptIn)]
    public class DynamicValueGenerator
    {
        private readonly List<ValueRange> _ranges;
        private readonly Random _random;

        public DynamicValueGenerator()
        {
            _ranges = new List<ValueRange>();
            _random = new Random();
        }

        public double Generate(string rangeName) => GetActiveRange(rangeName).GenerateValue(_random);

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private ValueRange GetActiveRange(string rangeName)
            => _ranges.FirstOrDefault(r => r.IsActive && string.Equals(r.ExternalSource, rangeName));

        public void AddRange(ValueRange valueRange)
        {
            if (!_ranges.Any(r => string.Equals(r.ExternalSource, valueRange.ExternalSource)))
                _ranges.Add(valueRange);
        }

        [JsonIgnore]
        public override string ToString()
        {
            var sb = new StringBuilder();
            foreach (var range in _ranges)
                if (range.IsActive)
                    sb.AppendLine($"{range.ExternalSource}: [{range.Min}, {range.Max}] {(range.InclusionType == RangeInclusivity.Exclusive ? "exclude" : "include")}");
            return sb.ToString();
        }
    }
}
```

