#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Config {
    char* key;
    char* value;
    struct Config* nested;
} Config;

Config* create_config() {
    return malloc(sizeof(Config));
}

int parse_entry(const char* line, Config* config) {
    // Simple implementation to split the line by "=" and trim whitespace
    size_t key_len = strcspn(line, "=");
    size_t value_len = strlen(line + key_len + 1);

    config->key = malloc(key_len + 1);
    memcpy(config->key, line, key_len);
    config->key[key_len] = '\0';

    if (value_len > 0) {
        config->value = malloc(value_len + 1);
        memcpy(config->value, line + key_len + 1, value_len);
        config->value[value_len] = '\0';
    } else {
        free(config->key);
        return -1; // Invalid entry format
    }

    return 0;
}

const char* get_value(Config* config, const char* key) {
    if (strcmp(config->key, key) == 0) {
        return config->value;
    }

    if (!config->nested) {
        return NULL; // Missing value or unsupported nested configuration
    }

    Config* current = config->nested;
    while (current && current->key) {
        if (strcmp(current->key, key) == 0) {
            return current->value;
        }
        current = current->nested;
    }

    return NULL; // Missing value or unsupported nested configuration
}
