function traverseAndFilterDOM(selector, testFn, processStringFn, config) {
    const cache = new Map();
    let queue = [document.body];
    let processedCount = 0;

    function getOrCreateCacheKey(element, traversalId) {
        return `${element.toString()}-${traversalId}`;
    }

    function processElement(element, parentKey, traversalId) {
        const key = getOrCreateCacheKey(element, traversalId);
        let result;

        if (cache.has(key)) {
            result = cache.get(key);
        } else {
            result = testFn(element);

            if (result) {
                const stringToProcess = element.toString().length > config.sizeLimit
                    ? null
                    : processStringFn(element.toString(), config.sizeLimit, config);

                if (stringToProcess) {
                    element[config.attributeName || 'data-custom'] = stringToProcess;
                }
            }

            cache.set(key, result);
        }

        if (result) {
            processedCount++;
        }

        for (const child of Array.from(element.children)) {
            queue.push(child);
        }
    }

    function traverseAndProcessQueue() {
        const currentSize = cache.size;

        if (currentSize > config.maxCacheSize) {
            // Implement LRU eviction strategy based on cache.
            cache.forEach((_, key) => {
                if (key.includes('-cached')) {
                    cache.delete(key);
                }
            });
        }

        for (let i = queue.length - 1; i >= 0; i--) {
            const element = queue[i];
            const parentKey = queue[i].parentElement ? getOrCreateCacheKey(queue[i].parentElement, traversalId) : null;

            processElement(element, parentKey, traversalId);
        }
    }

    let traversalId = Date.now();
    traverseAndProcessQueue();

    return Array.from(cache.values).filter((item) => item && item.matches(selector));
}
