class Logger {
public:
    virtual void log(const std::string& message) = 0;
};

class FileLogger : public Logger {
public:
    explicit FileLogger(const std::string& log_dir) : m_log_file("") {}

    void log(const std::string& message) override {
        if (!boost::filesystem::exists(m_log_dir))
            boost::filesystem::create_directory(m_log_dir);
        m_log_file = m_log_dir + "/server.log";
        std::ofstream out(m_log_file, std::ios_base::app);
        if (out) {
            out << message << "\n";
            out.close();
        }
    }

private:
    std::string m_log_file;
};

void readConfig(const std::string& filename, std::vector<ServerInstance>& instances) {
    json config = json::parse(std::ifstream(filename));
    for (auto instance : config.array()) {
        ServerInstance si;
        si.port = instance["port"].get<int>();
        si.document_root = instance["document_root"].get<std::string>("default_root");
        si.log_dir = instance["log_dir"].get<std::string>(".");
        si.logging_level = static_cast<LogLevel>(instance["logging_level"].get<int>());
        si.connection_pool_size = instance["connection_pool_size"].get<int>();
        instances.push_back(si);
    }
}

void setupConnectionPools(std::vector<ServerInstance>& instances, ConnectionPool& pool) {
    for (auto& instance : instances) {
        std::unique_lock<boost::mutex> lock(pool.mtx);
        while (pool.sockets.size() >= pool.capacity) {
            lock.unlock();
            this_thread::sleep_for(chrono::milliseconds(10));
            lock.lock();
        }
        instance.active_connections++;
        auto socket = std::move(pool.sockets.front());
        pool.sockets.pop_front();
        instance.connection_pool = std::unique_ptr<ConnectionPool>(new ConnectionPool{socket, 1, std::move(lock)});
    }
}

