sem_t sem_proc_limit, sem_cleanup;
pthread_mutex_t stats_lock;
int num_success = 0, num_timeout = 0, num_error = 0;

void sigterm_handler(int signum) {
    sem_post(&sem_cleanup);
}

void cleanup(struct command* cmd) {
    if (cmd->in_fd != STDIN_FILENO) close(cmd->in_fd);
    if (cmd->out_fd != STDOUT_FILENO) close(cmd->out_fd);
    if (cmd->err_fd != STDERR_FILENO) close(cmd->err_fd);
    if (cmd->in_fd >= 0 || cmd->out_fd >= 0 || cmd->err_fd >= 0) unlink("/tmp/io-redirect-XXXXXX");
}

void* run_command(void* data) {
    struct command* cmd = data;
    pid_t pid = fork();

    if (pid == -1) {
        fprintf(stderr, "Error forking process: %s\n", strerror(errno));
        num_error++;
        cleanup(cmd);
        return NULL;
    } else if (pid > 0) {
        sem_wait(&sem_cleanup);
        if (!WIFSIGNALED(waitpid(pid, NULL, WNOHANG))) waitpid(pid, NULL, 0);
        cleanup(cmd);
        return pid == 0 ? (void*)1 : NULL; // child process exit status
    } else {
        dup2(cmd->in_fd, STDIN_FILENO);
        dup2(cmd->out_fd, STDOUT_FILENO);
        dup2(cmd->err_fd, STDERR_FILENO);

        struct timeval now;
        gettimeofday(&now, NULL);

        // check timeout
        while (1) {
            gettimeofday(&now, NULL);
            if ((now.tv_sec - cmd->timeout.tv_sec) > cmd->timeout.tv_usec / 1000000 + 1) {
                printf("%s: Timed out\n", cmd->cmd);
                num_timeout++;
                _exit(124);
            }

            // execute command
            char* argv[32];
            int argc = 0;
            char** pos = strtok((char*)cmd->cmd, ";");
            while (pos != NULL) {
                argv[argc++] = *pos++;
                if (argc >= 32) break;

                char* next_pos = strchr(*pos, ' ');
                if (next_pos == NULL) next_pos = pos + strlen(pos);
                if (next_pos > *pos && *(next_pos - 1) != '\\') {
                    argv[argc] = "";
                    argc++;
                } else {
                    argv[argc] = next_pos;
                }
            }
            argv[argc] = NULL;

            if (execvp(argv[0], argv) == -1) {
                fprintf(stderr, "%s: Execution failed: %s\n", cmd->cmd, strerror(errno));
                num_error++;
                _exit(127);
            }
        }
    }
}

int execute_commands(const char* commands) {
    char** cmd_arr = calloc(32, sizeof(char*));
    int argc = 0;
    char* pos = strtok((char*)commands, ";");
    while (pos != NULL) {
        cmd_arr[argc++] = pos++;
        if (argc >= 32) break;

        char* next_pos = strchr(pos, ' ');
        if (next_pos == NULL) next_pos = pos + strlen(pos);
        if (next_pos > pos && *(next_pos - 1) != '\\') {
            cmd_arr[argc] = "";
            argc++;
        } else {
            cmd_arr[argc] = next_pos;
        }
    }
    cmd_arr[argc] = NULL;

    sem_init(&sem_proc_limit, 0, 10);
    sem_init(&sem_cleanup, 0, 0);
    pthread_mutex_init(&stats_lock, NULL);

    pid_t wpid;
    int status;
    int i = 0;
    struct command* cmds = malloc(sizeof(struct command) * argc);
    for (i = 0; i < argc; ++i) {
        struct command* cmd = &cmds[i];
        cmd->cmd = cmd_arr[i];
        cmd->in_fd = STDIN_FILENO;
        cmd->out_fd = STDOUT_FILENO;
        cmd->err_fd = STDERR_FILENO;
        cmd->timeout.tv_sec = 30;
        cmd->timeout.tv_usec = 0;

        sem_wait(&sem_proc_limit);

        int in_fd = -1, out_fd = -1, err_fd = -1;
        char* io_redir = strchr(cmd->cmd, '<');
        if (io_redir != NULL) {
            io_redir += 1;
            char redir[256];
            ssize_t len = snprintf(redir, sizeof(redir), "/tmp/io-redirect-%d", getpid());
            mkdir("/tmp/io-redirect", 0700);
            char* dir = strtok(redir, "-");
            char* file = strtok(NULL, NULL);
            in_fd = open(file, O_RDONLY | O_CREAT | O_TRUNC | O_EXCL, 0644);
            if (in_fd == -1) {
                perror("open");
                free(cmds);
                sem_destroy(&sem_proc_limit);
                sem_destroy(&sem_cleanup);
                pthread_mutex_destroy(&stats_lock);
                return 0;
            }
            cmd->in_fd = dup(in_fd);
        }

        io_redir = strchr(cmd->cmd, '>');
        if (io_redir != NULL) {
            io_redir += 1;
            char redir[256];
            ssize_t len = snprintf(redir, sizeof(redir), "/tmp/io-redirect-%d", getpid());
            mkdir("/tmp/io-redirect", 0700);
            char* dir = strtok(redir, "-");
            char* file = strtok(NULL, NULL);
            out_fd = open(file, O_WRONLY | O_CREAT | O_TRUNC | O_EXCL, 0644);
            if (out_fd == -1) {
                perror("open");
                free(cmds);
                sem_destroy(&sem_proc_limit);
                sem_destroy(&sem_cleanup);
                pthread_mutex_destroy(&stats_lock);
                return 0;
            }
            cmd->out_fd = dup2(out_fd, STDOUT_FILENO);
            if (cmd->out_fd == -1) {
                perror("dup2");
                free(cmds);
                sem_destroy(&sem_proc_limit);
                sem_destroy(&sem_cleanup);
                pthread_mutex_destroy(&stats_lock);
                return 0;
            }
        }

        io_redir = strchr(cmd->cmd, '>>');
        if (io_redir != NULL) {
            io_redir += 2;
            char redir[256];
            ssize_t len = snprintf(redir, sizeof(redir), "/tmp/io-redirect-%d", getpid());
            mkdir("/tmp/io-redirect", 0700);
            char* dir = strtok(redir, "-");
            char* file = strtok(NULL, NULL);
            out_fd = open(file, O_WRONLY | O_APPEND | O_CREAT | O_EXCL, 0644);
            if (out_fd == -1) {
                perror("open");
                free(cmds);
                sem_destroy(&sem_proc_limit);
                sem_destroy(&sem_cleanup);
                pthread_mutex_destroy(&stats_lock);
                return 0;
            }
            cmd->out_fd = dup2(out_fd, STDOUT_FILENO);
            if (cmd->out_fd == -1) {
                perror("dup2");
                free(cmds);
                sem_destroy(&sem_proc_limit);
                sem_destroy(&sem_cleanup);
                pthread_mutex_destroy(&stats_lock);
                return 0;
            }
        }

        io_redir = strchr(cmd->cmd, '|');
        if (io_redir != NULL) {
            // handle pipe redirection here
        }

        pid_t thread_id = pthread_create(&wpid, NULL, run_command, cmd);
        if (thread_id == -1) {
            perror("pthread_create");
            free(cmds);
            sem_destroy(&sem_proc_limit);
            sem_destroy(&sem_cleanup);
            pthread_mutex_destroy(&stats_lock);
            return 0;
        }
        wpid = waitpid(wpid, &status, WNOHANG);
        if (wpid > 0) {
            if (WIFEXITED(status)) {
                int exit_code = WEXITSTATUS(status);
                if (exit_code != 0) num_error++;
                else num_success++;
            } else if (WIFSIGNALED(status)) num_error++;
        }
    }

    pthread_mutex_lock(&stats_lock);
    sem_destroy(&sem_proc_limit);
    sem_destroy(&sem_cleanup);
    pthread_mutex_destroy(&stats_lock);

    if (num_success + num_timeout + num_error == argc) return 1;
    else return 0;
}
