using OctoTree = YourNamespace.Octree; // Assuming you have a custom Octree class

public class SiteManager
{
    private readonly ConcurrentDictionary<string, (Process process, OctoTree tree)> _sites;
    private readonly string _rootDirectory;

    public SiteManager(string rootDirectory)
    {
        _rootDirectory = rootDirectory;
        _sites = new ConcurrentDictionary<string, (Process, OctoTree)>();
    }

    public async Task<(bool success, string message)> AddSiteAsync(string siteName, int featureSize, int leafNodes, string directoryPath)
    {
        if (!Directory.Exists(directoryPath))
        {
            return (false, $"Directory '{directoryPath}' does not exist.");
        }

        if (!File.Exists($"{directoryPath}/web.config"))
        {
            return (false, $"Website at '{directoryPath}' is missing a web.config file.");
        }

        var siteKey = $"{_rootDirectory}/{siteName}";

        if (_sites.ContainsKey(siteKey))
        {
            _sites[siteKey].process.Refresh();

            if (!_sites[siteKey].process.HasExited)
            {
                return (false, $"The site '{siteName}' is already running.");
            }
        }

        try
        {
            var tree = new OctoTree(featureSize, leafNodes);
            var processStartInfo = new ProcessStartInfo($"dotnet", $"run --project {directoryPath}")
            {
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                WorkingDirectory = directoryPath,
                UseShellExecute = false,
                CreateNoWindow = true
            };

            var process = new Process();
            process.StartInfo = processStartInfo;
            process.Start();

            _sites[siteKey] = (process, tree);
            Log($"Successfully added site: {siteName}");

            CancellationTokenSource cts = null;
            var startedProcess = _sites[siteKey].process;
            if (startedProcess.Exited)
            {
                return (false, $"Failed to start the site '{siteName}'.");
            }

            cts = new CancellationTokenSource();
            Task.Run(async () =>
            {
                await Task.Delay(-1, cts.Token);
                if (!startedProcess.HasExited)
                {
                    cts.Cancel();
                    startedProcess.Kill();
                }
            }, cts.Token);

            return (true, $"Site '{siteName}' added and starting up.");
        }
        catch (Exception ex)
        {
            Log($"Failed to add site: {ex.Message}");
            return (false, ex.Message);
        }
    }

    private void Log(string message)
    {
        // Implement a robust logging mechanism here using your preferred logging library or custom implementation.
    }
}
