    public DatabaseConnection(String url, String user, String password) {
        this.url = url;
        this.user = user;
        this.password = password;
    }

    Connection getConnection() throws SQLException {
        return DriverManager.getConnection(url, user, password);
    }

    void close(AutoCloseable resource) {
        if (resource != null) try { resource.close(); } catch (Exception e) {}
    }
}

class QueryBuilder {
    String buildQuery(String commandTemplate, List<Object> values) {
        StringBuilder query = new StringBuilder();
        int index = 0;
        for (char c : commandTemplate.toCharArray()) {
            if (c == '{') {
                index = commandTemplate.indexOf('}', index);
                query.append(commandTemplate.substring(index, index + 1));
                query.append(values.get(index++));
            } else {
                query.append(c);
            }
        }
        return query.toString();
    }
}

class Cache {
    private final Duration expiration;
    private final ConcurrentHashMap<String, Object> cache = new ConcurrentHashMap<>();

    public Cache(Duration expiration) {
        this.expiration = expiration;
    }

    void put(String key, Object value) {
        cache.putIfAbsent(key, value);
    }

    Object get(String key) {
        return cache.getOrDefault(key, null);
    }

    void removeOutdatedEntries() {
        cache.values().removeIf(o -> System.currentTimeMillis() - o.getTimestamp() > expiration.toMillis());
    }
}

class Application {
