    private readonly int _maxConcurrentDecryptions;
    private SemaphoreSlim _semaphore;
    private readonly RetryPolicy _retryPolicy;

    public Decryptor(TripleDESCryptoServiceProvider cryptoProvider, int maxConcurrentDecryptions, RetryPolicy retryPolicy)
    {
