    public async Task<List<string>> DecryptMessagesAsync(string filePath, LoggingSettings loggingSettings)
    {
        var decryptedMessages = new List<string>();
        using (var reader = new StreamReader(filePath))
        {
            while (!reader.EndOfStream)
            {
                await ProcessMessageAsync(decryptedMessages, reader, _cryptoProvider, _retryPolicy, loggingSettings);
            }
        }

        return decryptedMessages;
    }

    private async Task ProcessMessageAsync(List<string> decryptedMessages, StreamReader reader, TripleDESCryptoServiceProvider cryptoProvider, RetryPolicy retryPolicy, LoggingSettings loggingSettings)
