                decryptedMessages.Add(decryptedMessage);
            }
            catch (Exception ex) when (_retryPolicy.ShouldRetry(ex))
            {
                if (!_retryPolicy.HasRetriedMaximum())
                {
                    // Log the error and retry the decryption process
                    _logger.ErrorFormat(loggingSettings, "Failed to decrypt message: {0}", encryptedMessage);
                    await Task.Delay(_retryPolicy.GetRetryInterval()).ConfigureAwait(false);
                    ProcessMessageAsync(decryptedMessages, reader, cryptoProvider, retryPolicy, loggingSettings).ContinueWith(task => _semaphore.Release());
                }
            }
        }
        catch (Exception ex)
        {
            // Log the exception and release the semaphore to prevent deadlocks
            _logger.ErrorFormat(loggingSettings, "An error occurred while reading the file: {0}", ex.Message);
            _semaphore.Release();
        }
    }

    private string Decrypt(string encryptedMessage, TripleDESCryptoServiceProvider cryptoProvider)
    {
        var decryptor = cryptoProvider.CreateDecryptor();
        var byteArray = Convert.FromBase64String(encryptedMessage);
        using (var ms = new MemoryStream(byteArray))
        {
            using (var cryptostream = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
            {
                var reader = new StreamReader(cryptostream);
                return reader.ReadToEnd();
            }
        }
    }
}

public class RetryPolicy
{
    private readonly TimeSpan _retryInterval;
    private readonly int _maxRetries;

    public RetryPolicy(TimeSpan retryInterval, int maxRetries)
    {
        _retryInterval = retryInterval;
        _maxRetries = maxRetries;
    }

    public bool ShouldRetry(Exception ex) => _maxRetries > 0 && (ex is CryptographicException || ex is IOException);
    public int HasRetriedMaximum() => _maxRetries <= 0 || _maxRetries == Interlocked.Read(ref _maxRetries);
    public TimeSpan GetRetryInterval() => _retryInterval;
}

public class LoggingSettings
{
    private readonly Func<IFormatProvider, IFormatableLogEntry, void> _format;
    private readonly string _formatProvider;

    public LoggingSettings(Func<IFormatProvider, IFormatableLogEntry, void> format, string formatProvider = null)
    {
        _format = format ?? throw new ArgumentNullException(nameof(format));
        _formatProvider = formatProvider;
    }

    public void LogErrorFormat(Exception exception, string format, params object[] arguments)
    {
        var entry = new LogEntry(LogEvent.Error, exception, new FormatableString(format, arguments));
        _format(_formatProvider ?? CultureInfo.InvariantCulture, entry);
    }
}
```

