            aes.IV = aesEncryption.IV;

            var encryptedData = await Task.Run(() => aes.Encrypt(data, aes.CreateEncryptor(), aes.IV));
            var mac = hmacSha256.ComputeHash(encryptedData);

            return (encryptedData, mac);
        }
