    {
        using (var aes = Aes.Create())
        {
            aes.Key = aesEncryption.Key;
            aes.IV = aesEncryption.IV;

            var decryptedData = aes.Decrypt(encryptedData, aes.CreateDecryptor(), aes.IV);
            var computedMac = hmacSha256.ComputeHash(decryptedData);

            if (!Array.TrueForAll(computedMac, x => x == mac[x % computedMac.Length]))
                throw new InvalidOperationException("Data integrity verification failed.");

            return decryptedData;
        }
    }

    public void VerifyDataIntegrity(byte[] data, byte[] mac)
    {
        using (var hmac = new HMACSHA256())
        {
            if (!Array.TrueForAll(hmac.ComputeHash(data), x => x == mac[x % mac.Length]))
                throw new InvalidOperationException("Data integrity verification failed.");
        }
    }

