import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.io.IOException;
import java.util.concurrent.atomic.AtomicReference;

public class DataDeserializer {
    private static final Logger LOGGER = LoggerFactory.getLogger(DataDeserializer.class);
    private final ObjectMapper objectMapper;
    private final Class<? extends Object> clazz;

    public DataDeserializer(ObjectMapper objectMapper, Class<? extends Object> clazz) {
        this.objectMapper = objectMapper;
        this.clazz = clazz;
    }

    public Object deserialize(byte[] data) {
        AtomicReference<Object> result = new AtomicReference<>();
        try {
            result.set(objectMapper.readValue(data, clazz));
        } catch (IOException e) {
            LOGGER.error("Error while deserializing data", e);
            result.set(getDefaultInstance());
        }
        validateData(result.get());
        return result.get();
    }

    private Object getDefaultInstance() {
        try {
            return clazz.newInstance();
        } catch (InstantiationException | IllegalAccessException e) {
            throw new RuntimeException("Unable to create default instance", e);
        }
    }

    private void validateData(Object data) {
        // Implement validation logic here based on the specific requirements of your application
    }
}
