use reqwest::Client;
use serde_json::{Map, Value};
use std::env;
use std::ffi::CString;
use std::fmt::{self, Write as FmtWrite};
use tokio::sync::Mutex;
use tokio::task::spawn;
use tokio::runtime::Runtime;

mod c_weather_report {
    use super::*;

    extern "CFFI" {
        fn snprintf(buf: *mut u8, len: size_t, format: *const i8, args: va_list) -> usize;
    }

    pub unsafe extern "C" fn generate_weather_report(city: *const i8, data: &Value) {
        let mut buffer = vec![0u8; 1024];
        let len = snprintf(
            buffer.as_mut_ptr(),
            buffer.len() as umax_t,
            std::ffi::CString::new("City: %s\nCurrent Temperature: %.2f°C\nWeather: %s\n")
                .unwrap()
                .as_ptr(),
            va_arg(std::mem::transmute::<*const i8, va_list>(std::ffi::VaList::new()), *const i8) as u32,
            data["temperature"].as_f64().unwrap() as f32,
            CString::new(data["weather"].as_str()).unwrap().as_ptr(),
        ) as usize;

        let s = std::str::from_utf8_unchecked(&buffer[..len]);
        println!("{}", s);
    }
}

struct WeatherApiClient {
    client: Client,
}

impl WeatherApiClient {
    async fn fetch_weather(city: &str) -> Result<Value, reqwest::Error> {
        let url = format!("https://api.openweathermap.org/data/2.5/weather?q={}&units=metric&appid={}", city, API_KEY);
        self.client.get(url).send().await?.json::<Value>()
    }
}

const API_KEY: &'static str = "YOUR_API_KEY";

async fn process_city_request(runtime: &Runtime, city: String) {
    let client = WeatherApiClient {
        client: Client::new(),
    };
    if let Ok(data) = client.fetch_weather(&city).await {
        unsafe {
            spawn(runtime.handle(), move || {
                c_weather_report::generate_weather_report(
                    CString::new(city.as_str()).unwrap().into_raw(),
                    &data,
                )
            })
            .await;
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        eprintln!("Usage: {} city [current|forecast]", args[0]);
        return;
    }

    let runtime = Runtime::new().unwrap();
    for city in args[1..] {
        spawn(runtime.handle(), move || process_city_request(&runtime, city)).await;
    }
}
```

