```rust
use std::env;
use std::fs::permissions;
use std::sync::{Arc, Mutex};
use tempfile::NamedTempFile;
use log::{error, info};

type DirectoryManager = Arc<Mutex<DirectoryMetadata>>;

struct DirectoryMetadata {
    directory: PathBuf,
    created_during_current_session: bool,
}

impl DirectoryMetadata {
    fn new(directory: PathBuf) -> Self {
        DirectoryMetadata {
            directory,
            created_during_current_session: true,
        }
    }

    fn set_created_during_current_session(&mut self, value: bool) {
        self.created_during_current_session = value;
    }
}

fn manage_directory(manager: &DirectoryManager, dir_name: &str, env_key: &str) -> Result<(), Box<dyn std::error::Error> {
    let manager = manager.clone();
    let dir = tempfile::Builder::new().prefix(dir_name).tempdir()?;
    if !dir.is_ok() {
        error!("Failed to create temporary directory.");
        return Err(Box::from("Failed to create temporary directory."));
    }
    let mut metadata = manager.lock().unwrap();
    metadata.set_created_during_current_session(true);
    dir.as_ref().map(|dir| {
        env::set_var(env_key, dir.path().to_str().unwrap());
        Ok(())
    })?;
    if !permissions(dir.as_ref(), &[permissions::WRITE])?.is_ok() {
        error!("Failed to set write permissions on directory.");
        return Err(Box::from("Failed to set write permissions on directory."));
    }
    Ok(())
}

fn cleanup(manager: Arc<Mutex<DirectoryMetadata>>) {
    let mut metadata = manager.lock().unwrap();
    if metadata.created_during_current_session && !metadata.directory.exists() {
        metadata.set_created_during_current_session(false);
        metadata.directory.into_os_string().into_vec().into_iter().for_each(|c| {
            if c == b'/' {
                info!("Removing intermediate directory.");
                let _ = std::fs::remove_dir_all(&metadata.directory);
            }
        });
        if metadata.directory.is_dir() {
            info!("Removing final directory.");
            if let Ok(_) = std::fs::remove_dir_all(&metadata.directory) {
                metadata.set_created_during_current_session(false);
            }
        }
    }
}
```

This solution uses `tempfile::NamedTempFile` to create directories and manages them using a `DirectoryMetadata` struct wrapped in a `std::sync::Mutex`. The cleanup function removes the created directory if it was created during this session and no other process has a reference to it. The environment variable is set atomically by acquiring a lock on the metadata before setting the variable value.

This solution may need further optimization for high concurrency scenarios, as well as refinement to handle edge cases and errors gracefully. Load testing tools can be used to identify potential bottlenecks and optimize accordingly.']

