        // Initialize a random number generator seeded with current time and thread ID
        unsigned long seed = time(NULL) + pthread_self();
        srand(seed);

        int value = rand() % 100;

        // Ensure unique values for each record
        do {
            if (!i || (*records)[i - 1].value != value) break;
        } while (true);

        (*records)[i].value = value;
    }
}

