use reqwest::{Client, Config};
use std::sync::Arc;
use reqwest_middleware::Middleware;

struct HttpClient {
    client: Arc<Client<Config>>,
}

impl HttpClient {
    async fn new(certificate_verifier: Option<&'static ssl::CertificateVerifier>) -> Result<Self, Box<dyn std::error::Error>> {
        let config = Config::new();
        if let Some(verifier) = certificate_verifier {
            config.builder()
                .https(move |config| {
                    config.add_root_certificate(verifier).build()
                })?;
        }

        let client = Arc::new(Client::new(config));

        Ok(Self { client })
    }

    async fn get(&self, url: &str) -> Result<String, Box<dyn std::error::Error>> {
        self.client.get(url).send().await?.text()
    }
}
