struct RuleSet {
    const char* name;
    void* config;
    void (*apply)(void*, uint8_t*, size_t);
};

struct TransformContext {
    FILE* inFile;
    FILE* outFile;
    struct RuleSet* ruleSet;
    rapidjson::Document metadata;
};

// Function to apply transformation rules
void applyRule(void* config, uint8_t* data, size_t len) {
