// Function to process binary file with transformations
int processBinaryFile(int argc, char** argv) {
    const char* inputFileName = nullptr;
    const char* outputFileName = nullptr;
    const char* rulesStr = nullptr;
    int verbosityLevel = 0;
    const char* configFilePath = nullptr;

    static struct option long_options[] = {
        {"input", required_argument, NULL, 'i'},
        {"output", required_argument, NULL, 'o'},
        {"rules", required_argument, NULL, 'r'},
        {"verbose", no_argument, NULL, 'v'},
        {"config", required_argument, NULL, 'c'},
        {NULL, 0, NULL, 0}
    };

    int opt;
    while ((opt = getopt_long(argc, argv, "i:o:r:vhc:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'i':
                inputFileName = optarg;
                break;
            case 'o':
                outputFileName = optarg;
                break;
            case 'r':
                rulesStr = optarg;
                break;
            case 'v':
                verbosityLevel++;
                break;
            case 'c':
                configFilePath = optarg;
                break;
        }
    }

    if (!inputFileName || !outputFileName || !rulesStr || !configFilePath) {
        fprintf(stderr, "Usage: %s --input <input_file> --output <output_file> --rules <rule_string> --config <config_path>\n", argv[0]);
        return 1;
    }

    rapidjson::Document configDoc;
    loadConfig(configFilePath, configDoc);

    const char* ruleSetName = configDoc["ruleSet"].GetString();
    auto it = std::find_if(configDoc["ruleSets"].Begin(), configDoc["ruleSets"].End(),
                           [ruleSetName](const rapidjson::Value& value) { return value.GetString() == ruleSetName; });

    if (it == configDoc["ruleSets"].End()) {
        syslog(LOG_ERR, "Invalid rule set: %s", ruleSetName);
        return 1;
    }

    struct RuleSet* ruleSet = (struct RuleSet*) malloc(sizeof(struct RuleSet));
    ruleSet->name = it->GetString();
    ruleSet->config = malloc(configDoc[ruleSet->name].Size());
    memcpy(ruleSet->config, configDoc[ruleSet->name].GetRawPointer(), configDoc[ruleSet->name].Size());
    ruleSet->apply = applyRule;

    FILE* inFile = fopen(inputFileName, "rb");
    if (!inFile) {
        perror("Error opening input file");
        return 1;
    }

    FILE* outFile = fopen(outputFileName, "wb");
    if (!outFile) {
        perror("Error opening output file");
        fclose(inFile);
        return 1;
    }

    struct TransformContext ctx = { inFile, outFile, ruleSet, rapidjson::Document() };

    // Batch processing for large files (use pthreads or other concurrency techniques)
    pthread_t threads[4];
    size_t bufferSize = 1 << 16; // 64KB buffer
    uint8_t* buffer = (uint8_t*) malloc(bufferSize);
    ssize_t bytesRead;

    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, processBinaryBuffer, &ctx);
    }

    while ((bytesRead = fread(buffer, 1, bufferSize, inFile)) > 0) {
        for (int i = 0; i < 4; ++i) {
            pthread_join(threads[i], NULL);
        }

        for (int i = 0; i < 4; ++i) {
            pthread_create(&threads[i], NULL, processBinaryBuffer, &ctx);
        }

        if (feof(inFile)) break;
    }

    fclose(inFile);
    free(buffer);

    // Save metadata and write output file header
    ctx.metadata["version"] = "1.0";
    rapidjson::StringBuffer sb;
    rapidjson::Writer<rapidjson::StringBuffer> writer(sb);
    configDoc.Accept(writer);
    ctx.metadata["config"] = sb.GetString();
    rapidjson::FileWritingStream outStream(outFile, rapidjson::UTF8<true>, true);
    ctx.metadata.Accept(outStream);

    fclose(outFile);

    free(ruleSet->config);
    free(ruleSet);

    return 0;
}

void* processBinaryBuffer(void* arg) {
    struct TransformContext* ctx = static_cast<struct TransformContext*>(arg);

    while ((ctx->inFile && ctx->ruleSet && !feof(ctx->inFile)) {
        ssize_t bytesRead = fread(ctx->buffer, 1, sizeof(ctx->buffer), ctx->inFile);
        if (bytesRead > 0) {
            (ctx->ruleSet->apply)(ctx->ruleSet->config, ctx->buffer, bytesRead);
            fwrite(ctx->buffer, 1, bytesRead, ctx->outFile);
        }
    }

    return nullptr;
}
```

