#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define MAX_INPUT 100000 // Maximum input size for efficient memory usage

typedef struct {
    float num;
    int is_valid;
} InputData;

InputData* read_and_validate_input(FILE *stream, size_t *count) {
    InputData *data = malloc(MAX_INPUT * sizeof(InputData));
    if (!data) {
        perror("Memory allocation failed");
        return NULL;
    }

    float number;
    size_t input_index = 0, valid_count = 0;
    while (fscanf(stream, "%f", &number) == 1) {
        if (input_index >= MAX_INPUT || number < -1e8 || number > 1e8) {
            break;
        }

        data[input_index].num = number;
        data[input_index].is_valid = 1;
        input_index++;
        valid_count++;
    }

    *count = valid_count;
    realloc(data, valid_count * sizeof(InputData));
    return data;
}

float compute_average(const InputData *input_data, size_t count) {
    float sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        if (input_data[i].is_valid == 1) {
            sum += input_data[i].num;
        }
    }

    return sum / count;
}

void print_average(const char *message, const float average) {
    printf("%s: %.16f\n", message, average);
}

int main() {
    FILE *file = fopen("numbers.txt", "r");
    if (!file) {
        perror("Unable to open file");
        return 1;
    }

    InputData *input_data = read_and_validate_input(file, NULL);
    if (!input_data) {
        return 1;
    }

    size_t count;
    float average = compute_average(input_data, count);
    print_average("Average:", average);

    free(input_data);
    fclose(file);

    return 0;
}
```

