import java.text.SimpleDateFormat;
import java.util.Comparator;
import java.util.Date;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.Map;
import java.util.Queue;
import java.util.concurrent.ConcurrentSkipListSet;
import org.apache.commons.lang3.StringUtils;

public class TaskProcessor {
    private static final SimpleDateFormat DATE_FORMAT = new SimpleDateFormat("MM/dd/yyyy");
    private Map<String, Task> taskMap;
    private ExternalDataProvider externalDataProvider;

    public TaskProcessor(ExternalDataProvider externalDataProvider) {
        this.taskMap = new ConcurrentSkipListSet<>();
        this.externalDataProvider = externalDataProvider;
    }

    public void addTask(String description, String dueDate, int priority, double importanceScore) {
        Task task = new Task(description, DATE_FORMAT.parse(dueDate), priority, importanceScore);
        if (isValidTask(task)) {
            taskMap.add(task.getId(), task);
        }
    }

    public void processTasks() {
        Queue<Task> sortedTasks = new LinkedList<>(taskMap.values());
        sortedTasks.sort(Comparator.comparingDouble(t -> t.getImportanceScore())
                .thenComparing(t -> t.getDueDate())
                .thenComparingInt(t -> t.getPriority()));

        while (!sortedTasks.isEmpty()) {
            Task currentTask = sortedTasks.poll();
            processSingleTask(currentTask);
        }
    }

    private void processSingleTask(Task task) {
        // Perform task processing logic here
    }

    private boolean isValidTask(Task task) {
        return !StringUtils.isEmpty(task.getDescription()) && task.getDueDate() != null
                && task.getPriority() >= 0 && task.getImportanceScore() > 0;
    }

    public static class Task {
        private String id;
        private Date dueDate;
        private int priority;
        private double importanceScore;
        private String description;

        public Task(String description, Date dueDate, int priority, double importanceScore) {
            this.description = description;
            this.dueDate = dueDate;
            this.priority = priority;
            this.importanceScore = importanceScore;
        }

        // Getters and setters for id, dueDate, priority, importanceScore, and description
    }
}

interface ExternalDataProvider {
    double getImportanceScore(String taskId);
}
