#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>
#include <fcntl.h>
#include <sys/stat.h>

#define MAX_CMDS 1024
#define TIMEOUT_DEFAULT 60
#define LOG_FILE "command_log.txt"

struct cmd {
    char *cmd;
    char **args;
    int timeout;
    pid_t pid;
    long start_time;
    int status;
};

sem_t log_mutex;
int log_fd = -1;

void log_command(struct cmd *cmd) {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);

    sem_wait(&log_mutex);
    if (log_fd != -1) {
        char timestr[32];
        strftime(timestr, sizeof(timestr), "%Y-%m-%d %H:%M:%S", localtime(&now.tv_sec));
        dprintf(log_fd, "[%s] | %ld | %d\n", timestr, cmd->start_time, cmd->status);
    }
    sem_post(&log_mutex);
}

void sigchld_handler(int signum) {
    while (waitpid(-1, NULL, WNOHANG) > 0);
}

void run_commands(struct cmd commands[], int n) {
    signal(SIGCHLD, sigchld_handler);

    if ((log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)) == -1) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    sem_init(&log_mutex, 0, 1);

    pid_t parent = getpid();
    struct cmd *running_cmds[MAX_CMDS];

    for (int i = 0; i < n; ++i) {
        struct cmd *cmd = &commands[i];
        if (!cmd->timeout || cmd->timeout > TIMEOUT_DEFAULT)
            cmd->timeout = TIMEOUT_DEFAULT;

        cmd->pid = fork();
        if (cmd->pid == 0) {
            // Child process
            setsid();
            dup2(log_fd, STDOUT_FILENO);
            dup2(log_fd, STDERR_FILENO);

            close(log_fd);

            char *argv[MAX_CMDS];
            int argc = 0;
            argv[argc++] = cmd->cmd;
            while (cmd->args && cmd->args[argc]) {
                argv[argc++] = cmd->args[argc];
            }
            argv[argc] = NULL;

            execvp(argv[0], argv);
            perror("Failed to execute command");
            exit(EXIT_FAILURE);
        } else if (cmd->pid > 0) {
            // Parent process
            running_cmds[i] = cmd;
        }
    }

    int completed_count = 0;
    struct timespec sleep_time = { .tv_sec = TIMEOUT_DEFAULT, .tv_nsec = 0 };

    while (completed_count < n) {
        for (int i = 0; i < MAX_CMDS; ++i) {
            if (!running_cmds[i]) continue;

            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            long elapsed = now.tv_sec - running_cmds[i]->start_time / TIMEOUT_DEFAULT * TIMEOUT_DEFAULT + now.tv_nsec / 1e9 * TIMEOUT_DEFAULT;
            if (elapsed >= running_cmds[i]->timeout) {
                kill(running_cmds[i]->pid, SIGTERM);
                running_cmds[i]->status = -143; // Custom exit code for timeout
            }
        }

        for (int i = 0; i < MAX_CMDS; ++i) {
            if (!running_cmds[i]) continue;

            int status;
            if (waitpid(running_cmds[i]->pid, &status, WNOHANG) > 0) {
                running_cmds[i] = NULL;
                ++completed_count;
                log_command(running_cmds[i]);
            }
        }

        nanosleep(&sleep_time, NULL);
    }

    sem_destroy(&log_mutex);
}
```

