    size_t len = strlen(input_path);
    if (len > 4096) {
        input_path[4095] = '\0';
    }

    // 2. Extract directory path and file name
    char* last_slash = strrchr(input_path, '/');
    if (!last_slash || (last_slash - input_path <= 1)) {
        last_slash = input_path;
    } else {
        last_slash++;
    }
    size_t file_name_len = strlen(last_slash);

    // Ensure the file name does not exceed 255 characters
    if (file_name_len > 255) {
        char* truncated_name = malloc(sizeof(char) * 256);
        strncpy(truncated_name, last_slash, 255);
        truncated_name[255] = '\0';
        free(last_slash);
        last_slash = truncated_name;
    }

    // Extract the directory path
    char* dir_path = malloc((len - file_name_len + 1) * sizeof(char));
    strncpy(dir_path, input_path, len - file_name_len);
    dir_path[len - file_name_len] = '\0';

    // Validate and create the directory if necessary
    struct stat st;
    if (stat(dir_path, &st) != 0 || !S_ISDIR(st.st_mode)) {
        mkdir(dir_path, 0755);
        if (errno != EEXIST) {
            fprintf(stderr, "Error creating directory: %s\n", strerror(errno));
            return NULL;
        }
    }

    // Replace special characters in the file name
    char* replacement_char = "_";
    for (size_t i = 0; last_slash[i]; ++i) {
        if (strchr("><:\""/|?*", last_slash[i])) {
            last_slash[i] = replacement_char[0];
