        size_t new_len = strlen(last_slash) + strlen(timestamp_str);
        char* new_name = malloc((new_len + 1) * sizeof(char));
        strncpy(new_name, last_slash, strlen(last_slash));
        strcat(new_name, timestamp_str);
        free(last_slash);
        last_slot = new_name;
    }

    // Determine the parent directory and handle symbolic links appropriately
    char* parent_path = getcwd(NULL, 4096);
    DIR *dir = opendir(parent_path);
    if (dir) {
