#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

static pthread_mutex_t mem_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t total_allocated = 0;
static size_t limit;
static size_t num_records;
static unsigned long seed;

Record* allocate_records(size_t n) {
    if (n > limit - total_allocated) {
        fprintf(stderr, "Insufficient memory\n");
        return NULL;
    }

    Record *records = malloc(sizeof(Record) * n);
    if (!records) {
        perror("malloc failed");
        return NULL;
    }

    pthread_mutex_lock(&mem_lock);
    total_allocated += n;
    pthread_mutex_unlock(&mem_lock);

    srand(seed);
    for (size_t i = 0; i < n; ++i) {
        records[i].value = rand();
    }

    return records;
}

void deallocate_records(Record *records, size_t n) {
    if (!records) return;

    pthread_mutex_lock(&mem_lock);
    total_allocated -= n;
    pthread_mutex_unlock(&mem_lock);

    free(records);
}

void log_memory_usage() {
    printf("Total allocated: %zu\n", total_allocated);
}

void set_limit(size_t new_limit) {
    limit = new_limit;
}

void set_seed(unsigned long new_seed) {
    seed = new_seed;
}

void run_threads(int num_threads) {
    pthread_t threads[num_threads];
    Record *records;
    size_t record_count;

    records = allocate_records(num_records);
    if (!records) {
        perror("allocate_records failed");
        exit(1);
    }

    record_count = num_records / num_threads;

    for (int i = 0; i < num_threads; ++i) {
        int ret = pthread_create(&threads[i], NULL, thread_func, &records[(i * record_count)]);
        if (ret != 0) {
            perror("pthread_create failed");
            exit(1);
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    deallocate_records(records, record_count * num_threads);
}

void* thread_func(void* arg) {
    Record *record = (Record*)arg;

    // Perform operations on the given record here
    printf("Thread: %p - Value: %d\n", record, record->value);

    return NULL;
}
```

