// Global variables for thread safety
NFAPI_RX_FRAME_INFO_T *frames;
size_t num_frames = 0;
double heap_usage = 0.0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond_full = PTHREAD_COND_INITIALIZER;
pthread_cond_t cond_empty = PTHREAD_COND_INITIALIZER;

void dynamic_array_init() {
    // Allocate memory for NUM_FRAMES elements and map it into the process's address space
    void *mapped_address = mmap(NULL, sizeof(NFAPI_RX_FRAME_INFO_T) * NUM_FRAMES, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mapped_address == MAP_FAILED) {
        // Handle error here
    }
    frames = static_cast<NFAPI_RX_FRAME_INFO_T*>(mapped_address);
}

void push_frame(const NFAPI_RX_FRAME_INFO_T *frame) {
    pthread_mutex_lock(&mutex);

    // If the array is full, wait until a space becomes available
    while (num_frames == NUM_FRAMES && heap_usage < MAX_HEAP) {
        pthread_cond_wait(&cond_full, &mutex);
    }

    if (heap_usage + sizeof(NFAPI_RX_FRAME_INFO_T) > 0.8 * get_available_heap()) {
        // Trigger an alert or resize the array here
    }

    frames[num_frames] = *frame;
    num_frames++;
    heap_usage += sizeof(NFAPI_RX_FRAME_INFO_T);

    pthread_mutex_unlock(&mutex);
    pthread_cond_signal(&cond_empty); // Wake up a consumer thread if available
}

void pop_frame(NFAPI_RX_FRAME_INFO_T *dest) {
    pthread_mutex_lock(&mutex);

    // If the array is empty, wait until an element becomes available
    while (num_frames == 0) {
        pthread_cond_wait(&cond_empty, &mutex);
    }

    *dest = frames[--num_frames];
    heap_usage -= sizeof(NFAPI_RX_FRAME_INFO_T);

    pthread_mutex_unlock(&mutex);
    pthread_cond_signal(&cond_full); // Wake up a producer thread if available
}

// Implement functions for logging frame information and signal quality metrics here
