using System;
using System.Xml.Linq;
using System.Xml.XPath;

public static XElement GetFirstMatchingElement(XmlDocument doc, string xpath) {
    if (doc == null || string.IsNullOrEmpty(xpath)) throw new ArgumentException("Invalid input.");

    XNamespace ns = doc.DocumentElement.Name.NamespaceName != "http://www.w3.org/2000/xmlns/" ? doc.DocumentElement.Name.Namespace + ":" : string.Empty;

    var nodes = doc.XPathSelectElements(xpath, ns);

    if (nodes.Count() > 1) throw new Exception("Multiple elements found.");

    return nodes.FirstOrDefault();
}
