void init_ue_context(LTE_UE_CONTEXT** ue, int cell_identity, enum frequency_band band, size_t num_carriers) {
    *ue = static_cast<LTE_UE_CONTEXT*>(malloc(sizeof(LTE_UE_CONTEXT)));
    if (!*ue) {
        fprintf(stderr, "Failed to allocate memory for UE context\n");
        exit(1);
    }

    memset(*ue, 0, sizeof(LTE_UE_CONTEXT));

    (*ue)->cell_identity = cell_identity;
    (*ue)->band = band;

    pthread_mutex_init(&(*ue)->mutex, nullptr);

    for (size_t i = 0; i < num_carriers; ++i) {
        (*ue)->measurements[i] = static_cast<MEASUREMENT_RESULT*>(malloc(sizeof(MEASUREMENT_RESULT)));
        if (!(*ue)->measurements[i]) {
            fprintf(stderr, "Failed to allocate memory for measurement result\n");
            exit(1);
        }
    }

    sem_init(&logging_semaphore, 0, 1);
}

void log_initialization(LTE_UE_CONTEXT* ue) {
    time_t current_time;
    struct tm* time_struct;

    time(&current_time);
    time_struct = localtime(&current_time);

    sem_wait(&logging_semaphore);

    printf("[%d-%02d-%02d %02d:%02d:%02d] UE initialized: cell_id=%d, band=%d\n",
           time_struct->tm_year + 1900, time_struct->tm_mon + 1, time_struct->tm_mday,
           time_struct->tm_hour, time_struct->tm_min, time_struct->tm_sec,
           ue->cell_identity, static_cast<int>(ue->band));

