typedef struct Record {
    int value;
} Record;

#define MAX_RECORDS 10000
#define MIN_KEY 1
#define MAX_KEY UINT_MAX / 2 // Ensure key range does not exceed INT_MAX

int load_state(const char *filename, size_t *offsets, size_t *keys, Record **records, size_t *num_records) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file");
        return 1; // File error code
    }

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (file_size < sizeof(*offsets) * MAX_RECORDS + sizeof(*keys) || !(offsets && keys && records)) {
        perror("Insufficient memory or invalid pointers");
        fclose(file);
        return 2; // Insufficient memory or invalid pointers error code
    }

    if (fread(offsets, sizeof(*offsets), MAX_RECORDS, file) != MAX_RECORDS ||
        fread(keys, sizeof(*keys), MAX_RECORDS, file) != MAX_RECORDS) {
        perror("Error reading data from file");
        free(offsets);
        free(keys);
        fclose(file);
        return 3; // Error reading data error code
    }

    *num_records = ftell(file) / (sizeof(*offsets) + sizeof(*keys));

    *records = malloc((*num_records) * sizeof(**records));
    if (!*records) {
        perror("Insufficient memory for records");
        free(offsets);
        free(keys);
        fclose(file);
        return 4; // Insufficient memory error code
    }

    fseek(file, 0, SEEK_SET);
    for (size_t i = 0; i < *num_records; ++i) {
        Record *record = &(*records)[i];
        if (fread(record, sizeof(*record), 1, file) != 1 || record->value > INT_MAX / 2 || record->value < INT_MIN) {
            perror("Corrupted data or invalid integer value");
            free(*records);
            free(offsets);
            free(keys);
            fclose(file);
            return 5; // Corrupted data or invalid integer value error code
        }
    }

    fclose(file);
    return 0; // Successful load
}
