#include <openssl/sha.h>
#include <openssl/aes.h>
#include <openssl/rand.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4]; // CRCFLAG derived from hash of tag contents
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* initializeCipherWithCRC(const char *password, int N, bool useSecureRandom) {
    const int keyLength = 32;
    const int ivLength = 16;
    unsigned char key[keyLength];
    unsigned char iv[ivLength];
    EVP_MD_CTX sha256;
    AES_KEY aesContext;
    unsigned char *hashedPassword;
    size_t hashedPasswordLen;
    NFAPI_CRC_INDICATION_PDU_T *crcIndications = NULL;
    int i, j;
    size_t memoryNeeded;

    // Initialize OpenSSL context for SHA-256 hashing
    EVP_SHA256_init(&sha256);
    hashedPasswordLen = strlen(password);
    hashedPassword = malloc(keyLength);

    // Hash the password and derive key from hash, using secure random for salt if necessary
    if (useSecureRandom) {
        unsigned char salt[8];
        RAND_bytes(salt, 8);
        EVP_DigestUpdate(&sha256, salt, 8);
        EVP_DigestUpdate(&sha256, password, hashedPasswordLen);
    } else {
        EVP_DigestUpdate(&sha256, password, hashedPasswordLen);
    }
    EVP_DigestFinal_ex(&sha256, hashedPassword, &hashedPasswordLen);

    // Generate key and IV from hashed password using AES-256-CBC context
    memset(key, 0, keyLength);
    memcpy(key, hashedPassword, keyLength);
    AES_set_encrypt_key(key, keyLength * 8, &aesContext);
    AES_cbc_encrypt((const unsigned char *)IV_KEYWORD, iv, ivLength, &aesContext, iv, AES_ENCRYPT);

    // Calculate memory requirements for CRC indication structures and allocate them dynamically
    memoryNeeded = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    crcIndications = malloc(memoryNeeded);
    if (!crcIndications) {
        free(hashedPassword);
        return NULL;
    }

    // Generate and populate CRC indication structures efficiently, handling large values of N
    for (i = 0; i < N; ++i) {
        uint32_t tag = (i << 16) | ((uint32_t)(rand() & 0xFFFF));
        crcIndications[i].RX_UE_INFORMATION_TAG = tag;
        crcIndications[i].RNTI = i % 256;

        // Hash the tag and RNTI contents to derive CRCFLAG for each structure
        uint8_t tagData[sizeof(NFAPI_CRC_INDICATION_PDU_T)];
        memcpy(tagData, &crcIndications[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        SHA256((const unsigned char *)tagData, sizeof(NFAPI_CRC_INDICATION_PDU_T), crcIndications[i].CRC_INDICATION_REL8_TAG);
    }

    // Clean up OpenSSL context and return the AES cipher context
    EVP_SHA256_free(&sha256);
    free(hashedPassword);
    return crcIndications;
}
```']

