using namespace std;
using namespace __gnu_cxx;

// Custom defined pointer structure
template<typename T>
struct RecordPointer {
    T* p;
    T* next;
};

// Helper function to find the largest integer in an array
void findLargestInteger(vector<int>& numbers) {
    *numbers.rbegin() = *max_element(numbers.begin(), numbers.end());
}

// Function to process and modify records
void processAndModifyRecords(forward_list<string> &records, const string& keyWord1, const string& keyWord2) {
    // Allocate arrays
    vector<long> offsets;
    vector<int> keys;
    vector<pair<RecordPointer<int>, int>> recordsVector;

    auto it = records.begin();
    long currentOffset = 0;
    while (it != records.end()) {
        auto recordIt = recordsVector.emplace_back(make_pair(RecordPointer{&currentOffset, nullptr}, *std::stoi(it->c_str())));
        keys.push_back(*it);
        if (it->compare(keyWord1) == 0) {
            recordIt.first.next = &currentOffset;
            currentOffset++;
        }
        it++;
    }

    // Set random values for each record's int field
    uniform_int_distribution<int> distrib(1, 100);
    default_random_engine engine;
    for (auto& rec : recordsVector) {
        rec.second = distrib(engine);
        rec.first.next = (rec.first.next == nullptr) ? &currentOffset++ : rec.first.next;
    }

    // Read a list of integers from standard input and find the largest integer in the array
    vector<int> numbers;
    int input;
    while(cin >> input) {
        numbers.push_back(input);
    }
    findLargestInteger(numbers);

    // Insert keyWord2 after the first occurrence of keyWord1 or at the end of the list
    if (records.begin() != records.end() && records.begin()->compare(keyWord1) == 0) {
        auto it = next(find(records.begin(), records.end(), keyWord1));
        records.insert(it, keyWord2);
    } else {
        records.push_back(keyWord2);
    }

    // Release all allocated resources to prevent memory leaks
    offsets.clear();
    keys.clear();
    recordsVector.clear();
}
```

