DataPipeline *initializeData(int offset_count, int key_count, int record_count, int min_value, int max_value) {
    DataPipeline *pipeline = malloc(sizeof(DataPipeline));
    pipeline->offsets = calloc(offset_count, sizeof(long));
    pipeline->keys = calloc(key_count, sizeof(int));
    pipeline->records = malloc(record_count * sizeof(Record));
    pipeline->access_token[0] = 0;
    pipeline->access_token_expiration = 0;
    pthread_mutex_init(&pipeline->mutex, NULL);

