        pipeline->records[i].key = i;
        pipeline->records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Periodically refresh the access token before it expires.
    pthread_t refresh_thread;
    pthread_create(&refresh_thread, NULL, refreshToken, pipeline);

    return pipeline;
}

void fetchAccessToken(DataPipeline *pipeline, char *app_id, char *app_secret) {
    CURL *curl;
    CURLcode res;
    char token[256];

    curl = curl_easy_init();
    if (curl) {
        snprintf(token, sizeof(token), "http://oauth.example.com/token?client_id=%s&client_secret=%s", app_id, app_secret);
        curl_easy_seturl(curl, token);
        res = curl_easy_perform(curl);

        if (res == CURLE_OK) {
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &res);
            if (res == 200) {
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_DATA, pipeline->access_token);
                pipeline->access_token_expiration = time(NULL) + 3600; // Access token expires in 1 hour.
            }
        }
        curl_easy_cleanup(curl);
    }
}

void *refreshToken(void *arg) {
    DataPipeline *pipeline = arg;
    while (true) {
        pthread_mutex_lock(&pipeline->mutex);
        time_t now = time(NULL);
        if (now > pipeline->access_token_expiration) {
            fetchAccessToken(pipeline, pipeline->app_id, pipeline->app_secret);
        }
        pthread_mutex_unlock(&pipeline->mutex);
        sleep(pow(2, (now - pipeline->access_token_expiration + 3600) / 3600)); // Exponential backoff with a minimum delay of 1 hour.
    }
}
