EncryptContext* create_context(const EVP_CIPHER *cipher, const unsigned char *key, unsigned int key_len,
                                const unsigned char *iv, unsigned int iv_len) {
    EncryptContext *ctx = malloc(sizeof(EncryptContext));
    ctx->ctx = EVP_CIPHER_CTX_new();
    ctx->key = malloc(key_len);
    ctx->iv = malloc(iv_len);
    memcpy(ctx->key, key, key_len);
    memcpy(ctx->iv, iv, iv_len);

    int ret = EVP_EncryptInit_ex(ctx->ctx, cipher, NULL, key, iv);
    if (ret != 1) {
        free(ctx);
        return nullptr;
    }

    ctx->buf = malloc(AES_BLOCK_SIZE + key_len);
    return ctx;
}

int encrypt(EncryptContext *ctx, const unsigned char *plaintext, unsigned int plaintext_len,
            unsigned char **ciphertext) {
    unsigned char *out = ctx->buf;
    unsigned char *data = out + AES_BLOCK_SIZE;

    memset(data, 0, key_len);
    memcpy(out, plaintext, plaintext_len);

    int ret = EVP_EncryptUpdate(ctx->ctx, data, &plaintext_len, plaintext, plaintext_len);
    if (ret != 1) {
        return -1;
    }

    ret = EVP_EncryptFinal_ex(ctx->ctx, out + AES_BLOCK_SIZE, &plaintext_len);
    if (ret != 1) {
        return -1;
    }

    *ciphertext = malloc(plaintext_len + AES_BLOCK_SIZE);
    memcpy(*ciphertext, out, plaintext_len + AES_BLOCK_SIZE);
    return 0;
}

int decrypt(EncryptContext *ctx, const unsigned char *ciphertext, unsigned int ciphertext_len,
            unsigned char **plaintext) {
    unsigned char *out = ctx->buf;
    unsigned char *data = out + AES_BLOCK_SIZE;

    memcpy(data, ciphertext, ciphertext_len);

    int ret = EVP_DecryptUpdate(ctx->ctx, data + AES_BLOCK_SIZE, &ciphertext_len, ciphertext, ciphertext_len);
    if (ret != 1) {
        return -1;
    }

    ret = EVP_DecryptFinal_ex(ctx->ctx, out, &ciphertext_len);
    if (ret != 1) {
        return -1;
    }

    *plaintext = malloc(ciphertext_len + AES_BLOCK_SIZE);
    memcpy(*plaintext, out, ciphertext_len + AES_BLOCK_SIZE);
    return 0;
}

void destroy_context(EncryptContext **ctx) {
