    struct stat st;
    size_t len;
    char *line = NULL;
    regex_t re;
    regmatch_t match;

    regcomp(&re, "^\\s*([0-9]+)\\s+(\\d+)", REG_EXTENDED);

    if ((fd = open(filepath, O_RDONLY)) == -1) {
        perror("open");
        goto cleanup;
    }

    if (fstat(fd, &st) == -1) {
        perror("fstat");
        goto close_file;
    }

    if ((line = malloc((st.st_size + 1) * sizeof(char))) == NULL) {
        perror("malloc");
        goto close_file;
    }

    len = read(fd, line, st.st_size);
    if (len != st.st_size) {
        perror("read");
        goto cleanup_line;
    }

    line[len] = '\0';

    // Parse and load configuration data into arrays here...

cleanup_line:
    free(line);
close_file:
    close(fd);
cleanup:
    regfree(&re);
    return ret;
}
