```rust
use reqwest::{Client, ConfirmDialog, Response};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::env;
use std::sync::Mutex;
use tokio::task::spawn_blocking;
use tokio::runtime::Runtime;

#[derive(Serialize, Deserialize, Debug)]
struct Config {
    key: i32,
    offset: i64,
}

static CONFIG_MAP: Mutex<HashMap<i32, i64>> = Mutex::new(HashMap::new());

async fn load_config(url: &str) -> Result<(), reqwest::Error> {
    let client = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(10))
        .build()?;

    let resp: Response<String> = client.get(url).send().await?;

    let configs: Vec<Config> = serde_json::from_str(&resp.text()).unwrap();

    let mut config_map = CONFIG_MAP.lock().unwrap();

    for c in configs {
        *config_map.entry(c.key).or_insert(0) = c.offset;
    }

    Ok(())
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        println!("Usage: config_loader <URL>");
        return;
    }

    let url = &args[1];
    let runtime = Runtime::new().unwrap();
    runtime.block_on(async move {
        match load_config(url).await {
            Ok(_) => println!("Config loaded successfully"),
            Err(e) => eprintln!("Error loading config: {}", e),
        }
    });
}
