["```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct Record {
    int value;
    size_t key;
    size_t offset;
    struct Record *next;
} Record;

Record* create_record(int value, size_t key) {
    Record *new_record = (Record *)malloc(sizeof(Record) + (16 - sizeof(Record) % 16));
    if (!new_record) return NULL;

    memset(new_record, 0, sizeof(Record) + (16 - sizeof(Record) % 16));
    new_record->value = value;
    new_record->key = key;
    new_record->offset = (size_t)(new_record - (char*)0);
    return new_record;
}

int* create_keys(size_t size) {
    int *keys = (int *)malloc(sizeof(int) * size);
    if (!keys) return NULL;
    memset(keys, 0, sizeof(int) * size);
    return keys;
}

size_t* create_offsets(size_t size) {
    size_t *offsets = (size_t *)malloc(sizeof(size_t) * size);
    if (!offsets) return NULL;
    memset(offsets, 0, sizeof(size_t) * size);
    return offsets;
}

void delete_record(Record **head, Record *record) {
    if (*head == record) {
        *head = record->next;
        free(record);
        return;
    }

    Record *current = *head;
    while (current && current->next != record) {
        current = current->next;
    }

    if (!current || !current->next) return;

    current->next = record->next;
    free(record);
}

void delete_all_records(Record **head) {
    Record *current, *temp;
    while (*head) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

Record* create_and_initialize_memory(size_t num_records) {
    Record *head = NULL, *current = NULL;
    int *keys = create_keys(num_records);
    size_t *offsets = create_offsets(num_records);

    if (!keys || !offsets) {
        delete_all_records(&head);
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        Record *new_record = create_record(i, i);
        if (!new_record) {
            delete_all_records(&head);
            free(keys);
            free(offsets);
            return NULL;
        }

        new_record->key = keys[i];
        new_record->offset = offsets[i];

        if (!head) {
            head = current = new_record;
        } else {
            current->next = new_record;
            current = current->next;
        }
    }

    return head;
}
```
