    int *fields;
} Record;

typedef enum CipherMode {
    ECB,
    CBC,
    CFB,
    NULL_ENCRYPT
} CipherMode;

Record** create_record_storage(int num_records, int fields_per_record, int min_value, int max_value) {
    Record **records = malloc(num_records * sizeof(Record*));
    for (int i = 0; i < num_records; ++i) {
        records[i] = malloc(fields_per_record * sizeof(int));
        for (int j = 0; j < fields_per_record; ++j) {
            records[i][j] = rand() % (max_value - min_value + 1) + min_value;
        }
    }
    return records;
}

EVP_CIPHER *choose_cipher(CipherMode mode) {
    EVP_CIPHER_CTX *ctx = NULL;
    EVP_CIPHER *cipher = NULL;

    switch (mode) {
        case ECB:
            cipher = EVP_aes_128_ecb();
            break;
        case CBC:
            ctx = EVP_CIPHER_CTX_new();
            cipher = EVP_aes_128_cbc();
            break;
        case CFB:
            ctx = EVP_CIPHER_CTX_new();
            cipher = EVP_aes_128_cfb128();
            break;
        case NULL_ENCRYPT:
            break;
        default:
            fprintf(stderr, "Invalid cipher mode\n");
            exit(EXIT_FAILURE);
    }

    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
        return cipher;
    } else {
        ERR_print_errors_fp(stderr);
        return NULL;
    }
}

