use std::collections::HashMap;
use std::env;
use std::fs::{File, OpenOptions};
use std::io::{Read, Write};
use std::path::Path;
use llvm_ir::{Lexer, Parser, ModuleBuilder, ValueKind, Operation};
use serde_json::{Map, Value as JsonValue}; // For external grammar definitions

// Define a custom error type for handling parsing errors
#[derive(Debug)]
enum ParseError {
    Io(std::io::Error),
    Lexer(LexerError),
    Parser(ParserError),
    Json(serde_json::Error),
}

fn main() -> Result<(), ParseError> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} input_file", args[0]);
        return Err(ParseError::Io(std::io::Error::new(
            std::io::IOErrorKind::NotFound,
            "No input file specified",
        )));
    }

    let input_path = Path::new(&args[1]);
    let mut file = match File::open(&input_path) {
        Ok(file) => file,
        Err(error) => return Err(ParseError::Io(error)),
    };

    // Load the file content into memory
    let mut input = Vec::new();
    file.read_to_end(&mut input)?;

    // Initialize the lexer and parser with the input data
    let lexer = Lexer::new(input);
    let parser = Parser::new(lexer);

    // Perform incremental parsing by iterating over the tokens produced by the lexer
    let mut parsed_nodes: Vec<JsonValue> = Vec::new();
    for token in lexer {
        match parser.parse_next() {
            Ok(node) => {
                parsed_nodes.push(node);
                println!("Parsed node: {:#?}", node);
            }
            Err(error) => return Err(ParseError::Parser(error)),
        }
    }

    // Generate LLVM IR code from the parsed nodes
    let mut module_builder = ModuleBuilder::new();
    for node in &parsed_nodes {
        match generate_llvm_ir(&module_builder, node) {
            Ok(_) => println!("Generated LLVM IR for node: {:#?}", node),
            Err(error) => return Err(ParseError::Json(error)),
        }
    }

    // Write the generated LLVM IR code to a file
    let output_path = input_path.with_extension(".ll");
    let mut output_file = OpenOptions::new()
        .write(true)
        .create(true)
        .open(&output_path)?;
    module_builder.finalize().write_to_writer(&mut output_file)?;

    Ok(())
}

