// Thread-safe data structure for storing settings (key-value pairs)
typedef struct Setting {
    char *key;
    char *value;
    pthread_mutex_t lock;
} Setting;

// Function to create and initialize a setting with given key and value
Setting *create_setting(const char *key, const char *value) {
    Setting *new_setting = (Setting *) malloc(sizeof(Setting));
    new_setting->key = strdup(key);
    new_setting->value = strdup(value);
    pthread_mutex_init(&new_setting->lock, NULL);
    return new_setting;
}

// Function to free resources associated with a setting
void free_setting(Setting *setting) {
    free(setting->key);
    free(setting->value);
    pthread_mutex_destroy(&setting->lock);
    free(setting);
}

// Function to parse a configuration line, handling potential errors and returning an error code
int parse_config_line(char *line, Setting ***settings) {
    // TODO: Parse the line using strtok or similar function, validate key-value pairs, and add valid entries to settings.
    // Return non-zero values (error codes) if any errors occur during parsing or validation.
}

// Function to dynamically load a configuration file and return the number of entries
int load_config(const char *path, Setting ***settings) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Error opening config file");
        return 1; // File not found or other I/O error
    }

    int num_entries = 0;
    Setting **settings = NULL;

    char line[4096];
    while (fgets(line, sizeof(line), file)) {
        int err = parse_config_line(line, &settings);
        if (err != 0) {
            free_setting(*settings); // Free memory for current entry, since it's invalid or malformed
            continue;
        }

        num_entries++;
    }

    fclose(file);

    *settings = realloc(*settings, sizeof(Setting *) * num_entries);

    return 0; // Configuration file loaded successfully
}

// Documentation for the load_config function
