['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>
#include <limits.h>
#include <semaphore.h> // For handling concurrent access with semaphores
#include "log_api.h" // External logging API

typedef struct {
    int key;
    long offset;
} Record;

struct record_pool {
    Semaphore pool_mutex; // Mutex for protecting shared resources
    size_t capacity;
    size_t allocated;
    Record* records;
};

void init_record_pool(struct record_pool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->allocated = 0;
    pool->records = malloc(capacity * sizeof(Record));

    if (!pool->records) {
        log_error("Failed to allocate memory for record pool");
        exit(1);
    }

    sem_init(&pool->pool_mutex, 0, 1);
}

Record* create_record() {
    int key = rand() % RANGE; // Modify RANGE to set the desired range for keys.

    if (key < MIN_KEY || key >= MAX_KEY) {
        log_error("Generated key is out of range");
        return NULL;
    }

    long offset = rand() % OFFSET_RANGE + 1; // Modify OFFSET_RANGE to set the desired range for offsets.

    Record* record = malloc(sizeof(Record));

    if (!record) {
        log_error("Failed to allocate memory for a single record");
        return NULL;
    }

    record->key = key;
    record->offset = offset;

    return record;
}

void destroy_record(Record* record) {
    free(record);
}

Record* acquire_record(struct record_pool* pool) {
    sem_wait(&pool->pool_mutex); // Lock the mutex before modifying shared state.

    if (pool->allocated < pool->capacity) {
        Record* record = &(pool->records[pool->allocated]);
        pool->allocated++;
        sem_post(&pool->pool_mutex); // Unlock the mutex after modifying shared state.
        return record;
    }

    sem_post(&pool->pool_mutex); // Unlock the mutex even when unable to acquire a record, allowing other threads to proceed.

    return NULL; // No free records available.
}

void release_record(struct record_pool* pool, Record* record) {
    sem_wait(&pool->pool_mutex); // Lock the mutex before modifying shared state.

    if (record && pool->allocated > 0) {
        pool->records[--pool->allocated] = *record;
        sem_post(&pool->pool_mutex); // Unlock the mutex after modifying shared state.
    }

    sem_post(&pool->pool_mutex); // Unlock the mutex even when unable to release a record, allowing other threads to proceed.
}
```

This code provides a simple implementation for creating a thread-safe record pool using semaphores to manage concurrent access. The `create_record()` function generates random records within specified ranges, and the `acquire_record()` and `release_record()` functions are used to allocate and deallocate records from the pool.

The implementation avoids unnecessary allocations and deallocations by reusing records when they are released, minimizing memory usage. The external logging API is called in case of memory allocation failures, out-of-range values, or other errors. The design allows for graceful handling of service downtimes and potential concurrent access from multiple threads, ensuring the application's performance and stability.']

