using boost::asio::ip::tcp;

struct Request {
    std::string apiUrl;
    int timeout = 5000ms; // milliseconds
};

class ApiClient {
public:
    ApiClient(const Request& req) : req_(req), cache_(), latencyStats_() {}

    void makeRequest(std::function<void(const std::string& response)> callback) {
        auto cacheIt = cache_.find(req_.apiUrl);
        if (cacheIt != cache_.end()) {
            callback(cacheIt->second);
            return;
        }

        curl_global_init(CURL_GLOBAL_DEFAULT);
        CURL* curl = curl_easy_init();

        if (!curl) {
            std::cerr << "Error initializing cURL" << std::endl;
            return;
        }

        curl_easy_setopt(curl, CURLOPT_URL, req_.apiUrl.c_str());
        curl_easy_setopt(curl, CURLOPT_TIMEOUT_MS, req_.timeout);

        std::unique_ptr<std::chrono::steady_clock::time_point> startTime;
        std::unique_ptr<CURLcode> resCode = nullptr;

        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](void* data, size_t size, size_t nmemb, void*) {
            auto& buffer = *static_cast<std::string*>(data);
            buffer.append(static_cast<char*>(const_cast<char*>(curl_easy_get_write_data(curl)), size * nmemb);
            return size * nmemb;
        });
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response_);

        startTime.reset(std::chrono::steady_clock::now());
        resCode.reset(curl_easy_perform(curl));

        if (resCode && *resCode != CURLE_OK) {
            std::cerr << "Error performing API request: " << curl_easy_strerror(*resCode) << std::endl;
            cache_[req_.apiUrl] = ""; // store the failure to cache
            return;
        }

        if (startTime && resCode) {
            auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - *startTime).count();
            latencyStats_.push_back(elapsed);
        }

        response_ = curl_easy_get_write_data(curl);
        cache_[req_.apiUrl] = std::move(response_);
        curl_easy_cleanup(curl);

        callback(std::move(response_));
    }

private:
    const Request& req_;
    boost::circular_buffer<int> latencyStats_; // buffer size is determined by the number of concurrent requests
    std::string response_;
    std::unordered_map<std::string, std::string> cache_;
};

void logRequestMetrics(const ApiClient& client) {
    auto latencyIt = client.latencyStats_.begin();
    auto avgLatency = std::accumulate(client.latencyStats_.cbegin(), client.latencyStats_.cend(), 0) / client.latencyStats_.size();
    std::cout << "Requests: Success=" << client.cache_.size() - client.latencyStats_.size()
              << ", Failed=" << client.latencyStats_.size()
              << ", Average latency(ms): " << avgLatency << std::endl;
}

