#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <semaphore.h>
#include <json-c/json.h>

typedef struct Bundle {
    char *name;
    void *data;
    size_t size;
    struct Bundle *next;
} Bundle;

typedef struct Cache {
    unsigned int max_size;
    unsigned int count;
    Bundle **cache;
    sem_t lock;
    pthread_mutex_t eviction_lock;
} Cache;

Cache *create_cache(unsigned int max_size) {
    Cache *cache = malloc(sizeof(Cache));
    cache->max_size = max_size;
    cache->count = 0;
    cache->cache = calloc(max_size, sizeof(Bundle*));
    sem_init(&cache->lock, 0, 1);
    pthread_mutex_init(&cache->eviction_lock, NULL);
    return cache;
}

void insert_bundle_into_cache(Cache *cache, Bundle *bundle) {
    unsigned int index = hash(bundle->name) % cache->max_size;
    sem_wait(&cache->lock);
    while (cache->cache[index] != NULL) {
        index = (index + 1) % cache->max_size;
    }
    cache->cache[index] = bundle;
    cache->count++;
    sem_post(&cache->lock);
}

Bundle *get_bundle_from_cache(Cache *cache, const char *name) {
    unsigned int index = hash(name) % cache->max_size;
    Bundle *bundle = NULL;
    sem_wait(&cache->lock);
    for (; cache->cache[index] != NULL; index = (index + 1) % cache->max_size) {
        if (strcmp(cache->cache[index]->name, name) == 0) {
            bundle = cache->cache[index];
            break;
        }
    }
    sem_post(&cache->lock);
    return bundle;
}

void remove_bundle_from_cache(Cache *cache, Bundle *bundle) {
    unsigned int index = hash(bundle->name) % cache->max_size;
    pthread_mutex_lock(&cache->eviction_lock);
    if (cache->cache[index] == bundle) {
        cache->cache[index] = bundle->next;
        free(bundle->name);
        free(bundle->data);
        free(bundle);
        cache->count--;
    }
    pthread_mutex_unlock(&cache->eviction_lock);
}

unsigned int load_resources(const char *dir, Cache *cache, FILE **config) {
    DIR *d = opendir(dir);
    struct dirent *entry;
    unsigned int total = 0;
    pthread_t threads[NUM_THREADS];
    LoaderThreadArgs args[NUM_THREADS];

    sem_t lock;
    sem_init(&lock, 0, 1);

    while ((entry = readdir(d)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;
        char path[PATH_MAX];
        snprintf(path, sizeof(path), "%s/%s", dir, entry->d_name);
        struct stat st;
        if (stat(path, &st) != 0 || S_ISDIR(st.st_mode))
            continue;
        // Process the file in a separate thread
        args[total].name = strdup(entry->d_name);
        args[total].path = path;
        args[total].cache = cache;
        total++;
    }
    closedir(d);

    for (unsigned int i = 0; i < total; ++i) {
        pthread_create(&threads[i], NULL, loader_thread, &args[i]);
    }

    for (unsigned int i = 0; i < total; ++i) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&lock);
    return total;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        printf("Usage: %s <directory> <cache_size>\n", argv[0]);
        exit(1);
    }
    const char *dir = argv[1];
    unsigned int cache_size = atoi(argv[2]);

    FILE *config = fopen("config.json", "r");
    if (config == NULL) {
        perror("Failed to open config file");
        exit(1);
    }

    JsonObject *obj = json_object_from_file(config);
    const char *range_str = json_object_get_string(obj, "random_value_range");
    unsigned int range = atoi(range_str);

    Cache *cache = create_cache(cache_size);
    unsigned int total = load_resources(dir, cache, &config);

    fclose(config);

    // Implement persistence, logging, error handling, etc.
}
