#include "LoggingLibrary.h" // Third-party logging library

typedef struct NFAPI_RX_FRAME_INFO_T {
    uint32_t tag;
    float signalQuality;
} FrameInfo;

class FrameQueue {
public:
    FrameQueue(size_t maxSize) : _maxSize(maxSize), _data(_maxSize), _head(_headMutex), _tail(_tailMutex) {}

    bool enqueue(const FrameInfo& frame) {
        std::unique_lock<std::mutex> headLock(_head);
        if (_head == _tail && _data.size() == _maxSize) return false; // Queue is full

        _data[_tail] = frame;
        _tail = (++_tail) % _maxSize;
        headLock.unlock();

        std::unique_lock<std::mutex> tailLock(_tail);
        _head = (++_head) % _maxSize;
        tailLock.unlock();

        return true;
    }

    FrameInfo dequeue() {
        std::unique_lock<std::mutex> headLock(_head);
        if (_head == _tail && _data.size() == 0) throw std::runtime_error("Queue is empty"); // Queue is empty

        auto result = _data[_head];
        _head = (++_head) % _maxSize;
        headLock.unlock();

        std::unique_lock<std::mutex> tailLock(_tail);
        if (_head == _tail) _data.clear(); // Queue is now empty
        else _tail = (++_tail) % _maxSize;
        tailLock.unlock();

        return result;
    }

    size_t getMemoryUsage() const {
        return static_cast<size_t>(sizeof(FrameInfo) * _data.size());
    }

private:
    std::array<FrameInfo, MAX_SIZE> _data;
    std::atomic<size_t> _head, _tail; // Atomic to ensure thread-safe access
    mutex _headMutex, _tailMutex; // Mutexes for locking while updating head and tail
    size_t _maxSize;
};

class FrameManager {
public:
    FrameManager(size_t maxSize) : _queue(maxSize), _stats(_numFrames, 0.f), _framePriorities(_numLevels, 0) {}

    void processFrame(const FrameInfo& frame) {
        if (enqueue(frame)) {
            ++_numFrames;
            updateSignalStats(frame.signalQuality);
            adjustFramePriority(frame.signalQuality);
        }
    }

    std::shared_ptr<std::vector<FrameInfo>> exportData() {
        std::unique_lock<std::mutex> lock(_queue._headMutex); // Lock before accessing the queue to get consistent data
        auto data = _queue.getData();
        _queue.clear();
        return data;
    }

    float getSignalMean() const { return _stats[0]; }
    float getSignalMedian() const { return _stats[_numFrames / 2]; }
    float getSignalPercentile(size_t percent) const {
        if (percent >= _numFrames || percent < 1) throw std::invalid_argument("Percentage must be between 1 and the number of frames");
        return _stats[_numFrames * percent / 100.f];
    }

    size_t getNumFrames() const { return _numFrames; }
    size_t getMemoryUsage() const { return _queue.getMemoryUsage(); }

private:
    FrameQueue _queue;
    std::vector<float> _stats; // Signal quality statistics (e.g., mean, median, percentiles)
    std::vector<size_t> _framePriorities; // Frame priorities based on signal quality
    size_t _numFrames;

    void updateSignalStats(float signalQuality) {
        if (_numFrames < _numFrames.load()) {
            ++_stats[_numFrames % _stats.size());
        } else {
            for (size_t i = 0; i < _stats.size(); ++i) {
                _stats[i] += static_cast<float>(signalQuality - _stats[_numFrames % _stats.size()]) / _numFrames;
            }
        }
    }

    void adjustFramePriority(float signalQuality) {
        for (size_t i = 1; i < _framePriorities.size(); ++i) {
            _framePriorities[i] = _framePriorities[i - 1];
        }
        _framePriorities[0] += signalQuality;
    }
};

void logFrameData(const FrameInfo& frame, const FrameManager& manager) {
    // Use the logging library to export frame data and statistics in a suitable format.
}
