char *process_filename(const char *input) {
    size_t base_name_len = 256;
    size_t extension_len = 4;
    size_t max_length = 256 + extension_len;
    size_t i, j;
    size_t base_name_pos = 0;
    size_t extension_pos = 0;
    char *modified_filename = malloc(max_length);
    if (!modified_filename) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    for (i = 0; i < base_name_len && input[i] != '\0'; ++i) {
        if (isspace(input[i])) {
            input[i] = '_';
        }
        modified_filename[base_name_pos++] = input[i];
    }
    modified_filename[base_name_pos] = '\0';
    base_name_len = base_name_pos;

    for (j = 0; j < base_name_len && isalnum(modified_filename[base_name_pos - 1 - j]) || modified_filename[base_name_pos - 1 - j] == '_' || modified_filename[base_name_pos - 1 - j] == '-'; ++j) {}
    if (j > 255 || base_name_len + extension_len - j > 256) {
        free(modified_filename);
        return NULL;
    }

    for (i = 0; i < j; ++i) {
        if (!isalnum(modified_filename[i]) && modified_filename[i] != '_' && modified_filename[i] != '-') {
            char temp = modified_filename[base_name_pos - 1];
            memmove(&modified_filename[i], &modified_filename[i + 1], base_name_len - (i + 1));
            modified_filename[base_name_pos - 1 - j] = temp;
        }
    }

    char extension[5];
    for (i = j, k = 0; i < base_name_len && k < 3; ++i) {
        if (isdigit(modified_filename[i])) {
            extension[k++] = modified_filename[i];
        } else if (!k) {
            extension[k++] = modified_filename[i];
        }
    }
    extension[k] = '\0';

    if (strcasecmp(&modified_filename[j], "etc") == 0 || strcasecmp(&modified_filename[j], "bin") == 0 || strcasecmp(&modified_filename[j], "tmp") == 0) {
        strcpy(&extension[2], "log");
    } else {
        strncpy(extension, &modified_filename[j], 3);
    }
    if (strlen(extension) > 4 || strlen(&modified_filename[0]) + strlen(extension) > max_length) {
        free(modified_filename);
        return NULL;
    }

    strcpy(&modified_filename[base_name_pos], extension);
    modified_filename = realloc(modified_filename, strlen(modified_filename) + 1);
    if (!modified_filename) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    return modified_filename;
}
