    for (int i = 0; i < num_instances; ++i) {
        ctx[i].cell_identity = -1;
        ctx[i].band = BAND_UNKNOWN;
        ctx[i].num_carriers = carriers_per_instance;
        ctx[i].carriers = calloc(carriers_per_instance, sizeof(struct carrier));
        if (!ctx[i].carriers) {
            perror("calloc failed");
            return NULL;
        }
        pthread_mutex_init(&ctx[i].sync_sem, NULL);
        ctx[i].cache = malloc(sizeof(void*) * carriers_per_instance);
        if (!ctx[i].cache) {
            perror("malloc failed");
            return NULL;
        }
    }

