Design a `ServiceLocator` class to manage object lifecycles and dependency resolution:

```csharp
public interface IServiceLocator
{
    T Resolve<T>();
}

public class ServiceLocator : IServiceLocator
{
    private readonly Dictionary<Type, Func<object>> _factories = new();

    public void RegisterFactory<T>(Func<T> factory) => _factories[typeof(T)] = () => factory();

    public T Resolve<T>()
    {
        if (!_factories.TryGetValue(typeof(T), out var factory))
            throw new KeyNotFoundException($"No factory registered for type '{nameof(T)}'.");

        return (T)factory();
    }
}
```

