        {
            _resourceService = resourceService;
            _logger = logger;
            _configuration = configuration;
        }

        [HttpPut]
        [Route("{id}")]
        public async Task<IActionResult> UpdateResource(string id, [FromBody] Resource resource)
        {
            // Implement rate limiting here.

            if (!ModelState.IsValid || !await _resourceService.ExistsAsync(id))
                return NotFound();

            var etag = Request.Headers["If-Match"];
            if (etag != null && await _resourceService.CheckETagAsync(id, etag))
                return BadRequest("Invalid ETag.");

            resource.Validate(); // Validate the data against a predefined schema.
            var updatedResource = await _resourceService.UpdateAsync(id, resource);
            _logger.LogInformation($"Updated resource {id} with new ETag: {updatedResource.ETag}");
            return Ok(updatedResource);
        }

        [HttpDelete]
        [Route("{id}")]
        public async Task<IActionResult> DeleteResource(string id)
        {
            if (!await _resourceService.ExistsAsync(id))
                return NotFound();

            var deletedResource = await _resourceService.DeleteAsync(id);
            _logger.LogInformation($"Deleted resource {id}");

            // Return a new resource with default values only if the deletion is successful.
            return Ok(deletedResource);
        }
    }
