#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <pthread.h>
#include <time.h>
#include <arpa/inet.h>
#include <sys/types.h>
#include <netdb.h>
#include <unistd.h>
#include <sys/mman.h>

typedef struct Theme {
    int value;
    AES_KEY key;
    unsigned char iv[AES_BLOCK_SIZE];
} Theme;

typedef struct ThemeManager {
    int capacity;
    int count;
    Theme** themes;
    pthread_mutex_t mutex;
    FILE* config_file;
    char* password;
    AES_KEY master_key;
    unsigned char master_iv[AES_BLOCK_SIZE];
} ThemeManager;

ThemeManager* create_theme_manager(int capacity, const char* password) {
    ThemeManager* manager = malloc(sizeof(ThemeManager));
    manager->capacity = capacity;
    manager->count = 0;
    manager->themes = calloc(capacity, sizeof(Theme*));
    manager->mutex = PTHREAD_MUTEX_INITIALIZER;
    manager->config_file = NULL;
    manager->password = strdup(password);
    AES_set_encrypt_key((const unsigned char*) password, 256, &manager->master_key);
    randomize(); // Implement your preferred randomization method here
    return manager;
}

int add_theme(ThemeManager* manager, int value) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->count >= manager->capacity) {
        pthread_mutex_unlock(&manager->mutex);
        return -1; // Themes limit reached
    }
    Theme* theme = malloc(sizeof(Theme));
    theme->value = value + rand() % 100; // Generate random value within range [value, value+100]
    AES_key_init(&theme->key, &manager->master_key, manager->master_iv, AES_ENCRYPT);
    randomize(); // Generate a new IV for the theme
    memcpy(theme->iv, manager->master_iv, AES_BLOCK_SIZE);
    encrypt_int(&theme->value, &theme->key, theme->iv);
    manager->themes[manager->count++] = theme;
    pthread_mutex_unlock(&manager->mutex);
    return 0; // Success
}

Theme* get_theme(ThemeManager* manager, int index) {
    if (index < 0 || index >= manager->capacity) {
        return NULL; // Invalid index
    }
    pthread_mutex_lock(&manager->mutex);
    Theme* theme = manager->themes[index];
    if (!theme) {
