        return 1;
    }

    fseek(png_file, 0, SEEK_END);
    size_t png_size = ftell(png_file);
    fseek(png_file, 0, SEEK_SET);

    void* png_data = mmap(NULL, png_size, PROT_READ, MAP_PRIVATE, fileno(png_file), 0);
    if (png_data == MAP_FAILED) {
        perror("mmap");
        fclose(png_file);
        munmap(theme, sizeof(NFAPI_CRC_INDICATION_PDU_T)*n);
        return 1;
    }

    fread(png_data, png_size, 1, png_file);
    fclose(png_file);

    memcpy(theme, png_data, png_size);
    munmap(png_data, png_size);

    *out_theme = theme;
    return 0;
}
