['1. C (establishDBConnection) using libpq:

```c
#include <libpq/libpq.h>
#include <stdio.h>
#include <stdlib.h>

PGconn *establishDBConnection(const char *host, const char *port, const char *dbname, const char *user, const char *password) {
    PGconn *conn;

    conn = PQconnectdb(host); // establish connection

    if (PQstatus(conn) == CONNECTION_BAD) {
        fprintf(stderr, "Connection failed: %s\n", PQerrorMessage(conn));
        PQfinish(conn);
        return NULL;
    }

    PGresult *res = PQexec(conn, PQmakePassword(password)); // set password

    if (PQresultStatus(res) != PGRES_COMMAND_OK) {
        fprintf(stderr, "Password setting failed: %s\n", PQerrorMessage(conn));
        PQclear(res);
        PQfinish(conn);
        return NULL;
    }

    res = PQexec(conn, PQsql("SET application_name TO 'myapp';")); // set application name

    if (PQresultStatus(res) != PGRES_COMMAND_OK) {
        fprintf(stderr, "Application name setting failed: %s\n", PQerrorMessage(conn));
        PQclear(res);
        PQfinish(conn);
        return NULL;
    }

    if (PQsetenv(conn, "database", dbname, TRUE) != 0 ||
        PQsetenv(conn, "user", user, TRUE) != 0) {
        fprintf(stderr, "Error setting env vars: %s\n", PQerrorMessage(conn));
        PQclear(res);
        PQfinish(conn);
        return NULL;
    }

    if (PQsetconnparams(conn, NULL) < 0) { // set connection parameters
        fprintf(stderr, "Error setting connection params: %s\n", PQerrorMessage(conn));
        PQclear(res);
        PQfinish(conn);
        return NULL;
    }

    if (PQping(conn) < 0) { // check connectivity
        fprintf(stderr, "Could not reach server: %s\n", PQerrorMessage(conn));
        PQclear(res);
        PQfinish(conn);
        return NULL;
    }

    return conn;
}
