['```csharp
using System;
using System.Data;
using System.Data.Common;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Diagnostics;
using DbType = System.Data.DbType;

namespace QueryExecutor
{
    public class QueryRunner
    {
        private readonly string _connectionString;
        private readonly IDbConnection _connection;

        public QueryRunner(string connectionString)
        {
            _connectionString = connectionString;
            _connection = CreateConnection();
        }

        private IDbConnection CreateConnection()
        {
            var builder = new System.Data.SqlClient.SqlConnectionStringBuilder(this._connectionString);
            if (builder.Pooling == false)
                builder.Pooling = true; // Enable connection pooling by default
            return System.Data.SqlClient.SqlConnectionFactory.CreateConnection(builder.ToString());
        }

        public IEnumerable<IDataReader> ExecuteQuery(string commandTemplate, IList<KeyValuePair<string, (DbType type, object value)>> parameters, CancellationToken cancellationToken = default)
        {
            var queryStartTime = DateTimeOffset.Now;

            using (var transaction = _connection.BeginTransaction())
            {
                IDbCommand command = CreateCommand(commandTemplate, parameters);
                command.Connection = _connection;
                command.Transaction = transaction;

                try
                {
                    command.ExecuteNonQuery();

                    using (var reader = command.ExecuteReader(CommandBehavior.SequentialAccess | CommandBehavior.CloseConnection))
                    {
                        while (reader.Read() && !cancellationToken.IsCancellationRequested)
                            yield return reader;
                    }
                }
                catch (Exception ex)
                {
                    LogQueryExecution(queryStartTime, commandTemplate, parameters, queryDuration: DateTimeOffset.Now - queryStartTime);
                    throw new QueryExecutionException($"Failed to execute query: {commandTemplate}, Params: {parameters}, Error: {ex}", ex);
                }
                finally
                {
                    transaction.Commit();
                    LogQueryExecution(queryStartTime, commandTemplate, parameters, queryDuration: DateTimeOffset.Now - queryStartTime);
                }
            }
        }

        private IDbCommand CreateCommand(string commandText, IList<KeyValuePair<string, (DbType type, object value)>> parameters)
        {
            var command = _connection.CreateCommand();
            command.CommandText = commandText;

            foreach (var parameter in parameters)
                command.Parameters.Add(parameter.Value.type, parameter.Value.value);

            return command;
        }

        private void LogQueryExecution(DateTimeOffset startTime, string commandTemplate, IEnumerable<KeyValuePair<string, (DbType type, object value)>> parameters, TimeSpan queryDuration = default)
        {
            Debug.Write($"[{startTime:yyyy-MM-dd HH:mm:ss.fff}]{Environment.NewLine}" +
                        $"Query Text: {commandTemplate}{Environment.NewLine}" +
                        $"Parameters: {string.Join(", ", parameters.Select(p => p.Key + ": " + p.Value.type.Name + "(" + p.Value.value + ")"))}{Environment.NewLine}" +
                        $"Query Duration: {queryDuration.TotalMilliseconds}ms{Environment.NewLine}{Environment.NewLine}");
        }
    }

    public class QueryExecutionException : Exception
    {
        public QueryExecutionException(string message, Exception innerException) : base(message, innerException) { }
    }
}
```
This code assumes the use of `System.Data.SqlClient` for SQL Server but can be easily adapted to other DBMS by changing the specific implementation (e.g., MySQL Connector or Oracle.ManagedDataAccess). The above implementation emphasizes performance, scalability, and reliability under high concurrency loads by utilizing connection pooling and executing queries within transactions. Additionally, logging is implemented for each query execution with relevant metadata such as query text, parameters, and execution duration. Exceptions are handled gracefully, ensuring the connection and transaction are properly disposed of after use.']

