typedef struct {
    int value;
    void* offset;
    void* key;
} Record;

Record* create_record(int value, void* offset, void* key) {
    Record* record = (Record*) malloc(sizeof(Record));
    if (!record) return NULL;

    record->value = value;
    record->offset = offset;
    record->key = key;

    return record;
}

void** initialize_array(size_t size) {
    void* memory = malloc(sizeof(void*) * size);
    if (!memory) return NULL;

    memset(memory, 0, sizeof(void*) * size);
    return memory;
}

int main() {
    srand(time(NULL));
    int array_size = 10000;
    Record** records = initialize_array(array_size);
    void* offsets = calloc(array_size, sizeof(void*));
    void* keys = calloc(array_size, sizeof(void*));

    if (!records || !offsets || !keys) {
        printf("Memory allocation failed\n");
        return 1;
    }

    for (int i = 0; i < array_size; ++i) {
        int value = rand() % 100 + 1;
        records[i] = create_record(value, &offsets[i], &keys[i]);
    }

    // Call the Java method to compute the MD5 hash of each integer's string representation.
    char command[256];
    snprintf(command, sizeof(command), "java -jar myjar.jar %d", array_size);
    system(command);

    int largest = find_largest_integer(records, offsets, keys, array_size);
    printf("Largest integer: %d\n", largest);

    for (int i = 0; i < array_size; ++i) {
        free(records[i]);
    }
    free(records);
    free(offsets);
    free(keys);

    return 0;
}

// Helper method to find and print the largest integer in the array.
int find_largest_integer(Record* records, void* offsets, void* keys, size_t size) {
    int largest = INT_MIN;
    for (size_t i = 0; i < size; ++i) {
        if (records[i]->value > largest) {
            largest = records[i]->value;
        }
    }

    return largest;
}
