} element;

size_t read_line(FILE *, char **, size_t *);
element *parse_record(char *);

void allocate_and_init_arrays(size_t *num_elements, FILE *file) {
    size_t line_len = 0;
    char *buffer = NULL;
    size_t num_doubles = 0;
    double *data_double = NULL;
    size_t num_chars = 0;
    char **data_char = NULL;
    size_t num_elems = 0;
    element **data_elem = NULL;

    while ((line_len = read_line(file, &buffer, &line_len)) > 0) {
        if (num_doubles >= num_elems) {
            num_elems *= 2;
            data_double = realloc(data_double, num_elems * sizeof(double));
            data_char = realloc(data_char, num_chars * sizeof(char*));
            data_elem = realloc(data_elem, num_elems * sizeof(element*));
        }
        if (num_chars >= num_elems) {
            num_elems *= 2;
            data_double = realloc(data_double, num_elems * sizeof(double));
            data_char = realloc(data_char, (num_elems + 1) * 256);
            data_elem = realloc(data_elem, num_elems * sizeof(element*));
        }

        data_elem[num_elems] = parse_record(buffer);
        data_double[num_elems] = atof(strtok(buffer, " \n"));
        data_char[num_chars++] = strdup(strtok(NULL, "\n"));
        num_doubles++;
    }

    *num_elements = num_doubles;
}

element *parse_record(char *line) {
    char *token;
    element *elem = malloc(sizeof(element));

    elem->id = atoi(token = strtok(line, " \t"));
    elem->value = atof(strtok(NULL, " \t"));
    elem->str = strdup(strtok(NULL, "\n"));

    return elem;
}

size_t read_line(FILE *file, char **buffer, size_t *len) {
    size_t pos = 0;
    char c;

    while ((c = fgetc(file)) != EOF && c != '\n') {
        (*buffer)[pos++] = c;
    }

    if (c == '\n') {
        (*buffer)[pos] = '\0';
        *len = pos + 1;
        return 1;
    } else {
        realloc(*buffer, ++*len);
        return 0;
    }
}
```
This code reads the input file in chunks and handles files larger than available memory by dynamically allocating memory for the arrays as needed. The parse_record function is used to parse each record into an element structure, and read_line function reads the next line from the file. The data_double, data_char, and data_elem are dynamically allocated with realloc based on the number of elements read so far.']

[' ```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct Node {
    char *str;
    int priority;
    struct list_item item;
} node;

typedef struct List {
    unsigned total_nodes;
    unsigned capacity;
    node **data;
} list;

void initList(list *list) {
    list->total_nodes = 0;
    list->capacity = 8;
    list->data = malloc(list->capacity * sizeof(node*));
}

bool isFull(const list *list) {
    return list->total_nodes == list->capacity;
}

void resizeList(list *list) {
    unsigned newCapacity = list->capacity * 2;
    node **newData = malloc(newCapacity * sizeof(node*));

    for (unsigned i = 0; i < list->total_nodes; ++i) {
        newData[i] = list->data[i];
    }

    free(list->data);
    list->data = newData;
    list->capacity = newCapacity;
}

node* createNode(const char *str, int priority) {
    node *newNode = malloc(sizeof(node));
    newNode->str = strdup(str);
    newNode->priority = priority;
    newNode->item.prev = NULL;
    newNode->item.next = NULL;
    return newNode;
}

void insertNodeAt(list *list, unsigned index, node *node) {
    if (isFull(list)) resizeList(list);

    for (unsigned i = list->total_nodes; i > index; --i) {
        list->data[i] = list->data[i - 1];
    }

    list->data[index] = node;
    ++list->total_nodes;
}

void traverseList(const list *list, void (*printNode)(node*)) {
    for (unsigned i = 0; i < list->total_nodes; ++i) {
        printNode(list->data[i]);
    }
}

void releaseMemory(list *list) {
    for (unsigned i = 0; i < list->total_nodes; ++i) {
        free(list->data[i]->str);
        free(list->data[i]);
    }
    free(list->data);
}

void printNode(node *node) {
    printf("String: %s, Priority: %d\n", node->str, node->priority);
}
```

In this code, a `List` data structure is used to manage the array of nodes. The `createNode()` function creates a new node with allocated memory for the string and doubly linked list elements. The `insertNodeAt()` function inserts a new node at a specified index within the list, handling edge cases such as inserting at the beginning or end of the list.

The `traverseList()` function prints the string and priority level of each node in an efficient manner for large lists by using a callback function `printNode()`. The `releaseMemory()` function safely releases all allocated memory when the application terminates or specific conditions are met.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>
#include <sys/mman.h> // For posix_memalign and malloc/free

typedef struct Record {
    int value;
} Record;

// Custom random number generator
unsigned int custom_rand(unsigned long seed) {
    seed = (seed * 25214903917 + 11) % 4294967296U;
    return (uint32_t)(seed >> 32);
}

// Function to allocate arrays and manage memory
void init_data(size_t* offsets, size_t* keys, size_t max_keys, Record** records, pthread_mutex_t* mutex) {
    // Allocate memory for offsets and keys
    offsets[0] = 0;
    size_t key_index = 0;
    for (size_t i = 1; i <= max_keys && offsets[i - 1] + 20000 < 20000; ++i) {
        offsets[i] = offsets[i - 1] + 1;
        keys[key_index++] = (int)(offsets[i] * 1.5f); // Minimize memory usage during initialization
    }

    // Check for unique integers in the range and adjust key_index if necessary
    while (--key_index >= 0) {
        bool unique = true;
        for (size_t i = 1; i <= key_index && keys[i] != keys[key_index]; ++i) {
            if (keys[i] == keys[key_index]) {
                unique = false;
                break;
            }
        }
        if (unique) continue;

        --key_index; // Adjust key_index to re-try the current index with a new value
    }

    // Allocate memory for records array
    size_t num_records = (size_t)(key_index * 1.5); // Max number of records based on key array size
    if (num_records > 5000) num_records = 5000; // Maximum limit on number of records
    Record* temp_records = malloc(num_records * sizeof(Record));

    // Synchronize access to the records array using a mutex
    pthread_mutex_init(mutex, NULL);

    // Set record values to unique random numbers within a specified range
    for (size_t i = 0; i < num_records; ++i) {
        uint32_t seed = custom_rand((uint32_t)time(NULL));
        unsigned int rand_value = custom_rand(seed);
        pthread_mutex_lock(mutex);
        for (size_t j = 0; j < i; ++j) {
            if (temp_records[j].value == rand_value) {
                --i; // Re-try with a new random value
                break;
            }
        }
        temp_records[i].value = rand_value;
        pthread_mutex_unlock(mutex);
    }
}

// Function to handle memory deallocation
void cleanup() {
    free(records);
    records = NULL;
    pthread_mutex_destroy(mutex);
}
```
