void *create_record(void *arg);

// Global variables
pthread_mutex_t gsl_multimap_lock;
gsl_multimap_type_int intmap;
gsl_multimap *id_map;
gsl_rng *rand;
const int min_value = 0;
const int max_value = 1000000; // Change as needed

void init_collection() {
    pthread_mutex_init(&gsl_multimap_lock, NULL);
    id_map = gsl_multimap_alloc(&intmap, max_value - min_value + 1);
    rand = gsl_rng_alloc(gsl_rng_mt19937); // Change as needed for specific RNG type
}

void destroy_collection() {
    gsl_multimap_free(id_map);
    pthread_mutex_destroy(&gsl_multimap_lock);
}

void *create_record(void *arg) {
    record_t *record = malloc(sizeof(record_t));
    int id;
    do {
        gsl_rng_set(rand, (unsigned long)pthread_self()); // Using thread ID as seed for RNG
        id = min_value + gsl_rng_uniform_int(rand) % (max_value - min_value + 1);
    } while (gsl_multimap_get(id_map, &id) != NULL);

    record->id = id;
    // Additional initialization if needed

    pthread_mutex_lock(&gsl_multimap_lock);
    gsl_multimap_set(id_map, &record->id, record);
    pthread_mutex_unlock(&gsl_multimap_lock);

    return record;
}
