};

struct List {
    size_t capacity;
    size_t count;
    node **nodes;
};

void list_init(struct List* list) {
    list->capacity = 16;
    list->count = 0;
    list->nodes = malloc(list->capacity * sizeof(node*));
}

void list_destroy(struct List* list) {
    for (size_t i = 0; i < list->capacity; ++i) {
        if (list->nodes[i]) free(list->nodes[i]->str);
        free(list->nodes[i]);
    }
    free(list->nodes);
}

void list_resize(struct List* list) {
    size_t new_capacity = list->capacity * 2;
    node **new_nodes = realloc(list->nodes, new_capacity * sizeof(node*));
    if (!new_nodes) return;

    list->nodes = new_nodes;
    list->capacity = new_capacity;
}

void list_insert(struct List* list, size_t index, const char *str, int priority) {
    if (index >= list->count) index = list->count;
    if (list->count == list->capacity) list_resize(list);

    node *new_node = malloc(sizeof(node));
    new_node->str = strdup(str);
    new_node->priority = priority;
    new_node->item.prev = NULL;
    new_node->item.next = list->nodes[index];

    if (list->nodes[index]) list->nodes[index]->item.prev = &new_node->item;
    list->nodes[index] = new_node;
    ++list->count;
}

void list_traverse(const struct List* list, void (*func)(const node*)) {
    for (size_t i = 0; i < list->capacity; ++i) {
        if (list->nodes[i]) func(list->nodes[i]);
    }
}

