    this.books = options.books || [];
    this.regexPattern = /(\b(?:[Oo]ld|[Nn]ew)\s+Testament\b|\b([A-Za-z]+)\b)/g;
  }

  process(input) {
    const startTime = performance.now();

    let normalizedInput = this._normalizeText(input);
    let matches = [];

    if (isXML(normalizedInput)) {
      // Use DOMParser for XML documents
      const parser = new DOMParser();
      const xmlDoc = parser.parseFromString(normalizedInput, "text/xml");
      matches = this._countMatchesInXml(xmlDoc);
    } else if (isHTML(normalizedInput)) {
      // Use DOMParser for HTML content
      const parser = new DOMParser();
      const doc = parser.parseFromString(normalizedInput, "text/html");
      matches = this._countMatchesInHtml(doc);
    } else {
      // Matches directly on plain text
      matches = normalizedInput.match(this.regexPattern);
    }

    const results = this._filterMatches(matches);
    const processingTime = performance.now() - startTime;

    console.log(`Processing time: ${processingTime} ms`);
    return results;
  }

  _normalizeText(text) {
    // Custom text normalization logic here (e.g. remove punctuation, normalize case sensitivity etc.)
    // ...
    return text;
  }

  _countMatchesInXml(xmlDoc) {
    let matches = [];

    for (let node of xmlDoc.childNodes) {
      if (node.nodeType === Node.ELEMENT_NODE) {
        const normalizedText = this._normalizeText(this._getTextContent(node));
        matches = [...matches, ...normalizedText.match(this.regexPattern)];

        for (let child of node.childNodes) {
          if (child.nodeType === Node.ELEMENT_NODE) {
            matches = [...matches, ...this._countMatchesInXml(child)];
          }
        }
      }
    }

    return matches;
  }

  _countMatchesInHtml(doc) {
    let matches = [];

    for (let node of doc.childNodes) {
      if (node.nodeType === Node.ELEMENT_NODE && node.tagName.toLowerCase() !== 'script' && node.tagName.toLowerCase() !== 'style') {
        const normalizedText = this._normalizeText(this._getTextContent(node));
        matches = [...matches, ...normalizedText.match(this.regexPattern)];

        for (let child of node.childNodes) {
          if (child.nodeType === Node.ELEMENT_NODE) {
            matches = [...matches, ...this._countMatchesInHtml(child)];
          }
        }
      }
    }

    return matches;
  }

  _getTextContent(node) {
    if (node.nodeType === Node.TEXT_NODE || node.nodeType === Node.CDATA_SECTION_NODE) {
      return node.textContent || '';
    } else if (node.nodeType === Node.ELEMENT_NODE) {
      let content = '';
      for (let child of node.childNodes) {
        content += this._getTextContent(child);
      }
      return content.trim();
    }
  }

  _filterMatches(matches) {
    const counts = {};

    matches.forEach((match) => {
      let testament, book;

      if (/Old Testament|new testament/.test(match)) {
        // If it's a testament, count it as a whole
        if (match === 'Old Testament') {
          testament = 'Old Testament';
          book = null;
        } else {
          testament = 'New Testament';
          book = null;
        }
      } else {
        // Otherwise, extract the book name
        const matchParts = match.split(/\s+/);
        if (matchParts.length > 1) {
          testament = matchParts[0];
          book = matchParts[1];
        } else {
          // In case of ambiguity, skip the match
          return;
        }
      }

      if (testament === null || !this.testaments.includes(testament)) return;

      if (book && this.books.includes(book)) {
        counts[book] = (counts[book] || 0) + 1;
      } else if (testament === 'Old Testament') {
        const oldTestamentBooks = ['Genesis', 'Exodus', 'Leviticus', 'Numbers', 'Deuteronomy', 'Joshua', 'Judges', 'Ruth', '1 Samuel', '2 Samuel', '1 Kings', '2 Kings', '1 Chronicles', '2 Chronicles', 'Ezra', 'Nehemiah', 'Esther', 'Job', 'Psalms', 'Proverbs', 'Ecclesiastes', 'Song of Solomon', 'Isaiah', 'Jeremiah', 'Lamentations', 'Ezekiel', 'Daniel', 'Hosea', 'Joel', 'Amos', 'Obadiah', 'Jonah', 'Micah', 'Nahum', 'Habakkuk', 'Zephaniah', 'Haggai', 'Zechariah', 'Malachi'];
        oldTestamentBooks.forEach((book) => {
          counts[book] = (counts[book] || 0) + 1;
        });
      } else if (testament === 'New Testament') {
        const newTestamentBooks = ['Matthew', 'Mark', 'Luke', 'John', 'Acts', 'Romans', '1 Corinthians', '2 Corinthians', 'Galatians', 'Ephesians', 'Philippians', 'Colossians', '1 Thessalonians', '2 Thessalonians', '1 Timothy', '2 Timothy', 'Titus', 'Philemon', 'Hebrews', 'James', '1 Peter', '2 Peter', '1 John', '2 John', '3 John', 'Jude', 'Revelation'];
        newTestamentBooks.forEach((book) => {
          counts[book] = (counts[book] || 0) + 1;
        });
      }
    });

    return counts;
  }
}

