// Third-party CRC library integration
typedef struct CRC_INDICATION_REL8_TAG {
    uint32_t CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG_T rx_ue_information_tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct STATISTICS_T {
    uint32_t unique_rntis;
} STATISTICS_T;

void nfapi_crc_indication_pdu_list_create(NFAPI_CRC_INDICATION_PDU_T **list, STATISTICS_T *stats) {
    *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*list) {
        fprintf(stderr, "Failed to allocate memory for initial list element.\n");
        return;
    }

    (*list)[0].rx_ue_information_tag.value = 0xDEADBEEF; // Replace with appropriate value
    (*list)[0].rnti = rand();
    (*list)[0].crc_indication_rel8_tag.CRCFLAG = rand() % 2;

    *stats = (STATISTICS_T){.unique_rntis = 1};

    size_t capacity = 1;
    NFAPI_CRC_INDICATION_PDU_T *temp_list = NULL;
    while (true) {
        capacity *= 2;
        temp_list = realloc(temp_list, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_list) {
            fprintf(stderr, "Failed to allocate memory for temporary list.\n");
            free(*list);
            return;
        }

        for (size_t i = 1; i < capacity; ++i) {
            (*list)[i].rx_ue_information_tag.value = 0xDEADBEEF; // Replace with appropriate value
            (*list)[i].rnti = rand();
            while ((*list)[i - 1].rnti == (*list)[i].rnti) {
                (*list)[i].rnti = rand();
            }
            (*list)[i].crc_indication_rel8_tag.CRCFLAG = rand() % 2;
            ++(*stats)->unique_rntis;
        }

        *list = temp_list;
        if (capacity >= *stats)->unique_rntis) {
            break;
        }
    }
}

void dump_statistics(const STATISTICS_T *stats) {
    printf("Unique RNTIs used: %u\n", stats->unique_rntis);
}
