#include <stdbool.h>

#define MAX_ELEMENTS 1000000
#define LOGGING_VERBOSE false
#define FILE_SIZE_LIMIT 10000000

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

struct list {
    NFAPI_CRC_INDICATION_PDU_T data[MAX_ELEMENTS];
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
};

void timestamped_init(NFAPI_CRC_INDICATION_PDU_T* pdu, time_t* timestamp) {
    *timestamp = time(NULL);
    pdu->timestamp = *timestamp;
}

struct list* create_list() {
    struct list* list = (struct list*)malloc(sizeof(struct list));
    if (!list) return NULL;

    list->count = 0;
    list->capacity = MAX_ELEMENTS;
    list->lock = PTHREAD_MUTEX_INITIALIZER;

    return list;
}

bool add_pdu(struct list* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (list->count == list->capacity) return false;

    pthread_mutex_lock(&list->lock);

    timestamped_init(&pdu.timestamp);
    pdu.crc_ind.crcflag = rand() % 2;

    list->data[list->count] = pdu;
    ++(list->count);

    pthread_mutex_unlock(&list->lock);
    return true;
}

bool save_to_file(const char* filename, const void* data, size_t size) {
    FILE* file = fopen(filename, "wb");
    if (!file) return false;

    size_t written = 0;
    while (written < size) {
        size_t to_write = size - written > FILE_SIZE_LIMIT ? FILE_SIZE_LIMIT : size - written;
        size_t written_this_time = fwrite((char*)data + written, sizeof(char), to_write, file);
        if (written_this_time == 0) {
            fclose(file);
            return false;
        }
        written += written_this_time;
    }

    fclose(file);
    return true;
}

void log(const char* message, bool verbose) {
    if (verbose && LOGGING_VERBOSE) {
        printf("%s\n", message);
    }
}

void serialize_list(struct list* list, const char* filename) {
    if (!list || !filename) return;

    log("Serializing list...", true);

    size_t data_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->count;
    bool success = save_to_file(filename, list->data, data_size);

    if (success) {
        log("List serialized successfully!", true);
    } else {
        log("Failed to serialize list.", true);
    }
}

int main() {
    struct list* list = create_list();

    // Your high-traffic environment concurrent operations here...

    serialize_list(list, "my_file.bin");

    free(list);

    return 0;
}
