#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    int num_carriers;
    int *cell_ids;
    int *freq_bands;
    sem_t validation_sem[16]; // Semaphore for validation
    pthread_mutex_t callback_mutex; // Mutex for managing callbacks
    void (*process_cb)(struct lte_ue_context*, int, double*);
} init_params;

typedef struct lte_ue_context {
    int num_carriers;
    int *cell_ids;
    int *freq_bands;
    double *aggregated_measurements; // Validation occurs here
    pthread_mutex_t cb_lock; // Mutex for callbacks
    void (*cb)(struct lte_ue_context*); // Callback function pointer
} lte_ue_context;

void validate(lte_ue_context *ctx) {
    double sum = 0.0;
    for (int i = 0; i < ctx->num_carriers; ++i) {
        sem_wait(&ctx->validation_sem[i]);
        sum += ctx->aggregated_measurements[i];
    }

    // Ensure consistency of aggregated measurements
    double avg = sum / ctx->num_carriers;
    for (int i = 0; i < ctx->num_carriers; ++i) {
        if (fabs(ctx->aggregated_measurements[i] - avg) > EPSILON) {
            // Log anomaly and take appropriate action, e.g., notify administrator
            fprintf(stderr, "Validation error: %s\n", ctx->name);
        }
    }
}

void lte_ue_context_init(lte_ue_context *ctx, init_params params) {
    ctx->num_carriers = params.num_carriers;
    ctx->cell_ids = (int*)malloc(ctx->num_carriers * sizeof(int));
    ctx->freq_bands = (int*)malloc(ctx->num_carriers * sizeof(int));
    ctx->aggregated_measurements = (double*)calloc(ctx->num_carriers, sizeof(double));
    ctx->cb = NULL;
    ctx->cb_lock = PTHREAD_MUTEX_INITIALIZER;

    // Initialize validation semaphores and copy input parameters
    for (int i = 0; i < ctx->num_carriers; ++i) {
        ctx->cell_ids[i] = params.cell_ids[i];
        ctx->freq_bands[i] = params.freq_bands[i];
        sem_init(&ctx->validation_sem[i], 0, 0); // Unlocked on creation
    }

    // Initialize callback mutex and copy input callback function
    pthread_mutex_init(&params.callback_mutex, NULL);
    if (params.process_cb) {
        ctx->cb = params.process_cb;
    }
}

void lte_ue_context_update(lte_ue_context *ctx, int carrier, double measurement) {
    sem_post(&ctx->validation_sem[carrier]); // Signal validation on updated measurement
    ctx->aggregated_measurements[carrier] = measurement;
}

void lte_ue_context_process(lte_ue_context *ctx) {
    if (ctx->cb) {
        pthread_mutex_lock(&ctx->cb_lock); // Lock callback mutex to avoid race conditions
        ctx->cb(ctx); // Call the registered callback function
        pthread_mutex_unlock(&ctx->cb_lock); // Unlock the callback mutex
    }
}

void lte_ue_context_cleanup(lte_ue_context *ctx) {
    free(ctx->cell_ids);
    free(ctx->freq_bands);
    free(ctx->aggregated_measurements);
    pthread_mutex_destroy(&ctx->cb_lock);
}
