    if (fd == -1) {
        perror("open");
        return 1;
    }

    off_t filesize = lseek(fd, 0, SEEK_END);
    if (filesize == (off_t)-1) {
        perror("lseek");
        close(fd);
        return 1;
    }

    char *map_base = mmap(NULL, filesize + getpagesize(), PROT_READ, MAP_PRIVATE, fd, 0);
    if (map_base == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return 1;
    }

    close(fd);

    *chunk = malloc(sizeof(struct chunk));
    (*chunk)->len = filesize;
    (*chunk)->data = map_base;

