import pandas as pd
from datetime import datetime

def parse_log(line):
    try:
        timestamp, request_id, status_code, request_duration = line.split()
        timestamp = datetime.strptime(timestamp, "%Y-%m-%d %H:%M:%S")
        return (timestamp, int(request_id), int(status_code), float(request_duration))
    except ValueError:
        error_report['parse_errors'].append(f"{line}: {sys.exc_info()[0]}")
        return None

def process_log_file(filepath, chunk_size=100000):
    errors = []
    stats = {"total_requests": 0, "total_time": 0, "error_rate": 0}
    df = pd.DataFrame(columns=["timestamp", "request_id", "status_code", "request_duration"])

    with open(filepath, 'r') as f:
        for i, chunk in enumerate(chunks(f, chunk_size)):
            for line in chunk:
                result = parse_log(line)
                if result is not None:
                    df = df.append(result, ignore_index=True)
                    stats["total_requests"] += 1
                    stats["total_time"] += result[3]
                    if result[2] >= 400:
                        stats["error_rate"] += 1 / (i + 1)

            if i > 0 and (i+1) % (chunk_size // 10) == 0:
                # Report parsing errors every 10% of the file
                print(f"Processing {filepath}: {len(errors)} parse errors")

    return stats, df, errors

def chunks(lst, n):
    for i in range(0, len(lst), n):
        yield lst[i:i+n]

error_report = {"parse_errors": []}
stats_aggregate = {}

with concurrent.futures.ThreadPoolExecutor() as executor:
    for root, _, files in os.walk("/path/to/logfiles"):
        for file in files:
            if file.endswith(".log"):
                stats, df, errors = process_log_file(os.path.join(root, file))
                stats_aggregate[file] = stats
                error_report["parse_errors"].extend(errors)

avg_request_duration = sum(stats_aggregate['total_time'] for _, stats in stats_aggregate.items()) / len(stats_aggregate)

summary_report = {
    "total_requests": sum(stats["total_requests"] for _, stats in stats_aggregate.items()),
    "average_request_duration": avg_request_duration,
    "error_rate": len(error_report['parse_errors']) / sum(stats["total_requests"] for _, stats in stats_aggregate.items())
}

detailed_report = {**summary_report, **{'parse_errors': error_report['parse_errors']}}
