// Record structure to store parsed data from input file
typedef struct record {
    int value;
} record;

// Thread-safe function to populate an array of records with random values
void* populate_records(void* arg) {
    pthread_mutex_t* lock = (pthread_mutex_t*)arg;
    record* records = NULL;
    int num_records, i, j;
    int max_records = 1000000; // Set maximum number of records here

    while (1) {
        pthread_mutex_lock(lock);
        if (!records || records->size >= max_records) {
            break;
        }
        if (!records) {
            records = (record*)malloc(sizeof(record));
            if (!records) {
                pthread_mutex_unlock(lock);
                continue;
            }
            records->size = 1;
            records->data = (int*)malloc(records->size * sizeof(int));
        } else {
            records->size *= 2;
            records->data = realloc(records->data, records->size * sizeof(int));
            if (!records->data) {
                pthread_mutex_unlock(lock);
                continue;
            }
        }
        pthread_mutex_unlock(lock);

        for (i = 0; i < records->size; ++i) {
            records->data[i] = rand_in_range(1, 1000000); // Set your desired range here
        }

        pthread_mutex_lock(lock);
    }

    return NULL;
}

