#define MAX_BANDS 10
#define MAX_NUMEROLOGIES 64

typedef struct band {
    int id;
    int num_numerologies;
    int *numerologies;
} Band;

typedef struct nr_ue_context {
    int num_bands;
    Band* bands;
    pthread_mutex_t mutex;
} NRUEContext;

void validate_measurements(NRUEContext* ctx, int band_id, int numerology_idx);
NRUEContext* create_nrue_context(int num_bands) {
    NRUEContext *ctx = (NRUEContext*) malloc(sizeof(NRUEContext));
    if (!ctx) return NULL;

    ctx->num_bands = num_bands;
    ctx->bands = (Band*) calloc(num_bands, sizeof(Band));
    if (!ctx->bands) {
        free(ctx);
        return NULL;
    }

    for (int i = 0; i < num_bands; ++i) {
        ctx->bands[i].id = i + 1;
        ctx->bands[i].num_numerologies = rand() % MAX_NUMEROLOGIES + 1;
        ctx->bands[i].numerologies = (int*) malloc(ctx->bands[i].num_numerologies * sizeof(int));
        if (!ctx->bands[i].numerologies) {
            for (int j = 0; j < i; ++j) free(ctx->bands[j].numerologies);
            free(ctx->bands);
            free(ctx);
            return NULL;
        }
    }

    pthread_mutex_init(&ctx->mutex, NULL);

    return ctx;
}

void nrue_context_destroy(NRUEContext** ctx) {
    if (!*ctx) return;

    for (int i = 0; i < (*ctx)->num_bands; ++i) free((*ctx)->bands[i].numerologies);
    free((*ctx)->bands);
    free(*ctx);
    *ctx = NULL;
}
```

