void initUEContexts(NFAPI_RRC_MESSAGE_T** contexts, size_t* numContexts, size_t maxContexts) {
    if (maxContexts > 1000 || maxContexts == 0) {
        printf("Invalid maximum number of UE contexts. Must be between 1 and 1000.\n");
        return;
    }

    *contexts = malloc(sizeof(NFAPI_RRC_MESSAGE_T) * maxContexts);
    if (!*contexts) {
        printf("Error: Failed to allocate memory for UE context structures.\n");
        return;
    }

    *numContexts = 0;
    size_t i;
    for (i = 0; i < maxContexts && (*numContexts) < maxContexts; ++i) {
        // Create and initialize UE_CONTEXT_INFO with a unique RNTI.
        (*contexts)[(*numContexts)].ueContextInfo = createUEContextInfo(i);
        if (!(*contexts)[(*numContexts)].ueContextInfo) {
            printf("Error: Failed to allocate memory for UE context info.\n");
            break;
        }

        // Generate RRM_MEASUREMENT_TAG with PHY_MEASUREMENT_T objects.
        populateMeasurementTag(&(*contexts)[(*numContexts)].rrmMeasurementTag);

        ++(*numContexts);
    }
}

void populateMeasurementTag(RRM_MEASUREMENT_TAG* tag) {
    size_t numMeasurements = 10; // Adjust based on desired measurement count.
