[' Here is a simplified C++ code for the given task, using a Red-Black Tree (RBTree) for efficient insertion, deletion, and searching operations, a LRU cache for faster access times, and employing multithreading with mutual exclusion to handle concurrent access.

```cpp
#include <iostream>
#include <list>
#include <unordered_map>
#include <memory>
#include <cstdlib>
#include <mutex>

struct Record {
    long offset;
    int key;
};

typedef std::shared_ptr<Record> RecordPtr;
typedef std::list<RecordPtr> NodeList;
typedef std::unique_ptr<NodeList> NodeListUPtr;
typedef std::pair<const long, RecordPtr> RBTreePair;
typedef std::shared_ptr<std::unordered_map<long, RBTreePair>> RBTreeUPtr;

class Cache {
private:
    static const int CACHE_SIZE = 1024;
    std::list<RecordPtr> cache_;
    std::mutex mtx_;
public:
    RecordPtr get(const long offset) {
        std::lock_guard<std::mutex> lck(mtx_);
        if (!cache_.empty()) {
            auto it = cache_.begin();
            if ((*it)->offset <= offset) {
                cache_.erase(it);
                return *it;
            }
        }
        // If not found, insert a new node with the given key-value pair and update the LRU order.
    }

    void put(RecordPtr record) {
        std::lock_guard<std::mutex> lck(mtx_);
        if (cache_.size() < CACHE_SIZE) {
            cache_.push_back(std::move(record));
            return;
        }
        auto it = cache_.begin();
        it->second->offset = offset;
        std::advance(it, cache_.size() - 1);
        cache_.erase(it);
        cache_.push_back(std::move(record));
    }
};

class RBTreeNode {
private:
    RecordPtr record_;
    RBTreeUPtr leftChild_, rightChild_, parent_;
public:
    explicit RBTreeNode(RecordPtr record) : record_(std::move(record)) {}

    // Implement insert, remove, and find functions here.
};

class SortedList {
private:
    NodeListUPtr root_;
    mutable Cache cache_;
public:
    void add(const Record &record) {
        std::unique_ptr<RBTreeNode> node = std::make_unique<RBTreeNode>(RecordPtr(new Record(record)));
        auto current = root_.get();
        RBTreeUPtr parent = nullptr;
        while (current != nullptr) {
            parent = current->get();
            if ((*parent)->record_->offset > record.offset) {
                current->leftChild_ = node;
                break;
            }
            current = current->rightChild_.get();
        }
        if (current == nullptr) {
            if (*parent)->record_->offset > record.offset) {
                parent->leftChild_ = std::move(node);
            } else {
                parent->rightChild_ = std::move(node);
            }
        }
    }

    void remove(const long offset) {
        // Implement removal here.
    }

    RecordPtr find(const long offset) const {
        auto current = root_.get();
        while (current != nullptr) {
            if ((*current)->record_->offset == offset) {
                return *(*current);
            }
            if ((*current)->record_->offset > offset) {
                current = current->leftChild_.get();
            } else {
                current = current->rightChild_.get();
            }
        }
        return nullptr;
    }

    std::list<RecordPtr> findInRange(const long startOffset, const long endOffset) const {
        // Implement finding records in a range here.
    }
};
```

