class DataChunk {
  constructor(data, offset, length) {
    this.data = data;
    this.offset = offset;
    this.length = length;
  }
}

async function copyDataChunks(chunks, destBuffer, byteCount) {
  let sourceOffset = 0;
  let totalBytesRead = 0;
  const tempBuffer = new Uint8Array(Math.max(byteCount, chunks.length));

  for (const chunk of chunks) {
    if (sourceOffset + chunk.length > byteCount) {
      throw new Error('Requested byte count exceeds total available data.');
    }

    const bytesToRead = Math.min(chunk.length - sourceOffset, byteCount - totalBytesRead);
    const srcSlice = chunk.data.slice(chunk.offset + sourceOffset, chunk.offset + sourceOffset + bytesToRead);
    tempBuffer.set(srcSlice, totalBytesRead);

    sourceOffset += bytesToRead;
    totalBytesRead += bytesToRead;
  }

  destBuffer.set(tempBuffer.subarray(0, totalBytesRead), 0);
}

// Example usage:
const chunk1 = new DataChunk(new Uint8Array([1, 2, 3]), 0, 3);
const chunk2 = new DataChart(new Uint8Array([4, 5]), 0, 2);
const destBuffer = new Uint8Array(6);

try {
  copyDataChunks([chunk1, chunk2], destBuffer, 5);
} catch (error) {
  console.error(error.message);
}
