#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct node {
    char *data;
    int index;
} Node;

typedef struct key_value_pair {
    int key;
    Node *node;
} KeyValuePair;

struct cache {
    KeyValuePair *kv_array;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
};

Cache* create_cache(size_t initial_capacity) {
    Cache *cache = malloc(sizeof(Cache));
    cache->capacity = initial_capacity;
    cache->count = 0;
    cache->kv_array = calloc(initial_capacity, sizeof(KeyValuePair));
    pthread_mutex_init(&cache->mutex, NULL);
    return cache;
}

Node* create_node(const char *data) {
    Node *node = malloc(sizeof(Node));
    node->data = strdup(data);
    node->index = -1;
    return node;
}

KeyValuePair* get_or_create_key_value_pair(Cache *cache, int key) {
    pthread_mutex_lock(&cache->mutex);

    for (size_t i = 0; i < cache->count; ++i) {
        if (cache->kv_array[i].key == key) {
            KeyValuePair *pair = &cache->kv_array[i];
            pthread_mutex_unlock(&cache->mutex);
            return pair;
        }
    }

    if (cache->count >= cache->capacity) {
        size_t new_capacity = cache->capacity * 2;
        KeyValuePair *new_kv_array = realloc(cache->kv_array, new_capacity * sizeof(KeyValuePair));

        if (!new_kv_array) {
            pthread_mutex_unlock(&cache->mutex);
            return NULL;
        }

        cache->kv_array = new_kv_array;
        cache->capacity = new_capacity;
    }

    KeyValuePair *pair = &cache->kv_array[cache->count++];
    pair->key = key;
    pair->node = NULL;

    pthread_mutex_unlock(&cache->mutex);
    return pair;
}

void populate(Cache *cache, size_t num_nodes) {
    for (size_t i = 0; i < num_nodes; ++i) {
        char key_str[12];
        sprintf(key_str, "%ld", i);

        int key = atoi(key_str);
        KeyValuePair *pair = get_or_create_key_value_pair(cache, key);

        if (pair) {
            pair->node = create_node(key_str);
        }
    }
}

void cleanup(Cache *cache) {
    for (size_t i = 0; i < cache->count; ++i) {
        free(cache->kv_array[i].node->data);
        free(cache->kv_array[i].node);
    }
    free(cache->kv_array);
    free(cache);
}
```']

