#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct NFAPI_L1_STATS_T {
    int id;
    // Other structure fields here...
} NFAPI_L1_STATS_T;

struct node {
    NFAPI_L1_STATS_T data;
    struct node* next;
    struct node* prev;
};

struct dl_list {
    struct node* head;
    struct node* tail;
    size_t unique_ids;
    size_t cap;
    size_t len;
    pthread_mutex_t list_lock;
};

void init_dl_list(struct dl_list* list) {
    list->head = NULL;
    list->tail = NULL;
    list->unique_ids = 0;
    list->cap = 0;
    list->len = 0;
    pthread_mutex_init(&list->list_lock, NULL);
}

void add_to_dl_list(struct dl_list* list, NFAPI_L1_STATS_T data) {
    struct node* new_node = malloc(sizeof(struct node));
    if (!new_node) return;

    new_node->data = data;
    new_node->next = NULL;
    new_node->prev = NULL;

    pthread_mutex_lock(&list->list_lock);
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        bool found = false;
        struct node* curr = list->head;
        while (curr && curr->data.id == data.id) {
            found = true;
            curr = curr->next;
        }
        if (!found) {
            if (!list->unique_ids % 2) { // Odd number of elements, append
                new_node->next = list->head;
                list->head->prev = new_node;
                list->head = new_node;
            } else { // Even number of elements, prepend
                new_node->prev = list->tail;
                list->tail->next = new_node;
                list->tail = new_node;
            }
        }
    }
    pthread_mutex_unlock(&list->list_lock);

    if (++(list->len) > list->cap && list->cap > 10) { // Adjust capacity only when necessary
        size_t new_cap = list->cap * 2;
        struct node** temp_array = realloc(list->head, sizeof(struct node) * new_cap);
        if (temp_array) {
            list->head = temp_array;
            memset(list->head + list->cap, 0, sizeof(struct node) * (new_cap - list->cap));
            list->cap = new_cap;
        }
    }
}

void dump_dl_list(const struct dl_list* list, const char* prefix) {
    pthread_mutex_lock(&list->list_lock);
    struct node* curr = list->head;
    while (curr) {
        printf("%s{ id: %d, // Other structure fields here... }\n", prefix, curr->data.id);
        curr = curr->next;
    }
    pthread_mutex_unlock(&list->list_lock);
}

void free_dl_list(struct dl_list* list) {
    pthread_mutex_lock(&list->list_lock);
    struct node* curr = list->head;
    while (curr) {
        struct node* temp = curr;
        curr = curr->next;
        free(temp);
    }
    pthread_mutex_unlock(&list->list_lock);
}
```

