/* Define the record structure */
typedef struct {
    int value;
} record;

int initialize_arrays(size_t array_size, size_t *offsets, int *keys, record **records, int min_value, int max_value) {
    if (max_value < min_value) {
        max_value = min_value + 1;
        min_value = INT_MIN;
    } else if (min_value == INT_MIN) {
        min_value = 0;
    }

    *offsets = calloc(array_size, sizeof(long));
    if (!*offsets) {
        perror("Failed to allocate offset memory");
        return -1;
    }

    *keys = calloc(array_size, sizeof(int));
    if (!*keys) {
        perror("Failed to allocate key memory");
        free(*offsets);
        return -1;
    }

    *records = calloc(array_size, sizeof(record));
    if (!*records) {
        perror("Failed to allocate record memory");
        free(*keys);
        free(*offsets);
        return -1;
    }

    pthread_mutex_t records_lock = PTHREAD_MUTEX_INITIALIZER;

    #pragma GCC ivdep
    for (size_t i = 0; i < array_size; ++i) {
        record *record_ptr = &((*records)[i]);
        record_ptr->value = xdr_rand(NULL, min_value, max_value);
        pthread_mutex_lock(&records_lock);
        (*keys)[i] = i;
        (*offsets)[(*keys)[i]] = (long)record_ptr;
        pthread_mutex_unlock(&records_lock);
    }

    long *sum_ptr = mmap(NULL, sizeof(long), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (sum_ptr == MAP_FAILED) {
        perror("Failed to allocate sum memory");
        free(*keys);
        free(*offsets);
        free(*records);
        return -1;
    }

    *sum_ptr = 0;
    #pragma GCC ivdep
    for (size_t i = 0; i < array_size; ++i) {
        record *record_ptr = &((*records)[(*keys)[(*offsets)[i]]]);
        (*sum_ptr) += record_ptr->value;
    }

    return 0;
}
```

