#include <sys/time.h>
#include <pthread.h>

struct Task {
    std::string name;
    int priority;
    struct timeval schedulingInfo;
};

using TaskMap = std::unordered_map<std::string, boost::circular_buffer<Task>>;
TaskMap taskCollection; // Global variable for access across threads
pthread_mutex_t mutex; // Mutex to protect the hash table

void addTask(const std::string& name, int priority, struct timeval schedulingInfo) {
    pthread_mutex_lock(&mutex);
    taskCollection[name].push_back({name, priority, schedulingInfo});
    pthread_mutex_unlock(&mutex);
}

void updateTask(const std::string& name, int priority, struct timeval schedulingInfo) {
    pthread_mutex_lock(&mutex);
    auto it = taskCollection.find(name);
    if (it != taskCollection.end()) {
        it->second.back().priority = priority;
        it->second.back().schedulingInfo = schedulingInfo;
    }
    pthread_mutex_unlock(&mutex);
}

void removeTask(const std::string& name) {
    pthread_mutex_lock(&mutex);
    auto it = taskCollection.find(name);
    if (it != taskCollection.end()) {
        it->second.clear(); // Removes the task from the corresponding bucket
        if (it->second.empty()) {
            taskCollection.erase(it); // Removes the empty bucket from the hash table
        }
    }
    pthread_mutex_unlock(&mutex);
}
```

This code creates a global variable `taskCollection`, which is an unordered map of linked lists (using boost::circular_buffer) for each unique task name. The mutex ensures atomic access to the hash table during updates and removals. The addTask, updateTask, and removeTask functions modify the data structure accordingly.

