// Function to insert a measurement into the dynamic array
void insert_measurement(struct LTEMeasurements* measurements, const Measurement* new_measurement) {
    pthread_mutex_lock(&measurements->mutex);

    MeasurementNode* current = measurements->head;
    MeasurementNode* prev = NULL;
    while (current != NULL && (current->data.timestamp - measurements->timestamp_threshold >= new_measurement->timestamp)) {
        prev = current;
        current = current->next;
    }

    if (prev == NULL) {
        measurements->head = malloc(sizeof(MeasurementNode));
        memcpy(&measurements->head->data, new_measurement, sizeof(Measurement));
        measurements->head->next = current;
    } else {
        MeasurementNode* new_node = malloc(sizeof(MeasurementNode));
        memcpy(&new_node->data, new_measurement, sizeof(Measurement));
        new_node->next = current;
        prev->next = new_node;
    }

    measurements->num_measurements++;
    measurements->avg_rssi = update_avg_rssi(measurements);

    pthread_mutex_unlock(&measurements->mutex);
}

// Function to remove a measurement from the dynamic array based on its timestamp
void remove_measurement(struct LTEMeasurements* measurements, const time_t timestamp) {
    pthread_mutex_lock(&measurements->mutex);

    MeasurementNode** current = &measurements->head;
    while (*current != NULL) {
        if ((*current)->data.timestamp == timestamp) {
            MeasurementNode* temp = *current;
            *current = (*current)->next;
            free(temp);
            measurements->num_measurements--;
            break;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&measurements->mutex);
}

