void addOrUpdate(const NFAPI_CRC_INDICATION_PDU_T& data) {
    std::unique_lock<std::mutex> lock(mtx);
    auto it = list.find(data.rnti);
    if (it == list.end()) {
        list[data.rnti] = std::make_unique<NFAPI_CRC_INDICATION_PDU_T>(data);
    } else {
        it->second->crc_indication.crcflag = data.crc_indication.crcflag; // Assuming you want to overwrite the CRCFLAG value during updates
    }
}

void removeByRnti(uint32_t rnti) {
    std::unique_lock<std::mutex> lock(mtx);
    auto it = list.find(rnti);
    if (it != list.end()) {
        list.erase(it);
    }
}

// Ensure thread safety by calling these functions with a unique lock around the mutex
void runAddOrUpdateThreads(const std::vector<NFAPI_CRC_INDICATION_PDU_T>& data) {
    for (auto& d : data) {
        std::thread{addOrUpdate, d}.detach();
    }
