// Java (MD5 Hash Concatenation)

import java.security.MessageDigest;
import java.math.BigInteger;
import java.nio.charSet;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class MD5Hasher {
    private final ConcurrentHashMap<String, BigInteger> hashedStrings = new ConcurrentHashMap<>();

    public String concatenateMD5Hashes(List<String> inputStrings) {
        StringBuilder sb = new StringBuilder();
        List<Callable<String>> tasks = new ArrayList<>();
        for (String s : inputStrings) {
            tasks.add(() -> getMD5Hash(s));
        }

        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        try {
            List<Future<String>> results = executor.invokeAll(tasks);
            for (Future<String> result : results) {
                sb.append(hashedStrings.putIfAbsent(result.get(), result.get()));
            }
        } catch (InterruptedException | ExecutionException e) {
            // Handle exceptions gracefully
        } finally {
            executor.shutdown();
            try {
                executor.awaitTermination(1, TimeUnit.MINUTES);
            } catch (InterruptedException e) {
                // Handle exceptions gracefully
            }
        }

        return sb.toString();
    }

    private String getMD5Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes(StandardCharsets.UTF_8));
            BigInteger no = new BigInteger(1, messageDigest);
            String hashedString = no.toString(16);
            while (hashedString.length() < 32) {
                hashedString = "0" + hashedString;
            }
            return hashedString;
        } catch (NoSuchAlgorithmException e) {
            // Handle exceptions gracefully
            return null;
        }
    }
