function updateProfileSettings($request) {
    // Session-based authentication
    if (!isset($_SESSION) || !isset($_SESSION['user_id']) || !isset($_SESSION['token'])) {
        return json_encode(['message' => 'error', 'data' => []]);
    }

    $userId = $request['id'];
    if ($userId != $_SESSION['user_id']) {
        session_destroy(); // Log out and prevent hijacking
        return json_encode(['message' => 'error', 'data' => []]);
    }

    $token = $request['token'];
    if (hash('sha256', $token) != $_SESSION['token']) {
        session_destroy(); // Log out and prevent hijacking
        return json_encode(['message' => 'error', 'data' => []]);
    }

    // Validate input data and sanitize inputs to protect against SQL injection
    $name = trim($request['name']);
    $email = filter_var($request['email'], FILTER_SANITIZE_EMAIL);
    $password = ($request['password']) ? password_hash($request['password'], PASSWORD_DEFAULT) : null;
    $preferences = isset($request['preferences']) ? array_map('trim', $request['preferences']) : [];

    if (empty($name)) {
        return json_encode(['message' => 'error', 'data' => []]);
    }

    // Check for session fixation attacks and implement a secure logout process to prevent hijacking
    if (!isset($_SESSION['token']) || hash('sha256', $token) != $_SESSION['token']) {
        session_destroy();
        return json_encode(['message' => 'error', 'data' => []]);
    }

    // Database connection and handling concurrent updates to avoid data corruption
    $db = new DistributedDatabaseSystem();
    try {
        $db->beginTransaction();

        // Update personal information
        $query = "UPDATE users SET name=?, email=? WHERE id=?";
        $stmt = $db->prepare($query);
        $stmt->bind_param("ssi", $name, $email, $userId);
        $stmt->execute();

        // Update password if provided
        if (!is_null($password)) {
            $query = "UPDATE users SET password=? WHERE id=?";
            $stmt = $db->prepare($query);
            $stmt->bind_param("si", $password, $userId);
            $stmt->execute();
        }

        // Handle 'delete-preferences' sub_action and manage account preferences
        if (isset($request['sub_action']) && $request['sub_action'] == 'delete-preferences') {
            $query = "UPDATE users SET preferences=? WHERE id=?";
            $stmt = $db->prepare($query);
            $defaultPreferences = array_merge([], config('default_preferences')); // Load default preferences from configuration file
            $preferencesToUpdate = array_diff($defaultPreferences, array_filter($preferences)); // Remove deprecated preference keys and ensure critical user data is not overwritten
            $stmt->bind_param("si", json_encode($preferencesToUpdate), $userId);
            $stmt->execute();
        } else {
            $query = "UPDATE users SET preferences=? WHERE id=?";
            $stmt = $db->prepare($query);
            $stmt->bind_param("si", json_encode($preferences), $userId);
            $stmt->execute();
        }

        if ($db->commit()) {
            return json_encode(['message' => 'success', 'data' => ['updated' => true, 'preferences' => $preferences]]);
        } else {
            return json_encode(['message' => 'error', 'data' => []]);
        }
    } catch (\Exception $e) {
        $db->rollback(); // Rollback if an error occurs during write operations
        return json_encode(['message' => 'error', 'data' => []]);
    }
}
