class DynamicArray {
public:
    explicit DynamicArray(size_t max_elements) : capacity_(max_elements), data_(std::make_unique<NFAPI_CRC_INDICATION_PDU_T[]>(capacity_)) {}

    void addElement() {
        if (size_ >= capacity_) {
            resize();
        }
        ++size_;
        data_[size_ - 1].crc_indication.crcflag = rand() % 2;
        LOG_INFO("Added element to the array.");
    }

    void removeElement(size_t index) {
        if (index >= size_) {
            throw std::out_of_range("Index out of range.");
        }
        --size_;
        data_[index].~NFAPI_CRC_INDICATION_PDU_T();
        memmove(&data_[index], &data_[index + 1], (capacity_ - index) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        LOG_INFO("Removed element from the array.");
    }

    constexpr size_t capacity() const { return capacity_; }
    size_t size() const { return size_; }

    class Iterator {
    public:
        Iterator(const DynamicArray* owner, size_t index) : owner_(owner), index_(index) {}

        auto operator++() -> decltype(*this) {
            if (index_ < owner_->size()) {
                ++index_;
            }
            return *this;
        }

        auto operator*() const -> const NFAPI_CRC_INDICATION_PDU_T& {
            if (index_ >= owner_->size()) {
                throw std::out_of_range("Index out of range.");
            }
            return owner_->data_[index_];
        }

        friend bool operator!=(const Iterator& lhs, const Iterator& rhs) {
            return &lhs.owner_ != &rhs.owner_ || lhs.index_ != rhs.index_;
        }

    private:
        const DynamicArray* owner_;
        size_t index_;
    };

    Iterator begin() const { return Iterator(this, 0); }
    Iterator end() const { return Iterator(this, size_); }

private:
    void resize() {
        size_t newCapacity = std::max(capacity_ * 2, MAX_ELEMENTS);
        auto newData = std::make_unique<NFAPI_CRC_INDICATION_PDU_T[]>(newCapacity);
        std::memcpy(newData.get(), data_.get(), capacity_ * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        data_ = std::move(newData);
        capacity_ = newCapacity;
    }

    mutable std::mutex m_;
    size_t size_{0};
    size_t capacity_{MAX_ELEMENTS};
    std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T[]> data_;
};
