int load_state(const char *filename, size_t *num_offsets, size_t *num_keys, size_t *record_count, Record **records) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) return -1;

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    rewind(fp);

    Record *loaded_records = mmap(NULL, file_size, PROT_READ, MAP_PRIVATE, fileno(fp), 0);
    if (loaded_records == MAP_FAILED) {
        fclose(fp);
        return -1;
    }

    *record_count = file_size / sizeof(Record);
    *num_offsets = *num_keys = 0;
    *records = loaded_records;
    fclose(fp);
    return 0;
