    if (mmap(NULL, record_count * sizeof(Record), PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0) == MAP_FAILED) {
        fclose(fp);
        return -1;
    }

    Record *mapped_records = mmap(NULL, record_count * sizeof(Record), PROT_READ | PROT_WRITE, MAP_SHARED, fileno(fp), 0);
    if (mapped_records == MAP_FAILED) {
        fclose(fp);
        munmap((void*)MAP_FAILED, record_count * sizeof(Record));
