    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    pthread_mutex_t mutex;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node *next;
    sem_t available; // Semaphore for thread synchronization
} Node;

Node* head = NULL;
pthread_mutex_t global_mutex = PTHREAD_MUTEX_INITIALIZER;

int create_element(NFAPI_CRC_INDICATION_PDU_T** element) {
    *element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*element) {
        perror("Failed to allocate memory");
        return 1;
    }
    (*element)->crc_indication.crcflag = rand() % 2; // Set CRCFLAG randomly
    return 0;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        free(*data);
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    sem_init(&new_node->available, 0, 1);
    return new_node;
}

int insert_element(NFAPI_CRC_INDICATION_PDU_T** element) {
    int status;
    NFAPI_CRC_INDICATION_PDU_T* data = *element;
    Node* current = head, *new_node;

    // Create new node and populate it with the provided data
    status = create_element(data);
    if (status) return status;
    new_node = create_node(data);
    if (!new_node) {
        free(data);
        return 1;
    }

    // Lock global mutex to ensure thread safety during list traversal
    pthread_mutex_lock(&global_mutex);

    // Traverse the linked list, checking for duplicates and updating pointers
    if (head == NULL) {
        head = new_node;
    } else {
        while (current->next && current->next->data->tag != data->tag) {
            current = current->next;
        }

        if (current->next == NULL) {
            current->next = new_node;
        }
    }

    // Unlock global mutex
    pthread_mutex_unlock(&global_mutex);

    return 0;
}

