import java.io.*;

public class MostStateLoader {
    public MoSTState loadMoSTStateFromFile(String filePath) {
        FileInputStream fis = null;
        ObjectInputStream ois = null;
        MoSTState mostState = null;

        try {
            fis = new FileInputStream(filePath);
            if (!fis.available() || !filePath.canRead()) {
                System.out.println("Error: The file is either empty or cannot be accessed.");
                return null;
            }

            ois = new ObjectInputStream(fis);
            mostState = (MoSTState) ois.readObject();

            if (!(mostState instanceof MoSTState)) {
                System.out.println("Error: The loaded object is not an instance of MoSTState.");
                return null;
            }
        } catch (IOException | ClassNotFoundException e) {
            System.out.println("Error: " + e.getMessage());
        } finally {
            if (ois != null) try { ois.close(); } catch (IOException ignored) {}
            if (fis != null) try { fis.close(); } catch (IOException ignored) {}
        }

        return mostState;
    }
}
