    void* tag_data;
} NFAPI_RRC_MESSAGE_T;

struct dynamic_array {
    NFAPI_RRC_MESSAGE_T* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
};

void initialize_nfaapi_rrc_message_array(struct dynamic_array* array, size_t initial_capacity) {
    array->data = calloc(initial_capacity, sizeof(NFAPI_RRC_MESSAGE_T));
    if (!array->data) {
        fprintf(stderr, "Failed to allocate memory for array\n");
        return;
    }
    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
}

void resize_if_necessary(struct dynamic_array* array) {
    if (array->count >= array->capacity && array->capacity > 1) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_RRC_MESSAGE_T* new_data = realloc(array->data, new_capacity * sizeof(NFAPI_RRC_MESSAGE_T));
        if (!new_data) {
            fprintf(stderr, "Failed to resize array\n");
            return;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
}

bool append_to_array(struct dynamic_array* array, const RRCCONFIGDYN_TAG tag, void* tag_data) {
    resize_if_necessary(array);
    if (array->count >= array->capacity) {
        fprintf(stderr, "Failed to append to the array due to lack of space\n");
        return false;
    }
    pthread_mutex_lock(&array->lock);
    array->data[array->count].tag = tag;
    array->data[array->count].tag_data = tag_data;
    ++(array->count);
    pthread_mutex_unlock(&array->lock);
    return true;
}

bool update_by_index(struct dynamic_array* array, size_t index, const RRCCONFIGDYN_TAG tag, void* tag_data) {
    if (index >= array->count) {
        fprintf(stderr, "Invalid index\n");
        return false;
    }
    pthread_mutex_lock(&array->lock);
    if (index < array->capacity) {
        array->data[index].tag = tag;
        array->data[index].tag_data = tag_data;
    } else {
        resize_if_necessary(array);
        memcpy(&array->data[index], &array->data[array->count - 1], sizeof(NFAPI_RRC_MESSAGE_T));
        array->data[index].tag = tag;
        array->data[index].tag_data = tag_data;
        ++(array->count);
    }
    pthread_mutex_unlock(&array->lock);
    return true;
}

void free_nfaapi_rrc_message_array(struct dynamic_array* array) {
    if (array->data) {
        free(array->data);
        array->data = NULL;
        pthread_mutex_destroy(&array->lock);
    }
}
