// Define record structure
typedef struct Record {
    int value;
    long *offset;
    int *key;
} Record;

void validate_pointers(Record* record, size_t offset_size, size_t key_size) {
    if (record->offset == NULL || record->key == NULL ||
        record->offset >= (long*)calloc(offset_size, sizeof(long)) + offset_size ||
        record->key >= (int*)calloc(key_size, sizeof(int)) + key_size) {
        perror("Invalid pointer");
        exit(EXIT_FAILURE);
    }
}

Record* create_record(size_t offset_size, size_t key_size, size_t num_records) {
    Record *records = mmap(NULL, sizeof(Record) * num_records, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (records == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_records; ++i) {
        Record *record = records + i;
        validate_pointers(record, offset_size, key_size);
        record->offset[(long)-1] = -1;
        record->key[(int)-1] = -1;
    }

    return records;
}

void populate_records(Record* records, size_t num_records, long offset_size, int key_size, int min_val, int max_val) {
    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        Record *record = records + i;
        record->value = rand() % (max_val - min_val + 1) + min_val;
        record->offset[(long)i] = offset_size * i;
        record->key[i] = key_size * i;
    }
}

void stable_sort(Record* records, size_t num_records) {
    // Implement a stable sorting algorithm like merge sort or timsort here.
    // For simplicity, we'll use a basic insertion sort which is not scalable but easy to understand:

    for (size_t i = 1; i < num_records; ++i) {
        Record key = records[i];
        size_t j = i - 1;

        while (j >= 0 && records[j].value > key.value) {
            records[j + 1] = records[j];
            j--;
        }

        records[j + 1] = key;
    }
}

void free_resources(Record* records, size_t num_records) {
    munmap((void*)records, sizeof(Record) * num_records);
}

int main() {
    size_t num_records = 10000;
    long offset_size = 1;
    int key_size = sizeof(int);
    int min_val = 0;
    int max_val = 100;

    Record* records = create_record(offset_size, key_size, num_records);
    populate_records(records, num_records, offset_size, key_size, min_val, max_val);
    stable_sort(records, num_records);

    // Process the sorted records...

    free_resources(records, num_records);

    return 0;
}
```
