            current->throughput = (1.0 - 0.1 * abs(current->throughput)) * throughput + 0.9 * current->throughput; // Exponential smoothing for average calculation

            if (latency < 0.0) latency = 0.0;
            current->latency = (1.0 - 0.1 * abs(current->latency)) * latency + 0.9 * current->latency; // Exponential smoothing for average calculation

            if (errorRate < 0.0 || errorRate > 1.0) errorRate = current->errorRate; // Constrain error rate to valid range
            current->errorRate = (1.0 - 0.1 * abs(current->errorRate)) * errorRate + 0.9 * current->errorRate; // Exponential smoothing for average calculation

            current->lastUpdate = time(NULL);
            return;
        }
        current = current->next;
    }
}
```
