typedef struct {
    char pattern[256];
    int performance_threshold;
} Rule;

struct PatternData {
    long long count;
    time_t start_time;
};

void *process_pattern(const void *arg) {
    const Rule *rule = (const Rule *) arg;
    struct PatternData *data = malloc(sizeof(struct PatternData));
    data->count = 0;
    data->start_time = time(NULL);

    FILE *fp = fopen(input_file, "r");
    if (!fp) {
        perror("Failed to open input file");
        return NULL;
    }

    char line[4096];
    time_t current_time = data->start_time;
    bool within_date_range = false;

    while (fgets(line, sizeof(line), fp)) {
        if (!within_date_range && strftime(line + strlen(line) - 18, 18, "%Y-%m-%d %H:%M:%S", localtime(&current_time))) {
            within_date_range = true;
        }

        if (within_date_range && strstr(line, rule->pattern)) {
            data->count++;
        }
    }

    fclose(fp);

    time_t elapsed = difftime(time(NULL), data->start_time);

    if (elapsed > rule->performance_threshold) {
        fprintf(stderr, "Warning: Processing took %.2f seconds for %s pattern and %lld records\n", elapsed, rule->pattern);
    }

    return data;
}

void write_summary(const char *output_file, const Rule rules[], size_t num_rules, struct PatternData patterns[]) {
    FILE *fp = fopen(output_file, "w");
    if (!fp) {
        perror("Failed to open output file");
        return;
    }

    fprintf(fp, "Summary Report\n");
    fprintf(fp, "------------------------\n");
    fprintf(fp, "Total Records Processed: %lld\n", patterns_total_count);

    for (size_t i = 0; i < num_rules; ++i) {
        const Rule *rule = &rules[i];
        struct PatternData *data = &patterns[i];

        if (!data) {
            fprintf(fp, "Warning: %s pattern processing failed\n", rule->pattern);
            continue;
        }

        fprintf(fp, "%s: %lld records, %.2f seconds\n", rule->pattern, data->count, difftime(time(NULL), data->start_time));
    }

    fclose(fp);
}

int main(int argc, char *argv[]) {
    if (argc < 6) {
        fprintf(stderr, "Usage: %s [input_file] [output_file] [date_range] [patterns_rules] [performance_threshold]\n", argv[0]);
        return 1;
    }

    const char *input_file = argv[1];
    const char *output_file = argv[2];
    char date_range[32];
    strcpy(date_range, argv[3]);
    const Rule rules[] = {{argv[4], atoi(argv[5])}};

    struct PatternData patterns[1]; // Initialize with one empty element
    pthread_t threads[num_rules];

    clock_t start = clock();

    for (size_t i = 0; i < num_rules; ++i) {
        pthread_create(&threads[i], NULL, process_pattern, &rules[i]);
    }

    for (size_t i = 0; i < num_rules; ++i) {
        pthread_join(threads[i], (void**)&patterns[i]);
    }

    clock_t elapsed = clock() - start;
    double seconds = ((double)elapsed) / CLOCKS_PER_SEC;

    if (seconds > rules[0].performance_threshold) {
        fprintf(stderr, "Warning: Processing took %.2f seconds\n", seconds);
    }

    write_summary(output_file, rules, num_rules, patterns);

    return 0;
}
```

