int compare_keys(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

void populate_records(Record **records, long *offsets, int *keys, size_t num_offsets, size_t num_keys) {
    qsort(keys, num_keys, sizeof(int), compare_keys);
    for (size_t i = 0; i < num_offsets && i < num_keys; ++i) {
        int found = false;
        for (size_t j = 0; j < i && !found; ++j) {
            if (keys[j] == keys[i]) {
                found = true;
            }
        }
        if (!found) {
            (*records)[i].offset = &offsets[i];
            (*records)[i].key = keys[i];
            (*records)[i].value = rand() % (INT_MAX - INT_MIN + 1) + INT_MIN;
        }
    }
}

