        let (tokens, _errors) = lexer.lex();

        let mut parser = parser::Parser::new(tokens);
        (parser.parse(), vec![])
    };

    if !errors.is_empty() {
        println!("Errors:\n{}", errors.join("\n"));
        return Err(anyhow::Error::new(errors.into()));
    }

    let ir = generate_llvm_ir("my_grammar.txt", file_cache)?;

    if cpu_time_limit > 0 && (std::time::Instant::now().duration_since(std::time::SystemTime::now())).as_secs() > cpu_time_limit {
        println!("Exceeded CPU time limit.");
        return Err(anyhow::Error::new("CPU time limit exceeded."));
    }

    Ok(ir)
}
```

