#include <pthread.h>
#include <time.h>

typedef struct {
    double temperature;
    double humidity;
    double pressure;
    int sensor_id;
    time_t timestamp;
} SensorReading;

struct queue_node {
    SensorReading data;
    struct queue_node* next;
};

typedef struct queue_node QueueNode;

struct dynamic_queue {
    QueueNode* head;
    QueueNode* tail;
    size_t size;
    pthread_mutex_t lock;
};

typedef struct dynamic_queue DynamicQueue;

DynamicQueue* create_queue() {
    DynamicQueue* queue = malloc(sizeof(DynamicQueue));
    queue->head = NULL;
    queue->tail = NULL;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);
    return queue;
}

void enqueue(DynamicQueue* queue, SensorReading reading) {
    QueueNode* new_node = malloc(sizeof(QueueNode));
    new_node->data = reading;
    new_node->next = NULL;

    pthread_mutex_lock(&queue->lock);
    if (queue->head == NULL) {
        queue->head = new_node;
        queue->tail = new_node;
    } else {
        queue->tail->next = new_node;
        queue->tail = new_node;
    }
    queue->size++;
    pthread_mutex_unlock(&queue->lock);
}

SensorReading* dequeue(DynamicQueue* queue) {
    SensorReading* reading;
    QueueNode* temp;

    pthread_mutex_lock(&queue->lock);
    if (queue->size == 0) {
        pthread_mutex_unlock(&queue->lock);
        return NULL;
    }

    reading = &queue->head->data;
    temp = queue->head;
    queue->head = queue->head->next;

    if (queue->head == NULL) {
        queue->tail = NULL;
    }

    free(temp);
    queue->size--;
    pthread_mutex_unlock(&queue->lock);

    return reading;
}

