    struct _NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_LIST_SIZE 10000

void populateNfapiPduList(NFAPI_CRC_INDICATION_PDU_T **head) {
