        fprintf(stderr, "Invalid input: N must be greater than zero.\n");
        return;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    *head = NULL;
    NFAPI_CRC_INDICATION_PDU_T **current = head;
    for (size_t i = 0; i < MAX_LIST_SIZE; ++i) {
        pthread_mutex_lock(&mutex);
        if (!*current) {
            *current = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!*current) {
                fprintf(stderr, "Error allocating memory.\n");
                pthread_mutex_unlock(&mutex);
                break;
            }
            (*current)->next = NULL;
        } else {
            current = &((*current)->next);
        }
        pthread_mutex_unlock(&mutex);

        RX_UE_INFORMATION_TAG_T *rx_ue_info = malloc(sizeof(RX_UE_INFORMATION_TAG_T));
        CRC_INDICATION_REL8_TAG_T *crc_indication = malloc(sizeof(CRC_INDICATION_REL8_TAG_T));

        if (!rx_ue_info || !crc_indication) {
            fprintf(stderr, "Error allocating memory.\n");
            free(crrc_indication);
            free(*current);
            pthread_mutex_lock(&mutex);
            *current = NULL;
            current = head;
            pthread_mutex_unlock(&mutex);
            break;
        }

        rx_ue_info->tag = rand() % 0xFFFF + 1; // Valid range: 1 - 65535
        if (rx_ue_info->tag == 0) {
            free(rx_ue_info);
            free(crc_indication);
            pthread_mutex_lock(&mutex);
            *current = NULL;
            current = head;
            pthread_mutex_unlock(&mutex);
            break;
        }

        crc_indication->CRCFLAG = (rand() % 2) == 0 ? true : false;

        pthread_mutex_lock(&mutex);
        if (!*current) {
            *current = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!*current) {
                fprintf(stderr, "Error allocating memory.\n");
                free(crc_indication);
                free(rx_ue_info);
                pthread_mutex_unlock(&mutex);
                break;
            }
            (*current)->next = NULL;
        } else {
            current = &((*current)->next);
        }
        pthread_mutex_unlock(&mutex);

        NFAPI_CRC_INDICATION_PDU_T *node = *current;
        node->rx_ue_information_tag = *rx_ue_info;
        node->rnti = rand() % 0x10000 + 1; // Valid range: 1 - 65535
        node->crc_indication_rel8_tag = *crc_indication;
    }
}
