        synchronized (node) {
            node.incrementCount();
            long startTime = System.nanoTime();
            // Implement domain parsing logic here
            long endTime = System.nanoTime();
            node.setAvgParsingTime((endTime - startTime + 1000) / 2);
        }

        totalUrlsProcessed++;
    }
}

