class NfapiCrcGenerator {
private:
    std::list<std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T>> structures;
    static std::mt19937_64 rng; // Mersenne Twister PRNG
    std::mutex mtx;
    int maxStructures = 10000;

    void generateStructure(NFAPI_CRC_INDICATION_PDU_T* structure) {
        structure->crc_indication_rel8_tag.crcFlag = (rng() % 2 == 0) ? false : true;
    }

public:
    NfapiCrcGenerator(int n) {
