void init_frame_manager() {
    manager.lock = PTHREAD_MUTEX_INITIALIZER;
    manager.frames = mmap(NULL, N * FRAME_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
}

void frame_manager_lock(FrameManager* fm) {
    pthread_mutex_lock(&fm->lock);
}

void frame_manager_unlock(FrameManager* fm) {
    pthread_mutex_unlock(&fm->lock);
}

