    return 1; // For now, we consider all frames as reliable
}

void insert_frame(FrameManager* fm, const NFAPI_RX_FRAME_INFO_T* frame) {
    if (!is_reliable(frame)) {
        return;
    }

    frame_manager_lock(fm);
    memcpy((char*)fm->frames + (fm->frames_count * FRAME_SIZE), frame, FRAME_SIZE);
    fm->frames_count++;
    frame_manager_unlock(fm);
}

void remove_frame(FrameManager* fm) {
    if (fm->frames_count == 0) {
        return;
    }

    frame_manager_lock(fm);
    memmove((char*)fm->frames, (char*)fm->frames + FRAME_SIZE, fm->frames_count * FRAME_SIZE);
    fm->frames_count--;
    frame_manager_unlock(fm);
