        }

        frame_manager_lock(fm);
        insert_frame(fm, &frame);
        frame_manager_unlock(fm);

        // Handle real-time processing here
    }

    return NULL;
}

void periodic_export() {
    while (1) {
        time_t current_time = time(NULL);
        if ((current_time - manager.last_export_time) >= 60) {
            export_statistics();
            manager.last_export_time = current_time;
        }
