#include <pthread.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int key;
    char buffer[256]; // Adjust the buffer size based on your requirements
} record;

struct records_list {
    record* records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
};

record* create_records(size_t count) {
    struct records_list* list = malloc(sizeof(*list));
    if (!list) return NULL;

    list->capacity = count;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);

    list->records = calloc(count, sizeof(record));
    if (!list->records) {
        free(list);
        return NULL;
    }

    return &list->records[0];
}

char* create_buffer(int key, int offset) {
    size_t len = strlen(KEY_PREFIX) + abs(key) * offset + 1; // Adjust KEY_PREFIX and offset values as needed
    char* buffer = malloc(len);
    if (!buffer) return NULL;

    snprintf(buffer, len, KEY_PREFIX"%d%0*d", key, offset, key);
    return buffer;
}

void fill_record(struct records_list* list, size_t index, const char* key, int offset) {
    pthread_mutex_lock(&list->mutex);

    record* record = &list->records[index];
    if (create_buffer(key, offset)) {
        strncpy(record->buffer, create_buffer(key, offset), sizeof(record->buffer));
        record->key = key;
        list->count++;
    } else {
        free(list->records[index].buffer);
    }

    pthread_mutex_unlock(&list->mutex);
}

void destroy_records(record* records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(records[i].buffer);
    }
    free(records);
}

// Thread-safe function that dynamically allocates and initializes multiple record structures based on the requested count.
record* create_and_initialize_records(size_t count, const char* key, int offset) {
    record* records = create_records(count);
    if (!records) return NULL;

    for (size_t i = 0; i < count && i < size_t(key); ++i) {
        fill_record(records, i, key + i, offset);
    }

    return records;
}
```

