struct filename_context {
    uintmax_t timestamp;
    char hash[8]; // 128-bit hash, assuming SHA-256 is sufficient for collision resistance
    sem_t conflict_sem;
};

void generate_hash(const char *filename, char *hash) {
    // Implement your preferred hashing algorithm here, such as SHA-256.
    // Note: This example uses a simplified hash function for demonstration purposes only.
    for (size_t i = 0; i < strlen(filename); ++i) {
        hash[i % 8] ^= filename[i];
    }
}

char *generate_unique_filename(const char *input_filename, size_t max_length) {
    static struct filename_context context = {};
    static pthread_key_t key;

    if (!context.timestamp || !context.hash[0]) {
        gettimeofday(&context.timestamp, NULL);
        generate_hash(input_filename, context.hash);
        pthread_once(&key, []() { context.conflict_sem = sem_init(PTHREAD_PROCESS_PRIVATE, 1, 1); });
    }

    char *unique_filename = mmap(NULL, max_length, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    snprintf(unique_filename, max_length, "%s_%llu_%.*s.new", input_filename, context.timestamp.tv_sec, 3, context.hash);

    if (fnmatch("*.new", unique_filename, 0) != 0) {
        sem_wait(&context.conflict_sem);
        // If the filename is still in use, try again with a different hash and timestamp.
        generate_unique_filename(unique_filename, max_length);
    }

    return unique_filename;
}
