uintmax_t hashFunction(uintmax_t key) {
    uintmax_t hash = 5381;
    uintmax_t i;

    for (i = 0; key != 0 && i < sizeof(key) * 8; ++i) {
        hash = ((hash << 5) + hash) + key[i];
    }

    return hash % MAX_MEMORY;
}

void initializeHashTable(Record*** table, size_t* offsets, uintmax_t maxMemory, size_t* capacity) {
    *table = malloc(maxMemory / sizeof(**table));
    *capacity = maxMemory / sizeof((**table)[0]);

    for (size_t i = 0; i < maxMemory; ++i) {
        (*table)[i] = NULL;
        offsets[i] = UINTMAX_MAX;
    }
}

Record* findRecord(Record** table, uintmax_t key, size_t* offsets, size_t capacity) {
    uint64_t hashIndex = hashFunction(key) % capacity;

    for (size_t i = 0; i < capacity; ++i) {
        if ((!table[hashIndex][i]) || table[hashIndex][i]->key == key)
            return table[hashIndex][i];

        hashIndex = (hashIndex + 1) % capacity;
    }

    return NULL;
}

void insertRecord(Record** table, uintmax_t key, int value, size_t* offsets, size_t capacity) {
    Record* newRecord = malloc(sizeof(Record));
    newRecord->value = value;
    newRecord->key = key;

    if (!newRecord) {
        printf("Memory allocation failure.\n");
        return;
    }

    uint64_t hashIndex = hashFunction(key) % capacity;

    for (size_t i = 0; i < capacity; ++i) {
        if (!table[hashIndex][i]) {
            table[hashIndex][i] = newRecord;
            offsets[hashIndex * sizeof(Record)] = offsetof(struct record, value);
            break;
        } else if (table[hashIndex][i]->key == key) {
            table[hashIndex][i]->value = value;
            break;
        }

        hashIndex = (hashIndex + 1) % capacity;
    }
}

void freeHashTable(Record** table, size_t* offsets, size_t capacity) {
    for (size_t i = 0; i < capacity; ++i) {
        Record* record = table[i];

        while (record) {
            Record* next = record->next;
            free(record);
            record = next;
        }
    }

    free(table);
}

void manageRecords(size_t maxMemory, size_t maxRecords, int minValue, int maxValue) {
    Record** table;
    size_t* offsets;
    size_t capacity = maxMemory / sizeof((**table)[0]);

    initializeHashTable(&table, &offsets, maxMemory, &capacity);

    srand(time(NULL));
    size_t recordsCount = 0;

    while (recordsCount < maxRecords) {
        uintmax_t key = rand() % UINTMAX_MAX; // Use your preferred method for generating unique keys.
        int value = minValue + (rand() % (maxValue - minValue + 1));

        Record* record = findRecord(table, key, offsets, capacity);

        if (!record) {
            insertRecord(table, key, value, offsets, capacity);
            ++recordsCount;
        } else if (record->value != value) { // Handle invalid input or incomplete records.
            printf("Data inconsistency detected.\n");
        }
    }

    freeHashTable(table, offsets, capacity);
}
