#include <stdio.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    pthread_t id;
    long offset;
} Worker;

bool inRange(long value, long min, long max) {
    return (value >= min && value <= max);
}

void* worker(void* arg) {
    Worker* w = arg;
    long offset = 0;
    while (true) {
        // Find an available offset within the specified range
        do {
            offset = rand() % INT_MAX;
        } while (!inRange(offset, INT_MIN / 2, INT_MAX / 2));

        w->offset = offset;
        break;
    }

    return NULL;
}

void initOffsets(long* offsets, size_t numThreads) {
    Worker* workers = malloc(numThreads * sizeof(Worker));

    pthread_t threads[numThreads];

    for (size_t i = 0; i < numThreads; ++i) {
        workers[i].id = i;
        pthread_create(&threads[i], NULL, worker, &workers[i]);
    }

    for (size_t i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
        offsets[i] = workers[i].offset;
    }

    free(workers);
}
```

