use std::collections::HashMap;
use serde::{Deserialize, Serialize};
use serde_json::to_string_pretty;
use std::fs;
use std::thread;
use std::sync::{Arc, Mutex};

#[derive(Serialize, Deserialize)]
struct Record {
    key: i32,
    timestamp: i64,
    offset: i128,
}

static RECORDS: Arc<Mutex<HashMap<i32, Record>>> = Arc::new(Mutex::new(HashMap::new()));

pub fn add_record(key: i32, timestamp: i64, offset: i128) {
    let mut records = RECORDS.lock().unwrap();

    // Find an available key within the specified range
    let key = find_available_key(&mut *records);

    let record = Record {
        key,
        timestamp,
        offset,
    };

    *records.entry(key).or_insert(record) = record;
}

fn find_available_key(records: &mut HashMap<i32, Record>) -> i32 {
    let mut available_keys = Vec::new();

    for key in 0..i32::MAX {
        if !records.contains_key(&key) {
            available_keys.push(key);
        }
    }

    if available_keys.len() > 0 {
        return available_keys[rand::thread_rng().gen_range(0, available_keys.len())];
    } else {
        panic!("No available keys found.");
    }
}
```

