['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    float value;
    char identifier[32];
    struct dependency* dependencies;
} entry;

struct dependency {
    void* data;
    struct dependency* next;
};

void init_arrays(size_t* float_array, size_t* char_array, entry** entries, size_t capacity, size_t batch_size) {
    *float_array = (float*)malloc(capacity * batch_size * sizeof(float));
    if (*float_array == NULL) {
        fprintf(stderr, "Memory allocation for float array failed.\n");
        exit(EXIT_FAILURE);
    }

    *char_array = (char*)calloc(capacity * batch_size, sizeof(char));
    if (*char_array == NULL) {
        free(*float_array);
        fprintf(stderr, "Memory allocation for char array failed.\n");
        exit(EXIT_FAILURE);
    }

    *entries = malloc(capacity * batch_size * sizeof(entry));
    if (*entries == NULL) {
        free(*char_array);
        free(*float_array);
        fprintf(stderr, "Memory allocation for entry array failed.\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < capacity * batch_size; ++i) {
        (*entries)[i].value = (float)(rand() / RAND_MAX * 100.0);
        sprintf((*entries)[i].identifier, "%lu", i);
        (*entries)[i].dependencies = NULL;
    }
}

void add_dependency(entry* entry, void* data) {
    struct dependency* new_dependency = malloc(sizeof(struct dependency));
    if (new_dependency == NULL) {
        fprintf(stderr, "Memory allocation for new dependency failed.\n");
        return;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    new_dependency->data = data;
    new_dependency->next = entry->dependencies;
    pthread_mutex_lock(&lock);
    entry->dependencies = new_dependency;
    pthread_mutex_unlock(&lock);
}

void release_resources(size_t* float_array, size_t* char_array, entry** entries) {
    free(*float_array);
    free(*char_array);
    free(*entries);
}
```

