// Global variables
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int rate_limit = 1000; // Per minute limit for log entries
static int limit_interval = 60; // Limit interval in seconds (1 minute)
static int current_count = 0; // Current log count
static time_t last_reset = 0; // Last reset time

// Logging severity levels
enum Severity { INFO, WARNING, ERROR };

// Thread-safe snprintf function
int thread_snprintf(char *buf, size_t len, const char *format, ...) {
    va_list args;
    int ret;

    pthread_mutex_lock(&mutex);
    ret = vsnprintf(buf, len, format, va_start(args, format));
    va_end(args);
    pthread_mutex_unlock(&mutex);

    return ret < 0 ? -1 : ret;
}

// Logging function for a given severity level
void log(enum Severity level, const char *format, ...) {
    char buf[4096];
    int len = thread_snprintf(buf, sizeof(buf), format);

    if (len < 0 || current_count >= rate_limit) return;

    // Your implementation for asynchronous logging to multiple destinations
    // ...

    current_count++;
    time_t now = time(NULL);
    if ((now - last_reset) >= limit_interval) {
        last_reset = now;
        current_count = 0;
    }
}
