    if (!records) {
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }

    long offsets[size];
    int keys[size];

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand_range(0, 10000);
        keys[i] = rand_range(1, 5000);
    }

