        unsigned long seed;
        if (EXTERNAL_DATA_SOURCE) {
            // Replace with logic for getting the shuffle seed from external data source
        } else {
            init_shuffle_seed(&seed);
        }

        for (size_t i = size - 1; i > 0; --i) {
            size_t j = rand() % (i + 1);

            long temp_offset = offsets[i];
            int temp_key = keys[i];
            bool temp_active = records[i].active;

            offsets[i] = offsets[j];
            keys[i] = keys[j];
            records[i].active = records[j].active;

            offsets[j] = temp_offset;
            keys[j] = temp_key;
            records[j].active = temp_active;
        }
    }

    for (size_t i = 0; size > MAX_RECORDS && i < size - 1; ++i) {
        free(records + i);
        --size;
    }

    for (size_t i = 0; i < size; ++i) {
        records[i].offset = offsets + i;
        records[i].key = keys + i;
        records[i].active = true;
    }

    return records;
}

