#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>
#include <time.h>

typedef struct {
    int value;
    long offset;
} Record;

struct shared_data {
    long *offsets;
    int *keys;
    Record *records;
    size_t capacity;
    size_t used;
    pthread_mutex_t mutex;
};

static struct shared_data* init_memory(size_t offset_capacity, size_t key_capacity, size_t record_capacity, size_t max_key_sum) {
    struct shared_data *data = mmap(NULL, sizeof(struct shared_data), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (data == MAP_FAILED) {
        return NULL;
    }

    data->offsets = data + 1;
    data->keys = (long*)((char*)data->offsets + sizeof(long) * offset_capacity);
    data->records = (Record*)((char*)data->keys + sizeof(int) * key_capacity);

    pthread_mutex_init(&data->mutex, NULL);
    data->capacity = offset_capacity;
    data->used = 0;

    return data;
}

static long get_available_key_sum(struct shared_data *data) {
    return data->capacity * (data->capacity - data->used) - data->used;
}

static void* generate_random_values(void *arg) {
    struct shared_data *data = arg;
    while (get_available_key_sum(data) > 0 && get_available_key_sum(data) < data->capacity * 2) {
        long offset = rand() % data->capacity;
        int key = rand() % *((int*)data);

