['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    int value;
    long offset;
    int metadata;
} Record;

// LRU cache structure
struct CacheNode {
    Record* record;
    struct CacheNode* next;
};

typedef struct CacheNode CacheNode;

void lru_cache_add(CacheNode** head, CacheNode* node) {
    if (*head == NULL) {
        *head = node;
        return;
    }

    // Insert at the beginning of the list
    node->next = *head;
    *head = node;
}

void lru_cache_remove(CacheNode** head, CacheNode* node) {
    if (*head == node) {
        *head = node->next;
        return;
    }

    CacheNode* current = *head;
    while (current && current->next != node) {
        current = current->next;
    }

    if (current) {
        current->next = node->next;
    }
}

void lru_cache_evict(CacheNode** head, size_t max_size) {
    CacheNode* to_remove = NULL;
    CacheNode* current = *head;
    size_t count = 0;

    while (current && ++count > max_size) {
        to_remove = current;
        current = current->next;
    }

    if (to_remove) {
        lru_cache_remove(head, to_remove);
        free(to_remove->record);
        free(to_remove);
    }
}

Record* create_record(long offset, int value, int metadata) {
    Record* record = malloc(sizeof(Record));
    if (!record) {
        perror("Out of memory");
        return NULL;
    }

    record->offset = offset;
    record->value = value;
    record->metadata = metadata;

    return record;
}

CacheNode* create_cache_node(Record* record) {
    CacheNode* node = malloc(sizeof(CacheNode));
    if (!node) {
        perror("Out of memory");
        free(record);
        return NULL;
    }

    node->record = record;
    node->next = NULL;
    return node;
}

Record* init_memory(size_t offsets_size, size_t keys_size, size_t records_size, size_t metadata_size, int min_metadata, int max_key_sum) {
    if (max_key_sum * (keys_size + 1) > INT_MAX) {
        fprintf(stderr, "Error: Maximum key sum exceeds the maximum integer value\n");
        return NULL;
    }

    long* offsets = malloc(offsets_size * sizeof(long));
    if (!offsets) {
        perror("Out of memory");
        return NULL;
    }

    int* keys = malloc(keys_size * sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Out of memory");
        return NULL;
    }

    Record* records = malloc(records_size * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        perror("Out of memory");
        return NULL;
    }

    int* metadata = malloc(metadata_size * sizeof(int));
    if (!metadata) {
        free(offsets);
        free(keys);
        free(records);
        perror("Out of memory");
        return NULL;
    }

    CacheNode* cache_head = NULL;
    size_t current_cache_size = 0;

    // Initialize keys with unique random values within the specified range
    for (int i = 0; i < keys_size; ++i) {
        int key;
        do {
            key = rand() % max_key_sum;
        } while (keys_contains(keys, key, keys_size));

        keys[i] = key;

        // Check if we can create a new record without exceeding the cache limit or memory constraints
        if ((current_cache_size + 1) > records_size) {
            lru_cache_evict(&cache_head, current_cache_size);
        }

        if (cache_head) {
            // Evict the least recently used record from the cache
            lru_cache_remove(&cache_head, cache_head->next);
        }

        Record* new_record = create_record(0, keys[i], rand() % (INT_MAX - min_metadata + 1) + min_metadata);
        if (!new_record) {
            free(offsets);
            free(keys);
            free(records);
            free(metadata);
            perror("Out of memory");
            return NULL;
        }

        // Add the new record to the cache and update its offset value based on the current index in the keys array
        CacheNode* new_cache_node = create_cache_node(new_record);
        if (!new_cache_node) {
            free(new_record);
            free(offsets);
            free(keys);
            free(records);
            free(metadata);
            perror("Out of memory");
            return NULL;
        }

        lru_cache_add(&cache_head, new_cache_node);

        current_cache_size++;
    }

    // Calculate offsets for the records based on their associated keys
    for (int i = 0; i < records_size; ++i) {
        if (cache_head && cache_head->next) {
            Record* record = cache_head->next->record;
            if (i == record->offset) {
                offsets[record->offset] = i;
            }
            cache_head = cache_head->next->next;
        } else {
            break;
        }
    }

    return records;
}

bool keys_contains(const int* keys, int key, size_t keys_size) {
    for (int i = 0; i < keys_size; ++i) {
        if (keys[i] == key) {
            return true;
        }
    }
    return false;
}
