import requests
from functools import lru_cache
import json
import os

@lru_cache(maxsize=128)
def get_weather_data(city):
    api_key = os.environ['WEATHERAPI_KEY']
    url = f'https://api.openweathermap.org/data/2.5/weather?q={city}&appid={api_key}'
    response = requests.get(url)
    if response.status_code == 200:
        return json.loads(response.text)

@lru_cache(maxsize=128)
def get_air_quality(city):
    api_key = os.environ['AQIAPI_KEY']
    url = f'https://api.openaq.org/v1/latest?parameter=pm2.5&stationid=&category=air&sortby=value&direction=asc&limit=10&q={city}'
    response = requests.get(url)
    if response.status_code == 200:
        return json.loads(response.text)['data'][0]['result']['values']['pm2_5_ugm3']

@lru_cache(maxsize=128)
def get_traffic_data(city):
    api_key = os.environ['TRAFFICAPI_KEY']
    url = f'https://api.waze.com/maps/v1/traffic/{city}/road/{city}.json?access_token={api_key}'
    response = requests.get(url)
    if response.status_code == 200:
        return json.loads(response.text)
