    int pipefd[2];
    char buffer[128];

    if (pipe(pipefd) == -1) {
        log("Error: Failed to create pipe.", VERBOSITY_HIGH);
        return;
    }

    if ((shell_pid = fork()) < 0) {
        log("Error: Fork failed.", VERBOSITY_HIGH);
        close(pipefd[0]);
        return;
    } else if (shell_pid == 0) {
        close(pipefd[1]);
        dup2(pipefd[0], STDIN_FILENO);
        close(pipefd[0]);
        execl("/bin/sh", "/bin/sh", "-c", command, (char *) 0);
    } else {
