        waitpid(shell_pid, NULL, 0);

        ssize_t bytes_read;
        while ((bytes_read = read(pipefd[0], buffer, sizeof(buffer))) > 0) {
            // Output the result to a designated part of the user interface
            printf("%s\n", buffer);
        }
    }
}

