std::vector<record> processXML(const std::string& xmlFile, const std::string& targetTag, size_t maxRecords, int minValue, int maxValue) {
    // Seed random number generator
    std::srand((unsigned int)time(0));

    boost::property_tree::ptree tree;
    try {
        boost::property_tree::read_xml(xmlFile, tree);
    } catch (const std::exception& e) {
        std::cerr << "Error reading XML file: " << e.what() << std::endl;
        return {};
    }

    size_t recordsCount = 0;
    auto root = tree.get_child("root");
    for (auto iter = root.begin(); iter != root.end(); ++iter) {
        if (iter->second.get<std::string>() == targetTag) {
            std::vector<record> records(std::min((size_t)(maxRecords - recordsCount), 1u));
            for (auto& record : records) {
                // Dynamically allocate memory only when needed and store pointers in the vector
                record.value = minValue + std::rand() % ((maxValue - minValue) + 1);
                recordsCount++;
                if (recordsCount >= maxRecords) break;
            }
            return records;
        }
    }

    std::cerr << "No element found with tag '" << targetTag << "' or multiple elements matched." << std::endl;
    return {};
}
