#include <time.h>

typedef struct {
    int id;
    time_t timestamp;
    void* payload;
} record;

struct config {
    int min_id, max_id;
    time_t min_timestamp, max_timestamp;
};

void init_records(int N, record** records, const struct config* cfg) {
    if (!N || !records || !cfg) return;

    *records = malloc(N * sizeof(record*));
    if (!*records) {
        perror("Memory allocation error");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < N; ++i) {
        record* current = malloc(sizeof(record));
        if (!current) {
            perror("Memory allocation error");
            continue; // skip to next iteration and free previous allocations
        }

        // Use C99-style compound literals for generating random values within the specified ranges.
        current->id = cfg->min_id + (rand() % (cfg->max_id - cfg->min_id + 1));
        current->timestamp = cfg->min_timestamp + rand() % ((long int)difftime(cfg->max_timestamp, cfg->min_timestamp) + 1);
        current->payload = malloc(sizeof(void*) * (rand() % 10 + 1)); // random payload size within [1, 10] elements

        for (int j = 0; j < current->payload ? sizeof(current->payload) / sizeof(void*); ++j) {
            current->payload[j] = (void*)rand(); // random payload value
        }

        (*records)[i] = current;
    }
}
