#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    unsigned long timestamp;
    double value;
} event;

// Global variables to store total allocated memory and coordinate array usage status
size_t total_allocated = 0;
size_t coord_array_usage = 0;

// Mutex for synchronizing access to global variables
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

event* initialize_data(size_t timestamps, size_t coords, size_t events, size_t max_distance, unsigned int min_value, unsigned int max_value) {
    // Allocate memory for arrays and structures
    unsigned long *timestamps_arr = (unsigned long*) malloc(timestamps * sizeof(unsigned long));
    double *coords_arr = (double*) malloc(coords * sizeof(double));
    event *events_arr = (event*) malloc(events * sizeof(event));
    unsigned char *status_arr = (unsigned char*) calloc(coords, sizeof(unsigned char));

    if(!timestamps_arr || !coords_arr || !events_arr || !status_arr) {
        // Free allocated memory and return NULL on failure
        free(timestamps_arr);
        free(coords_arr);
        free(events_arr);
        free(status_arr);
        return NULL;
    }

    total_allocated = timestamps + coords + events + status_arr;

    // Initialize coordinate array with unique random values within the specified range
    pthread_mutex_lock(&mutex);
    coord_array_usage = coords;
    pthread_mutex_unlock(&mutex);

    srand(time(NULL));
    for (size_t i = 0; i < coords; ++i) {
        coords_arr[i] = ((double)(rand() % (max_value - min_value + 1))) + min_value;
    }

    // Check if average distance between consecutive coordinates does not exceed threshold
    double current_distance, avg_distance = 0.0;
    for (size_t i = 1; i < coords; ++i) {
        current_distance = fabs(coords_arr[i] - coords_arr[i - 1]);
        avg_distance += current_distance;

        if (current_distance > max_distance) {
            // Reset coordinates and free allocated memory if average distance exceeds threshold
            free(timestamps_arr);
            free(coords_arr);
            free(events_arr);
            free(status_arr);
            return NULL;
        }
    }
    avg_distance /= (coords - 1);

    // Populate events with random values within the given range
    for (size_t i = 0; i < events; ++i) {
        events_arr[i].timestamp = rand() % max_value;
        events_arr[i].value = ((double)(rand() % (max_value - min_value + 1))) + min_value;
    }

    return events_arr;
}
```
