#include <fcntl.h>

struct NetworkConfig {
    struct sockaddr_in addr;
    int socket;
};

void *dns_resolve(const char *hostname, void *arg) {
    struct addrinfo hints, *res = NULL, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;   /* Allow IPv4 */
    hints.ai_socktype = SOCK_STREAM;   /* TCP stream socket */

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        perror("getaddrinfo");
        return NULL;
    }

    p = res;
    while (p != NULL) {
        char ipstr[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &((struct sockaddr_in *)p)->sin_addr, ipstr, sizeof(ipstr));
        printf("IP address: %s\n", ipstr);
        p = p->ai_next;
    }
    freeaddrinfo(res);

    return NULL;
}

void setupDir(const char *appConfigPath) {
    if (appConfigPath && access(appConfigPath, F_OK | R_OK | X_OK) == 0) {
        struct stat st;
        const char *subdir = "application_data";

        if (stat(appConfigPath}/subdir", &st) != 0 || !S_ISDIR(st.st_mode)) {
            mkdir(appConfigPath "/" subdir, S_IRUSR | S_IWUSR | S_IXUSR);
        }
    } else {
        const char *rootDir = getenv("TMPDIR") ?: "/tmp";
        char appPath[PATH_MAX];
        snprintf(appPath, sizeof(appPath), "%s/app_%d", rootDir, (int)time(NULL));
        mkdir(appPath, S_IRUSR | S_IWUSR | S_IXGRP);
    }
}

void setupNetworkConfig(struct NetworkConfig *config) {
    /* Configure network settings and set up TCP socket parameters for optimal performance */

    config->socket = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (config->socket < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    int optval = 1;
    setsockopt(config->socket, SOL_SOCKET, SO_REUSEADDR, &optval, sizeof(optval));

    /* Handle high concurrent connections efficiently */
    listen(config->socket, SOMAXCONN);

    memset(&(config->addr), 0, sizeof(struct sockaddr_in));
    config->addr.sin_family = AF_INET;
    config->addr.sin_port = htons(8080); /* Set port number */
}

int networkConfigAndDirSetup() {
    const char *appConfigPath = getenv("APP_CONFIG_PATH");

    pthread_t dnsThread;
    if (pthread_create(&dnsThread, NULL, dns_resolve, "example.com") != 0) {
        perror("pthread_create");
        return -1;
    }

    setupDir(appConfigPath);

    struct NetworkConfig config;
    setupNetworkConfig(&config);

    pthread_join(dnsThread, NULL);

    /* Manage resource allocation carefully */
    free(config.addr.sin_zero);

    return 0;
}
