#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct Record {
    int key;
    struct Record *next;
} Record;

typedef struct Collection {
    Record **records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Collection;

Collection* create_collection(size_t initial_capacity) {
    Collection *collection = malloc(sizeof(Collection));
    if (!collection) {
        perror("Failed to allocate memory for collection");
        return NULL;
    }

    collection->records = calloc(initial_capacity, sizeof(Record*));
    if (!collection->records) {
        perror("Failed to allocate memory for records array");
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

bool add_record(Collection *collection, int key) {
    if (collection->size == collection->capacity) {
        // Handle resizing here if needed for scalability
    }

    pthread_mutex_lock(&collection->lock);

    Record **current = &collection->records[key % collection->capacity];
    Record *record;
    while (*current && (*current)->key < key) {
        current = &(*current)->next;
    }

    if (!*current || (*current)->key == key) {
        record = malloc(sizeof(Record));
        if (!record) {
            perror("Failed to allocate memory for record");
            pthread_mutex_unlock(&collection->lock);
            return false;
        }

        record->key = key;
        record->next = *current;
        *current = record;

        pthread_mutex_unlock(&collection->lock);
        return true;
    }

    pthread_mutex_unlock(&collection->collection->lock);
    return false;
}

void destroy_collection(Collection *collection) {
    if (!collection) {
        return;
    }

    for (size_t i = 0; i < collection->capacity; ++i) {
        Record *current = collection->records[i];
        while (current != NULL) {
            Record *next = current->next;
            free(current);
            current = next;
        }
    }

    free(collection->records);
    free(collection);
}
```

