#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <sys/mman.h>

typedef struct wifi_client {
    char bssid[6];
    int channel;
    int signal_strength;
    int quality_metric;
    pthread_mutex_t lock;
} wifi_client_t;

#define MAX_CLIENTS 500
#define CACHE_LINE_SIZE 64

void init_wifi_clients(wifi_client_t** clients, size_t num_clients) {
    *clients = mmap(NULL, (num_clients * sizeof(wifi_client_t) + CACHE_LINE_SIZE - 1), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (*clients == MAP_FAILED) {
        perror("mmap failed");
        exit(1);
    }

    size_t client_size = sizeof(wifi_client_t);
    size_t cache_line_offset = ((uintptr_t)*clients % CACHE_LINE_SIZE) + (CACHE_LINE_SIZE - client_size);
    for (size_t i = 0; i < num_clients; ++i) {
        (*clients)[i].bssid[0] = '\0';
        (*clients)[i].channel = 0;
        (*clients)[i].signal_strength = 0;
        (*clients)[i].quality_metric = 0;
        pthread_mutex_init(&(*clients)[i].lock, NULL);

        if (i != 0 && ((uintptr_t)(*clients + i) % CACHE_LINE_SIZE == cache_line_offset)) {
            memset((*clients) + i, 0, client_size);
        }
    }
}

void deinit_wifi_clients(wifi_client_t* clients, size_t num_clients) {
    munmap((void*)clients, (num_clients * sizeof(wifi_client_t) + CACHE_LINE_SIZE - 1));
}
