#include <boost/property_tree/ptree.hpp>
#include <boost/random.hpp>
#include <boost/thread/mutex.hpp>
#include <boost/assign/list_of.hpp>

namespace pt = boost::property_tree;
using Record = std::pair<int, std::string>;
using RecordArray = std::vector<Record>;
using IdCache = std::map<std::string, int>;

class IdGenerator {
public:
    int getNextId() {
        if (!idPool_.empty()) {
            auto idIt = idPool_.lower_bound(nextId_);
            if (idIt != idPool_.end() && idIt->first >= nextId_) {
                auto id = idIt->second;
                idPool_.erase(idIt);
                return id;
            }
        }
        return nextGen_(rng_);
    }

    int getUniqueId(const std::string& identifier) {
        auto it = uniqueIds_.find(identifier);
        if (it != uniqueIds_.end())
            return it->second;

        int id = getNextId();
        uniqueIds_[identifier] = id;
        return id;
    }

private:
    IdCache idPool_;
    std::map<std::string, int> uniqueIds_;
    int nextId_ = 0;
    boost::mt19937 rng_;

    int nextGen_(boost::uniform_int<> &d) {
        static boost::uniform_int<> idGen(0, MAX_ID);
        return idGen();
    }
};

RecordArray parseXml(const std::string& xmlData, const std::string& namespacePrefix, const std::string& localName) {
    IdGenerator idGen;
    RecordArray records;
    pt::ptree tree;

    try {
        pt::read_xml(xmlData, tree);

        auto ns = pt::namespaces().get_namespace<std::string>(namespacePrefix);
        auto it = tree.get<pt::ptree>("/" + localName, ns).begin();
        if (it == tree.end()) {
            std::cerr << "Error: No matching element found." << std::endl;
            return {};
        }

        IdCache recordIds;
        for (const auto& node : it) {
            int id = idGen.getUniqueId(node.path());
            records.emplace_back(id, node.path().c_str());
        }
    } catch (std::exception& e) {
        std::cerr << "Error: XML parsing failed: " << e.what() << std::endl;
        return {};
    }

    return records;
}
