Compound* create_compounds(int N, Compound** compounds) {
    if (N <= 0 || compounds == NULL) return NULL;

    *compounds = malloc(sizeof(Compound) * N);

    if (!(*compounds)) {
        perror("malloc failed");
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        (*compounds)[i].record.value = -1; // Indicator of uninitialized value
    }

    return *compounds;
