void destroy_compounds(Compound* compounds, int N) {
    if (!compounds || N <= 0) return;

    free(compounds);
}

Compound* init_compound(Compound* compound, const time_t timestamp, short tag) {
    if (!compound) return NULL;

    if (compound->record.value == -1) { // Prevent reinitialization of an already initialized compound
        compound->timestamp = timestamp;
        compound->tag = tag;
        compound->record.value = 0; // Indicator of initialized value
    }

    return compound;
}

void lock_free_queue* my_lock_free_queue; // Assume a custom lock-free queue implementation is defined elsewhere

int add_compound(Compound* new_compound) {
    if (!my_bounded_wait_add(&my_lock_free_queue, new_compound)) {
