        return -1;
    }

    return 0;
}

Compound* get_compound() {
    Compound* compound = my_lock_free_queue.pop(); // Assume a custom lock-free queue pop implementation is defined elsewhere

    if (!compound) return NULL;

    return compound;
}

void graceful_shutdown(void) {
    while (my_lock_free_queue.size() > 0) {
        Compound* compound = get_compound(); // Drain queue before freeing resources

