using System;
using System.Collections.Concurrent;
using System.Runtime.Serialization;
using System.Runtime.Serialization.Formatters.Binary;
using System.Text;

[Serializable]
public class DataObject
{
    public string Name { get; set; }
    public double Value { get; set; }
    public bool Status { get; set; }
}

public class DataManager
{
    private ConcurrentDictionary<string, DataObject> _dataObjects;

    public DataManager()
    {
        _dataObjects = new ConcurrentDictionary<string, DataObject>();
    }

    public void Add(DataObject dataObject) => _dataObjects.AddOrUpdate(dataObject.Name, dataObject, (name, oldDataObject) => oldDataObject ?? dataObject);

    public bool Remove(string name) => _dataObjects.TryRemove(name, out _);

    public DataObject GetByName(string name) => _dataObjects.GetOrAdd(name, _ => new DataObject { Name = name });

    public void Update(DataObject updatedDataObject)
    {
        if (_dataObjects.TryUpdate(updatedDataObject.Name, updatedDataObject, updatedDataObject))
        {
            // Handle update success
        }
        else
        {
            // Handle update failure (object not found)
        }
    }

    public void Serialize(string filePath)
    {
        using var ms = new MemoryStream();
        var formatter = new BinaryFormatter();
        formatter.Serialize(ms, _dataObjects);
        File.WriteAllBytes(filePath, ms.ToArray());
    }

    public void Deserialize(string filePath)
    {
        using var ms = new MemoryStream(File.ReadAllBytes(filePath));
        var formatter = new BinaryFormatter();
        _dataObjects.Clear();
        while (ms.Position < ms.Length)
        {
            _dataObjects[formatter.Deserialize<DataObject>(ms).Name] = formatter.Deserialize<DataObject>(ms);
        }
    }

    public override string ToString()
    {
        var totalValue = 0.0;
        var nonZeroCount = 0;
        foreach (var dataObject in _dataObjects.Values)
        {
            totalValue += dataObject.Value;
            if (dataObject.Value > 0)
                nonZeroCount++;
        }

        return $"DataManager: Count={_dataObjects.Count}, TotalSum={totalValue}, AverageNonZeroValue={nonZeroCount > 0 ? totalValue / nonZeroCount : 0}";
    }
}
```
