static pthread_mutex_t fallback_mutex = PTHREAD_MUTEX_INITIALIZER;
static sem_t fallback_semaphore = SEM_INITIALIZE(&fallback_mutex, 1);
static Record* fallback_pool = NULL;
static int fallback_pool_size = 0;
static size_t pooled_records = 0;

Record* initializeRecords(int N, Record*** records, const Config* config) {
    // Allocate memory for array of pointers to records and fill with NULL pointers
    *records = malloc(N * sizeof(Record*));
    if (!(*records)) {
        perror("Memory allocation failed");
        return NULL;
    }

    memset(*records, 0, N * sizeof((*records)[0]));

    // Allocate memory for individual records and initialize them with random values within the specified ranges
    Record** current_record = *records;
    for (int i = 0; i < N; ++i) {
        if (!current_record[i]) {
            current_record[i] = generate_record();
            if (!current_record[i]) {
                perror("Memory allocation failed");
                // Free previously allocated memory and return error
                for (int j = 0; j < i; ++j) free(current_record[j]);
                free(*records);
                *records = NULL;
                return NULL;
            }
        }
    }

    // Log initialization success or failure
    if (*records)
        log_message("Initialization successful");
    else
        log_message("Initialization failed");

    return *records;
}

Record* generate_record(void) {
    Record* record = malloc(sizeof(Record));
    if (!record) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Use fallback mechanism when external API is not available or responds slowly
    sem_wait(&fallback_semaphore);
    int num_pooled = pooled_records;
    if (num_pooled > 0) {
        pooled_records--;
        fallback_pool[pooled_records].data = NULL; // Release the data for this record to be reused
        record = &fallback_pool[pooled_records];
    } else {
        pthread_mutex_lock(&fallback_mutex);
        if (fallback_pool_size < N) {
            fallback_pool_size += 100; // Adjust the pool size based on expected number of records
            fallback_pool = realloc(fallback_pool, fallback_pool_size * sizeof(Record));
            if (!fallback_pool) {
                perror("Memory allocation failed");
                pthread_mutex_unlock(&fallback_mutex);
                return NULL;
            }
        }
        record = &fallback_pool[fallback_pool_size - 1];

        // Generate identifier and timestamp using local algorithms as a fallback
        generate_identifier_and_timestamp(record, config);
    }
    pthread_mutex_unlock(&fallback_mutex);

    return record;
}

void generate_identifier_and_timestamp(Record* record, const Config* config) {
    // Call external API for generating unique identifiers and timestamps
    // ...

    // Fallback mechanism for when the external API is not available or responds slowly
    if (!record->id || !record->timestamp) {
        pthread_mutex_lock(&fallback_mutex);
        record->id = config->min_id + rand() % (config->max_id - config->min_id + 1);
        record->timestamp = time(NULL);
        pthread_mutex_unlock(&fallback_mutex);
    }
}

void log_message(const char* message) {
    // Logging implementation here, such as writing to a file or sending to a logging service
}
