#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <limits.h>
#include <external_library.h> // Replace with your actual external library header

typedef struct Record {
    int key;
    long offset;
    struct Record *next;
} Record;

Record* create_record() {
    Record *r = (Record*)malloc(sizeof(Record));
    if (!r) return NULL;
    r->key = rand() % MAX_INT;
    r->offset = 0;
    r->next = NULL;
    return r;
}

void link_records(Record **head, Record *new_record) {
    if (*head == NULL) {
        *head = new_record;
        return;
    }
    Record *curr = *head;
    while (curr->next != NULL) curr = curr->next;
    curr->next = new_record;
}

void process_batch(Record **head, int batch_size, external_library_function_t function) {
    if (head == NULL || batch_size <= 0) return;

    Record *curr = *head;
    Record *temp;
    for (int i = 0; i < batch_size && curr != NULL; ++i) {
        temp = curr;
        curr = curr->next;
        function(temp->key, temp->offset); // Replace with your actual external library function call
        free(temp);
    }

    if (curr != NULL) *head = curr;
}

void cleanup_records(Record **head) {
    Record *curr = *head;
    while (*head != NULL) {
        curr = *head;
        *head = curr->next;
        free(curr);
    }
}

void manage_memory(int record_count, int batch_size, int min_alloc_size, external_library_function_t function) {
    Record **records_head = NULL;
    Record *current_batch = NULL;
    int current_batch_size = 0;

    srand(time(NULL));

    for (int i = 0; i < record_count; ++i) {
        Record *new_record = create_record();
        if (!new_record) {
            cleanup_records(&current_batch);
            printf("Memory allocation failure.\n");
            return;
        }
        link_records(&records_head, new_record);

        if (++current_batch_size >= min_alloc_size || i == record_count - 1) {
            process_batch(&current_batch, current_batch_size, function);
            current_batch = NULL;
            current_batch_size = 0;
        }
    }

    if (current_batch != NULL && current_batch_size > 0)
        process_batch(&current_batch, current_batch_size, function);

    cleanup_records(&records_head);
}
```
