    for (size_t i = 0; i < size; ++i) {
        array[i] = -1;
    }
    return array;
}

int* createKeyArray(size_t size) {
    int* array = malloc(sizeof(int) * size);
    for (size_t i = 0; i < size; ++i) {
        array[i] = -1;
    }
    return array;
}

void initRecords(node** records, long* offsets, int* keys, size_t count, int min, int max) {
    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        node* current = records[i];
        if (!current) {
            current = malloc(sizeof(node));
            current->next = NULL;
            records[i] = current;
        }
        current->data.value = rand() % (max - min + 1) + min;
        if (offsets[-1] == -1) {
            offsets[-1] = i;
        } else {
            current->data.offset = offsets[i - 1] + 1;
        }
        current->data.key = keys[i];
    }
}

void freeRecords(node** records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        node* temp = records[i];
        while (temp != NULL) {
            node* next = temp->next;
            free(temp);
            temp = next;
        }
    }
    free(records);
}
