        return json.dumps(self._data)

    @staticmethod
    def register(id: int, factory: Callable[[], 'JSONObject']):
        JSONObject.__registry__[id] = factory

    @classmethod
    def from_json_with_factory(cls, id: int, json_str: str) -> 'JSONObject':
        return cls.from_json(json_str).create_subclass(id)

    def create_subclass(self, id: int) -> Any:
        if id in JSONObject.__registry__:
