typedef struct {
    size_t length;
    char* data;
} Line;

Line* read_line(FILE* file) {
    char c;
    Line* line = malloc(sizeof(Line));
    line->length = 0;
    while ((c = fgetc(file)) != EOF) {
        line->data = realloc(line->data, ++line->length);
        line->data[line->length - 1] = c;
    }
    line->data[line->length] = '\0';
    return line;
}

void write_average(FILE* output_file, Line* line) {
    if (line->length < 3) return;
    fprintf(output_file, "%s\n", &line->data[line->length - 2]);
}

int main(int argc, char** argv) {
    FILE* input_file = fopen(argv[1], "r");
    if (!input_file) return 1;

    FILE* output_file = fopen(argv[2], "w");
    if (!output_file) return 1;

    Line* current_line;
    while ((current_line = read_line(input_file))) {
        write_average(output_file, current_line);
        free(current_line);
    }

    fclose(input_file);
    fclose(output_file);
    return 0;
}
