    pthread_cond_t task_queue_cond;
    size_t max_concurrency;
    size_t current_concurrency;
    Queue pending_tasks;
};

void *transcode(void *arg) {
    TranscodeTask *task = arg;
    // Perform transcoding using third-party library
    // Handle errors and log detailed messages for debugging purposes

    free(task->video_file);
    free(task);
    return 0;
}

int transcode_video(char *video_file, char *output_dir, void *config, Queue queue) {
    struct transcoder *transcoder = calloc(1, sizeof(*transcoder));
    pthread_mutex_init(&transcoder->task_queue_mutex, NULL);
    pthread_cond_init(&transcoder->task_queue_cond, NULL);
    transcoder->max_concurrency = 4; // Adjust this value based on system resources and desired throughput
    transcoder->current_concurrency = 0;
    transcoder->pending_tasks = queue;

    TranscodeTask *task = calloc(1, sizeof(*task));
    task->video_file = video_file;
    task->output_dir = output_dir;
    task->config = config;

    while (true) {
        pthread_mutex_lock(&transcoder->task_queue_mutex);
        if (!Queue_empty(transcoder->pending_tasks)) {
            Task *current_task = Queue_dequeue(transcoder->pending_tasks);
            task = (TranscodeTask *) current_task;
            if (transcoder->current_concurrency < transcoder->max_concurrency) {
                pthread_t transcode_thread;
                pthread_create(&transcode_thread, NULL, transcode, task);
                transcoder->current_concurrency++;
            } else {
                pthread_cond_wait(&transcoder->task_queue_cond, &transcoder->task_queue_mutex);
            }
        } else {
            pthread_mutex_unlock(&transcoder->task_queue_mutex);
            break;
        }
        pthread_mutex_unlock(&transcoder->task_queue_mutex);
    }

    free(transcoder);
    return 0;
}
