#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/mman.h>

typedef struct {
    int value;
} record;

// Custom malloc function with configuration options
void* custom_malloc(size_t size, size_t alignment, size_t min_free) {
    void* ptr = mmap(NULL, size + alignment, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }

    size_t usable_size = ((uintptr_t)ptr + alignment - 1) & ~((uintptr_t)alignment - 1);
    if (usable_size < size) {
        munmap(ptr, size + alignment);
        fprintf(stderr, "Error: Insufficient memory\n");
        return NULL;
    }

    if ((uintptr_t)ptr % min_free != 0) {
        munmap(ptr, size + alignment);
        fprintf(stderr, "Error: Minimum free space constraint not met\n");
        return NULL;
    }

    return ptr;
}

void init_data_structures(int n, int m, size_t total_memory_limit, int min_value, int max_value, FILE* log_fd) {
    // Allocate long array for offset values
    long* offsets = custom_malloc((n + alignof(long) - 1) & ~(alignof(long) - 1), alignof(long), total_memory_limit);
    if (!offsets) return;

    // Allocate int array for keys
    int* keys = custom_malloc((n + alignof(int) - 1) & ~(alignof(int) - 1), alignof(int), total_memory_limit);
    if (!keys) {
        free(offsets);
        return;
    }

    // Allocate record array
    record* records = custom_malloc((m + alignof(record) - 1) & ~(alignof(record) - 1), alignof(record), total_memory_limit);
    if (!records) {
        free(offsets);
        free(keys);
        return;
    }

    // Initialize random number generator with reproducible seed
    srand(time(NULL));

    // Initialize offset values and keys
    for (int i = 0; i < n; ++i) {
        offsets[i] = i;
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
    }

    // Initialize record values
    for (int i = 0; i < m; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Log initial memory usage
    fprintf(log_fd, "Initial allocation:\n");
    fprintf(log_fd, "- offsets: %zu bytes\n", (size_t)((n + alignof(long) - 1) & ~(alignof(long) - 1)));
    fprintf(log_fd, "- keys: %zu bytes\n", (size_t)((n + alignof(int) - 1) & ~(alignof(int) - 1)));
    fprintf(log_fd, "- records: %zu bytes\n", (size_t)((m + alignof(record) - 1) & ~(alignof(record) - 1)));
}
```
This code creates a custom malloc function that takes into account alignment requirements and minimum free space between allocations. The init_data_structures function initializes the long, int, and record arrays with random values while adhering to the given constraints. It also logs the initial memory usage for each data structure at the beginning of its execution.']

