typedef struct {
    AES_KEY aes_ctx;
    unsigned char iv[AES_BLOCK_SIZE];
} gcm_context;

static semaphore_t cipher_mutex; // Mutex for synchronizing context creation and destruction
static size_t num_ciphers = 0;     // Total number of created cipher contexts
static pthread_key_t key_ctx = PTHREAD_KEY_NULL;  // Thread-specific storage for cipher context

void aes256gcm_init_fallback(const unsigned char *password, size_t length, AES_GCM *cipher) {
    // Fast path for performance-critical conditions
}

int aes256gcm_init(const unsigned char *password, size_t length, AES_GCM *cipher, bool optimized) {
    if (optimized) {
        if (aes256gcm_init_fallback(password, length, cipher)) {
            return 0;
        }
    }

    // Key derivation using PBKDF2 with SHA-256
    unsigned char derived_key[AES_KEYSIZE];
    const int salt_length = 8;
    unsigned char salt[salt_length];
    RAND_bytes(salt, salt_length);

    PKCS5_PBKDF2_HMAC(EVP_sha256(), password, length, salt, salt_length, PBKDF2_ITER_COUNT, derived_key, AES_KEYSIZE);

    // IV generation
    RAND_bytes(cipher->iv, AES_BLOCK_SIZE);

    // Cipher initialization with derived key and IV
    AES_set_encrypt_key(derived_key, AES_KEYSIZE, &cipher->mac_key);
    AES_GCM_set(cipher, derived_key, cipher->mac_key);

    sem_wait(&cipher_mutex); // Acquire mutex to manage context creation and destruction safely

    gcm_context *ctx = NULL;
    if (key_ctx != PTHREAD_KEY_NULL) {
        ctx = pthread_getspecific(key_ctx);
        num_ciphers--;
    }

    if (!ctx) {
        ctx = malloc(sizeof(gcm_context));
        if (!ctx) {
            sem_post(&cipher_mutex); // Release mutex to minimize resource contention
            ERR_print_errors_fp(stderr);
            return -1;
        }

        memcpy(ctx->iv, cipher->iv, AES_BLOCK_SIZE);
        AES_set_encrypt_key(derived_key, AES_KEYSIZE, &ctx->aes_ctx);
        AES_GCM_set(&ctx->aes_ctx, derived_key, cipher->mac_key);

        if (pthread_setspecific(key_ctx, ctx)) {
            free(ctx);
            sem_post(&cipher_mutex); // Release mutex to minimize resource contention
            ERR_print_errors_fp(stderr);
            return -1;
        }

        num_ciphers++;
    }

    *cipher = ctx->aes_ctx.encrypt;
    sem_post(&cipher_mutex); // Release mutex to minimize resource contention

    return 0;
}
```
