    int key;
    int record;
} Record;

#define MAX_RECORDS 100000

Record* offsets;
int* keys;
int* records;

void init_data(uint64_t max_offset, uint32_t max_keys) {
    int i;

    if ((offsets = mmap(NULL, (MAX_RECORDS + 1) * sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0)) == MAP_FAILED) {
        log_message("Failed to allocate memory for offsets.");
        return;
    }

    if ((keys = malloc(max_keys * sizeof(int))) == NULL) {
        log_message("Failed to allocate memory for keys.");
        munmap(offsets, (MAX_RECORDS + 1) * sizeof(Record));
        return;
    }

    if ((records = calloc(MAX_RECORDS, sizeof(int))) == NULL) {
        log_message("Failed to allocate memory for records.");
        free(keys);
        munmap(offsets, (MAX_RECORDS + 1) * sizeof(Record));
        return;
    }

    srand((unsigned)time(NULL));
    for (i = 0; i < MAX_RECORDS; ++i) {
        offsets[i].record = records[i] = rand() % 1000000;
        keys[offsets[i].offset] = i + 1;
        offsets[i].offset += (rand() % max_keys);
    }

    log_message("Successfully allocated and initialized data.");
}

void free_data() {
    free(records);
    free(keys);
    munmap(offsets, (MAX_RECORDS + 1) * sizeof(Record));
}
