        prev = current;
        current = current->next;
    }

    // Add the new record to the cache and adjust the order of least recently used entries.
    if (prev) prev->next = record;
    else *cache = record;

    Record* last = *cache;
    while (last->next != NULL) last = last->next;
    Record* lru = find_lru(*cache);
    last->next = record;
