    long min_ts;
    long max_ts;
    long data_range;
    long key_range;
} Config;

void* createRecord(long id, time_t ts, void* data) {
    Record* rec = malloc(sizeof(Record));
    rec->id = id;
    rec->timestamp = ts;
    rec->data = data;
    rec->key = NULL;
    rec->offset = 0;
    return rec;
}

void initializeRecords(size_t N, Record*** records, const Config* config) {
    long* offsets = malloc(N * sizeof(long));
    int* keys = malloc(N * sizeof(int));

    for (size_t i = 0; i < N; ++i) {
        records[i] = &createRecord(-1, -1, NULL);
    }

    srand(time(NULL));

    for (size_t i = 0; i < N; ++i) {
        long id = config->min_id + rand() % (config->max_id - config->min_id + 1);
        time_t ts = config->min_ts + rand() % (config->max_ts - config->min_ts + 1);
        void* data = malloc(rand() % config->data_range);
        (*records[i])->id = id;
        (*records[i])->timestamp = ts;
        (*records[i])->data = data;
        (*records[i])->key = NULL;
        (*records[i])->offset = offsets[i];
        keys[i] = rand() % config->key_range;
    }

    for (size_t i = 0; i < N; ++i) {
        long offset = offsets[i];
        int key = keys[i];
        (*records[offset])->key = *records[i];
        if (offset != i) {
            keys[i] = keys[offset];
        }
        offsets[i] = offset;
    }
}
