        self.id = id
        self.timestamp = timestamp
        self.data = data

    @staticmethod
    def from_json(json_string: str) -> 'JsonRecord':
        json_object = json.loads(json_string)
        id = json_object['id']
        timestamp = float(json_object['timestamp'])
        data = json_object['data']
        return registry[id](id, timestamp, data)

    @staticmethod
    def to_json(record: 'JsonRecord') -> str:
        json_object = {'id': record.id,
                       'timestamp': record.timestamp,
                       'data': record.data}
        return json.dumps(json_object)

    @classmethod
    def register(cls, id_factory: Callable[[], 'JsonRecord']) -> None:
        cls.registry[id_factory().id] = id_factory
