typedef struct {
    long offset;
    int key;
    int value;
} record;

typedef struct Node {
    record* data;
    struct Node* next;
} Node;

Node** create_array(size_t size) {
    Node** array = malloc(sizeof(Node*) * size);
    if (!array) return NULL;
    for (size_t i = 0; i < size; ++i)
        array[i] = NULL;
    return array;
}

record* create_record() {
    record* rec = malloc(sizeof(record));
    if (!rec) return NULL;
    rec->offset = 0;
    rec->key = 0;
    rec->value = 0;
    return rec;
}

void init_records(Node** offsets, Node** keys, size_t num_records, int min, int max) {
    for (size_t i = 0; i < num_records; ++i) {
        record* rec = create_record();
        if (!rec) {
            fprintf(stderr, "Out of memory\n");
            exit(1);
        }
        rec->value = rand() % (max - min + 1) + min;
        Node* node = malloc(sizeof(Node));
        if (!node) {
            free(rec);
            fprintf(stderr, "Out of memory\n");
            exit(1);
        }
        node->data = rec;
        node->next = NULL;

        Node* offset_head = offsets[rec->offset];
        if (offset_head) {
            offset_head->next = node;
        } else {
            offsets[rec->offset] = node;
        }

        Node* key_head = keys[rec->key];
        if (key_head) {
            key_head->next = node;
        } else {
            keys[rec->key] = node;
        }
    }
}

void free_records(Node** offsets, Node** keys, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        while (offsets[i]) {
            Node* tmp = offsets[i];
            offsets[i] = offsets[i]->next;
