#include <stdio.h>
#include <stdlib.h>

int* read_integers(size_t* num) {
    int* arr = NULL;
    size_t size = 0;
    while (1) {
        char c = getchar();
        if (c == '\n') break;
        if (c < '0' || c > '9') {
            fprintf(stderr, "Invalid input\n");
            exit(1);
        }
        size *= 10;
        size += (c - '0');
    }
    *num = size;
    arr = malloc(sizeof(int) * size);
    if (!arr) {
        fprintf(stderr, "Out of memory\n");
        exit(1);
    }
    scanf("%d", arr);
    return arr;
}

int find_max(int* arr, size_t num) {
    int max = arr[0];
    for (size_t i = 1; i < num; ++i) {
        if (arr[i] > max) max = arr[i];
    }
    return max;
}
