                exit(EXIT_FAILURE);
            }
            numbers = tempNumbers;
        }
        numbers[numElements - 1] = number;
    }

    // Sort the array and find the largest integer.
    qsort(numbers, numElements, sizeof(int), (int (*)(const void*, const void*))compar);
    int largestNumber = numbers[numElements - 1];

    free(numbers);
}

// Comparison function for qsort.
int compar(const void* a, const void* b) {
    return *(const int*)a - *(const int*)b;
