typedef struct {
    unsigned int cell_identity;
    uint32_t frequency_band;
    gsl_hash_table* measurements; // Measurement results per carrier
} lte_ue_context_t;

static void* init_measurements(void* key) {
    gsl_hash_table_set_default((gsl_hash_table*)key, sizeof(int));
    return key;
}

void create_lte_ue_context(unsigned int cell_id, uint32_t frequency, size_t carriers, pthread_mutex_t* lock) {
    gsl_hash_table* context = gsl_hash_table_alloc(_N_ELEMENTS(carriers), sizeof(int));
    gsl_hash_table_set_free_key_function(context, free);
    gsl_hash_table_set_destroy_data_function(context, gsl_hash_table_free_all);

    for (size_t i = 0; i < carriers; ++i) {
        if (!gsl_hash_table_insert(context, &i, NULL)) {
            log_error("Failed to allocate memory");
            // Rollback changes and free allocated resources up until this point
            gsl_hash_table_destroy(context);
            return;
        }
    }

    lte_ue_context_t* context_data = mmap(NULL, sizeof(*context_data), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (context_data == MAP_FAILED) {
        log_error("Memory mapping failed: %s", strerror(errno));
        // Rollback changes and free allocated resources up until this point
        gsl_hash_table_destroy(context);
        return;
    }

    context_data->cell_identity = cell_id;
    context_data->frequency_band = frequency;
    context_data->measurements = context;

    pthread_mutex_init(&context_data->lock, NULL);
    // Initialize and configure the measurement results for each carrier using init_measurements()
    pthread_t thread;
    if (pthread_create(&thread, NULL, init_measurements, context)) {
        log_error("Failed to create thread: %s", strerror(errno));
        // Rollback changes and free allocated resources up until this point
        munmap((void*)context_data, sizeof(*context_data));
        gsl_hash_table_destroy(context);
        return;
    }
}

