void createMemoryPool(size_t newMaxPoolSize) {
    maxPoolSize = newMaxPoolSize > 0 ? newMaxPoolSize : maxPoolSize;
}

record* allocateRecord() {
    pthread_mutex_lock(&poolMutex);
    if (availableSlots > 0) {
        record* rec = memoryPool[--availableSlots];
        pthread_mutex_unlock(&poolMutex);
        return rec;
    }

    pthread_mutex_unlock(&poolMutex);
    return malloc(sizeof(record));
}

void deallocateRecord(record* rec) {
    if (rec == NULL) {
        return;
    }

    pthread_mutex_lock(&poolMutex);
    memoryPool[availableSlots++] = rec;
    pthread_mutex_unlock(&poolMutex);
