            auto newFreeList = static_cast<char*>(std::realloc(freeList_, freeListSize_));
            if (!newFreeList) {
                throw std::bad_alloc();
            }
            freeList_ = newFreeList;
            freeListEnd_ += freeListSize_ - initialBlockSize_;
        }

        auto result = static_cast<void*>(freeList_);
        freeList_ = static_cast<char*>(std::memmove(freeList_, freeList_ + size, freeListSize_ - size));
        freeListEnd_ -= size;

        return result;
    }

