        auto data = static_cast<char*>(ptr);
        if (data < freeList_ || data >= freeListEnd_) {
            std::cerr << "Invalid memory block" << std::endl;
            exit(1);
        }
        std::memmove(freeList_, data, sizeof(void*) + std::distance(data, freeListEnd_));
    }

private:
    char* freeList_;
    char* freeListEnd_;
    size_t freeListSize_;
    constexpr static size_t initialBlockSize_ = 16 * 1024; // Initial block size (16KB)
    constexpr static size_t alignment_ = alignof(std::max_align_t); // Maximum alignment required by any type
};

