typedef struct {
    int value;
} Record;

void init_pipeline(size_t size, long* offsets, int* keys, Record** records, FILE* log) {
    time_t t;
    struct timespec ts;

    if (!(offsets = malloc(size * sizeof(long)))) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    if (!(keys = malloc(size * sizeof(int)))) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        exit(EXIT_FAILURE);
    }

    if (!(records = malloc(size * sizeof(Record*)))) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    clock_gettime(CLOCK_REALTIME, &ts);
    t = ts.tv_sec;

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = t + i * 1e6; // Ensure uniqueness
        keys[i] = rand() % 100 + 1;
        records[i] = malloc(sizeof(Record));
        records[i]->value = rand() % 100 + 1;

        if (!records[i]) {
            perror("Failed to allocate memory for a record");
            fprintf(log, "Failed to initialize record at index: %ld\n", i);
            free(offsets);
            free(keys);
            free(records);
            exit(EXIT_FAILURE);
        }

        fprintf(log, "Initialized offset: %ld, key: %d, value: %d\n", offsets[i], keys[i], records[i]->value);
    }
}
