typedef struct Entry {
    char* key;
    int value_key;
    double value;
} Entry;

typedef struct ThreadSafeArray {
    Entry** entries;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
} ThreadSafeArray;

ThreadSafeArray* create_threadsafe_array(size_t initial_capacity) {
    ThreadSafeArray* tsa = (ThreadSafeArray*) malloc(sizeof(ThreadSafeArray));
    if (!tsa) {
        fprintf(stderr, "Memory allocation failure\n");
        return NULL;
    }

    tsa->capacity = initial_capacity;
    tsa->length = 0;
    tsa->entries = (Entry**) calloc(initial_capacity, sizeof(Entry*));
    if (!tsa->entries) {
        fprintf(stderr, "Memory allocation failure\n");
        free(tsa);
        return NULL;
    }

    pthread_mutex_init(&tsa->mutex, NULL);

    return tsa;
}

void destroy_threadsafe_array(ThreadSafeArray* tsa) {
    for (size_t i = 0; i < tsa->length; ++i) {
        free(tsa->entries[i]->key);
        free(tsa->entries[i]);
    }

    free(tsa->entries);
    pthread_mutex_destroy(&tsa->mutex);
    free(tsa);
}

Entry* find_entry(ThreadSafeArray* tsa, const char* key) {
    for (size_t i = 0; i < tsa->length; ++i) {
        if (!strcmp(tsa->entries[i]->key, key)) return tsa->entries[i];
    }
    return NULL;
}

Entry* allocate_entry() {
    Entry* entry = (Entry*) malloc(sizeof(Entry));
    if (!entry) {
        fprintf(stderr, "Memory allocation failure\n");
        return NULL;
    }

    entry->key = NULL;
    entry->value_key = -1;
    entry->value = 0.0;

    return entry;
}

void update_entry_values(ThreadSafeArray* tsa, size_t start, size_t end, double value) {
    pthread_mutex_lock(&tsa->mutex);

    for (size_t i = start; i < end; ++i) {
        Entry* entry = find_entry(tsa, i < tsa->length ? (&tsa->entries[i]->key)[0] : "");
        if (!entry) continue; // Skip invalid entries or if the range exceeds array bounds

        entry->value += value;
    }

    pthread_mutex_unlock(&tsa->mutex);
}

void insert_entry(ThreadSafeArray* tsa, const char* key, int value_key, double value) {
    if (tsa->length == tsa->capacity) {
        size_t new_capacity = tsa->capacity ? (tsa->capacity * 2) : 4;
        Entry** new_entries = realloc(tsa->entries, new_capacity * sizeof(Entry*));
        if (!new_entries) {
            fprintf(stderr, "Memory allocation failure\n");
            return;
        }
        tsa->entries = new_entries;
        tsa->capacity = new_capacity;
    }

    Entry* entry = allocate_entry();
    if (!entry) return;

    size_t key_length = strlen(key);
    entry->key = (char*) malloc((key_length + 1) * sizeof(char));
    if (!entry->key) {
        fprintf(stderr, "Memory allocation failure\n");
        free(entry);
        return;
    }

    strcpy(entry->key, key);
    entry->value_key = value_key;
    entry->value = value;

    pthread_mutex_lock(&tsa->mutex);
    tsa->entries[tsa->length++] = entry;
    pthread_mutex_unlock(&tsa->mutex);
}
