private:
    SessionTracker* sessionTracker;
    RefreshTokenStore* refreshTokenStore;
    LoggingService* loggingService;
    mutex dataCacheMutex;
    boost::circular_buffer<std::pair<time_t, bool>> expiredSessionsBuffer(1000); // 1000 sessions maximum in buffer for performance considerations

public:
    SessionProcessor(SessionTracker* sessionTracker, RefreshTokenStore* refreshTokenStore, LoggingService* loggingService)
        : sessionTracker(sessionTracker), refreshTokenStore(refreshTokenStore), loggingService(loggingService) {}

    json_t* processSession(const json_t* payload) {
        json_t* error = nullptr;
        jansson_check(payload);

        if (!json_object_get_field(payload, "session_id")) {
            error = json_pack("{s:s}", "error", "Missing field 'session_id'");
            goto cleanup;
        }

        if (!json_object_get_field(payload, "user_id")) {
            error = json_pack("{s:s}", "error", "Missing field 'user_id'");
            goto cleanup;
        }

        time_t currentTime = time(nullptr);
        if (!json_object_get_field(payload, "exp") || json_integer_value(json_object_get_field(payload, "exp")) <= currentTime) {
            error = json_pack("{s:s}", "error", "Invalid expiration timestamp");
            goto cleanup;
        }

        const char* sessionId = json_string_value(json_object_get_field(payload, "session_id"));

        if (sessionTracker->isUnique(sessionId)) {
            error = json_pack("{s:s}", "error", "Duplicate session_id");
            goto cleanup;
        }

        bool foundExpiredSession = false;
        std::unique_lock<std::mutex> lock(dataCacheMutex);
        for (auto& expiredSession : expiredSessionsBuffer) {
            if (expiredSession.first == currentTime && expiredSession.second == sessionId) {
                foundExpiredSession = true;
                break;
            }
        }
        if (foundExpiredSession) {
            error = json_pack("{s:s}", "error", "Session is already expired");
            goto cleanup;
        }

        // Refresh token validation here, assuming you have an implementation for this abstraction.

        // Admin action verification here, assuming you have an implementation for this abstraction.

        json_t* session = json_pack("{s:s}", "session_id", sessionId);
        goto cleanup;

    cleanup:
        if (error) {
            json_t* response = json_pack("{s:s}", "response", json_string(json_dump(error, 0)));
            return response;
        }
        return nullptr; // No error or session data returned indicates an issue in the processing function.
    }
};
