        fprintf(stderr, "Failed to allocate memory for data structure\n");
        return NULL;
    }

    pthread_rwlock_init(&ds->rwlock, NULL);
    ds->size = num_elements;

    ds->offsets = malloc(num_elements * sizeof(long));
    if (!ds->offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets array\n");
        free(ds);
        return NULL;
    }

    ds->keys = malloc(num_elements * sizeof(int));
    if (!ds->keys) {
        fprintf(stderr, "Failed to allocate memory for keys array\n");
        free(ds->offsets);
        free(ds);
        return NULL;
    }

    ds->records = malloc(num_elements * sizeof(struct record));
    if (!ds->records) {
        fprintf(stderr, "Failed to allocate memory for records array\n");
        free(ds->offsets);
        free(ds->keys);
        free(ds);
        return NULL;
    }

    ds->summary.min = INT32_MAX;
    ds->summary.max = INT32_MIN;
    ds->summary.sum = 0;
    ds->summary.count = 0;

    // Initialize with random values
    for (size_t i = 0; i < num_elements; ++i) {
        ds->offsets[i] = rand() % offset_range;
        ds->keys[i] = rand() % key_range;
        init_record(&ds->records[i]);
        ds->records[i].value = rand();

        if (ds->records[i].value > ds->summary.max) {
            ds->summary.max = ds->records[i].value;
        }
        if (ds->records[i].value < ds->summary.min) {
            ds->summary.min = ds->records[i].value;
        }
        ds->summary.sum += ds->records[i].value;
        ds->summary.count++;
    }

    return ds;
}

void destroy_data_struct(data_struct* ds) {
    if (ds->offsets) free(ds->offsets);
    if (ds->keys) free(ds->keys);
    if (ds->records) free(ds->records);
    pthread_rwlock_destroy(&ds->rwlock);
    free(ds);
}

#define LOG(fmt, ...) fprintf(stderr, "[%lu]: " fmt "\n", pthread_self(), __VA_ARGS__)

// Thread-safe access functions for data structure
void ds_read_lock(data_struct* ds) {
    pthread_rwlock_rdlock(&ds->rwlock);
}

void ds_write_lock(data_struct* ds) {
    pthread_rwlock_wrlock(&ds->rwlock);
}

void ds_unlock(data_struct* ds) {
    pthread_rwlock_unlock(&ds->rwlock);
}
```
