ContextData* initUEContextsAndManageRecords(unsigned int num_carriers, double latency_bound) {
    ContextData* data = (ContextData*) mmap(NULL, sizeof(ContextData), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!data) return NULL;

    sem_init(&data->lock, 0, 1);
    data->num_carriers = num_carriers;
    data->ue_contexts = (UEContext*) malloc(sizeof(UEContext) * num_carriers);
    if (!data->ue_contexts) goto error;

    data->records.resize(1024); // Adjust as needed
    for (auto& record : data->records) {
        record.key = rand() % 10000;
        record.offset = rand() * RAND_MAX;
    }

    data->ml_model = ml_model_init();
    if (!data->ml_model) goto error;

    data->latency_bound = latency_bound;
    pthread_create(&data->upload_thread, NULL, uploader_start, (void*) uploader.js);

    return data;

error:
    if (data->ue_contexts) free(data->ue_contexts);
    if (data) munmap(data, sizeof(ContextData));
    return NULL;
}

void deinitUEContextsAndManageRecords(ContextData* data) {
    if (data->ue_contexts) free(data->ue_contexts);
    if (data->ml_model) ml_model_destroy(data->ml_model);
    pthread_join(data->upload_thread, NULL);
    sem_destroy(&data->lock);
    munmap(data, sizeof(ContextData));
}
