        List<ByteBuffer> bufferList = ByteBufferUtil.bytesToBuffers(decryptedThemes);
        List<ThemeConfiguration> themeConfigurations = new ArrayList<>();

        int processedCount = 0;
        for (ByteBuffer buffer : bufferList) {
            if (processedCount >= MAX_THEMES) {
                throw new LimitExceededException("Maximum number of themes exceeded");
            }

            try (ObjectInputStream ois = new ObjectInputStream(new CipherInputStream(new ByteArrayInputStream(buffer.array()), getCipher()))){
                ThemeConfiguration themeConfig = (ThemeConfiguration) ois.readObject();
                if (themeConfig instanceof ThemeConfiguration) {
                    themeConfigurations.add(themeConfig);
                } else {
                    LOGGER.log(Level.WARNING, "Deserialized object does not implement ThemeConfiguration interface");
                }
            } catch (Exception e) {
                LOGGER.log(Level.SEVERE, "Failed to deserialize theme configuration", e);
            }

            processedCount++;
        }

        return themeConfigurations;
    }

    private Cipher getCipher() throws NoSuchAlgorithmException, NoSuchPaddingException {
        KeyGenerator keyGen = KeyGenerator.getInstance("PBKDF2WithHmacSHA256");
        keyGen.init(new PBEParameterSpec(passwordBytes, 2048, 128, 32));
        SecretKeyFactory keyFactory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        SecretKey secretKey = keyFactory.generateSecret(keyGen.generateKey());

        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.DECRYPT_MODE, secretKey);
        return cipher;
    }

    private byte[] decryptAES256CBC(byte[] encrypted) throws GeneralSecurityException {
        Cipher cipher = getCipher();
        IvParameterSpec iv = generateRandomIV();
        cipher.init(Cipher.DECRYPT_MODE, secretKey, iv);
        return cipher.doFinal(encrypted);
    }

    private byte[] encryptAES256CBC(byte[] plaintext) throws GeneralSecurityException {
        Cipher cipher = getCipher();
        IvParameterSpec iv = generateRandomIV();
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, iv);
        return cipher.doFinal(plaintext);
    }

    private byte[] generateRandomIV() {
        SecureRandom random = new SecureRandom();
        byte[] ivBytes = new byte[16];
        random.nextBytes(ivBytes);
        return ivBytes;
    }

    private final byte[] passwordBytes = "your-password".getBytes(StandardCharsets.UTF_8);
}
```
