import java.util.concurrent.atomic.AtomicLong;
import java.lang.reflect.InvocationTargetException;
import java.nio.ByteOrder;

public class EventDeserializer {
    private static final double COORDINATE_THRESHOLD = 100.0; // Adjust as needed
    private static final AtomicLong nextId = new AtomicLong(0);

    public static Object[] deserializeEvents(byte[] byteArray) {
        ObjectInputStream ois = null;
        try {
            ois = new ObjectInputStream(new ByteArrayInputStream(byteArray)) {
                @Override
                protected synchronized Object readObject() throws IOException, ClassNotFoundException {
                    try {
                        return super.readObject();
                    } catch (ClassNotFoundException e) {
                        throw new RuntimeException("Unable to find class for deserialized object.", e);
                    }
                }
            };
            List<Event> events = new ArrayList<>();
            Event currentEvent;
            long timestamp, prevTimestamp = -1;
            double prevCoordinate, coordinate;
            while ((currentEvent = (Event) ois.readObject()) != null) {
                if (prevTimestamp == -1) { // First event
                    prevTimestamp = currentEvent.getTimestamp();
                    continue;
                }

                timestamp = currentEvent.getTimestamp();
                coordinate = currentEvent.getValue();
                if ((timestamp - prevTimestamp) / (coordinate - prevCoordinate) > COORDINATE_THRESHOLD) {
                    throw new RuntimeException("Average distance between consecutive coordinates exceeds the specified threshold.");
                }
                prevTimestamp = timestamp;
                prevCoordinate = coordinate;

                events.add(currentEvent);
            }

            long[] timestamps = new long[events.size()];
            double[] coordinates = new double[events.size()];
            for (int i = 0; i < events.size(); ++i) {
                timestamps[i] = events.get(i).getTimestamp();
                coordinates[i] = events.get(i).getValue();
            }

            return new Object[]{timestamps, coordinates, events};
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Failed to deserialize byte array.", e);
        } finally {
            try { if (ois != null) ois.close(); } catch (IOException ex) {}
        }
    }

    static class Event implements Serializable {
        private static final long serialVersionUID = -302465798719992986L;
        private transient volatile long id;
        private long timestamp;
        private double value;

        public Event() {
            this.id = nextId.getAndIncrement();
        }

        public long getTimestamp() { return timestamp; }
        public void setTimestamp(long timestamp) { this.timestamp = timestamp; }
        public double getValue() { return value; }
        public void setValue(double value) { this.value = value; }
        public long getId() { return id; }
    }
}
