void addMeasurement(struct DynArray* dyn, Measurement measurement) {
    pthread_mutex_lock(&dyn->lock);

    if (dyn->size + 1 >= dyn->capacity) {
        dyn->capacity *= 2;
        void* new_data = mmap(NULL, dyn->capacity * sizeof(Measurement), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        memcpy(new_data, dyn->data, dyn->size * sizeof(Measurement));
        munmap(dyn->data, dyn->capacity * sizeof(Measurement));
        dyn->data = new_data;
    }

    dyn->data[dyn->size] = measurement;
    dyn->size++;

    pthread_mutex_unlock(&dyn->lock);
}

