}

void serialize(DYNAMIC_LIST *list, FILE *fp) {
    for (int i = 0; i < list->length; ++i) {
        fwrite(&list->buffer[i]->tag, sizeof(RX_UE_INFORMATION_TAG), 1, fp);
        fwrite(&list->buffer[i]->rnti, sizeof(RNTI), 1, fp);
