int enqueue(DYNAMIC_LIST *list, NFAPI_CRC_INDICATION_PDU* node) {
    if (isUniqueTag(list, node->tag)) {
        pthread_mutex_lock(&list->buffer_lock);
        while (list->length == list->capacity && resizeBuffer(list)) {}

        if (list->length >= list->capacity) {
            pthread_mutex_unlock(&list->buffer_lock);
            return -1;  // Buffer overflow
        }

        NFAPI_CRC_INDICATION_PDU *head = list->buffer[list->length];
        node->prev = head;
        node->next = head ? head->next : NULL;

        if (head) {
            head->next = node;
            if (node->next) node->next->prev = node;
        }
        list->buffer[list->length] = node;
        list->length++;
        pthread_mutex_unlock(&list->buffer_lock);
        logEvent("Enqueued", node);
    } else {
        free(node);
    }
    return 0;
}

void dequeue(DYNAMIC_LIST *list) {
    if (list->length > 0) {
        pthread_mutex_lock(&list->buffer_lock);
        NFAPI_CRC_INDICATION_PDU *head = list->buffer[0];
        if (head) {
            list->buffer[0] = head->next;
            if (list->buffer[0]) list->buffer[0]->prev = NULL;
            list->length--;
            logEvent("Dequeued", head);
        }
        pthread_mutex_unlock(&list->buffer_lock);
    }
}

void destroyDynamicList(DYNAMIC_LIST *list) {
    while (list->length > 0) dequeue(list);
    free(list->buffer);
    free(list);
