#include <time.h>

typedef struct record {
    long offset;
    int key;
} Record;

struct config {
    int min_val, max_val;
    char *filename;
};

static pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;
static struct config config_data = {0, 0, ""};

void *parse_config(char *file) {
    FILE *fp = fopen(file, "r");
    if (!fp) return NULL;

    int min_val, max_val;
    char line[256];

    while (fgets(line, sizeof(line), fp)) {
        if (sscanf(line, "%d %d", &min_val, &max_val) == 2) {
            config_data.min_val = min_val;
            config_data.max_val = max_val;
            break;
        }
    }

    fclose(fp);
    return &config_data;
}

Record *allocate_records(size_t num) {
    if (num <= 0) return NULL;

    Record *records = mmap(NULL, sizeof(Record) * num, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (records == MAP_FAILED) {
        perror("mmap");
        return NULL;
    }

    return records;
}

void init_records(Record *records, size_t num) {
    for (size_t i = 0; i < num; ++i)
        records[i].key = rand() % (config_data.max_val - config_data.min_val + 1) + config_data.min_val;
}

void *init_and_allocate(void *arg) {
    size_t num = *(size_t *)arg;
    Record *records = allocate_records(num);

    if (records) {
        pthread_mutex_lock(&config_lock);
        init_records(records, num);
        pthread_mutex_unlock(&config_lock);
    }

    return records;
}

void log_allocation(const char *message, Record *records, size_t num) {
    printf("%s: Successfully allocated and initialized %zu records\n", message, num);
    if (records) {
        for (size_t i = 0; i < num; ++i)
            printf("  [%zu]: key=%d\n", i, records[i].key);
    } else {
        perror("Failed to allocate and initialize records");
    }
}

int main(int argc, char **argv) {
    size_t num_records;
    void *config = NULL;

    static struct option long_options[] = {
        {"config", required_argument, 0, 'c'},
        {0, 0, 0, 0}
    };

    int opt;
    while ((opt = getopt_long(argc, argv, "", long_options, NULL)) != -1) {
        switch (opt) {
            case 'c':
                config = parse_config(optarg);
                break;
            default:
                break;
        }
    }

    if (!config) {
        printf("Missing or improperly formatted configuration file\n");
        return 1;
    }

    if (config_data.min_val > config_data.max_val) {
        fprintf(stderr, "Invalid range: min=%d, max=%d\n", config_data.min_val, config_data.max_val);
        return 1;
    }

    num_records = strtoul(getenv("NUM_RECORDS"), NULL, 10);

    if (num_records <= 0 || RLIMIT_RSS < (sizeof(Record) * num_records)) {
        fprintf(stderr, "Invalid number of records or memory limits exceeded\n");
        return 1;
    }

    pthread_t threads[num_records];
    log_allocation("Initial", NULL, 0);

    for (size_t i = 0; i < num_records; ++i) {
        void *arg = &num_records;
        if (pthread_create(&threads[i], NULL, init_and_allocate, &arg)) {
            perror("Failed to create thread");
            return 1;
        }
    }

    for (size_t i = 0; i < num_records; ++i) {
        void *result;
        if (pthread_join(threads[i], &result)) {
            perror("Failed to join thread");
            return 1;
        }

        log_allocation("Final", result, num_records);
    }

    return 0;
}
```
