    size_t count;
    NFAPI_CRC_INDICATION_PDU_T **data;
    pthread_mutex_t lock;
};

void list_init(struct list_header *list, size_t initial_capacity) {
    list->capacity = initial_capacity;
    list->count = 0;
    list->data = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list->data) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    list->lock = PTHREAD_MUTEX_INITIALIZER;
}

void *list_new_node() {
    void *mem = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!mem) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    return mem;
}

void list_append(struct list_header *list, NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t new_capacity = 2 * list->capacity;
        NFAPI_CRC_INDICATION_PDU_T **new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!new_data) {
            fprintf(stderr, "Out of memory\n");
            pthread_mutex_unlock(&list->lock);
            exit(EXIT_FAILURE);
        }
        list->capacity = new_capacity;
        list->data = new_data;
    }

    list->data[list->count] = node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T *list_get(const struct list_header *list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index >= list->count || index < 0) {
        fprintf(stderr, "Index out of bounds\n");
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *node = list->data[index];
    pthread_mutex_unlock(&list->lock);
    return node;
}

void list_iterate(const struct list_header *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *node = list->data[i];
        callback(node);
    }
    pthread_mutex_unlock(&list->lock);
}

void list_update(struct list_header *list, ...) {
    va_list args;
    va_start(args, list);

    pthread_mutex_lock(&list->lock);

    while (list->count > 0) {
        NFAPI_CRC_INDICATION_PDU_T *first = list->data[0];
        NFAPI_CRC_INDICATION_PDU_T *next;
        do {
            next = first->next;
            free(first);
            first = NULL;
            if (--list->count > 0) {
                list->data[0] = va_arg(args, NFAPI_CRC_INDICATION_PDU_T*);
            }
        } while (next != NULL);
    }

    size_t new_capacity = va_arg(args, size_t);
    list->capacity = new_capacity;
    list->data = calloc(new_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list->data) {
        fprintf(stderr, "Out of memory\n");
        pthread_mutex_unlock(&list->lock);
        va_end(args);
        exit(EXIT_FAILURE);
