    size_t i;

    if (offsets == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Initialize offsets with Fibonacci sequence
    offsets[0] = params.start_offset;
    offsets[1] = params.ratio_offset * (params.start_offset + 1);
    for (i = 2; i < params.num_records; ++i) {
        offsets[i] = offsets[i - 1] + offsets[i - 2] * params.ratio_offset;
    }

    // Initialize keys with geometric progression
    size_t j;
    for (i = 0; i < params.num_records; ++i) {
        records = realloc(records, (i + 1) * sizeof(record));
        if (!records) {
            perror("Memory allocation failed");
            free(offsets);
            return NULL;
        }

        records[i].offset = offsets[i];
        records[i].value = (params.min_value + rand() * (params.max_value - params.min_value + 1) / RAND_MAX) * params.min_value;
        for (j = 0; j < i; ++j) {
            if (records[i].offset == records[j].offset) {
                printf("Error: Duplicate offset found.\n");
                free(records);
                free(offsets);
                return NULL;
            }
        }
    }

    return records;
}

int main() {
    struct parameters params = {.num_records = 10, .start_offset = 0, .ratio_offset = 1.61803398875, .start_key = 1, .ratio_key = 2, .min_value = -100, .max_value = 100};
    srand(time(NULL));
    record *records = create_records(params);

    if (records) {
        size_t i;
        for (i = 0; i < params.num_records; ++i) {
            printf("Record %zu: value = %d, offset = %ld\n", i, records[i].value, records[i].offset);
        }

        free(records);
    }

    return 0;
}
```

