// Custom memory pool allocator
typedef struct Allocator {
    void *pool_base;
    size_t total_size;
    size_t used_size;
    pthread_mutex_t lock;
} Allocator;

void init_allocator(Allocator *alloc, size_t total_size) {
    alloc->pool_base = mmap(NULL, total_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (alloc->pool_base == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    alloc->total_size = total_size;
    alloc->used_size = 0;
    pthread_mutex_init(&alloc->lock, NULL);
}

void *alloc(Allocator *alloc, size_t size) {
    pthread_mutex_lock(&alloc->lock);

    void *ptr = alloc->pool_base + alloc->used_size;
    alloc->used_size += size;

    pthread_mutex_unlock(&alloc->lock);
    return ptr;
}

void free(Allocator *alloc, void *ptr) {
    pthread_mutex_lock(&alloc->lock);

    memset(ptr, 0, alloc->total_size);
    alloc->used_size -= (ptr - alloc->pool_base);

    pthread_mutex_unlock(&alloc->lock);
}

// Lock-free dynamic array
typedef struct {
    Allocator records_alloc;
    Record *records;
    size_t capacity;
    size_t length;
    pthread_rwlock_t rwlock;
