#include <unistd.h>

typedef struct SensorNode {
    double temperature;
    char timestamp[32];
    struct SensorNode *next;
} SensorNode;

struct SysData {
    int node_count;
    SensorNode **nodes;
    double temp_min, temp_max;
    char template[64];
    FILE *file;
};

void create_timestamp(char *str, size_t len, const char *template) {
    struct tm tm;
    time_t current_time = time(NULL);
    strftime(str, len, template, localtime_r(&current_time, &tm));
}

SensorNode* create_node() {
    SensorNode *new_node = (SensorNode *)malloc(sizeof(SensorNode));
    if (!new_node) return NULL;
    new_node->next = NULL;
    return new_node;
}

SysData* init_system(int node_count, double temp_min, double temp_max, const char *template) {
    SysData *sys_data = (SysData *)calloc(1, sizeof(SysData));
    if (!sys_data) return NULL;

    sys_data->node_count = node_count;
    sys_data->temp_min = temp_min;
    sys_data->temp_max = temp_max;
    strncpy(sys_data->template, template, sizeof(sys_data->template));

    sys_data->nodes = (SensorNode **)calloc(node_count, sizeof(SensorNode *));
    if (!sys_data->nodes) {
        free(sys_data);
        return NULL;
    }

    for (int i = 0; i < node_count; ++i)
        sys_data->nodes[i] = create_node();
    if (!sys_data->nodes) {
        free(sys_data->template);
        free(sys_data->nodes);
        free(sys_data);
        return NULL;
    }

    return sys_data;
}

void delete_system(SysData *sys_data) {
    for (int i = 0; i < sys_data->node_count; ++i) {
        SensorNode *next = sys_data->nodes[i]->next;
        free(sys_data->nodes[i]);
        sys_data->nodes[i] = next;
    }

    free(sys_data->template);
    free(sys_data->nodes);
    free(sys_data);
}

void save_data(SysData *sys_data, const char *filename) {
    if (sys_data->file) fclose(sys_data->file);

    sys_data->file = fopen(filename, "w");
    if (!sys_data->file) return;

    for (int i = 0; i < sys_data->node_count; ++i) {
        SensorNode *current = sys_data->nodes[i];
        while (current != NULL) {
            fprintf(sys_data->file, "%s %lf\n", current->timestamp, current->temperature);
            current = current->next;
        }
    }

    fclose(sys_data->file);
}

void load_data(SysData *sys_data, const char *filename) {
    if (sys_data->file) fclose(sys_data->file);

    struct stat st;
    if (stat(filename, &st) != 0 || !S_ISREG(st.st_mode)) return;

    sys_data->file = fopen(filename, "r");
    if (!sys_data->file) return;

    char line[128];
    for (int i = 0; i < sys_data->node_count; ++i) {
        SensorNode *current = sys_data->nodes[i];
        while (fgets(line, sizeof(line), sys_data->file)) {
            sscanf(line, "%s %lf", current->timestamp, &current->temperature);
            current = current->next;
            if (!current) break;
        }
    }

    fclose(sys_data->file);
}

void process_sensor_data(SysData *sys_data, void (*process_function)(SensorNode *)) {
    for (int i = 0; i < sys_data->node_count; ++i) {
        SensorNode *current = sys_data->nodes[i];
        while (current != NULL) {
            process_function(current);
            current = current->next;
        }
    }
}

SysData* create_system(int node_count, double temp_min, double temp_max, const char *template, void (*process_function)(SensorNode *)) {
    SysData *sys_data = init_system(node_count, temp_min, temp_max, template);
    if (!sys_data) return NULL;

    sys_data->process_function = process_function;
    srand(time(NULL));

    for (int i = 0; i < node_count; ++i) {
        SensorNode *current = sys_data->nodes[i];
        create_timestamp(current->timestamp, sizeof(current->timestamp), sys_data->template);
        current->temperature = temp_min + (rand() % ((int)(temp_max - temp_min) + 1)) / (double)RAND_MAX * (temp_max - temp_min);
        current->next = sys_data->nodes[(i+1)%node_count];
    }

    process_sensor_data(sys_data, sys_data->process_function);

    return sys_data;
}
```
