void* mem_alloc(size_t size) {
    void *ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (ptr == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    mlockall(MCL_CURRENT | MCL_FUTURE);
    return ptr;
}

// Function to populate structures with random values
void initialize_records(NFAPI_CRC_INDICATION_PDU* records, int num_records) {
