        records[i].crc_indication.crcflag = (rand() % 2) ? true : false; // Randomly set CRCFLAG
    }
}

// Stable sorting function using merge sort
void stable_sort(NFAPI_CRD_INDICATION_PDU* records, int num_records) {
    if (num_records <= 1) return;

    int mid = num_records / 2;
    NFAPI_CRD_INDICATION_PDU *left = malloc(mid * sizeof(NFAPI_CRD_INDICATION_PDU));
    NFAPI_CRD_INDICATION_PDU *right = malloc((num_records - mid) * sizeof(NFAPI_CRD_INDICATION_PDU));

    memcpy(left, records, mid * sizeof(NFAPI_CRD_INDICATION_PDU));
    memcpy(right, &records[mid], (num_records - mid) * sizeof(NFAPI_CRD_INDICATION_PDU));

    stable_sort(left, mid);
    stable_sort(right, num_records - mid);

    merge_sorted_arrays(left, right, records, mid, num_records - mid);

