void append_packet_descriptor(tsn_packet_descriptor_t packet) {
    pthread_mutex_lock(&mutex);

    // Check if buffer is full and handle potential overflow
    if ((tail + 1) % MAX_PACKET_DESCRIPTORS == head) {
        fprintf(stderr, "Buffer overflow!\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Validate packet descriptor integrity before appending it to the list
    validate_packet_descriptor(&packet);
    buffer[tail] = packet;
    tail = (tail + 1) % MAX_PACKET_DESCRIPTORS;

    pthread_mutex_unlock(&mutex);
}
