struct SensorData {
    double temperature;
    char* timestamp;
};

class SensorNode {
public:
    SensorData data;
    SensorNode* next = nullptr;

    SensorNode() : data({ 0.0, static_cast<char*>(calloc(1, sizeof(char) * 26)) }) {}
};

void serializeSensorData(const SensorData& data, std::ofstream& file) {
    char buffer[sizeof(data.temperature) + strlen(data.timestamp) + sizeof(int)]; // Assumes little-endian byte order

    memcpy(buffer, &data.temperature, sizeof(data.temperature));
    memcpy(buffer + sizeof(data.temperature), data.timestamp, strlen(data.timestamp) + 1);
    memcpy(buffer + sizeof(data.temperature) + strlen(data.timestamp) + sizeof(int), &static_cast<std::streamsize>(strlen(data.timestamp)), sizeof(int));

    file.write(reinterpret_cast<const char*>(buffer), sizeof(buffer));
}

SensorData deserializeSensorData(const char* buffer, std::istream& file) {
    SensorData data;

    file.read(reinterpret_cast<char*>(&data.temperature), sizeof(data.temperature));
    file.read(reinterpret_cast<char*>(static_cast<char*>(&data.timestamp)), strlen(data.timestamp) + 1);
    int len;
    file.read(reinterpret_cast<char*>(&len), sizeof(int));
    data.timestamp = static_cast<char*>(malloc(len));
    file.read(reinterpret_cast<char*>(data.timestamp), len);

    return data;
}

void initializeSensorData(std::vector<SensorNode>& sensors, int count, double minTemp, double maxTemp) {
    for (SensorNode& node : sensors) {
        node.data.temperature = static_cast<double>(rand()) / RAND_MAX * (maxTemp - minTemp) + minTemp;

        auto now = std::time(nullptr);
        char timestamp[26];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", std::localtime(&now));
        node.data.timestamp = new char[strlen(timestamp) + 1];
        strcpy(node.data.timestamp, timestamp);
    }
}

void allocateSensorDataStructure(int& size, SensorNode** sensors, external_data_processing_library* processor) {
    try {
        *sensors = new SensorNode[size];
        initializeSensorData((*sensors), size, -50.0, 150.0);
        for (int i = 0; i < size; ++i) {
            if (!(*sensors + i)) {
                std::cerr << "Memory allocation failure!" << std::endl;
                throw std::bad_alloc();
            }
            if (i != size - 1) {
                (*sensors + i)->next = (*sensors + i + 1);
            }
        }
    } catch (const std::exception& e) {
        for (int i = 0; i < size; ++i) {
            delete[] (*sensors + i)->data.timestamp;
            delete (*sensors + i);
        }
        free(sensors);
        throw e;
    }

    if (!processor->initialize()) {
        for (int i = 0; i < size; ++i) {
            delete[] (*sensors + i)->data.timestamp;
            delete (*sensors + i);
        }
        free(sensors);
        throw std::runtime_error("Data processing library initialization failure.");
    }
}

void deallocateSensorDataStructure(int size, SensorNode* sensors) {
    for (int i = 0; i < size; ++i) {
        delete[] sensors[i]->data.timestamp;
        delete sensors[i];
    }
    free(sensors);
}
```

