std::shared_ptr<std::mutex> gMutex = std::make_shared<std::mutex>();

template<typename Iterator>
void processIntegerList(Iterator first, Iterator last, int searchValue, int incrementValue) {
    std::unique_ptr<Iterator> tempIterator(first); // Create a unique pointer to the iterator. This will ensure proper memory management.
    std::advance(tempIterator, static_cast<std::ptrdiff_t>(last - first)); // Move the iterator to the end of the list.

    std::unique_lock<std::shared_locked_t> lock(*gMutex); // Create a unique lock to prevent concurrent modifications.

    while (tempIterator != last) {
        if (*tempIterator == searchValue) {
            *tempIterator += incrementValue;
        } else {
            lock.unlock(); // Release the lock to avoid holding it for an extended period of time.

            // Perform the assignment outside the critical section to improve performance.
            last = std::prev(last);
            *last = searchValue + incrementValue;

            lock.lock(); // Reacquire the lock to prevent concurrent modifications.
            tempIterator = std::make_unique<Iterator>(last); // Create a new unique pointer to the updated iterator position.
        }
        std::advance(tempIterator, -1); // Move the iterator back one position.
    }
}
```

This code uses a shared mutex for synchronization and unique pointers for memory management. The function performs the required operations efficiently by minimizing critical section time and performing assignments outside the critical section whenever possible.']

