mod lexer;
mod parser;
mod generator;

fn generate_assembly(config_path: &str) -> Result<(), Box<dyn std::error::Error> {
    let config_file = File::open(config_path)?;
    let reader = BufReader::new(config_file);

    let mut hardware_settings: HashMap<String, String> = HashMap::new();
    for line in reader.lines() {
        let line = line?;
        if let Some((directive, value)) = parser::parse_line(&line) {
            hardware_settings.insert(directive, value);
        }
    }

    let architecture = match &hardware_settings["architecture"] {
        "arm" => generator::ArmArchitecture::new(),
        "x86_64" => generator::X86_64Architecture::new(),
        "riscv" => generator::RISCVAArchitecture::new(),
        _ => return Err(format!("Unsupported architecture: {}", &hardware_settings["architecture"]).into()),
    };

    let assembly = architecture.generate_assembly(&hardware_settings)?;

    println!("{}", assembly);

    Ok(())
}

fn main() {
