#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    long offset;
    int key;
} Record;

static pthread_mutex_t allocatorMutex = PTHREAD_MUTEX_INITIALIZER;
static size_t totalMemoryAllocated = 0;

long *offsets, *maxOffsets;
int *keys, *maxKeys;

int allocateAndInitializeRecords(size_t n, int minKey, int maxKey) {
    long *tmpOffsets, *tmpMaxOffsets;
    int *tmpKeys, *tmpMaxKeys;

    pthread_mutex_lock(&allocatorMutex);

    if ((totalMemoryAllocated + sizeof(long) * 2 * n + sizeof(int) * 2 * n) > (1ULL << 30)) { // 30MB limit for this example
        printf("Error: Memory allocation exceeded the allowed limit.\n");
        pthread_mutex_unlock(&allocatorMutex);
        return -1;
    }

    totalMemoryAllocated += sizeof(long) * 2 * n + sizeof(int) * 2 * n;

    if ((tmpOffsets = realloc(offsets, (totalMemoryAllocated / sizeof(long)) + n)) == NULL ||
        (tmpMaxOffsets = realloc(maxOffsets, (totalMemoryAllocated / sizeof(long)) + 1)) == NULL ||
        (tmpKeys = realloc(keys, (totalMemoryAllocated / sizeof(int)) + 2 * n)) == NULL ||
        (tmpMaxKeys = realloc(maxKeys, (totalMemoryAllocated / sizeof(int)) + 1)) == NULL) {
        printf("Error: Failed to allocate memory.\n");
        totalMemoryAllocated -= sizeof(long) * 2 * n + sizeof(int) * 2 * n;
        pthread_mutex_unlock(&allocatorMutex);
        return -1;
    }

    offsets = tmpOffsets;
    maxOffsets = tmpMaxOffsets;
    keys = tmpKeys;
    maxKeys = tmpMaxKeys;

    *maxOffsets = totalMemoryAllocated / sizeof(long) - 1;
    *maxKeys = (totalMemoryAllocated / sizeof(int)) / 2 - n;

    pthread_mutex_unlock(&allocatorMutex);

    // Initialize keys with random values
    for (size_t i = 0; i < n; ++i) {
        keys[i] = minKey + rand() % (maxKey - minKey + 1);
    }

    return 0;
}
