    nfapi_frames = n;
    offsets = calloc(n, sizeof(long));
    if (!offsets) return FAILURE;
    keys = malloc(m * sizeof(int));
    if (!keys) { free(offsets); return FAILURE; }
    records = calloc(p, sizeof(RECORD));
