    }

    return SUCCESS;
}

int insert(const NFAPI_RX_FRAME_INFO_T *frame_info, const int key) {
    // Your custom logic for handling potential race conditions and updating the NFAPI_RX_FRAME_INFO_T array goes here.

    if (key >= min && key <= max) {
        ++nfapi_frames;
        (*(records + (key % n)).offset)[*(records + (key % n)).record]++;
    }

    return SUCCESS;
}

int remove(const int key) {
