use std::env;
use std::fs::{self, create_dir_all, remove_dir_all};
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::time::Duration;

use futures::stream::StreamExt;
use reqwest::{Client, Response};
use serde_json::Value;

type Result<T> = std::result::Result<T, Box<dyn std::error::Error>>;

const CONFIG_DIR_NAME: &str = ".my-app";
const MAX_RETRIES: u32 = 10;
const RETRY_DELAY: Duration = Duration::from_secs(1);

async fn get_config_server_url() -> Result<String> {
    let config_server_url = match env::var("CONFIG_SERVER_URL") {
        Ok(val) => val,
        Err(_) => return Err(box_err!("Missing CONFIG_SERVER_URL environment variable.")),
    };

    let client = Client::new();
    let response: Response = client.get(&config_server_url).send().await?;
    response.text().await
}

fn create_config_dir() -> Result<PathBuf> {
    // Check if .my-app exists in the current working directory, if not then use it as the config dir.
    let mut config_dir = Path::new(".");
    if !config_dir.join(CONFIG_DIR_NAME).is_dir() {
        config_dir.push(CONFIG_DIR_NAME);
    }

    // Ensure only one instance creates a new directory in case of concurrent launches.
    if let Ok(lockfile) = fs::open(&config_dir.join("lock")) {
        io::Write::flush(&lockfile)?;
        return Err(io::Error::new(
            io::ErrorKind::AlreadyExists,
            "Another instance is running.",
        ))
    }

    create_dir_all(&config_dir)?;
    fs::remove_file(&config_dir.join("lock"))?;

    Ok(config_dir)
}

async fn retry_on_error<F, R>(f: F) -> Result<R>
where
    F: FnOnce() -> Result<R>,
{
    0..MAX_RETRIES
        .into_iter()
        .fold(Ok::<_, Box<dyn std::error::Error>>(())?, |res, _| {
            if let Ok(result) = res {
                return result;
            }

            async move {
                tokio::time::sleep(RETRY_DELAY).await;
                f().await?
            }
            .await
        })
}

fn main() -> Result<()> {
    let config_server_url = retry_on_error(get_config_server_url)?;
    let config_dir = create_config_dir()?;

    // Use the common configuration directory here.
    // ...
}
```

