            self._repository = RemoteRepository(repository['url'], repository.get('auth_data'))
        else:
            self._repository = None
        self._format = format

    def load_config(self, filename):
        if self._repository:
            file_content = self._repository.fetch(filename)
        else:
            with open(filename, 'r') as f:
                file_content = f.read()

        configuration = None
        if self._format == 'json':
            configuration = json.loads(file_content)
        elif self._format == 'yaml':
            configuration = yaml.load(file_content, Loader=yaml.FullLoader)
