// Mutex for thread safety
pthread_mutex_t data_mutex = PTHREAD_MUTEX_INITIALIZER;
Record* data = NULL;
size_t data_size = 0;

void add_record(const Record* record) {
    // Validate the input record
    if (record->offset < 0 || record->key <= 0) {
        fprintf(stderr, "Invalid record format: %ld, %d\n", record->offset, record->key);
        return;
    }

    // Allocate memory for a new array element and copy the input data
    Record* new_data = realloc(data, sizeof(Record) * (data_size + 1));
    if (!new_data) {
        perror("Memory allocation failure");
        return;
    }
    data = new_data;

    // Lock the mutex to ensure thread safety during modification
    pthread_mutex_lock(&data_mutex);
    data[data_size] = *record;
    data_size++;
    pthread_mutex_unlock(&data_mutex);
}

void manage_memory() {
    if (data_size < 1024 && data_size > 0) {
        // If the number of records is below the threshold, free memory and reset the array size
        free(data);
        data = NULL;
        data_size = 0;
    }
}

// The function to manage dynamically sized array of record structures.
void manage_records(const Record* dataset, size_t dataset_size) {
    // Handle the case where the input dataset is empty
    if (dataset_size == 0) {
        manage_memory();
        return;
    }

    // Iterate through the input dataset and add each record to the managed data structure
    for (size_t i = 0; i < dataset_size; ++i) {
        add_record(&dataset[i]);
    }

    // Call manage_memory() periodically to minimize memory consumption and optimize performance
    mange_memory();
}
