#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

// Structure for records
typedef struct record {
    int key;
    long offset;
    struct record *next;
} Record;

typedef struct mem_pool {
    void* data;
    size_t capacity;
    size_t used;
    struct mem_pool* next;
} MemPool;

// Memory pool functions
MemPool* create_mem_pool(size_t size, size_t capacity);
void* acquire_from_mem_pool(MemPool** head);
void release_to_mem_pool(MemPool** head, void* ptr);

// List functions
Record* create_record();
void insert_head(Record** head, Record* new_node);
void insert_tail(Record** head, Record* new_node);
void insert_after(Record* current, Record* new_node);

// Random number generation
long rand_in_range(long min, long max);

// Configuration file functions
bool exists(const char* path);
int configure();

// Web server functions (not provided due to scope and complexity)
void start_web_server();
void stop_web_server();

MemPool* create_mem_pool(size_t size, size_t capacity) {
    MemPool* head = NULL;
    for (size_t i = 0; i < capacity; ++i) {
        MemPool* new_node = malloc(sizeof(MemPool));
        if (!new_node) return NULL;
        new_node->data = calloc(1, size);
        if (!new_node->data) {
            free(new_node);
            return NULL;
        }
        new_node->capacity = size;
        new_node->used = 0;
        new_node->next = head;
        head = new_node;
    }
    return head;
}

void* acquire_from_mem_pool(MemPool** head) {
    MemPool* current = *head;
    if (!current) return NULL;

    void* data = current->data;
    if (current->used < current->capacity) {
        current->used++;
        return data;
    } else {
        *head = current->next;
        free(current->data);
        free(current);
    }
    return acquire_from_mem_pool(head);
}

void release_to_mem_pool(MemPool** head, void* ptr) {
    if (!ptr) return;

    MemPool* current = *head;
    if (!current) {
        MemPool* new_node = create_mem_pool(1, 1);
        if (!new_node) return;
        new_node->data = ptr;
        new_node->capacity = 1;
        new_node->used = 0;
        *head = new_node;
        return;
    }

    while (current->next && current->next->used < current->next->capacity) {
        current = current->next;
    }

    if (!current->next) {
        MemPool* new_node = create_mem_pool(1, 1);
        if (!new_node) return;
        new_node->data = ptr;
        new_node->capacity = 1;
        new_node->used = 0;
        current->next = new_node;
    } else {
        current->next->used = 0;
        memcpy(current->next->data, ptr, current->next->capacity);
    }
}
```

