        for (const auto& s : strings) {
            if (uniqueStrings.find(s) != uniqueStrings.end()) {
                throw std::runtime_error("Duplicate input string detected");
            }
            uniqueStrings.insert(s);
        }
        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5_CTX ctx;
        MD5_Init(&ctx);
        for (const auto& s : strings) {
            MD5_Update(&ctx, s.c_str(), s.length());
        }
        MD5_Final(digest, &ctx);
        return boost::algorithm::hex(reinterpret_cast<const char*>(digest), sizeof(digest));
    }

private:
    size_t _maxCarriersPerAggregation;
    std::map<int64_t, UEContext> _ueContexts; // unique id as key, UE context as value
