#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct Record {
    int value;
    long offset;
    int key;
    struct Record *next;
} Record;

Record* create_record(long offset, int key) {
    Record* new_record = (Record*) malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }
    new_record->offset = offset;
    new_record->key = key;
    new_record->value = 0;
    new_record->next = NULL;
    return new_record;
}

void* generate_records(int num_records, int min_value, int max_value, Record** head) {
    pthread_t threads[num_threads];
    Record** records = (Record**) malloc(num_threads * sizeof(Record*));
    for (int i = 0; i < num_threads; ++i) {
        records[i] = NULL;
    }

    int num_threads = sysconf(_SC_NPROCESSORS_ONLN);
    if (num_records % num_threads != 0) {
        fprintf(stderr, "Error: Incorrect number of records and threads\n");
        return NULL;
    }

    int records_per_thread = num_records / num_threads;

    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, thread_func, (void*)(i * records_per_thread));
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
        Record* curr = records[i];
        while (curr != NULL) {
            Record* temp = curr;
            curr = curr->next;
            *head = merge_lists(*head, temp);
        }
    }

    free(records);
    return head;
}

void* thread_func(void* arg) {
    int start = *(int*)arg;
    int end = start + records_per_thread;
    for (int i = start; i < end; ++i) {
        Record* new_record = create_record((long)i, rand() % range + min_value);
        if (!new_record) return NULL;
        new_record->value = rand() % (max_value - min_value + 1) + min_value;
        new_record->next = records[*(int*)arg];
        records[*(int*)arg] = new_record;
    }
    return NULL;
}

Record* merge_lists(Record* list1, Record* list2) {
    if (!list1) return list2;
    if (!list2) return list1;

    if (list1->offset < list2->offset) {
        list1->next = merge_lists(list1->next, list2);
        return list1;
    } else {
        list2->next = merge_lists(list1, list2->next);
        return list2;
    }
}

void free_memory(Record* head) {
    while (head != NULL) {
        Record* temp = head;
        head = head->next;
        free(temp);
    }
}
