using boost::asio::ip::tcp;
namespace http = boost::beast::http;

class InterfaceTable {
public:
    virtual std::string FindVmUuidFromMetadataIp(const std::string& ip) const = 0;
};

struct TestDouble : public InterfaceTable {
    MOCK_METHOD0(FindVmUuidFromMetadataIp, std::string());
};

class VmManager {
public:
    explicit VmManager(const std::shared_ptr<InterfaceTable>& interfaceTable)
        : io_(io_service_), server_("0.0.0.0", port_) {
        server_.set_option(boost::asio::ip::tcp::acceptor::reuse_address(true));
    }

    void Run() {
        do_run();
    }

private:
    void do_run() {
        server_.async_accept([self = shared_from_this()](boost::system::error_code ec, tcp::socket socket) {
            if (!ec) {
                std::make_shared<RequestHandler>(std::move(socket), self->interfaceTable_)->run();
                do_run();
            }
        });

        io_.run();
    }

    static constexpr int port_ = 8080;
    tcp::acceptor server_;
    boost::asio::io_service io_;
    std::shared_ptr<InterfaceTable> interfaceTable_;
};

class RequestHandler {
public:
    explicit RequestHandler(tcp::socket socket, const std::shared_ptr<InterfaceTable>& interfaceTable)
        : strand_(io_service_.get_executor()), interfaceTable_(interfaceTable), requests_sent_(0), proxies_(0), errors_(0) {
        request_ = http::request<http::empty_body>();
        request_.set(http::field::host, "example.com");
        request_.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);
    }

    void run() {
        bool close = false;
        try {
            boost::beast::error_code ec;
            http::read(stream_, buffer_, ec);
            if (ec == http::error::end_of_stream)
                return;
            if (ec)
                throw ec;

            request_.reset();
            request_.method(http::verb::get);
            request_.version(11);
            request_.target(buffer_);

            auto headers_it = request_.need_vhost().emplace("Host", "example.com");
            auto it = request_.need_headers().emplace(*headers_it);
            *it = make_pair(http::field::user_agent, BOOST_BEAST_VERSION_STRING);

            bool isPost = (request_.method() == http::verb::post);
            if (isPost) {
                request_.set(http::field::content_type, "application/x-www-form-urlencoded");
                request_.body().prepare(buffers_);
            }

            write_request();
        } catch (const std::exception& ex) {
            ++errors_;
            close = true;
        }

        if (!close) {
            read_response();
        }
    }

private:
    void write_request() {
        auto self = shared_from_this();
        boost::asio::async_write(socket_, request_, [self](boost::system::error_code ec, size_t /*length*/) {
            if (!ec && isPost) {
                std::string body("input=somevalue");
                boost::beast::flat_buffer sendBuffer;
                http::write(sendBuffer, self->request_);
                self->request_.body().assign(body.begin(), body.end());
                self->socket_.write_some(boost::asio::buffer(sendBuffer.data()), ec);
            }

            if (!ec) {
                read_response();
            } else {
                ++errors_;
            }
        });
    }

    void read_response() {
        auto self = shared_from_this();
        boost::beast::flat_buffer buffer;
        http::response<http::dynamic_body> response;
        bool close = false;

        self->socket_.async_read_some(boost::asio::buffer(buffer), [self, &close](boost::system::error_code ec, size_t /*length*/) {
            if (ec == http::error::end_of_stream)
                close = true;
            else if (ec)
                ++self->errors_;

            if (!ec) {
                http::response<http::dynamic_body> oldResponse(buffer);
                response.swap(oldResponse);
                self->on_response(ec, response);
            }
        });
    }

    void on_response(const boost::system::error_code& ec, const http::response<http::dynamic_body>& response) {
        if (!ec && response.need_eof()) {
            ++self->requests_sent_;

            auto status = response.result() / 100;
            if (status >= 2) {
                self->proxies_ += response.body().size();

                if (!self->cache_.count(response.target())) {
                    self->cache_[response.target()] = std::move(response.body());
                    writeToLog("[" + std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()) + "] " + response.target() + " -> " + std::to_string(self->requests_sent_) + " requests, " + std::to_string(self->proxies_) + " bytes, " + std::to_string(self->errors_) + " errors");
                }
            }
        } else if (!ec) {
            ++self->errors_;
        }

        if (close)
            self->socket_.close();
    }

    boost::asio::io_context& io_service_;
    http::stream<tcp::socket> stream_;
    http::request<http::empty_body> request_;
    http::response<http::dynamic_body> response_;
    std::stringstream buffer_;
    mutable boost::beast::flat_buffer buffers_;
    tcp::socket socket_;
    std::shared_ptr<InterfaceTable> interfaceTable_;
    std::atomic<size_t> requests_sent_;
    std::atomic<size_t> proxies_;
    std::atomic<size_t> errors_;
    mutable std::map<std::string, std::vector<char>> cache_;
    std::shared_ptr<std::ofstream> log_;
    std::unique_ptr<boost::asio::strand> strand_;
};

void writeToLog(const std::string& message) {
    static constexpr size_t max_log_size = 1024 * 1024;
    static auto log_file = "http_requests.log";
    static std::mutex mtx;
    static auto log = std::make_shared<std::ofstream>(log_file, std::ios::out | std::ios::app);
    if (log->tellp() >= max_log_size) {
        std::unique_lock<std::mutex> lock(mtx);
        log.reset(new std::ofstream(log_file, std::ios::trunc));
    }

    *log << message << '\n';
}

