typedef struct Record {
    int value;
    long offset;
    int key;
} Record;

// Custom memory alignment function
void* aligned_malloc(size_t size, size_t alignment) {
    void* ptr = malloc(size + alignment - 1);
    if (ptr) {
        memset((char *)ptr + alignment - 1, 0, alignment);
        return (char *)ptr + alignment - 1;
    }
    return NULL;
}

// Memory management struct
typedef struct MemManager {
    size_t* offsets;
    int* keys;
    Record** records;
    size_t capacity;
    size_t used;
    size_t memory_limit;
    pthread_mutex_t lock;
} MemManager;

MemManager* mem_manager_init(size_t memory_limit) {
    MemManager* mm = (MemManager*)aligned_malloc(sizeof(MemManager), 64);
    if (!mm) {
        fprintf(stderr, "Failed to allocate memory for MemManager\n");
        return NULL;
    }

    mm->offsets = (size_t*)aligned_malloc((sizeof(size_t)) * memory_limit, 8);
    if (!mm->offsets) {
        fprintf(stderr, "Failed to allocate offsets array\n");
        free(mm);
        return NULL;
    }

    mm->keys = (int*)aligned_malloc((sizeof(int)) * memory_limit, 4);
    if (!mm->keys) {
        fprintf(stderr, "Failed to allocate keys array\n");
        free(mm->offsets);
        free(mm);
        return NULL;
    }

    mm->records = (Record**)aligned_malloc((sizeof(Record*) * memory_limit), 8);
    if (!mm->records) {
        fprintf(stderr, "Failed to allocate records array\n");
        free(mm->offsets);
        free(mm->keys);
        free(mm);
        return NULL;
    }

    mm->capacity = memory_limit;
    mm->used = 0;
