public:
    CombatStrategyManager(unsigned int numStrategies, unsigned int minCooldown, unsigned int maxCooldown)
        : strategies_(numStrategies), rng_(std::random_device{}()), effectivenessScores_{} {
        for (auto& strategy : strategies_) {
            strategy.id = rng() % MAX_STRATEGY_ID;
            strategy.cooldownMin = minCooldown + rng() % (maxCooldown - minCooldown + 1);
            strategy.priorityOffset = rng() % PRIORITY_OFFSET_RANGE + 1;
        }
    }

    void executeStrategy(CombatStrategy& strategy, std::function<void()> executionFunc) {
        auto it = effectivenessScores_.find(strategy.id);
        if (it == effectivenessScores_.end()) {
            it = effectivenessScores_.emplace_hint(std::end(effectivenessScores_), strategy.id, 0).first;
        }
        it->second += executeStrategyWithRetries(executionFunc);
    }

    void combatStrategyManager() {
        std::mutex mtx;
        std::vector<std::future<int>> futures;

        for (auto& strategy : strategies_) {
            if (!strategy.cooldownActive) {
                auto executionFunc = std::bind(&CombatStrategyManager::executeStrategyWithRetries, this, std::ref(strategy), std::placeholders::_1);
                auto task = std::async(std::launch::async, executionFunc, std::ref(mtx));
                futures.push_back(task);
                strategy.cooldownActive = true;
                strategy.cooldownEnd = std::chrono::system_clock::now() + std::chrono::seconds(strategy.cooldownMin);
            }
        }

        for (auto& future : futures) {
