            std::cout << "Strategy ID: " << id << ", Effectiveness Score: " << score << "\n";
        }

        strategies_.clear();
        effectivenessScores_.clear();
    }

private:
    int executeStrategyWithRetries(CombatStrategy& strategy, std::function<void()> executionFunc) {
        const unsigned int MAX_RETRIES = 3;
        const auto retryDelay = std::chrono::seconds(1);
        unsigned int retries = 0;
        int effectivenessScore = 0;

        for (; retries < MAX_RETRIES; ++retries) {
            try {
                executionFunc();
                success(); // Call predefined function to handle successful outcomes.
                return strategy.priorityOffset * retries + 1;
            } catch (const std::exception& e) {
                if (retries == MAX_RETRIES - 1) {
                    failure(e); // Call predefined function to handle failures.
                    return 0;
                }
                std::this_thread::sleep_for(retryDelay);
            }
        }

        return strategy.priorityOffset * retries + MAX_RETRIES;
    }

private:
