void init_list(struct list* list, size_t initial_size) {
    list->capacity = initial_size;
    list->length = 0;
    list->data = calloc(initial_size, sizeof(item));
    if (!list->data) {
        perror("Failed to allocate memory for data array");
        exit(1);
    }
    list->mutex = PTHREAD_MUTEX_INITIALIZER;
}

void push_item(struct list* list, const char* name, int value) {
    pthread_mutex_lock(&list->mutex);

    // Ensure capacity is not exceeded and allocate new memory if necessary
    if (list->length >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        item* tmp = realloc(list->data, new_capacity * sizeof(item));
        if (!tmp) {
            perror("Failed to allocate more memory for data array");
            pthread_mutex_unlock(&list->mutex);
            exit(1);
        }
        list->data = tmp;
        list->capacity *= 2;
    }

    // Set name and value for new item
    sprintf(list->data[list->length].name, "%ld", list->length);
    list->data[list->length].value = (rand() % 100) + 50;

    ++list->length;

    pthread_mutex_unlock(&list->mutex);
}

