CipherContext* initialize_cipher(const char *password) {
    // Initialize AES context with given password and derive key length from the password using SHA256
    unsigned char sha256[SHA256_DIGEST_LENGTH];
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, password, strlen(password));
    SHA256_Final(sha256, &sha256);
    int key_len = sha256[0] & 0xf;
    AES_KEY aes_ctx;
    AES_set_encrypt_key((const unsigned char *)sha256, key_len, &aes_ctx);
    CipherContext* ctx = malloc(sizeof(CipherContext));
    ctx->password = strdup(password);
    ctx->aes = aes_ctx;
    return ctx;
}

void destroy_cipher(CipherContext *ctx) {
    free(ctx->password);
    free(ctx);
}

int read_binary_file(const char *filename, unsigned char **buf, size_t *len) {
    FILE *file = fopen(filename, "rb");
    if (!file) return 0;
    fseek(file, 0, SEEK_END);
    *len = ftell(file);
    rewind(file);
    *buf = malloc(*len);
    size_t read = fread(*buf, 1, *len, file);
    fclose(file);
    if (read != *len) {
        free(*buf);
        return 0;
    }
    return 1;
}

void write_binary_file(const char *filename, const unsigned char *buf, size_t len) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;
    fwrite(buf, 1, len, file);
    fclose(file);
}

