    struct timeval tv;
    gettimeofday(&tv, NULL);
    long usec = tv.tv_usec + UPDATE_INTERVAL_USECS;
    struct timespec ts = {tv.tv_sec, usec};
    nanosleep(&ts, NULL);

    // Main processing loop
    while (true) {
        sem_wait(sem);

        for (uint32_t i = 0; i < num_ue_contexts; ++i) {
            lte_ue_context_t *ctx = &ctxs[i];

            if (!validate_measurements(ctx)) {
                log_func("Potential inconsistency detected in UE context %d.", i);
            }

            // Update measurements here based on network conditions
        }

        sem_post(sem);

        // Sleep for a configurable interval to minimize load and latency
        gettimeofday(&tv, NULL);
        usec = tv.tv_usec + SLEEP_INTERVAL_USECS;
        ts = (struct timespec){tv.tv_sec, usec};
        nanosleep(&ts, NULL);
    }

