```cpp
#include <iostream>
#include <vector>
#include <mutex>
#include <cstdint>
#include <cstring>
#include <algorithm>
#include <boost/serialization/access.hpp>
#include <boost/serialization/vector.hpp>
#include <boost/serialization/uint64_t.hpp>
#include <boost/serialization/int.hpp>
#include <boost/serialization/char.hpp>

struct Entry {
    std::uint64_t timestamp;
    int priority;
    char message[1024]; // Adjust the size according to requirements
    char padding[3];     // Placeholder for future extensions

    friend class boost::serialization::access;

    template<class Archive>
    void serialize(Archive & ar, const unsigned int version) {
        ar & timestamp & priority & message;
    }
};

struct EntryList {
    std::vector<Entry> entries;
    mutex mtx;

    void push_back(const Entry& entry) {
        lock_guard<mutex> lock(mtx);
        entries.push_back(entry);
        if (entries.size() > entries.capacity())
            entries.reserve(std::max(entries.size() * 2, 1024)); // Resize when necessary
    }

    class Iterator {
        std::vector<Entry>::iterator it;

    public:
        Iterator(std::vector<Entry>::iterator i) : it(i) {}

        Entry& operator*() const { return *it; }
        Iterator& operator++() { ++it; return *this; }
        bool operator!=(const Iterator& other) const { return it != other.it; }
    };

    Iterator begin() { return Iterator(entries.begin()); }
    Iterator end() { return Iterator(entries.end()); }
};
