    SensorData* data;
    size_t capacity;
    size_t length;
};

void free_sensor_data(SensorData* data) {
    if (!data) return;
    free(data);
}

void free_sensor_data_container(struct sensor_data_container* container) {
    if (!container) return;
    free_sensor_data(container->data);
    free(container);
}

struct sensor_data_container* create_sensor_data_container(size_t capacity) {
    struct sensor_data_container* container = (struct sensor_data_container*)malloc(sizeof(struct sensor_data_container));
    if (!container) return NULL;
    container->capacity = capacity;
    container->length = 0;
    container->data = (SensorData*)calloc(capacity, sizeof(SensorData));
    if (!container->data) {
        free_sensor_data_container(container);
        return NULL;
    }
    return container;
}

static size_t write_callback(void* contents, size_t size, size_t nmemb, void* userp) {
    size_t remaing = ((size_t*)userp)[0];
    size_t total = remaing + size * nmemb;
    if (total > 1e6) { // Limit response to 1MB
        return 0;
    }
    memcpy(((char*)userp) + remaing, contents, size * nmemb);
    ((size_t*)userp)[0] = total;
    return size * nmemb;
}

