static size_t WriteCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    HttpRequest *request = (HttpRequest *)userp;
    size_t realsize = size * nmemb;
    request->size += realsize;
    request->buffer = realloc(request->buffer, request->size + realsize);
    memcpy(&(request->buffer[request->size - realsize]), contents, realsize);
    return realsize;
}

// JSON parsing function to extract numerical values
