// Thread pool management functions
pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t queue_cv = PTHREAD_COND_INITIALIZER;
HttpRequest *request_queue[20] = {0};
int queue_head = 0, queue_tail = 0, num_threads = 0;

void enqueue_request(HttpRequest *req) {
    pthread_mutex_lock(&queue_mutex);
    while (num_threads == 20 && queue_head != queue_tail)
        pthread_cond_wait(&queue_cv, &queue_mutex);

    request_queue[queue_head] = req;
    queue_head = (queue_head + 1) % 20;
    num_threads++;
    pthread_mutex_unlock(&queue_mutex);
}

HttpRequest* dequeue_request() {
    HttpRequest *req;
    pthread_mutex_lock(&queue_mutex);
    req = request_queue[queue_tail];
    if (req) {
        queue_tail = (queue_tail + 1) % 20;
        num_threads--;
    }
    pthread_mutex_unlock(&queue_mutex);
    return req;
}

