    // Set encryption algorithm and key
    EVP_CIPHER_CTX_set_cipher(&ctx, cipher);
    EVP_CIPHER_CTX_set_key(&ctx, key);

    int plaintext_len = strlen(encrypted_message) + 1; // Account for null terminator
    unsigned char *plaintext = malloc(plaintext_len);

    if (!plaintext) {
        printf("Error: Failed to allocate memory for plaintext.\n");
        return;
    }

    int ciphertext_len = plaintext_len + AES_BLOCK_SIZE; // Account for padding and overhead
    unsigned char *ciphertext = malloc(ciphertext_len);

    if (!ciphertext) {
        printf("Error: Failed to allocate memory for ciphertext.\n");
        free(plaintext);
        return;
    }

    // Decrypt message and store the result in plaintext
    int decrypted_length = EVP_DecryptUpdate(&ctx, plaintext, &plaintext_len, (unsigned char*)encrypted_message, strlen(encrypted_message));
