typedef struct sensor_device {
    int id;
    time_t last_update;
    double temperature, humidity;
    bool quality_flag;
    sem_t update_sem;
    struct sensor_device *next;
} sensor_device;

struct network {
    size_t capacity;
    size_t window_size;
    size_t num_threads;
    double moving_average;
    sensor_device **devices;
    pthread_mutex_t devices_lock;
    semaphore_t device_queue;
};

sensor_device* create_sensor(int id) {
    sensor_device *sd = malloc(sizeof(sensor_device));
    sd->id = id;
    sd->last_update = time(NULL);
    sd->temperature = 0.0;
    sd->humidity = 0.0;
    sd->quality_flag = true;
    sem_init(&sd->update_sem, 0, 1);
    sd->next = NULL;
    return sd;
}

void add_sensor(struct network *network, sensor_device *sd) {
    pthread_mutex_lock(&network->devices_lock);
    sd->next = network->devices[network->capacity % network->capacity];
    network->devices[network->capacity % network->capacity] = sd;
    pthread_mutex_unlock(&network->devices_lock);
}

void move_average(struct network *network) {
    double sum = 0.0;
    size_t count = 0;

    pthread_mutex_lock(&network->devices_lock);
    for (size_t i = 0; i < network->capacity; ++i) {
        sensor_device *sd = network->devices[i];
        if (!sd) continue;

        if ((time(NULL) - sd->last_update <= network->window_size) && sd->quality_flag) {
            sum += sd->temperature;
            ++count;
        }
    }
    pthread_mutex_unlock(&network->devices_lock);

    if (count > 0)
        network->moving_average = sum / count;
}

