  id: Joi.string().required(),
  data: Joi.any().required()
});

app.put('/resources/:id', async (req, res) => {
  const { error } = updateSchema.validate(req.params);
  if (error) return res.status(400).json({ error: error.message });

  // Check if the resource exists in cache or database
  let resource;
  try {
    resource = await redisClient.get(`resource_${req.params.id}`);
  } catch (err) {
    try {
      const response = await axios.get(`/api/resources/${req.params.id}`);
      resource = response.data;
      redisClient.set(`resource_${req.params.id}`, JSON.stringify(resource), 'EX', 600); // Cache for 10 minutes
    } catch (err) {
      return res.status(404).json({ error: 'Resource not found' });
    }
  }

  // Implement optimistic locking or versioning for concurrent updates
  if (resource.version !== req.query.version) {
    return res.status(409).json({ error: 'Conflict during update' });
  }

  // Update the resource and cache it
  const updatedResource = { ...resource, data: req.body.data, version: uuidv4() };
  redisClient.set(`resource_${updatedResource.id}`, JSON.stringify(updatedResource), 'EX', 600);

  res.json(updatedResource);
});
