using System;
using System.Data;
using System.Data.SqlClient;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;
using System.Configuration;

public class DataProcessor
{
    private readonly HttpClient _httpClient;
    private readonly SqlConnection _dbConnection;
    private readonly int _maxConcurrentRequests = 50;
    private readonly int _maxRetries = 3;
    private readonly TimeSpan _retryInterval = TimeSpan.FromSeconds(5);

    public DataProcessor()
    {
        _httpClient = new HttpClient();
        var connectionString = ConfigurationManager.ConnectionStrings["DefaultConnection"].ConnectionString;
        _dbConnection = new SqlConnection(connectionString);
        _dbConnection.Open();
    }

    public async Task<IDataReader> ProcessRequestsAsync(List<string> urls, Func<HttpResponseMessage, object> processingFunction, Func<SqlCommand, IDataReader> dbQuery)
    {
        var semaphoreSlim = new SemaphoreSlim(_maxConcurrentRequests);
        var httpTasks = urls.Select(async url =>
        {
            await semaphoreSlim.WaitAsync();
            try
            {
                HttpResponseMessage response = await _httpClient.GetAsync(url);
                if (response.IsSuccessStatusCode)
                {
                    var result = processingFunction(response);
                    return result;
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error fetching data from '{url}': {ex.Message}");
            }
            finally
            {
                semaphoreSlim.Release();
            }

            return RetryHttpRequest(urls, url, processingFunction);
        }).ToList();

        var databaseTask = Task.Run(() =>
        {
            using (var command = new SqlCommand($"SELECT EmployeeName, City, Address FROM Employees WHERE SupervisorID = @SupervisorID", _dbConnection))
            {
                command.Parameters.AddWithValue("@SupervisorID", supervisorId);
                return dbQuery(command);
            }
        });

        var tasks = httpTasks.Concat(new[] { databaseTask }).ToList();
        var completedTasks = await Task.WhenAll(tasks);

        var consolidatedResultSet = new List<object>();
        foreach (var task in completedTasks)
        {
            if (task != null)
                consolidatedResultSet.Add(task);
        }

        return consolidatedResultSet.AsDataReader();
    }

    private async Task<object> RetryHttpRequest(List<string> urls, string currentUrl, Func<HttpResponseMessage, object> processingFunction)
    {
        for (int i = 0; i < _maxRetries; i++)
        {
            try
            {
                HttpResponseMessage response = await _httpClient.GetAsync(currentUrl);
                if (response.IsSuccessStatusCode)
                    return processingFunction(response);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error fetching data from '{currentUrl}': {ex.Message}");
            }
            await Task.Delay(_retryInterval);
        }

        Console.WriteLine($"Failed to fetch data from '{currentUrl}' after {_maxRetries} attempts.");
        return null;
    }
}
