void allocateAndInitializeRecords(size_t* userInput, int maxSize) {
    if (*userInput > maxSize || *userInput <= 0) {
        fprintf(stderr, "Invalid input size.\n");
        return;
    }

    long* offsets = malloc(*userInput * sizeof(long));
    if (!offsets) {
        perror("malloc failed");
        return;
    }

    int* keys = calloc(*userInput, sizeof(int));
    if (!keys) {
        free(offsets);
        perror("calloc failed");
        return;
    }

    for (size_t i = 0; i < *userInput; ++i) {
        keys[i] = rand() % 100 + 1; // Range: [1, 100]
        offsets[i] = i;
    }

    long sum = 0;
    for (size_t i = 0; i < *userInput; ++i) {
        sum += keys[i];
    }

    free(keys);
}
