```rust
use reqwest::{Client, Config};
use std::sync::Mutex;

static CLIENT_POOL: Mutex<Vec<Client>> = Mutex::new(vec![]);

fn createHttpClient(url: &str, validate_certificate: bool) -> Result<Client, reqwest::Error> {
    let mut clients = CLIENT_POOL.lock().unwrap();

    if clients.is_empty() || clients[0].is_err() {
        let config = Config::new().https(Config::default_tls_client());
        *clients = vec![Client::builder().config(config).build_session()?];
    }

    let client = match &*clients.last().unwrap() {
        Ok(ref c) => c.clone(),
        Err(_) => Client::builder().config(Config::new().https(Config::default_tls_client()))
            .build_session()?
    };

    client.get(url).send()?.error_for_status_ref(|res| {
        let status = res.status();
        if status >= 400 && status < 600 {
            reqwest::Error::new(reqwest::StatusCode::from_u32(status).unwrap(), format!("Request failed with status {}.", status))
        } else {
            reqwest::Error::new(reqwest::StatusCode::from_u32(500).unwrap(), "Internal server error.")
        }
    })?;

    if !validate_certificate {
        client.config().ssl_validator(None);
    }

    Ok(client)
}
```

