        exit(EXIT_FAILURE);
    }

    // Read integers from standard input and populate the record array with valid data.
    int i = 0;
    while (i < *size && scanf("%ld %d %d", &((*records)[i].offset), &((*records)[i].key), &((*records)[i].value) ) == 3) {
        if ((*records)[i].key <= 0 || (*records)[i].value <= 0 || (*records)[i].value > max_value) {
