std::string md5Hash(const char* str) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;

    MD5_Init(&ctx);
    MD5_Update(&ctx, str, strlen(str));
    MD5_Final(digest, &ctx);

    std::string result;
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        result += std::to_string(static_cast<unsigned int>(digest[i]));
        if (i != MD5_DIGEST_LENGTH - 1) {
            result += '-';
        }
    }

    return result;
}

