#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

typedef struct {
    float value;
    int ref_count;
    struct item *next;
} Item;

typedef struct {
    Item **items;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    Context *context;
} Node;

typedef struct {
    Node **nodes;
    size_t nodes_capacity;
    size_t nodes_count;
    Item *cache;
    size_t cache_capacity;
    size_t cache_hit_count;
    pthread_mutex_t cache_lock;
} Context;

void item_init(Item **item, float value) {
    *item = malloc(sizeof(Item));
    (*item)->value = value;
    (*item)->ref_count = 1;
    (*item)->next = NULL;
}

Node* node_create() {
    Node *node = malloc(sizeof(Node));
    node->items = NULL;
    node->capacity = 0;
    node->count = 0;
    pthread_mutex_init(&node->lock, NULL);
    return node;
}

void node_free(Node *node) {
    for (size_t i = 0; i < node->count; ++i) {
        Item *item = node->items[i];
        if (item != NULL) {
            free(item);
        }
    }

    free(node->items);
    pthread_mutex_destroy(&node->lock);
    free(node);
}

Context* context_create(size_t nodes_capacity) {
    Context *context = malloc(sizeof(Context));
    context->nodes = NULL;
    context->nodes_capacity = nodes_capacity;
    context->nodes_count = 0;
    context->cache = NULL;
    context->cache_capacity = 0;
    context->cache_hit_count = 0;
    pthread_mutex_init(&context->cache_lock, NULL);
    return context;
}

void context_free(Context *context) {
    for (size_t i = 0; i < context->nodes_count; ++i) {
        Node *node = context->nodes[i];
        node_free(node);
    }

    if (context->cache != NULL) {
        free(context->cache);
    }

    pthread_mutex_destroy(&context->cache_lock);
    free(context);
}

void cache_insert(Context *context, Item *item) {
    pthread_mutex_lock(&context->cache_lock);
    if (context->cache_capacity == context->cache_hit_count) {
        size_t new_capacity = context->cache_capacity * 2;
        Item *new_cache = realloc(context->cache, new_capacity * sizeof(Item));
        if (new_cache == NULL) {
            pthread_mutex_unlock(&context->cache_lock);
            return;
        }
        context->cache = new_cache;
        context->cache_capacity = new_capacity;
    }
    context->cache[context->cache_hit_count] = item;
    context->cache_hit_count++;
    pthread_mutex_unlock(&context->cache_lock);
}

Item* cache_get(Context *context) {
    pthread_mutex_lock(&context->cache_lock);
    if (context->cache_hit_count > 0 && context->cache != NULL) {
        Item *item = context->cache[context->cache_hit_count - 1];
        context->cache_hit_count--;
        pthread_mutex_unlock(&context->cache_lock);
        return item;
    }
    pthread_mutex_unlock(&context->cache_lock);
    return NULL;
}

void populate(Context *context, size_t node_count, float min, float max) {
    for (size_t i = 0; i < node_count; ++i) {
        Node *node = context->nodes[i];
        srand(time(NULL));

        pthread_mutex_lock(&node->lock);
        for (size_t j = node->count; j < node->capacity; ++j) {
            Item *item = cache_get(context);
            if (item == NULL) {
                item_init(&item, (rand() % static_cast<int>((max - min) + 1)) + min);
            }

            node->items[j] = item;
            item->ref_count++;
        }
        pthread_mutex_unlock(&node->lock);
    }
}

void* create_and_populate(void *arg) {
    Context *context = static_cast<Context*>(arg);
    size_t node_count = context->nodes_capacity;
    node_count = (node_count < 1) ? 1 : node_count;

    for (size_t i = context->nodes_count; i < node_count; ++i) {
        Node *node = node_create();
        node->capacity = rand() % 10 + 5;
        node->items = malloc(node->capacity * sizeof(Item*));

        for (size_t j = 0; j < node->capacity; ++j) {
            item_init(&node->items[j], (rand() % static_cast<int>((max - min) + 1)) + min);
        }

        context->nodes[i] = node;
        context->nodes_count++;
    }

    populate(context, node_count, min, max);

    return NULL;
}

void cleanup(Context *context) {
    pthread_t threads[context->nodes_count];

    for (size_t i = 0; i < context->nodes_count; ++i) {
        pthread_create(&threads[i], NULL, &cleanup_node, static_cast<void*>(context->nodes[i]));
    }

    for (size_t i = 0; i < context->nodes_count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void* cleanup_node(void *arg) {
    Node *node = static_cast<Node*>(arg);
    node_free(node);
    return NULL;
}
