typedef struct {
    time_t timestamp;
    int status;
    long value;
} Record;

// Custom shuffle function, optimized for performance and minimal memory usage
void custom_shuffle(Record *records, size_t size) {
    for (size_t i = 0; i < size - 1; ++i) {
        size_t j = i + 1;
        while (j < size && records[j].status == records[i].status) {
            ++j;
        }
        if (j != i + 1) {
            Record temp = records[i];
            records[i] = records[j];
            records[j] = temp;
        }
    }
}

void manage_records(Record **records, size_t *offsets, size_t capacity, size_t num_keys, void (*key_map)[capacity]) {
    // Allocate memory for records and initialize timestamps with current time and status indicators with default value.
    *records = malloc(num_keys * sizeof(Record));
    memset(*records, 0, num_keys * sizeof(Record));
    for (size_t i = 0; i < num_keys; ++i) {
        (*records + i)->timestamp = time(NULL);
        (*records + i)->offset = offsets[i];
    }

    // Initialize offsets array with sequential values.
    for (size_t i = 0; i < capacity; ++i) {
        if (!offsets[i]) {
            offsets[i] = i;
        }
    }

    // Update each record’s timestamp and set its status based on the key_map.
    for (size_t i = 0; i < num_keys; ++i) {
        size_t key = key_map[i][0];
