#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Record {
    int value;
};

struct MemoryPool {
    void* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
};

void init_memory_pool(struct MemoryPool* pool, size_t initial_size) {
    pool->data = malloc((initial_size + 1) * sizeof(long) + (initial_size + 1) * sizeof(int) + initial_size * sizeof(struct Record));
    if (!pool->data) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    pool->capacity = initial_size * 2;
    pool->size = initial_size;
    pool->lock = PTHREAD_MUTEX_INITIALIZER;
}

long* get_offsets(struct MemoryPool* pool) {
    return (long*) pool->data;
}

int* get_keys(struct MemoryPool* pool) {
    return ((long*) pool->data + pool->size);
}

struct Record* get_records(struct MemoryPool* pool) {
    return ((int*) pool->data + 2 * pool->size);
}

void extend_memory_pool(struct MemoryPool* pool) {
    void* new_data = realloc(pool->data, (pool->capacity + (pool->capacity / 2)) * sizeof(long) + (pool->capacity + (pool->capacity / 2)) * sizeof(int) + (pool->capacity + (pool->capacity / 2)) * sizeof(struct Record));
    if (!new_data) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    pool->data = new_data;
    pool->capacity *= 2;
}

void initialize_records(struct MemoryPool* pool, size_t count) {
    pthread_mutex_lock(&pool->lock);

    if (pool->size + count > pool->capacity) {
        extend_memory_pool(pool);
    }

    struct Record* records = get_records(pool) + pool->size;

    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % 100;
    }

    pool->size += count;

    pthread_mutex_unlock(&pool->lock);
}

struct MemoryPool offsets_keys_records_pool;

void initialize_system(size_t initial_offsets, size_t initial_keys, size_t initial_records) {
    init_memory_pool(&offsets_keys_records_pool, initial_offsets);

    long* offsets = get_offsets(&offsets_keys_records_pool);
    for (size_t i = 0; i < initial_offsets; ++i) {
        offsets[i] = i;
    }

    int* keys = get_keys(&offsets_keys_records_pool);
    for (size_t i = 0; i < initial_keys; ++i) {
        keys[i] = rand() % 100;
    }

    initialize_records(&offsets_keys_records_pool, initial_records);
}
