typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    TAI_RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU;

typedef struct _NFAPI_DYNAMIC_LIST {
    NFAPI_CRC_INDICATION_PDU* data;
    size_t capacity;
    size_t count;
    MemPool* mem_pool;
    pthread_mutex_t lock;
    Logging* log;
} NFAPI_DYNAMIC_LIST;

NFAPI_DYNAMIC_LIST* init_dynamic_list(MemPool* mem_pool, Logging* log) {
    NFAPI_DYNAMIC_LIST* list = malloc(sizeof(NFAPI_DYNAMIC_LIST));
    if (!list) {
        log_error("Failed to allocate memory for dynamic list");
        return NULL;
    }

    list->data = NULL;
    list->capacity = 0;
    list->count = 0;
    list->mem_pool = mem_pool;
    pthread_mutex_init(&list->lock, NULL);
    list->log = log;

    return list;
}

void destroy_dynamic_list(NFAPI_DYNAMIC_LIST* list) {
    if (list->data) {
        size_t i;
        for (i = 0; i < list->count; ++i) {
            free(list->data[i].crc_indication.buffer);
        }
        free(list->data);
    }

    free(list);
}

void* dynamic_list_mem_pool_alloc(size_t size, MemPool* pool) {
    void* mem = pool_alloc(pool, size);
    if (!mem) {
        log_error("Failed to allocate memory from memory pool");
    }
    return mem;
}

void dynamic_list_mem_pool_free(void* mem, MemPool* pool) {
    pool_free(pool, mem);
}

NFAPI_CRC_INDICATION_PDU* create_nfapi_crc_indication_pdu() {
    NFAPI_CRC_INDICATION_PDU* pdu = (NFAPI_CRC_INDICATION_PDU*)dynamic_list_mem_pool_alloc(sizeof(NFAPI_CRC_INDICATION_PDU), list->mem_pool);
    if (!pdu) {
        return NULL;
    }

    pdu->crc_indication.crcflag = rand() % 2;

    return pdu;
}

void insert(NFAPI_DYNAMIC_LIST* list, RX_UE_INFORMATION_TAG tag, TAI_RNTI rnti) {
    pthread_mutex_lock(&list->lock);

    size_t i, found = 0;
    for (i = 0; i < list->count; ++i) {
        if (list->data[i].tag == tag && list->data[i].rnti == rnti) {
            found = 1;
            break;
        }
    }

    if (!found) {
        NFAPI_CRC_INDICATION_PDU* new_pdu = create_nfapi_crc_indication_pdu();
        if (!new_pdu) {
            pthread_mutex_unlock(&list->lock);
            return;
        }

        new_pdu->tag = tag;
        new_pdu->rnti = rnti;

        if (list->count == list->capacity) {
            NFAPI_CRC_INDICATION_PDU** new_data = dynamic_list_mem_pool_alloc(sizeof(NFAPI_CRC_INDICATION_PDU*) * (list->capacity * 2), list->mem_pool);
            if (!new_data) {
                free(new_pdu);
                pthread_mutex_unlock(&list->lock);
                return;
            }

            memmove(new_data, list->data, list->count * sizeof(NFAPI_CRC_INDICATION_PDU*));
            dynamic_list_mem_pool_free(list->data, list->mem_pool);
            list->data = new_data;
            list->capacity *= 2;
        }

        list->data[list->count] = new_pdu;
        ++list->count;
    }

    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU* find(NFAPI_DYNAMIC_LIST* list, RX_UE_INFORMATION_TAG tag, TAI_RNTI rnti) {
    pthread_mutex_lock(&list->lock);

