```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

struct task {
    char *name;
    struct timespec deadline;
    int priority;
    struct task *next;
};

struct priority_queue {
    pthread_mutex_t lock;
    struct task *head[3]; //priority levels: 0-2
};

void push(struct priority_queue *pq, struct task *task) {
    pthread_mutex_lock(&pq->lock);
    int level = task->priority;
    task->next = pq->head[level];
    pq->head[level] = task;
    pthread_mutex_unlock(&pq->lock);
}

struct task *pop(struct priority_queue *pq, int level) {
    pthread_mutex_lock(&pq->lock);
    struct task *task = pq->head[level];
    if (task != NULL) {
        pq->head[level] = task->next;
    }
    pthread_mutex_unlock(&pq->lock);
    return task;
}

void init_queue(struct priority_queue *pq) {
    for (int i = 0; i < 3; ++i) {
        pq->head[i] = NULL;
    }
    pthread_mutex_init(&pq->lock, NULL);
}

void task_free(struct task *task) {
    free(task->name);
    free(task);
}

// Create and initialize a priority queue and return a pointer to it.
struct priority_queue* create_priority_queue() {
    struct priority_queue *pq = malloc(sizeof(struct priority_queue));
    if (!pq) {
        perror("Memory allocation error.");
        exit(1);
    }
    init_queue(pq);
    return pq;
}
```

This code defines a `task` structure and a `priority_queue` structure that manages tasks by priority level. The functions `push`, `pop`, and `init_queue` allow you to add, remove, and initialize the queue, respectively. The `create_priority_queue` function creates and initializes a new queue dynamically.

