typedef struct {
    size_t offset;
    const char *key;
    int value;
} Record;

typedef struct {
    std::map<const char*, size_t> key_to_index;
    size_t num_records;
    Record* records;
} Pipeline;

Pipeline* initialize_pipeline(size_t offsets_count, size_t keys_count, size_t event_subset_size) {
    Pipeline *pipeline = (Pipeline*)malloc(sizeof(Pipeline));
    if (!pipeline) {
        fprintf(stderr, "Failed to allocate pipeline memory\n");
        return NULL;
    }

    pipeline->key_to_index.clear();
    pipeline->num_records = 0;

    pipeline->records = (Record*)calloc(offsets_count * keys_count, sizeof(Record));
    if (!pipeline->records) {
        fprintf(stderr, "Failed to allocate records memory\n");
        free(pipeline);
        return NULL;
    }

    std::vector<size_t> offsets(offsets_count), keys(keys_count);

    // Populate offsets and keys arrays with user-provided values

    // Initialize records with random integer values
    for (size_t i = 0; i < offsets_count * keys_count; ++i) {
        pipeline->records[i].value = rand() % 100 + 1;
        pipeline->records[i].offset = offsets[i % offsets_count];
        pipeline->records[i].key = keys[i % keys_count];
    }

    // Initialize key-to-index mapping and record indices
    for (size_t i = 0; i < offsets_count * keys_count; ++i) {
        const char* key = pipeline->records[i].key;
        size_t index = pipeline->key_to_index.find(key)->second;
        if (index == (size_t)-1) {
            index = pipeline->num_records++;
            pipeline->key_to_index[key] = index;
        }
        pipeline->records[i].index = index;
    }

    // Initialize events array with non-overlapping subsets of records
    size_t event_count = offsets_count * keys_count / event_subset_size;
    std::vector<std::vector<Record*>> events(event_count);
    for (size_t i = 0, j = 0; i < offsets_count * keys_count; ++i) {
        const size_t index = pipeline->records[i].index;
        if (j >= event_subset_size || i - events[j][events[j].size() - 1]->index > event_subset_size) {
