    public class XmlDocumentManager
    {
        private ConcurrentDictionary<string, XElement> _cache = new ConcurrentDictionary<string, XElement>();
        private HttpClient _httpClient = new HttpClient();
        private TimeSpan _cacheDuration;
        private int _maxCacheSize;
        private string _apiEndpoint;
        private Logger _logger;

        public XmlDocumentManager(TimeSpan cacheDuration, int maxCacheSize, string apiEndpoint, Logger logger)
        {
            _cacheDuration = cacheDuration;
            _maxCacheSize = maxCacheSize;
            _apiEndpoint = apiEndpoint;
            _logger = logger;
        }

        public async Task<XElement> LoadDocumentAsync(string url)
        {
            if (_cache.TryGetValue(url, out var cached)) return cached;

            XElement document;

            try
            {
                var response = await _httpClient.GetAsync(url);
                if (!response.IsSuccessStatusCode) throw new Exception($"Failed to load XML document: {url}");

                document = XDocument.Load(await response.Content.ReadAsStreamAsync()).Root;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex);
                return LoadFromCache(url);
            }

            UpdateCache(document, url);
            return document;
        }

        public void UpdateDocumentAsync(string url)
        {
            Task.Run(async () =>
            {
                try
                {
                    var metadata = await FetchMetadata();
                    if (metadata != null && !IsUpdated(url, metadata)) return;

                    var document = LoadFromCache(url);
                    await ProcessDocumentUpdateAsync(document, url);
                    UpdateCache(document, url);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex);
                }
            });
        }

