        }

        private async Task ProcessDocumentUpdateAsync(XElement document, string url)
        {
            // Implement specific processing logic for updating XML documents based on the received metadata
        }

        private void UpdateCache(XElement document, string key)
        {
            if (_cache.Count > _maxCacheSize) _cache.TryRemove(_cache.MinByKey(x => x.Value.ToString().Length).Key);
            _cache[key] = document;
        }

        private XElement LoadFromCache(string key)
        {
            if (_cache.TryGetValue(key, out var value)) return value;
            return null;
        }
    }
