void write_ue_context_to_file(const char* filename, LTE_UE_CONTEXT* ue) {
    sem_wait(&filename_mutex);
    FILE* file = fopen(filename, "w");
    if (!file) {
        perror("Error opening file");
        sem_post(&filename_mutex);
        return;
    }

    // Serialize the ue context data to the file

    fclose(file);
    sem_post(&filename_mutex);
}

void* create_ue_contexts(void* args) {
    int max_ues = *(int*)args;

    for (int i = 0; i < max_ues; ++i) {
        LTE_UE_CONTEXT* ue = create_ue_context(i, RB_10); // Choose appropriate frequency bands based on your system's requirements
        validate_measurements(ue);

        char* filename = generate_unique_filename("lte_ue_contexts");
        write_ue_context_to_file(filename, ue);

        free(ue);
    }

    return NULL;
}

int main(int argc, char** argv) {
    if (argc != 2) {
        printf("Usage: %s <number_of_ues>\n", argv[0]);
        return 1;
    }

    int max_ues = atoi(argv[1]);

    init_filename_mutex();

    pthread_t threads[max_ues];
    for (int i = 0; i < max_ues; ++i) {
        int rc = pthread_create(&threads[i], NULL, create_ue_contexts, &max_ues);
        if (rc) {
            perror("Error creating thread");
            return rc;
        }
    }

    for (int i = 0; i < max_ues; ++i) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&filename_mutex);
    return 0;
}
