#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <NFAPI_CRC_INDICATION_PDU_T.h>
#include <memory_management_module.h>
#include <logging_library.h>

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    semaphore_t sem;
} dynamic_list_t;

static dynamic_list_t *mem_pool = NULL;

void initialize_memory_pool() {
    mem_pool = memory_management_module_create(sizeof(NFAPI_CRC_INDICATION_PDU_T), 10000);
}

dynamic_list_t *create_list() {
    dynamic_list_t *list = (dynamic_list_t *)memory_management_module_get(mem_pool);
    list->data = NULL;
    list->capacity = 0;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    sem_init(&list->sem, 0, 1);
    return list;
}

void destroy_list(dynamic_list_t *list) {
    if (list == NULL)
        return;

    pthread_mutex_destroy(&list->lock);
    sem_destroy(&list->sem);
    memory_management_module_put(mem_pool, list);
}

NFAPI_CRC_INDICATION_PDU_T *acquire_element(dynamic_list_t *list) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = memory_management_module_get(mem_pool);
    if (pdu == NULL) {
        log_error("Out of memory!");
        return NULL;
    }

    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        size_t new_capacity = (list->capacity * 2 > 10000) ? list->capacity : list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = memory_management_module_realloc(mem_pool, list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            log_error("Failed to reallocate memory!");
            pthread_mutex_unlock(&list->lock);
            return NULL;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    memcpy((void *)&list->data[list->size], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size++;

    sem_post(&list->sem);
    pthread_mutex_unlock(&list->lock);
    return pdu;
}

void release_element(dynamic_list_t *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pthread_mutex_trylock(&list->lock) != 0)
        sem_wait(&list->sem);

    list->data[list->size - 1] = *pdu;
    list->size--;

    pthread_mutex_unlock(&list->lock);
    memory_management_module_put(mem_pool, pdu);
}
