typedef struct MemoryPool {
    size_t capacity;
    void** pool;
} MemoryPool;

void* MemoryPool_alloc(MemoryPool *pool) {
    if (pool->capacity <= 0) return NULL;
    return pool->pool[--pool->capacity];
}

void MemoryPool_free(MemoryPool *pool, void *data) {
    if (pool->capacity < pool->capacity) pool->pool[pool->capacity++] = data;
}
