typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

static Node **head = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init() {
    if (!head) {
        pthread_mutex_lock(&mutex);
        head = (Node **)calloc(1, sizeof(Node*));
        *head = NULL;
        pthread_mutex_unlock(&mutex);
    }
}

void destroy() {
    Node *current, *next;
    pthread_mutex_lock(&mutex);
    for (current = *head; current; current = next) {
        next = current->next;
        free(current);
    }
    free(*head);
    *head = NULL;
    pthread_mutex_unlock(&mutex);
}

void insert(const NFAPI_CRC_INDICATION_PDU_T *data) {
    Node **current = head, *new_node;

    pthread_mutex_lock(&mutex);
    while (*current && (*current)->data.rnti < data->rnti)
        current = &(*current)->next;

    new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    new_node->data = *data;
    new_node->next = *current;
    *current = new_node;

    pthread_mutex_unlock(&mutex);
}

void cleanup() {
    time_t now = time(NULL);
    Node *current, *dead;
    pthread_mutex_lock(&mutex);

    for (current = *head; current; current = dead) {
        dead = current->next;
        if (difftime(now, current->data.timestamp) > MAX_LIFESPAN) {
            current->next = dead;
            free(current);
        }
    }
    pthread_mutex_unlock(&mutex);
}
