#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <openssl/crypto.h>
#include <vector>

typedef struct {
    const char *name;
    const char *cipher_suite;
} AlgorithmInfo;

std::vector<AlgorithmInfo*> load_algorithms(const char *filename) {
    std::vector<AlgorithmInfo*> algorithms;
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening configuration file");
        return algorithms;
    }

    ssize_t len;
    char line[4096];
    while ((len = readline(fd, line, sizeof(line))) > 0) {
        AlgorithmInfo *info = (AlgorithmInfo*) malloc(sizeof(AlgorithmInfo));
        info->name = strtok(line, ":");
        info->cipher_suite = strtok(NULL, "\n");
        algorithms.push_back(info);
    }

    close(fd);
    return algorithms;
}

const char *get_hash_function(const char *name) {
    const EVP_MD *md = EVP_get_digestbyname(name);
    if (!md) {
        fprintf(stderr, "Error: Unsupported hash function %s\n", name);
        return NULL;
    }
    return md->nid;
}

const char *get_cipher_function(const char *name) {
    const EVP_CIPHER *cipher = EVP_get_cipherbyname(name);
    if (!cipher) {
        fprintf(stderr, "Error: Unsupported cipher %s\n", name);
        return NULL;
    }
    return cipher->nid;
}

std::vector<AlgorithmInfo*> get_available_algorithms(const char *filename) {
    std::vector<AlgorithmInfo*> algorithms = load_algorithms(filename);
    for (AlgorithmInfo *info : algorithms) {
        info->name = get_hash_function(info->name);
        if (!info->name) continue;

        info->cipher_suite = get_cipher_function(info->cipher_suite);
        if (!info->cipher_suite) continue;
    }
    return algorithms;
}
```

