    std::uint64_t timestamp;
    std::uint32_t sequence_number;
    int cell_id;
};

class NFAPIManager {
public:
    explicit NFAPIManager(int max_structures);

    void addRequest(const CRC_INDICATION_PDU_T& req, std::function<void(const CRC_INDICATION_PDU_T&)> cb);

private:
    static inline constexpr size_t align_to(size_t value) { return value & ~(sizeof(CRC_INDICATION_PDU_T)-1); }
    void handleRequest(const CRC_INDICATION_PDU_T& req, std::function<void(const CRC_INDICATION_PDU_T&)> cb);

    std::vector<CRC_INDICATION_PDU_T> structures_;
    std::mutex structures_mutex_;
    int max_structures_;
    boost::asio::io_service io_service_;
    std::atomic_int num_requests_{0};
    std::atomic_int num_retries_{0};
    std::atomic<bool> circuit_breaker_{false};
};

NFAPIManager::NFAPIManager(int max_structures) : max_structures_(max_structures), structures_(align_to(sizeof(CRC_INDICATION_PDU_T))*max_structures, CRC_INDICATION_PDU_T()) {}

void NFAPIManager::addRequest(const CRC_INDICATION_PDU_T& req, std::function<void(const CRC_INDICATION_PDU_T&)> cb) {
    if (max_structures_ <= 0) {
        // Handle invalid input parameters
        return;
    }

    boost::unique_lock<std::mutex> lock(structures_mutex_);
    for (auto it = structures_.begin(); it != structures_.end(); ++it) {
        if (!it->timestamp || !it->sequence_number || it->cell_id < 0) {
            // Initialize empty structure with valid data
            it->tag.setTag(1);
            it->rnti = rand() % std::numeric_limits<uint16_t>::max();
            it->crc_indication_tag.setValue(rand());
            it->crcflag = rand() % 2 == 0;
            it->timestamp = std::time(nullptr);
            it->sequence_number = ++num_requests_;
            it->cell_id = std::this_thread::get_id();
        }
    }
    structures_.emplace_back(req);
    lock.unlock();

    if (circuit_breaker_) {
        // Circuit breaker is closed, add request to the backlog and return
        cb(structures_.back());
        return;
    }

    boost::asio::post(io_service_, [this, req, cb]() { handleRequest(req, cb); });
}

void NFAPIManager::handleRequest(const CRC_INDICATION_PDU_T& req, std::function<void(const CRC_INDICATION_PDU_T&)> cb) {
    // Implement retry mechanism with configurable backoff strategies
    static constexpr int max_retries = 5;
    static constexpr unsigned int initial_backoff_ms = 100;
    static constexpr double backoff_multiplier = 2.0;

    boost::unique_lock<std::mutex> lock(structures_mutex_);
    for (int i = 0; i < max_retries; ++i) {
        if (structures_.size() >= max_structures_) {
            // Handle memory exhaustion
            break;
        }
        if (structures_[req.sequence_number - num_requests_] == req) {
            lock.unlock();
            cb(req);
            return;
        }
        boost::this_thread::sleep_for(boost::chrono::milliseconds(initial_backoff_ms * std::pow(backoff_multiplier, i)));
    }

    // Handle potential failures gracefully by updating circuit breaker and backlogging the request
    if (++num_retries_ > 10) {
        circuit_breaker_.store(true);
    }
    cb(structures_[req.sequence_number - num_requests_]);
}
} // namespace NFAPI
