// Thread-safe memory pool with auto-resizing
class MemoryPool {
public:
    MemoryPool(size_t initialSize) : data_(initialSize), cache_(128) {}

    // Returns a pointer to a new block of memory, resizes if necessary
    void* Allocate() {
        if (data_.empty()) {
            Resize();
        }
        void* ptr = data_[--end_];
        std::fill(ptr, ptr + sizeof(long), 0);
        return ptr;
    }

    // Frees the memory block at the given pointer and returns it to the pool if possible
    void Free(void* ptr) {
        if (ptr >= data_.data() && ptr < data_.data() + data_.size()) {
            new (ptr) long();
            std::fill(ptr, ptr + sizeof(long), 0);
            data_[end_++] = nullptr;
        }
    }

private:
    void Resize() {
        auto newDataSize = static_cast<size_t>(2 * data_.size());
        auto oldData = std::move(data_);
        data_.resize(newDataSize);
        std::copy(oldData.begin(), oldData.end(), data_.begin());
    }

    std::vector<void*> data_; // Dynamic array for offsets
    std::vector<void*>::iterator end_; // Iterator tracking the last allocated block
    std::unordered_map<int, int> cache_; // Hash-based deduplication of keys
};

