public:
    void Enqueue(std::function<void()> task) {
        std::unique_lock<std::mutex> lock(mtx_);
        taskQueue_.emplace_back(task);
        cond_.notify_one();
    }

    void ProcessTasks() {
        while (!taskQueue_.empty()) {
            auto task = std::move(taskQueue_.front());
            taskQueue_.pop_front();
            lock_.lock();
            task();
            lock_.unlock();
        }
    }

private:
    std::priority_queue<std::function<void()>, std::vector<std::function<void()>>, std::greater<std::function<void()>>> taskQueue_;
    MutexLock mtx_;
    MutexLock lock_;
    std::condition_variable cond_;
};
