typedef struct RNTI_CRC_NODE {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct RNTI_CRC_NODE *prev, *next;
} RNTI_CRC_NODE;

struct thread_data {
    RNTI_CRC_NODE **head_ptr;
    pthread_t tid;
};

void init_list(RNTI_CRC_NODE **head) {
    *head = NULL;
}

RNTI_CRC_NODE* create_node() {
    RNTI_CRC_NODE *new_node = (RNTI_CRC_NODE*) malloc(sizeof(RNTI_CRC_NODE));
    if (!new_node) return NULL;
    new_node->prev = new_node->next = new_node;
    new_node->data.timestamp = time(NULL);
    new_node->data.CRCFLAG = (uint32_t)rand();
    return new_node;
}

void insert_node(RNTI_CRC_NODE **head, RNTI_CRC_NODE *new_node) {
    if (!*head) {
        *head = new_node;
        (*head)->prev = *head;
        (*head)->next = *head;
    } else {
        RNTI_CRC_NODE *current = *head;
        while (1) {
            if (current->data.RNTI == new_node->data.RNTI) {
                current->prev->next = new_node;
                new_node->next = current;
                new_node->prev = current->prev;
                current->prev = new_node;
                break;
            }
            if (current == (*head)->prev) {
                current->prev->next = new_node;
                new_node->next = *head;
                new_node->prev = (*head)->prev;
                (*head)->prev = new_node;
                break;
            }
            current = current->next;
        }
    }
}

RNTI_CRC_NODE* find_node(const RNTI_CRC_NODE *head, uint32_t rnti) {
    for (RNTI_CRC_NODE *current = head->next; current != head; current = current->next) {
        if (current->data.RNTI == rnti)
            return current;
    }
    return NULL;
}

void* thread_func(void *arg) {
    struct thread_data *data = arg;
    RNTI_CRC_NODE *new_node;

    while (1) {
        new_node = create_node();
        if (!new_node) break;
        insert_node(data->head_ptr, new_node);
        pthread_yield();
    }

    data->tid = 0;
    return NULL;
}

RNTI_CRC_NODE* get_head(const RNTI_CRC_NODE *head) {
    return head->next != head ? head->next : NULL;
}
