        exit(1);
    }
    task->name = strdup(name);
    task->priority = rand() % 10 + 1;
    task->next = NULL;
    pthread_mutex_init(&task->lock, NULL);
    return task;
}

void insert_task(Task** head, Task* task) {
    if (*head == NULL) {
        *head = task;
    } else {
        Task* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = task;
    }
}

void manage_resources(Node** nodes, Data** data, Task** head) {
    for (int i = 0; i < nodes_size; ++i) {
        init_data(nodes[i]->data);
        // Use the dynamically allocated data structure here

        // Insert a new task with a random priority
        Task* task = create_task("Task");
        insert_task(head, task);
    }
}

void cleanup(Node** nodes, Data** data, Task** head) {
    for (int i = 0; i < nodes_size; ++i) {
        free(nodes[i]);
    }
    free(nodes);

    if (data != NULL) {
        free(*data);
        *data = NULL;
    }

    Task* current = *head;
    while (*head != NULL) {
        current = *head;
        *head = current->next;
        free(current->name);
        free(current);
    }
