#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Task {
    char name[256];
    int priority;
    long timestamp;
} Task;

typedef void (*TaskCallback)(Task*);

// Function to create and manage a dynamic collection of tasks with error handling
void manage_tasks(size_t max_tasks, Task*** tasks, TaskCallback callback, size_t initial_capacity) {
    *tasks = malloc(initial_capacity * sizeof(Task*));
    if (*tasks == NULL) {
        fprintf(stderr, "Failed to allocate memory for tasks array\n");
        return;
    }

    size_t num_tasks = 0;
    Task** current_tasks = *tasks;

    // Function to insert a new task into the dynamic collection
    void push_task(Task* task) {
        if (num_tasks == max_tasks) {
            size_t new_capacity = initial_capacity * 2;
            Task** temp_array = realloc(current_tasks, new_capacity * sizeof(Task*));
            if (temp_array == NULL) {
                fprintf(stderr, "Failed to reallocate memory for tasks array\n");
                return;
            }
            current_tasks = temp_array;
            initial_capacity *= 2;
        }
        current_tasks[num_tasks] = malloc(sizeof(Task));
        if (current_tasks[num_tasks] == NULL) {
            fprintf(stderr, "Failed to allocate memory for task %ld\n", num_tasks);
            return;
        }
        memcpy(current_tasks[num_tasks], task, sizeof(Task));
        num_tasks++;
    }

    // Function to remove a task from the dynamic collection
    void pop_task() {
        if (num_tasks == 0) return;
        free(current_tasks[0]);
        memmove(current_tasks, current_tasks + 1, --num_tasks * sizeof(Task*));
    }

    qsort(*tasks, num_tasks, sizeof(Task*), (int (*)(const void*, const void*)) compare_tasks);

    // Function to compare two tasks based on priority and timestamp
    int compare_tasks(const void* a, const void* b) {
        Task* ta = (Task*)a;
        Task* tb = (Task*)b;

        if (ta->priority != tb->priority) return tb->priority - ta->priority;
        return tb->timestamp - ta->timestamp;
    }

    // Process tasks based on priority and callback function
    for (size_t i = 0; i < num_tasks && callback != NULL; i++) {
        Task* current_task = (*tasks)[i];
        if (current_task->priority <= getpriority(0)) {
            callback(current_task);
            pop_task();
        }
    }
}
