#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    int value;
    long offset;
    int key;
} record;

typedef struct {
    long offset;
    size_t index;
} lookup;

struct cache {
    record* records;
    lookup* lookups;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
};

struct cache* create_cache(size_t capacity) {
    struct cache* cache = malloc(sizeof(struct cache));
    if (!cache) return NULL;
    cache->capacity = capacity;
    cache->size = 0;
    cache->records = calloc(capacity, sizeof(record));
    if (!cache->records) {
        free(cache);
        return NULL;
    }
    cache->lookups = calloc(capacity, sizeof(lookup));
    if (!cache->lookups) {
        free(cache->records);
        free(cache);
        return NULL;
    }
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void destroy_cache(struct cache* cache) {
    free(cache->records);
    free(cache->lookups);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

record* init_data_structures(size_t size, size_t record_size, size_t key_range) {
    record* records = malloc(sizeof(record) * size);
    if (!records) return NULL;
    long* offsets = calloc(size, sizeof(long));
    int* keys = calloc(size, sizeof(int));
    if (!offsets || !keys) {
        free(records);
        return NULL;
    }

    lookup* lookups = malloc(sizeof(lookup) * size);
    if (!lookups) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand() % key_range;
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        lookups[i] = (lookup){ .offset = offsets[i], .index = i };
    }

    return records;
}

void populate_data(struct cache* cache, size_t size, size_t record_size, size_t key_range) {
    record* data = init_data_structures(size, record_size, key_range);
    if (!data) return;

    pthread_mutex_lock(&cache->lock);
    memcpy(cache->records, data, sizeof(record) * size);
    memcpy(cache->lookups, data + size, sizeof(lookup) * size);
    pthread_mutex_unlock(&cache->lock);
}

// Implement additional functions for batch processing, caching, thread safety, etc.
```
