#include <pthread.h>
#include <stdlib.h>
#include <time.h>
#include <sys/mman.h>

typedef struct {
    time_t timestamp;
    uint32_t sequence_id;
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
    pthread_mutex_t lock;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed.");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);
    return new_node;
}

void push_back(Node** head_ref, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if (*head_ref == NULL) {
        *head_ref = new_node;
        return;
    }

    Node* last = *head_ref;
    while (last->next != NULL) {
        last = last->next;
    }
    last->next = new_node;
}

NFAPI_CRC_INDICATION_PDU_T pop_front(Node** head_ref) {
    if (*head_ref == NULL) {
        return (NFAPI_CRC_INDICATION_PDU_T){.timestamp=0, .sequence_id=0};
    }
    Node* first = *head_ref;
    NFAPI_CRC_INDICATION_PDU_T ret = first->data;
    *head_ref = first->next;
    free(first);
    return ret;
}

void lock_node(Node* node) {
    pthread_mutex_lock(&node->lock);
}

void unlock_node(Node* node) {
    pthread_mutex_unlock(&node->node->lock);
}

// Implement concurrent access functions here using appropriate synchronization mechanisms.
