    while (1) {
        SemaphoreConfig sem_cfg;
        size_t sem_size = offsetof(SemaphoreConfig, semaphores[0]);
        if (semctl(semget(SEM_FAILED, 1, IPC_CREAT | IPC_EXCL | 0666), 0, SETALL, &sem_cfg) == -1) {
