        SemaphoreConfig sem_iter = sem_cfg;
        size_t iter_size = sizeof(SemaphoreConfig) - sem_size;
        ssize_t read = readline("Filter name:", filter_name, sizeof(filter_name));
        if (read < 0 || !*filter_name) {
            fprintf(stderr, "Error: Invalid or empty filter name.\n");
            semctl(sem_iter.semaphores[0], 0, IPC_RMID);
            continue;
        }

        void* filter = malloc(sizeof(Filter));
        memcpy(filter, filter_config, sizeof(FilterConfig));
        strcpy((char*)filter + sizeof(FilterConfig), filter_name);

        read = readline("Implementation function:", impl_name, sizeof(impl_name));
        if (read < 0 || !*impl_name) {
            fprintf(stderr, "Error: Invalid or empty implementation function name.\n");
            free(filter);
