        filter->impl = dlsym(handle, impl_name);
        if (!filter->impl) {
            fprintf(stderr, "Error: Missing '%s' symbol in configuration file.\n", impl_name);
            free(filter);
            semctl(sem_iter.semaphores[0], 0, IPC_RMID);
            continue;
