#include "absl/container/flat_hash_map.h"
#include "absl/synchronization/mutex.h"
#include "absl/status/statusor.h"

using absl::flat_hash_map;
using absl::Mutex;
using absl::StatusOr;

// Entry structure
struct Entry {
  std::string key;
  int value;
};

class DynamicCollection {
 public:
  StatusOr<void> AddEntry(const std::string& key, int value) {
    mutex_.Lock();
    if (entries.count(key)) {
      mutex_.Unlock();
      return absl::InvalidArgumentError("Key already exists.");
    }
    entries[key] = value;
    mutex_.Unlock();
    return absl::OkStatus();
  }

  StatusOr<void> RemoveEntry(const std::string& key) {
    mutex_.Lock();
    auto it = entries.find(key);
    if (it == entries.end()) {
      mutex_.Unlock();
      return absl::NotFoundError("Key not found.");
    }
    entries.erase(it);
    mutex_.Unlock();
    return absl::OkStatus();
  }

  StatusOr<void> UpdateEntry(const std::string& key, int value) {
    mutex_.Lock();
    auto it = entries.find(key);
    if (it == entries.end()) {
      mutex_.Unlock();
      return absl::NotFoundError("Key not found.");
    }
    it->second = value;
    mutex_.Unlock();
    return absl::OkStatus();
  }

  auto Begin() { return entries.begin(); }
  auto End()   { return entries.end(); }

  void PrintAllEntries() {
    for (const auto& entry : entries) {
      std::cout << "Key: " << entry.first << ", Value: " << entry.second << '\n';
    }
  }

 private:
  Mutex mutex_;
  flat_hash_map<std::string, int> entries;
};
```

This code creates a `DynamicCollection` class that uses an absl::flat_hash_map to store the entries and absl::Mutex for concurrency safety. The AddEntry(), RemoveEntry(), UpdateEntry() functions are provided for adding, removing, and updating entries respectively. The Begin() and End() functions provide iterators to iterate over all entries, while PrintAllEntries() prints all the entries in the collection.

