typedef struct Record {
    int value;
    long offset;
    int key;
} Record;

void memory_manager(size_t *offsets_size, size_t *keys_size, size_t *records_size, size_t max_offset, size_t max_key, size_t chunk_size) {
    long *offsets = malloc(*offsets_size * sizeof(long));
    int *keys = malloc(*keys_size * sizeof(int));
    Record *records = malloc(*records_size * sizeof(Record));
    bool *used_offsets = calloc(max_offset + 1, sizeof(bool));
    bool *used_keys = calloc(max_key, sizeof(bool));

    if (!offsets || !keys || !records || !used_offsets || !used_keys) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    size_t offset_count = 0, key_count = 0, record_count = 0;

    while (record_count < *records_size) {
        long candidate_offset = rand() % max_offset + 1;
        if (!used_offsets[candidate_offset]) {
            used_offsets[candidate_offset] = true;
            offsets[offset_count] = candidate_offset;
            offset_count++;
        }

        int candidate_key = rand() % max_key;
        if (!used_keys[candidate_key]) {
            used_keys[candidate_key] = true;
            keys[key_count] = candidate_key;
            key_count++;
        }

        int candidate_value = rand() % 1001;
        for (size_t i = 0; i < record_count; ++i) {
            if (records[i].value == candidate_value) {
                break;
            }
            if (i == record_count - 1 || records[i].key != candidate_key) {
                records[record_count].value = candidate_value;
                records[record_count].offset = offsets[candidate_key];
                records[record_count++].key = candidate_key;
                break;
            }
        }
    }

    free(used_offsets);
    free(used_keys);
}
