    FileEntry *files = aligned_malloc(max_entries * sizeof(FileEntry), getpagesize());
    handle_error("Memory allocation failed");

    // Initialize memory blocks with zeroes to prevent heap corruption
    memset(dirs, 0, (max_entries + 1) * sizeof(DirectoryEntry));
    memset(files, 0, max_entries * sizeof(FileEntry));

    // Set up root directory entry
