        file->size = rand() % (max_size - min_size + 1) + min_size;
        file->dir = root;
        entry->offset = sizeof(DirectoryEntry) * (i + 1);
        entry->name = strdup("entry_");
        entry->size = file->size;
    }

    // Set up children pointers in the root directory entry
    for (size_t i = 0; i < max_entries; ++i) {
        DirectoryEntry *child = &dirs[i + 1];
