#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_COMMAND_LENGTH 100
#define MAX_INDEX 10000
#define ELEMENT_SIZE 2 * sizeof(uint32_t) // char string and unsigned int

typedef struct {
    char str[MAX_COMMAND_LENGTH];
    uint32_t value;
} element;

// Thread-safe double-ended queue (deque) implementation
typedef struct deque {
    size_t size;
    size_t capacity;
    void **data;
    pthread_mutex_t lock;
    pthread_cond_t not_full, not_empty;
} deque;

void init_deque(deque *q) {
    q->size = 0;
    q->capacity = 16;
    q->data = malloc(q->capacity * sizeof(void*));
    memset(q->data, 0, q->capacity * sizeof(void*));
    q->lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_init(&q->not_full, NULL);
    pthread_cond_init(&q->not_empty, NULL);
}

static void deque_push(deque *q, void *data) {
    pthread_mutex_lock(&q->lock);
    if (q->size == q->capacity) {
        // Double the capacity if it's full
        void **new_data = realloc(q->data, (q->capacity << 1) * sizeof(void*));
        if (!new_data) {
            fprintf(stderr, "Out of memory\n");
            pthread_mutex_unlock(&q->lock);
            return;
        }
        q->data = new_data;
        q->capacity <<= 1;
    }
    memcpy((char*)q->data[q->size] + ELEMENT_SIZE, data, ELEMENT_SIZE);
    q->size++;
    if (q->size == 1) {
        pthread_cond_signal(&q->not_empty);
    } else {
        pthread_cond_signal(&q->not_full);
    }
    pthread_mutex_unlock(&q->lock);
}

static void* deque_pop(deque *q) {
    void *data;
    pthread_mutex_lock(&q->lock);
    if (q->size == 0) {
        pthread_cond_wait(&q->not_empty, &q->lock);
    }
    memcpy(&data, q->data[--q->size], ELEMENT_SIZE);
    if (q->size == q->capacity / 4 && q->capacity > 16) {
        // Half the capacity if it's less than 4/4th full
        void **new_data = realloc(q->data, q->capacity >> 1 * sizeof(void*));
        if (!new_data) {
            fprintf(stderr, "Out of memory\n");
            pthread_mutex_unlock(&q->lock);
            return NULL;
        }
        q->data = new_data;
        q->capacity >>= 1;
    }
    if (q->size == 0) {
        pthread_cond_signal(&q->not_full);
    }
    pthread_mutex_unlock(&q->lock);
    return data;
}

// Function prototype for the component responsible for processing and executing operations
typedef void (*operation_func)(const char *, size_t, const element *);
void process_and_execute(deque *operations, operation_func op_func);
