typedef struct Record {
    long offset;
    int key;
} Record;

// External logging service API
void log_memory(size_t bytes);

pthread_mutex_t mem_lock = PTHREAD_MUTEX_INITIALIZER; // For memory accounting

// Memory pool for dynamic collection
Record* records;
size_t capacity = 0, size = 0;

// Function to manage the dynamic collection of records
void manage_records(size_t new_size) {
    if (new_size <= size) return; // No need to resize if new_size is less than or equal to current size

    Record* temp_records = mmap(NULL, new_size * sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (temp_records == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    // Copy existing records into the new memory pool and update pointers
    if (capacity > 0) {
        memcpy(temp_records, records, size * sizeof(Record));
        free(records);
    }

    records = temp_records;
    capacity = new_size;
    log_memory((new_size - size) * sizeof(Record)); // Log the additional memory allocated
}

// Function to add a record to the collection, ensuring input validation and efficient memory management
void add_record(long offset, int key) {
    if (size == capacity) manage_records(capacity * 2); // Double capacity when it's full

    records[size].offset = offset;
    records[size].key = key;
    size++;
}

// Function to clean up memory when the program exits or encounters an error
void cleanup() {
    munmap(records, capacity * sizeof(Record)); // Unmap and free memory pool
}

// Register the cleanup function with atexit to ensure it is called on program exit
atexit(cleanup);
