```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>

typedef struct {
    int value;
} Record;

#define MAX_RECORDS 10000
#define ALLOCATION_GRANULARITY (MAX_RECORDS / 2)
#define THREAD_SAFE_SIZE ((ALLOCATION_GRANULARITY * 4) + sizeof(pthread_mutex_t))

struct dynamic_array {
    Record* records;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
};

static void grow_capacity(struct dynamic_array* array) {
    if ((array->capacity + ALLOCATION_GRANULARITY) > MAX_RECORDS) return;
    array->records = realloc(array->records, (array->capacity + ALLOCATION_GRANULARITY) * sizeof(Record));
    array->capacity += ALLOCATION_GRANULARITY;
}

static inline void lock(pthread_mutex_t* mutex) {
    pthread_mutex_lock(mutex);
}

static inline void unlock(pthread_mutex_t* mutex) {
    pthread_mutex_unlock(mutex);
}

void init_dynamic_array(struct dynamic_array* array) {
    array->records = mmap(NULL, THREAD_SAFE_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (array->records == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    array->capacity = ALLOCATION_GRANULARITY;
    array->length = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

