typedef struct HashTable {
    size_t capacity;
    uint32_t* keys;
    void** data;
} HashTable;

HashTable create_hash_table(size_t capacity) {
    HashTable table = {capacity, NULL, NULL};
    table.keys = calloc(capacity, sizeof(uint32_t));
    table.data = malloc(capacity * sizeof(void*));
    return table;
}

Record create_record() {
    Record record = {0};
    record.value = rand() % 100; // Adjust range as needed
    return record;
}

bool hash_collision(HashTable* table, uint32_t key) {
    size_t index = (key % table->capacity);
    for (size_t i = index; i < table->capacity; ++i) {
        if (!table->keys[i]) {
            return false;
        }
        if (table->keys[i] == key) {
            return true;
        }
    }
    for (size_t i = 0; i < index; ++i) {
        if (!table->keys[i]) {
            continue;
        }
        if (table->keys[(index + i) % table->capacity] == key) {
            return true;
        }
    }
    return false;
}

void* find_empty_slot(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        if (!table->keys[i]) {
            return &table->data[i];
        }
    }
    return NULL;
}

