#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_ELEMENTS 1000
#define MAX_ELEM_SIZE 128
#define MAX_TOTAL_BYTES 10000
#define MAX_VALUES 5000

typedef struct {
    char str[MAX_ELEM_SIZE];
    unsigned int value;
} element;

typedef struct {
    const char *command;
    size_t index;
    element *element;
} operation;

static size_t doubleArraySize = 0, sizeArraySize = 0, elementArraySize = 0, operationArraySize = 0;
static unsigned int totalValues = 0;
static double *doubles = NULL, *tempDoubles = NULL;
static size_t *indices = NULL, *tempIndices = NULL;
static element **elements = NULL, *tempElements = NULL;
static operation *operations = NULL, *tempOperations = NULL;

void growMemory() {
    if (doubleArraySize + sizeof(double) > MAX_TOTAL_BYTES ||
        sizeArraySize + sizeof(size_t) > MAX_TOTAL_BYTES ||
        elementArraySize * (MAX_ELEM_SIZE + sizeof(unsigned int)) > MAX_TOTAL_BYTES ||
        totalValues > MAX_VALUES) {
        fprintf(stderr, "Memory error: Cannot allocate more memory\n");
        exit(EXIT_FAILURE);
    }

    size_t newSize = doubleArraySize + sizeof(double), tempSize = 0;

    if (newSize > 2 * doubleArraySize) {
        tempDoubles = realloc(doubles, 2 * doubleArraySize);
        if (!tempDoubles) {
            fprintf(stderr, "Memory error: Failed to reallocate double array\n");
            exit(EXIT_FAILURE);
        }
        doubles = tempDoubles;
    } else {
        tempDoubles = realloc(doubles, newSize);
        if (!tempDoubles) {
            fprintf(stderr, "Memory error: Failed to reallocate double array\n");
            exit(EXIT_FAILURE);
        }
        doubles = tempDoubles;
    }

    tempIndices = realloc(indices, newSize);
    if (!tempIndices) {
        fprintf(stderr, "Memory error: Failed to reallocate size array\n");
        exit(EXIT_FAILURE);
    }
    indices = tempIndices;

    tempElements = realloc(elements, elementArraySize * 2);
    if (!tempElements) {
        fprintf(stderr, "Memory error: Failed to reallocate element array\n");
        exit(EXIT_FAILURE);
    }
    elements = tempElements;

    tempOperations = realloc(operations, operationArraySize * 2);
    if (!tempOperations) {
        fprintf(stderr, "Memory error: Failed to reallocate operation array\n");
        exit(EXIT_FAILURE);
    }
    operations = tempOperations;

    doubleArraySize += sizeof(double);
    sizeArraySize += sizeof(size_t);
    elementArraySize++;
    operationArraySize++;
}

void initialize() {
    doubles = malloc(sizeof(double));
    indices = malloc(sizeof(size_t));
    elements = malloc(sizeof(element*));
    operations = malloc(sizeof(operation));
}

void deinitialize() {
    free(doubles);
    free(indices);
    for (size_t i = 0; i < elementArraySize; ++i) {
        free(elements[i]);
    }
    free(elements);
    free(operations);
}

int main() {
    initialize();

    char command[32];
    while (1) {
        printf("Enter a command (add, get, remove, quit): ");
        scanf("%s", command);

        if (!strcmp(command, "quit")) {
            break;
        } else if (!strcmp(command, "add")) {
            double value;
            printf("Enter value: ");
            scanf("%lf", &value);

            growMemory();
            doubles[doubleArraySize / sizeof(double)] = value;
            indices[sizeArraySize / sizeof(size_t)] = doubleArraySize / sizeof(double) - 1;

            element *newElement = malloc(sizeof(element));
            newElement->value = (unsigned int)(value + 0.5); // round up to nearest integer
            totalValues += newElement->value;
            if (totalValues > MAX_VALUES) {
                for (size_t i = 0; i < elementArraySize; ++i) {
                    elements[i]->value /= (doubleArraySize / sizeof(double));
                }
            }

            strcpy(newElement->str, ""); // ensure zero-initialized
            elements[elementArraySize - 1] = newElement;
        } else if (!strcmp(command, "get")) {
            size_t index;
            printf("Enter index: ");
            scanf("%zu", &index);

            if (index >= doubleArraySize / sizeof(double)) {
                fprintf(stderr, "Error: Index out of range\n");
                continue;
            }

            operation *op = malloc(sizeof(operation));
            op->command = strdup("get");
            op->index = index;
            op->element = elements[indices[index]];
            operations[operationArraySize - 1] = op;
        } else if (!strcmp(command, "remove")) {
            size_t index;
            printf("Enter index: ");
            scanf("%zu", &index);

            if (index >= doubleArraySize / sizeof(double)) {
                fprintf(stderr, "Error: Index out of range\n");
                continue;
            }

            size_t elemIndex = indices[index];

            for (size_t i = elemIndex + 1; i < elementArraySize; ++i) {
                elements[i - 1] = elements[i];
            }
            free(elements[elementArraySize - 1]);

            for (size_t i = index; i < doubleArraySize / sizeof(double); ++i) {
                indices[i]--;
            }
            indices[index] = SIZE_MAX;

            growMemory();
        } else {
            fprintf(stderr, "Error: Unknown command\n");
        }
    }

    deinitialize();
    return 0;
}
```
This code provides a memory-managed data structure in C that allows users to add, get, and remove elements while ensuring the total memory usage does not exceed 10,000 bytes and the sum of all `unsigned int` values does not exceed 5,000. The code also handles potential edge cases gracefully through error handling mechanisms.']

