    if (total_size > max_size) {
        fprintf(stderr, "Memory error: Total size %zu exceeds the maximum size of %zu.\n", total_size, max_size);
        return MEMORY_ERROR;
    }

    record_t* records = mmap(NULL, total_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (records == MAP_FAILED) {
        perror("mmap");
        return MEMORY_ERROR;
    }

    size_t i, offset = 0;
    for (i = 0; i < num_allocated && i < num_records; ++i) {
        records[i].id = rand();

        // Ensure unique identifiers within the collection.
        for (size_t j = 0; j < i; ++j) {
            if (records[i].id == records[j].id) {
                fprintf(stderr, "Memory error: Duplicate identifier found.\n");
                munmap(records, total_size);
                return MEMORY_ERROR;
            }
        }

        for (size_t k = 0; k < avg_offsets_per_record + 1; ++k) {
            records[i].offsets[k] = offset + rand() % ((total_size - offset) / (avg_offsets_per_record + 1));
            offset = records[i].offsets[k];
        }
    }

    *num_allocated = i;

    // Align the return address to avoid cache pollution and improve performance.
    long* aligned_ptr = (long*)(((size_t)records + ALIGNMENT - 1) & ~(ALIGNMENT - 1));
    *aligned_ptr = (long)records;

    return SUCCESS;
}
```
