#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct Node {
    double value;
    struct Node* next;
} Node;

Node* head = NULL;
size_t length = 0;
double running_avg = 0.0;

void insert_at_beginning(double value) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return;

    new_node->value = value;
    new_node->next = head;
    head = new_node;
    ++length;
}

size_t find_node_index(double value, size_t* previous_index) {
    size_t index = 0;
    Node* current = head;

    while (current && current->value != value) {
        (*previous_index) = index++;
        current = current->next;
    }

    if (current) {
        (*previous_index) = index - 1;
        return index;
    }

    return ~0ull; // Indicates not found (use a large constant instead of -1 for unsigned type)
}

void compute_running_avg() {
    if (!length) return;

    double sum = 0.0;
    size_t i;
    Node* current = head;

    for (i = 0; i < length && current != NULL; ++i, current = current->next)
        sum += current->value;

    running_avg = sum / length;
}

void flush_and_reset() {
    Node* next;
    while (head != NULL) {
        next = head->next;
        free(head);
        head = next;
    }

    length = 0;
    running_avg = 0.0;
}
```

