    Record **records;
    size_t capacity;
    size_t threshold;
    size_t used;
    sem_t mem_sem; // Semaphore for memory usage tracking and notifications
};

void init_mem_manager(struct MemManager *mm, size_t capacity, size_t threshold) {
    mm->offsets = calloc(capacity, sizeof(long));
    mm->keys = malloc(capacity * sizeof(int));
    mm->records = malloc(capacity * sizeof(Record*));
    mm->capacity = capacity;
    mm->threshold = threshold;
    mm->used = 0;
    sem_init(&mm->mem_sem, 0, capacity - threshold); // Initialize semaphore with available memory
}

void free_mem_manager(struct MemManager *mm) {
