    free(mm->keys);
    for (size_t i = 0; i < mm->capacity; ++i) {
        if (mm->records[i]) {
            free(mm->records[i]->str);
            free(mm->records[i]);
        }
    }
    free(mm->records);
}

void log_mem_usage(const struct MemManager *mm) {
