typedef struct MemoryPool {
    void *memory;
    size_t capacity;
    size_t used;
    struct MemoryPool *next;
} MemoryPool;

void initMemoryPool(MemoryPool **pool, size_t size) {
    *pool = malloc(sizeof(MemoryPool));
    (*pool)->capacity = size;
    (*pool)->used = 0;
    (*pool)->memory = memalign(64, size); // Optimized for cache performance
    (*pool)->next = NULL;
}

void* allocateFromPool(MemoryPool **pool) {
    if (!*pool || (*pool)->used >= (*pool)->capacity) {
        MemoryPool *new_pool = malloc(sizeof(MemoryPool));
        new_pool->capacity = 128; // You can adjust this value based on your needs
        new_pool->used = 0;
        new_pool->memory = memalign(64, (*pool)->capacity);
        new_pool->next = *pool;
        *pool = new_pool;
    }

    void* ptr = (*pool)->memory + (*pool)->used;
    (*pool)->used++;
    return ptr;
}

void freeMemoryPool(MemoryPool **pool) {
    if (!*pool) return;
    free(*pool->memory);
    MemoryPool *temp = *pool;
    *pool = temp->next;
    free(temp);
}

