        free(offsets);
        perror("Memory allocation failed for key array");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < record_count; ++i) {
        records[i].key = min_int + rand() % (max_int - min_int + 1);
        records[i].offset = offsets[i] = i;

        size_t string_length = strlen(string_array[i]);
        if (string_length > MAX_STRING_LENGTH) {
            perror("String length exceeded maximum allowed");
