        }

        records[i].value = (char*) malloc(string_length + 1);
        if (!records[i].value) {
            free(offsets);
            free(keys);
            free(records);
            perror("Memory allocation failed for record values");
            return NULL;
        }

        strcpy(records[i].value, string_array[i]);
    }

    pthread_mutex_init(&mutex, NULL);

    return records;
}

