['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct Node {
    int value;
    struct Node* next;
    struct Node* prev;
} Node;

Node* create_node(int val) {
    Node* new_node = malloc(sizeof(Node));
    new_node->value = val;
    new_node->next = NULL;
    new_node->prev = NULL;
    return new_node;
}

void insert_beginning(Node** head, Node* new_node) {
    if (*head == NULL) {
        *head = new_node;
        return;
    }
    new_node->next = *head;
    (*head)->prev = new_node;
    *head = new_node;
}

void insert_end(Node** head, Node* new_node) {
    if (*head == NULL) {
        *head = new_node;
        return;
    }
    Node* current = *head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_node;
    new_node->prev = current;
}

int find_index(Node** head, int target) {
    Node* current = *head;
    int index = 0;
    while (current != NULL) {
        if (current->value == target) {
            return index;
        }
        current = current->next;
        index++;
    }
    return -1;
}

Node* find_node(Node** head, int target) {
    Node* current = *head;
    while (current != NULL) {
        if (current->value == target) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void rolling_average(Node** head, float* average, int sample_size, int reset) {
    static Node* buffer[sample_size];
    static int buffer_index = 0;
    if (reset) {
        for (int i = 0; i < sample_size; ++i) {
            if (buffer[i] != NULL) {
                remove_node(head, buffer[i]);
            }
            buffer[i] = NULL;
        }
        buffer_index = 0;
        *average = 0.0f;
    }

    Node* current = *head;
    while (current != NULL) {
        if (buffer_index == sample_size) {
            remove_node(head, buffer[buffer_index % sample_size]);
            --buffer_index;
        }
        buffer[(buffer_index + 1) % sample_size] = current;
        ++buffer_index;

        *average += current->value;
        current = current->next;
    }
    if (buffer_index > sample_size) {
        remove_node(head, buffer[(buffer_index - 1) % sample_size]);
        --buffer_index;
    }
    *average /= buffer_index;
}

void remove_node(Node** head, Node* node_to_remove) {
    if (node_to_remove == NULL || *head == NULL) {
        return;
    }
    if (*head == node_to_remove) {
        *head = node_to_remove->next;
        if ((*head) != NULL) {
            (*head)->prev = NULL;
        }
        free(node_to_remove);
        return;
    }
    Node* current = *head;
    while (current != NULL) {
        if (current == node_to_remove) {
            if (current->next != NULL) {
                current->next->prev = current->prev;
            }
            if (current->prev != NULL) {
                current->prev->next = current->next;
            }
            free(node_to_remove);
            break;
        }
        current = current->next;
    }
}
```
This code defines a doubly-linked list data structure for managing nodes with integers and pointers to next and previous nodes. The `insert_beginning()`, `insert_end()`, `find_index()`, and `rolling_average()` functions implement the specified operations, while `remove_node()` is used to remove a specific node from the list.

The code includes a buffer for calculating the rolling average, which is reset when a specific event occurs (as determined by the `reset` parameter in the `rolling_average()` function). The array is properly resized and freed when no longer needed using the `remove_node()` function.']

