```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct Node {
    char str[256];
    int priority;
    struct Node* next;
} Node;

Node* create_linked_list(int num_nodes) {
    if (num_nodes <= 0 || num_nodes > MAX_NODES) {
        fprintf(stderr, "Invalid number of nodes. Use a value between 1 and %d\n", MAX_NODES);
        return NULL;
    }

    Node* head = malloc(sizeof(Node));
    if (!head) {
        perror("Memory allocation failure");
        return NULL;
    }

    head->next = NULL;

    for (int i = 1; i < num_nodes; ++i) {
        Node* curr = head;
        for (int j = 0; j < i; ++j)
            curr = curr->next;

        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            perror("Memory allocation failure");
            free_linked_list(head);
            return NULL;
        }

        strcpy(new_node->str, "");
        new_node->priority = 0;
        new_node->next = NULL;

        curr->next = new_node;
        curr = new_node;
    }

    return head->next;
}
