std::atomic<size_t> insertPoint{0};

// Mutex for thread safety during list insertions
std::mutex listMutex;

void processRecords(int offsetSize, int keySize, int recordsCount, int minValue, int maxValue) {
    std::vector<Record*> records;
    std::unique_ptr<long[]> offsets(new long[offsetSize]);
    std::unique_ptr<int[]> keys(new int[keySize * recordsCount]);

    // Generate random 'int' values for each record within the specified range
    std::srand(std::time(nullptr));
    for (int i = 0; i < recordsCount; ++i) {
        Record* r = new Record();
        r->data = minValue + rand() % (maxValue - minValue + 1);
        records.push_back(r);
        offsets[i] = i;
    }

    // Sort records by their offset values
    std::sort(records.begin(), records.end(), [](const Record* a, const Record* b) { return a->offset.get()[0] < b->offset.get()[0]; });

    // Assign offsets and keys to the sorted records
    for (size_t i = 0; i < records.size(); ++i) {
        records[i]->offset.reset(new long[1]);
        records[i]->key.reset(new int[1]);
        records[i]->offset.get()[0] = offsets[i];
        records[i]->key.get()[0] = i;
    }

    // Integrate with the external data processing library here

    // Update forwardList with new strings based on the keys array
    for (const auto& r : records) {
        std::lock_guard<std::mutex> lock(listMutex);
        auto it = forwardList.begin();
        auto end = forwardList.end();

        while (it != end && *it != *(r->key)) {
            ++it;
        }

        if (it != end) {
            forwardList.insert(++it, "Processing record with key: " + std::to_string(*(r->key)));
        } else {
            forwardList.insert(insertPoint++, "Processing record with key: " + std::to_string(*(r->key)));
        }
    }

    // Release all allocated resources at the end of function's execution
    for (auto& r : records) {
        delete r;
    }
}
