#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Data {
    char *str;
    int value;
} Data;

typedef struct Node {
    Data data;
    size_t index;
    struct Node *next;
} Node;

struct Array {
    size_t capacity;
    size_t size;
    Node **nodes;
    pthread_mutex_t mutex;
};

void init_array(struct Array *arr, size_t initial_capacity) {
    arr->capacity = initial_capacity;
    arr->size = 0;
    arr->nodes = calloc(initial_capacity, sizeof(Node*));
    if (!arr->nodes) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }
    arr->mutex = PTHREAD_MUTEX_INITIALIZER;
}

void resize_array(struct Array *arr, size_t new_capacity) {
    Node **new_nodes = calloc(new_capacity, sizeof(Node*));
    if (!new_nodes) {
        perror("malloc failed");
        return;
    }

    pthread_mutex_lock(&arr->mutex);

    size_t i;
    for (i = 0; i < arr->capacity && i < new_capacity; ++i) {
        if (arr->nodes[i]) {
            new_nodes[i] = arr->nodes[i];
            arr->nodes[i] = NULL;
        }
    }

    free(arr->nodes);
    arr->nodes = new_nodes;
    arr->capacity = new_capacity;

    pthread_mutex_unlock(&arr->mutex);
}

void add_node(struct Array *arr, Data data, size_t index) {
    pthread_mutex_lock(&arr->mutex);

    if (arr->size == arr->capacity)
        resize_array(arr, arr->capacity + 10);

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("malloc failed");
        pthread_mutex_unlock(&arr->mutex);
        return;
    }

    new_node->data = data;
    new_node->index = index;
    new_node->next = arr->nodes[index];
    arr->nodes[index] = new_node;

    pthread_mutex_unlock(&arr->mutex);
}

void populate(struct Array *arr, size_t num_elements) {
    size_t i;
    for (i = 0; i < num_elements; ++i) {
        Data data;
        data.str = malloc(rand() % 20 + 5);
        sprintf(data.str, "%.*s", rand() % 16 + 8, "abcdefghijklmnopqrstuvwxyz");
        data.value = rand() % 100;
        add_node(arr, data, i);
    }
}
```
