#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    long offset;
    int key;
} record;

struct record_node {
    record data;
    struct record_node* next;
};

struct record_list {
    struct record_node* head;
    struct record_node* tail;
    pthread_mutex_t lock;
};

void init_record_list(struct record_list* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void insert_record(struct record_list* list, int value, long offset, int key) {
    struct record_node* node = malloc(sizeof(struct record_node));
    if (!node) {
        perror("Memory allocation failed");
        return;
    }
    node->data.value = value;
    node->data.offset = offset;
    node->data.key = key;
    node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
    pthread_mutex_unlock(&list->lock);
}

void deallocate_record_list(struct record_list* list) {
    struct record_node* current = list->head;
    while (current != NULL) {
        struct record_node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
}

void* generate_records(void* args) {
    struct record_list* list = (struct record_list*)args;
    int size, min_value, max_value;

    if (sscanf((char*)args, "%d-%d-%d", &size, &min_value, &max_value) != 3 ||
        size <= 0 || min_value > max_value || min_value < 0) {
        fprintf(stderr, "Invalid input: %s\n", (char*)args);
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < size; ++i) {
        int value = rand() % (max_value - min_value + 1) + min_value;
        long offset = rand();
        int key = rand();
        insert_record(list, value, offset, key);
    }

    return NULL;
}

void generate_records_sequentially(struct record_list* list, int count, int min_value, int max_value) {
    pthread_t threads[count];
    for (size_t i = 0; i < count; ++i) {
        void* res = pthread_create(&threads[i], NULL, generate_records, list);
        if (res != 0) {
            perror("Thread creation failed");
        }
    }

    for (size_t i = 0; i < count; ++i) {
        void* res;
        pthread_join(threads[i], &res);
    }
}

