bool dynamic_array_push_back(NFAPI_CRC_INDICATION_PDU_T* element) {
    if (!element) return false;

    if (length == capacity) {
        size_t new_capacity = (capacity / 2) + INITIAL_CAPACITY;
        if (new_capacity > MAX_ELEMENTS) return false;

        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
