// Custom record structure containing a single 'int' value
typedef struct Record {
    int key;
    long offset;
    struct Record *next;
} Record;

// Helper function to read integers from standard input and store them in an array
void read_integers(int *arr, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        scanf("%d", arr + i);
    }
    qsort(arr, size, sizeof(int), (int (*)(const void *, const void *))compar);
}

// Comparator function for qsort to find the largest integer
static int compar(const void *a, const void *b) {
    return *(const int *)a - *(const int *)b;
}

// Function to initialize dynamic memory for offset and key arrays with locking mechanism
Record* init_arrays(size_t size) {
    Record *offsets = (Record *)mmap(NULL, size * sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    Record *keys = (Record *)mmap(NULL, (size + 1) * sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    Record *head = NULL;
    for (size_t i = 0; i < size; ++i) {
        pthread_mutex_lock(&lock);
        Record *new_rec = (Record *)malloc(sizeof(Record));
        new_rec->key = -1; // marker for empty records
        new_rec->offset = i;
        new_rec->next = head;
        head = new_rec;
        pthread_mutex_unlock(&lock);
    }

    keys[size].key = -1; // marker for end of key array
    return offsets;
}

// Function to populate the record arrays with random values within a specified range
void populate(Record *arr, size_t size, int min, int max) {
    for (size_t i = 0; i < size; ++i) {
        Record *rec = arr + i;
        if (rec->key == -1) { // empty record found
            rec->key = rand() % (max - min + 1) + min;
        }
    }
}

// Main function to manage the data processing and error handling
