    if (argc != 2) {
        fprintf(stderr, "Usage: %s <input_size>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int *input = malloc(atoi(argv[1]) * sizeof(int));
    read_integers(input, atoi(argv[1]));

    size_t size = atoi(argv[1]);
