#include <arpa/inet.h>

typedef struct {
    int key;
    int value;
} Record;

struct mem_manager {
    long *offsets;
    int *keys;
    Record *records;
    size_t capacity;
    size_t used;
    pthread_mutex_t lock;
};

struct data_source {
    int socket;
    // other data source specific properties
};

void init_data_source(struct data_source *ds) {
    // Initialize the data source here, such as setting up a socket connection.
}

int get_random(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

void initialize_mem_manager(struct mem_manager *mm, size_t capacity, int offset_min, int offset_max, int key_min, int key_max, int record_min, int record_max, struct data_source *ds) {
    mm->offsets = malloc(capacity * sizeof(long));
    if (!mm->offsets) {
        fprintf(stderr, "Error allocating memory for offsets\n");
        exit(EXIT_FAILURE);
    }
    mm->keys = malloc(capacity * sizeof(int));
    if (!mm->keys) {
        fprintf(stderr, "Error allocating memory for keys\n");
        free(mm->offsets);
        exit(EXIT_FAILURE);
    }
    mm->records = calloc(capacity, sizeof(Record));
    if (!mm->records) {
        fprintf(stderr, "Error allocating memory for records\n");
        free(mm->offsets);
        free(mm->keys);
        exit(EXIT_FAILURE);
    }
    mm->capacity = capacity;
    mm->used = 0;
    pthread_mutex_init(&mm->lock, NULL);
    init_data_source(ds);
}

void destroy_mem_manager(struct mem_manager *mm) {
    free(mm->offsets);
    free(mm->keys);
    free(mm->records);
    pthread_mutex_destroy(&mm->lock);
}

int find_key(const struct mem_manager *mm, int key) {
    for (size_t i = 0; i < mm->used; ++i) {
        if (mm->keys[i] == key) return i;
    }
    return -1;
}

bool search(const struct mem_manager *mm, int key, int *result) {
    int index = find_key(mm, key);
    if (index != -1) {
        *result = mm->records[index].value;
        return true;
    }
    return false;
}

void add_record(struct mem_manager *mm, int key, int value) {
    pthread_mutex_lock(&mm->lock);
    if (mm->used == mm->capacity) {
        fprintf(stderr, "Error: Memory manager is full\n");
        pthread_mutex_unlock(&mm->lock);
        return;
    }
    int index = find_key(mm, key);
    if (index != -1) {
        mm->records[index].value = value;
    } else {
        if (index == -1) index = mm->used;
        mm->keys[index] = key;
        mm->offsets[index] = get_random(0, mm->used);
        mm->records[index].key = key;
        mm->records[index].value = value;
        ++mm->used;
    }
    pthread_mutex_unlock(&mm->lock);
}

void mem_manager_example(int argc, char **argv) {
    if (argc != 6) {
        fprintf(stderr, "Usage: %s <capacity> <offset_min> <offset_max> <key_min> <key_max>\n", argv[0]);
        exit(EXIT_FAILURE);
    }
    size_t capacity = atoi(argv[1]);
    int offset_min = atoi(argv[2]);
    int offset_max = atoi(argv[3]);
    int key_min = atoi(argv[4]);
    int key_max = atoi(argv[5]);

    struct mem_manager mm;
    struct data_source ds;
    initialize_mem_manager(&mm, capacity, offset_min, offset_max, key_min, key_max, 0, INT_MAX, &ds);

    srand(time(NULL));

    for (int i = 0; i < 10000; ++i) {
        int key = get_random(key_min, key_max);
        int value = get_random(0, INT_MAX);
        add_record(&mm, key, value);
    }

    // Example usage of the memory manager with a search operation
    int result;
    if (search(&mm, get_random(key_min, key_max), &result)) {
        printf("Found: %d\n", result);
    } else {
        fprintf(stderr, "Not found\n");
    }

    destroy_mem_manager(&mm);
}
```

