#include <iostream>
#include <vector>
#include <cstdlib>
#include <ctime>
#include <cmath>

class DataGenerator {
private:
    unsigned long minOffset;
    unsigned long maxOffset;
    int minKey;
    int maxKey;
    std::vector<long> offsets;
    std::vector<int> keys;
    std::vector<std::vector<int>> records;

    static std::mt19937 generator;
    long randomOffset();
    int random(int min, int max, bool exclusive);

public:
    DataGenerator(unsigned long minOffset, unsigned long maxOffset, int minKey, int maxKey, size_t offsetSize, size_t keySize, size_t recordSize);
    ~DataGenerator();
    void generate();
    std::string ToString() const;
    int getRecord(size_t index) const;

    static void seed(unsigned long seed);
};

std::mt19937 DataGenerator::generator;

DataGenerator::DataGenerator(unsigned long minOffset, unsigned long maxOffset, int minKey, int maxKey, size_t offsetSize, size_t keySize, size_t recordSize) {
    if (minOffset >= maxOffset || maxOffset - minOffset < 1) {
        throw std::invalid_argument("Invalid range for offsets.");
    }
    if (minKey > maxKey || maxKey - minKey < 1) {
        throw std::invalid_argument("Invalid range for keys.");
    }

    this->minOffset = minOffset;
    this->maxOffset = maxOffset;
    this->minKey = minKey;
    this->maxKey = maxKey;

    offsets.resize(offsetSize, static_cast<long>(std::rand()) % (static_cast<unsigned long>(maxOffset - minOffset) + 1) + minOffset);
    keys.resize(keySize, std::rand() % (maxKey - minKey + 1) + minKey);

    records.resize(recordSize);
}

DataGenerator::~DataGenerator() = default;

void DataGenerator::generate() {
    for (auto& record : records) {
        record.push_back(std::rand() % (maxKey - minKey + 1) + minKey);
    }
}

long DataGenerator::randomOffset() {
    return static_cast<long>(static_cast<unsigned long>(generator()) % (static_cast<unsigned long>(maxOffset - minOffset) + 1)) + minOffset;
}

int DataGenerator::random(int min, int max, bool exclusive) {
    if (exclusive) {
        return static_cast<int>(std::rand() % (max - min));
    } else {
        return static_cast<int>(std::rand() % (max - min + 1));
    }
}

std::string DataGenerator::ToString() const {
    std::ostringstream os;
    os << "Data Generator: [MinOffset=" << minOffset << ", MaxOffset=" << maxOffset << ", MinKey=" << minKey << ", MaxKey=" << maxKey << "]\n";
    os << "Offsets:\n";
    for (const auto& offset : offsets) {
        os << offset << "\n";
    }
    os << "Keys:\n";
    for (const auto& key : keys) {
        os << key << "\n";
    }
    os << "Records:\n";
    for (size_t i = 0; i < records.size(); ++i) {
        os << "[";
        for (const auto& recordValue : records[i]) {
            os << recordValue << ", ";
        }
        os << "]\n";
    }
    return os.str();
}

int DataGenerator::getRecord(size_t index) const {
    if (index >= records.size()) {
        throw std::out_of_range("Invalid record index.");
    }
    return records[index][0];
}

void DataGenerator::seed(unsigned long seed) {
    generator.seed(seed);
}
