#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    int value;
    int key_ref;
} Record;

typedef struct CacheNode {
    int key;
    struct CacheNode *next;
    size_t index;
} CacheNode;

struct DataManager {
    long *offsets;
    int *keys;
    Record *records;
    unsigned long offset_range_start, offset_range_end;
    unsigned int key_range_start, key_range_end;
    unsigned int record_value_range_start, record_value_range_end;
    size_t offsets_size, keys_size, records_size;
    CacheNode *cache_head;
    pthread_mutex_t cache_mutex;
};

DataManager* data_manager_init(unsigned long offset_range_start, unsigned long offset_range_end,
                                unsigned int key_range_start, unsigned int key_range_end,
                                unsigned int record_value_range_start, unsigned int record_value_range_end) {
    DataManager *manager = malloc(sizeof(DataManager));
    if (!manager) return NULL;

    manager->offsets = NULL;
    manager->keys = NULL;
    manager->records = NULL;
    manager->offset_range_start = offset_range_start;
    manager->offset_range_end = offset_range_end;
    manager->key_range_start = key_range_start;
    manager->key_range_end = key_range_end;
    manager->record_value_range_start = record_value_range_start;
    manager->record_value_range_end = record_value_range_end;
    manager->offsets_size = offset_range_end - offset_range_start + 1;
    manager->keys_size = key_range_end - key_range_start + 1;
    manager->records_size = (manager->keys_size > 0) ? manager->keys_size : 1;
    manager->cache_head = NULL;
    pthread_mutex_init(&manager->cache_mutex, NULL);

    return manager;
}

void data_manager_log(DataManager *manager, const char *message) {
    printf("%s\n", message);
}

void* data_manager_malloc(size_t size, DataManager *manager, const char *function_name) {
    void *ptr = malloc(size);
    if (!ptr) {
        data_manager_log(manager, "Error: Memory allocation failure in function %s", function_name);
        return NULL;
    }
    data_manager_log(manager, "Memory allocated: %zu bytes by function %s", size, function_name);
    return ptr;
}

void data_manager_free(void *ptr, DataManager *manager, const char *function_name) {
    if (!ptr) return;
    free(ptr);
    data_manager_log(manager, "Memory deallocated: %p by function %s", ptr, function_name);
}

int data_manager_search(DataManager *manager, int key) {
    CacheNode *node = manager->cache_head;
    size_t index;
    pthread_mutex_lock(&manager->cache_mutex);

    while (node) {
        if (node->key == key) {
            index = node->index;
            break;
        }
        node = node->next;
    }

    if (!node) {
        for (index = 0; index < manager->keys_size; ++index) {
            if (manager->keys[index] == key) {
                CacheNode *new_node = malloc(sizeof(CacheNode));
                if (!new_node) {
                    pthread_mutex_unlock(&manager->cache_mutex);
                    return -1;
                }
                new_node->key = key;
                new_node->next = manager->cache_head;
                new_node->index = index;
                manager->cache_head = new_node;
                index = new_node->index;
                break;
            }
        }
    }

    pthread_mutex_unlock(&manager->cache_mutex);

    return index < manager->keys_size ? index : -1;
}

void data_manager_initialize(DataManager *manager) {
    if (manager->offsets) free(manager->offsets);
    manager->offsets = data_manager_malloc(manager->offsets_size * sizeof(long), manager, "data_manager_initialize");
    for (size_t i = 0; i < manager->offsets_size; ++i) {
        manager->offsets[i] = manager->offset_range_start + i;
    }

    if (manager->keys) free(manager->keys);
    manager->keys = data_manager_malloc(manager->keys_size * sizeof(int), manager, "data_manager_initialize");
    for (size_t i = 0; i < manager->keys_size; ++i) {
        manager->keys[i] = rand() % (manager->key_range_end - manager->key_range_start + 1) + manager->key_range_start;
    }

    if (manager->records) free(manager->records);
    manager->records = data_manager_malloc((manager->keys_size > 0) ? manager->keys_size : 1, manager, "data_manager_initialize");
    for (size_t i = 0; i < manager->records_size; ++i) {
        Record *record = &manager->records[i];
        record->value = rand() % (manager->record_value_range_end - manager->record_value_range_start + 1) + manager->record_value_range_start;
        record->key_ref = data_manager_search(manager, record->value);
    }
}
