// Define record structure
struct Record {
    int value;
    int key;
};

// Function to initialize arrays with random values
void initArrays(std::vector<long>& offsets, std::vector<int>& keys, std::vector<Record>& records, int arraySize, int offsetMin, int offsetMax, int keyMin, int keyMax, int recordMin, int recordMax) {
    std::mt19937 generator(std::random_device{}());
    std::uniform_int_distribution<int> distOffset(offsetMin, offsetMax);
    std::uniform_int_distribution<int> distKey(keyMin, keyMax);
    std::uniform_int_distribution<int> distRecord(recordMin, recordMax);

    for (size_t i = 0; i < arraySize; ++i) {
        offsets[i] = distOffset(generator);
        keys[i] = distKey(generator);
        records[i].value = distRecord(generator);
        records[i].key = keys[i];
    }
}

// Function to perform a linear search on the 'records' array, checking for out-of-bounds access
int findRecord(const std::vector<Record>& records, int key) {
    for (const auto& record : records) {
        if (record.key == key) {
            return record.value;
        }
    }
    return -1;
}

// Function to demonstrate the use of the initialized arrays and linear search function
void testFunction() {
    const int arraySize = 1000;
    std::vector<long> offsets(arraySize);
    std::vector<int> keys(arraySize);
    std::vector<Record> records(arraySize);

    initArrays(offsets, keys, records, arraySize, 0, 10000, 1, 100, -100, 100);

    int key = keys[std::rand() % arraySize];
    int recordValue = findRecord(records, key);

    std::cout << "Key: " << key << ", Record Value: " << recordValue << std::endl;
}
```

