class Semaphore {
private:
    int count;
    int maxCount;
    boost::mutex mutex;
    boost::condition_variable condition;
public:
    Semaphore(int initialCount, int maxCount) : count(initialCount), maxCount(maxCount) {}
    void wait() {
        std::unique_lock<boost::mutex> lock(mutex);
        while (count >= maxCount) {
            condition.wait(lock);
        }
        --count;
        lock.unlock();
    }
    void post() {
        std::unique_lock<boost::mutex> lock(mutex);
        ++count;
        lock.notify_one();
    }
};

