['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

struct MemoryBlock {
    void* offsets;
    void* keys;
    Record* records;
    size_t capacity;
    size_t allocated;
    pthread_mutex_t lock;
};

struct MemoryPool {
    struct MemoryBlock* blocks;
    size_t size;
};

void* allocate_memory(struct MemoryPool* pool, size_t size) {
    for (size_t i = 0; i < pool->size; ++i) {
        if (!pool->blocks[i].allocated || pool->blocks[i].capacity - pool->blocks[i].allocated >= size) {
            void* result = pool->blocks[i].offsets + pool->blocks[i].allocated;
            pool->blocks[i].allocated += size;
            return result;
        }
    }

    // Allocate new memory block if none can be reused
    struct MemoryBlock* new_block = realloc(pool->blocks, sizeof(struct MemoryBlock) * (pool->size + 1));
    if (!new_block) {
        perror("realloc failed");
        exit(EXIT_FAILURE);
    }

    pool->blocks = new_block;
    pool->blocks[pool->size] = (struct MemoryBlock){0};

    return allocate_memory(pool, size);
}

void free_memory(struct MemoryPool* pool, void* ptr) {
    for (size_t i = 0; i < pool->size; ++i) {
        if (ptr >= pool->blocks[i].offsets && ptr < pool->blocks[i].offsets + pool->blocks[i].capacity) {
            pool->blocks[i].allocated -= (size_t)(ptr - pool->blocks[i].offsets);
            break;
        }
    }
}

void record_init(struct MemoryBlock* block, unsigned long offset, unsigned int key, int value) {
    pthread_mutex_lock(&block->lock);
    Record* record = (Record*)(block->records + offset / sizeof(Record));
    record->value = value;
    pthread_mutex_unlock(&block->lock);
}

int* get_key(struct MemoryBlock* block, unsigned long offset) {
    return (int*)(block->keys + offset / sizeof(int));
}

unsigned long* get_offset(struct MemoryBlock* block, unsigned int key) {
    return (unsigned long*)(block->offsets + key);
}

void init_memory_pool(struct MemoryPool* pool, size_t capacity) {
    pool->blocks = malloc(sizeof(struct MemoryBlock));
    pool->size = 1;
    pool->blocks[0] = (struct MemoryBlock){.capacity = capacity};
}

void free_memory_pool(struct MemoryPool* pool) {
    free(pool->blocks);
}
```

This code provides a basic implementation for managing memory pools, with thread-safe dynamic allocation and reuse of memory blocks. The `MemoryBlock` structure contains the offset values, keys, records, and associated synchronization lock. The custom memory pool manages an array of such memory blocks to efficiently handle multiple concurrent invocations.

The `allocate_memory()` function checks if there is any free or partially-used block in the memory pool and reuses it if possible. If no suitable block can be found, a new one is allocated. The `free_memory()` function updates the used capacity of a specific block when a memory block is freed.

The `record_init()`, `get_key()`, and `get_offset()` functions provide access to the record structures within the memory blocks. Developers can use these functions in their larger application to manage numerous record sets concurrently while leveraging shared memory pools for optimized performance.']

