#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

typedef struct Record {
    int value;
    time_t timestamp;
    void* key;
    long offset;
} Record;

Record* create_record(void* key, long offset) {
    Record* record = malloc(sizeof(Record));
    if (!record) return NULL;
    record->key = key;
    record->offset = offset;
    time(&record->timestamp);
    return record;
}

void set_random_value(Record* record, int min, int max) {
    record->value = rand() % (max - min + 1) + min;
}

bool read_and_filter_ints(int** integers, size_t* capacity, size_t* size, bool (*predicate)(int)) {
    if (!integers || !capacity || !size) return false;

    int* filtered = NULL;
    size_t filtered_size = 0;

    while (getchar() != '\n'); // consume input until newline
    while (scanf("%d", integers + *size) == 1) {
        if ((*predicate)(*(integers + *size))) {
            if (!filtered || filtered_size == filtered_capacity) {
                filtered_capacity *= 2;
                filtered = realloc(filtered, filtered_capacity * sizeof(int));
                if (!filtered) return false;
            }
            filtered[filtered_size++] = *(integers + *size);
        }
        (*size)++;
    }

    if (filtered && filtered_size > 0) {
        *integers = realloc(*integers, filtered_size * sizeof(int));
        if (!*integers) return false;
        memcpy(*integers, filtered, filtered_size * sizeof(int));
        free(filtered);
    }

    *capacity = filtered_size;
    return true;
}

void log_record(const char* filename, const Record* record) {
    FILE* file = fopen(filename, "a");
    if (file) {
        fprintf(file, "%zu: %d, %ld, %lu, %.16s\n", record - records, record->value, record->offset, record->key, ctime(&record->timestamp));
        fclose(file);
    }
}

void free_memory(Record** records, int* integers, size_t capacity) {
    if (records) {
        for (size_t i = 0; i < capacity; ++i) free(records[i]);
        free(records);
    }
    if (integers) free(integers);
}

int main() {
    int min = 1, max = 100;
    size_t records_capacity = 100, integers_size = 0, integers_capacity = 10;
    Record* records = NULL;
    int* integers = NULL;

    srand(time(NULL));
    while (read_and_filter_ints(&integers, &integers_capacity, &integers_size, (int (*)(int))(min % 2 ? (bool(*)(int))even : odd))) {
        if (!records) records = malloc(records_capacity * sizeof(Record));
        if (!records) return 1; // memory allocation failure

        for (size_t i = 0; i < integers_size; ++i) {
            Record* record = create_record((void*)(integers + i), i);
            if (!record) goto cleanup; // memory allocation failure
            set_random_value(record, min, max);
            if (records_capacity == records_capacity) {
                records_capacity *= 2;
                records = realloc(records, records_capacity * sizeof(Record));
                if (!records) goto cleanup; // memory allocation failure
            }
            records[records_size++] = record;
        }
    }

cleanup:
    free_memory(records, integers, records_size);
    return 0;
}
