    private readonly ILogger<MyController> _logger;

    public MyController(MyDbContext context, ILogger<MyController> logger)
    {
        _context = context;
        _logger = logger;
    }

    [HttpPut("{id}")]
    public async Task<IActionResult> UpdateResource(Guid id, [FromBody] MyResource resource, string eTag)
    {
        var existingResource = await _context.Resources.FindAsync(id);
        if (existingResource == null) return NotFound();

        if (!ModelState.IsValid || string.IsNullOrEmpty(resource.Data)) return BadRequest(ModelState);
        resource.Id = id; // Ensure the ID is not overwritten by validation

        using var shaMd = SHA256.Create();
        byte[] inputBytes = Encoding.ASCII.GetBytes(resource.Data);
        byte[] hash = shaMd.ComputeHash(inputBytes);
        string md5Hash = BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();

        _logger.LogInformation($"Resource with ID {id} updated with MD5 Hash: {md5Hash}");

        // Implement validation layer for predefined schema rules here...

        if (existingResource.ETag != eTag) return Conflict("Current ETag does not match expected ETag.");

        _context.Entry(existingResource).CurrentValues.SetValues(resource);
        await _context.SaveChangesAsync();

        return Ok();
    }

    [HttpDelete("{id}")]
    public async Task<IActionResult> DeleteResource(Guid id)
    {
        var resource = await _context.Resources.FindAsync(id);
        if (resource == null) return NotFound();

        _context.Resources.Remove(resource);
        await _context.SaveChangesAsync();

        // Return a new resource with default values only if the deletion was successful...

        _logger.LogInformation($"Resource with ID {id} deleted.");

        return NoContent();
    }
}

public class MyDbContext : DbContext
{
