// Function to process records with dynamic memory management and thread synchronization
void* process_records(void* arg) {
    struct record* records = (struct record*)arg;

    for (size_t i = 0; i < memory_usage; ++i) {
        sem_wait(&semaphore);

        // Generate random value and store it in the current record
        records[i].value = random_value(&config);
        records[i].timestamp = (float)time(NULL);

        // Log record creation if logging is enabled
        if (log_file != NULL) {
            log_record(&records[i], log_file);
        }

        sem_post(&semaphore);

        // Check if the current record's array capacity has been exceeded, and if so, double its size
        if (memory_usage >= config.initial_capacity) {
            memory_usage >>= 1;
            struct record* new_records = allocate_records(memory_usage * 2);
            memcpy(new_records, records, memory_usage * sizeof(struct record));
            free(records);
            records = new_records;
        }
    }

    return NULL;
}

// Function to initialize the program with given configuration and start processing records
int main(int argc, char** argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return 1;
    }

    parse_config(argv[1]);

    // Initialize semaphore with specified initial value
    sem_init(&semaphore, 0, config.initial_capacity);

    // Allocate initial array of records based on the given configuration
    struct record* records = allocate_records(config.initial_capacity);

    // Open log file if logging is enabled
    if (config.log_interval > 0) {
        log_file = fopen(config.log_file, "w");
    }

    pthread_t threads[config.initial_capacity];
    for (size_t i = 0; i < config.initial_capacity; ++i) {
        pthread_create(&threads[i], NULL, process_records, &records[i]);
    }

    // Wait for all the threads to finish processing records
    for (size_t i = 0; i < config.initial_capacity; ++i) {
        pthread_join(threads[i], NULL);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    free(records);
    sem_destroy(&semaphore);

    return 0;
}
