typedef struct entry {
    float value;
    char id[32];
    struct entry **linked_list;
} Entry;

static unsigned int djb2(const void *str) {
    const unsigned char *data = str;
    unsigned hash = 5381;
    int c;

    while ((c = *(unsigned char*)data++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % MAX_ENTRIES;
}

void create_entries(Entry **collection, int seed, int num_entries, float min_value, float max_value) {
    srand((unsigned)seed + getpid());
    *collection = malloc(MAX_ENTRIES * sizeof(Entry));
    if (!*collection) {
        perror("Memory allocation error");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_entries; ++i) {
        Entry *entry = (*collection) + i;
        entry->value = rand()*(max_value - min_value)/RAND_MAX + min_value;
        snprintf(entry->id, sizeof(entry->id), "%d", seed + i);
        entry->linked_list = malloc(sizeof(Entry*) * MAX_ENTRIES);
        if (!entry->linked_list) {
            perror("Memory allocation error");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < num_entries; ++i) {
        Entry *current = (*collection) + i;
        unsigned index = djb2(current->id);
        current->linked_list[index] = current;
    }
}

