                json_object* record_obj = json_array_get_object_elem(records_array, i);
                int value = json_object_get_int(json_object_find(record_obj, "value"));
                long offset = json_object_get_int(json_object_find(record_obj, "offset"));
                int key = json_object_get_int(json_object_find(record_obj, "key"));

                record* new_record = new record{value, offset, key};
                struct pointer_record* new_pointer = new struct pointer_record{new_record, nullptr};

                if (!current) {
                    current = new_pointer;
                } else {
                    new_pointer->next = *head;
                    *head = new_pointer;
                }
            }
        } else {
            // Handle deserialization error gracefully
            g_error_free(error);
        }

        g_variant_unref(serialized_data);
        fclose(file);
    } else {
        // Handle file opening error gracefully
    }
}

// Implement logging mechanisms...
