[' Java MD5 Hash Method:

```java
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HashSet;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.Set;
import java.util.stream.Collectors;

public String concatMD5Hashes(List<String> inputs) {
    Set<String> uniqueInputs = new HashSet<>();
    Set<String> duplicates = new HashSet<>();

    for (String input : inputs) {
        if (uniqueInputs.add(input)) {
            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] messageDigest = md.digest(input.getBytes(StandardCharsets.UTF_8));
                StringBuilder sb = new StringBuilder();
                for (byte b : messageDigest) {
                    sb.append(String.format("%02x", b));
                }
                String md5Hash = sb.toString();
                uniqueInputs.put(input, md5Hash);
            } catch (Exception e) {
                logException("Error computing MD5 hash: " + e.getMessage());
            }
        } else {
            duplicates.add(input);
        }
    }

    if (!duplicates.isEmpty()) {
        String duplicatesMessage = duplicates.stream().collect(Collectors.joining(","));
        logMessage("Duplicate strings found: " + duplicatesMessage);
    }

    return uniqueInputs.values().stream().reduce((a, b) -> a + b).orElseThrow(() -> new NoSuchElementException("No unique inputs found."));
}
```

