      await checkFileIntegrity(file);
    }
  }

  async function checkFileIntegrity(file) {
    if (!fileIntegrityChecked) {
      try {
        const res = await axios.get(`${process.env.API_URL}/verify/${file.filename}`);
        if (res.data.status !== 'ok') {
          throw new Error('File is corrupted');
        }
        fileIntegrityChecked = true;
      } catch (err) {
        console.error(`Error checking file integrity: ${err}`);
        if (process.env.RETRY_COUNT && process.env.RETRY_COUNT <= 5) {
          setTimeout(() => checkFileIntegrity(file), parseInt(process.env.RETRY_INTERVAL) * Math.pow(2, process.env.RETRY_COUNT));
        }
      }
    }
  }

  function createReadWriteStreams() {
    const filePath = path.join(__dirname, 'uploads', file.filename);
    readStream = fs.createReadStream(filePath, { start: currentChunk * chunkSize, end: (currentChunk + 1) * chunkSize });
    writeStream = fs.createWriteStream(path.join(__dirname, 'processed', `${file.originalname}-${currentChunk}.part`), { flags: 'a' });
  }

  async function processChunk() {
    createReadWriteStreams();
    return new Promise((resolve, reject) => {
      readStream.on('data', data => writeStream.write(data));
      readStream.on('end', () => {
        if (++currentChunk === Math.ceil(file.size / chunkSize)) {
          resolve();
        } else {
          currentChunk = 0;
          processChunk().then(resolve).catch(reject);
        }
      });
      readStream.on('error', reject);
      writeStream.on('finish', () => {
        fs.renameSync(path.join(__dirname, 'processed', `${file.originalname}-${currentChunk}.part`), path.join(__dirname, 'processed', file.originalname));
      });
      writeStream.on('error', reject);
    });
  }

  async function handleError(err) {
    console.error(`Error processing file: ${err}`);
    if (process.env.RETRY_COUNT && process.env.RETRY_COUNT <= 5) {
      setTimeout(() => processFile(file), parseInt(process.env.RETRY_INTERVAL) * Math.pow(2, process.env.RETRY_COUNT));
    }
  }

  async function logProcessingActivity() {
    const logEntry = new LogSchema({
      action: 'process',
      file: file.filename,
      startTime: Date.now(),
      logType: process.env.LOGGING_VERBOSITY || 'info'
    });
    await logEntry.save();
  }

  async function main() {
    await pauseResume();
    await logProcessingActivity();
    await processChunk().catch(handleError);
    await resume();
  }

  return main();
}

// Handle file uploads
app.post('/upload', upload.single('file'), async (req, res) => {
  try {
    const file = req.file;
    await processFile(file);
    res.sendStatus(200);
  } catch (err) {
    console.error(`Error processing file: ${err}`);
    res.status(500).send({ error: err.message });
  }
});

// Start the server
const port = process.env.PORT || 3000;
app.listen(port, () => console.log(`Server started on port ${port}`));
```

