// Struct for holding the input file and output file paths
typedef struct {
    char *input;
    char *output;
} FilePaths;

// Function to convert JPEG to PDF using ImageMagick and libpdf
void fileConverter(const FilePaths *filePath) {
    MagickBooleanType status;
    Image *image = MagickReadImageFromFile(filePath->input, "JPEG");
    if (image == NULL) {
        fprintf(stderr, "Error reading input file: %s\n", MagickErrorString());
        return;
    }

    pdf_document *pdf = pdf_new();
    status = pdf_start_page(pdf, A4);
    if (status != PDF_OK) {
        fprintf(stderr, "Error starting page in output file: %s\n", pdf_get_error_message(pdf));
        return;
    }

    // Write the JPEG image to the PDF
    status = pdf_write_image(pdf, image);
    if (status != PDF_OK) {
        fprintf(stderr, "Error writing image to output file: %s\n", pdf_get_error_message(pdf));
        return;
    }

    // Save the output PDF
    pdf_save(pdf, filePath->output);
    MagickWriteImage(image, filePath->output, "PDF");
    pdf_free(pdf);
    MagickDestroyImage(image);
}
