#include <float.h>

// Custom memory pool for efficient allocation and deallocation
typedef struct MemoryBlock {
    void *data;
    size_t size;
    struct MemoryBlock *next;
} MemoryBlock;

MemoryBlock *memoryPool = NULL;
const char delimiter = ',';
const int MAX_TASKS = 10;

Task* createTask(char *name) {
    Task *task = (Task*) malloc(sizeof(Task));
    task->name = strdup(name);
    task->priority = strlen(name);
    task->duration = (double)(strlen(name)) / 1000.0;
    return task;
}

void addToMemoryPool(void *data, size_t size) {
    MemoryBlock *newBlock = (MemoryBlock*) malloc(sizeof(MemoryBlock));
    newBlock->data = data;
    newBlock->size = size;
    newBlock->next = memoryPool;
    memoryPool = newBlock;
}

void* getFromMemoryPool() {
    if (!memoryPool) return NULL;
    MemoryBlock *temp = memoryPool;
    void *data = temp->data;
    memoryPool = temp->next;
    free(temp);
    return data;
}

void loadTasks(char *input, Task **tasks) {
    char *token = strtok(input, &delimiter);
    int i = 0;
    while (token && i < MAX_TASKS) {
        if (*token == delimiter) continue;
        addToMemoryPool(createTask(token), sizeof(Task));
        token = strtok(NULL, &delimiter);
        i++;
    }
    *tasks = getFromMemoryPool();
}

void freeTasks(Task *tasks) {
    Task *current = tasks;
    while (current != NULL) {
        Task *temp = current;
        current = current->next;
        free(temp->name);
        free(temp);
    }
}

// Function to manage the array of Task structures
void manageTasks(char *configFilePath, void (*taskProcessor)(Task*)) {
    FILE *file = fopen(configFilePath, "r");
    if (!file) {
        printf("Error: Unable to open configuration file.\n");
        return;
    }

    char line[1024];
    Task *tasks = NULL;
    while (fgets(line, sizeof(line), file)) {
        loadTasks(line, &tasks);
        for (int i = 0; tasks && i < MAX_TASKS; i++) {
            taskProcessor(tasks[i]);
        }
        freeTasks(tasks);
    }
    fclose(file);
}
```

