#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* name;
    int priority;
    double duration;
} Task;

// Custom memory pool for tasks
Task* allocate_task() {
    // Allocate and initialize memory for a new task structure
    Task* task = (Task*) malloc(sizeof(Task));
    if (!task) return NULL;

    task->name = NULL;
    task->priority = 0;
    task->duration = 0.0;

    return task;
}

void deallocate_task(Task* task) {
    // Free memory allocated for a task structure and its name
    free(task->name);
    free(task);
}

// Function to populate the array with tasks from a string
void populate_tasks(char* input, Task** tasks, size_t max_tasks) {
    char* token = strtok(input, " \n");

    int i = 0;
    while (i < max_tasks && token) {
        if (!tasks[i]) {
            tasks[i] = allocate_task();
            if (!tasks[i]) break; // Error handling for allocation failure
        }

        tasks[i]->name = token;
        sscanf(token, "%d %lf", &(tasks[i]->priority), &(tasks[i]->duration));

        token = strtok(NULL, " \n");
        i++;
    }
}

// Thread-safe function to process tasks using a task queue
void* process_tasks(void* arg) {
    TaskQueue* queue = (TaskQueue*) arg;

    while (!queue->empty()) {
        // Dequeue and process a task from the queue
        Task* task = dequeue(queue);
        // ... Perform processing on the task ...
        // ... Release resources when processing is complete ...
        deallocate_task(task);
    }

    return NULL;
}

int main() {
    size_t max_tasks = 100;
    Task* tasks = malloc(max_tasks * sizeof(Task));

    if (!tasks) {
        fprintf(stderr, "Error allocating memory for tasks\n");
        return 1;
    }

    // Input example: task1 5.0 2.0 task2 7.0 3.0 ...
    char* input = "task1 5.0 2.0 task2 7.0 3.0";
    populate_tasks(input, tasks, max_tasks);

    // Create a thread-safe task queue and process the tasks concurrently
    TaskQueue queue = create_task_queue();

    for (size_t i = 0; i < max_tasks && tasks[i]; i++) {
        enqueue(queue, tasks[i]);
    }

    pthread_t threads[max_threads];
    for (int i = 0; i < max_threads; i++) {
        int rc = pthread_create(&threads[i], NULL, process_tasks, &queue);
        if (rc) fprintf(stderr, "Error creating thread: %s\n", strerror(-rc));
    }

    // Join all threads and deallocate resources upon completion
    for (int i = 0; i < max_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    free(tasks);
    return 0;
}
```

