#define VALUES_COUNT 50000
#define LABELS_SIZE 26
#define NODE_MAX_VALUE 1 << 30

typedef struct data_point {
    double value;
    char label;
} data_point;

typedef struct node {
    int value;
    struct node* next;
} node;

node* head = NULL;
data_point* values;
char labels[LABELS_SIZE];

void initLabels() {
    for (size_t i = 0; i < LABELS_SIZE; ++i) {
        labels[i] = 'a' + i;
    }
}

void* safeMalloc(size_t size, const char* type) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Insufficient memory for %s allocation\n", type);
        exit(1);
    }
    return ptr;
}

void initValues() {
    values = safeMalloc((VALUES_COUNT + 1) * sizeof(double), "values array");
    memset(values, 0, VALUES_COUNT * sizeof(double));
}

data_point* createDataPoint(char label) {
    data_point* dp = safeMalloc(sizeof(data_point), "data point");
    dp->label = label;
    return dp;
}

void addLabelValue(int value, char label) {
    for (node* curr = head; curr != NULL; curr = curr->next) {
        if (curr->value == value) {
            fprintf(stderr, "Error: Duplicate value %d detected\n", value);
            exit(1);
        }
        if (!curr->next && label < 'a' + LABELS_SIZE) {
            curr->next = createNode(value, labels[label]);
            break;
        }
    }
}

node* createNode(int value, char label) {
    node* newNode = safeMalloc(sizeof(node), "new node");
    newNode->value = value;
    if (label < 'a' + LABELS_SIZE) {
        newNode->next = createDataPoint(label);
    } else {
        newNode->next = NULL;
    }
    return newNode;
}

int main() {
    srand(time(NULL));

    initLabels();
    initValues();

    head = createNode(0, 'a');

    for (size_t i = 0; i < VALUES_COUNT; ++i) {
        double randVal = (double)(rand() % ((1 << 30) - 1)) / (double)(1 << 30);
        int index = (int)((VALUES_COUNT - 1) * randVal);
        addLabelValue(values[index], 'a' + i % LABELS_SIZE);
    }

    return 0;
}
