#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <sys/mman.h>
#include <unistd.h>
#include <semaphore.h>
#include <log4cxx/logger.h>
#include <log4cxx/basicconfigurator.h>
#include <log4cxx/propertyconfigurator.h>

struct record {
    long offset;
    int key;
    time_t timestamp;
};

typedef struct record Record;

// Global variables for logging and synchronization
static log4cxx::LoggerPtr logger = log4cxx::Logger::getLogger("RecordInitializer");
static sem_t mutex;
static int max_records;
static int min_offset, max_offset, min_key, max_key;

// Function to initialize record structures with random values
void init_record(Record* rec) {
    time_t rawtime;
    struct tm * timeinfo;

    rec->offset = (long)(min_offset + rand() % (max_offset - min_offset + 1));
    rec->key = (int)(min_key + rand() % (max_key - min_key + 1));

    rawtime = time(NULL);
    timeinfo = localtime(&rawtime);
    rec->timestamp = mktime(timeinfo);
}

// Function to ensure timestamp uniqueness
int is_unique_timestamp(const Record* rec, Record* records, int count) {
    for (int i = 0; i < count; ++i) {
        if (rec->timestamp == records[i].timestamp) {
            return 0;
        }
    }
    return 1;
}

// Function to allocate and initialize memory for an array of record structures
Record* init_record_array(int num_records) {
    Record* records = (Record*)mmap(NULL, sizeof(Record) * num_records, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!records) {
        log4cxx::LoggerPtr logger = log4cxx::Logger::getRootLogger();
        logger->error("Failed to allocate memory for record array.");
        return NULL;
    }

    int count = 0;
    Record* cur_rec = records;
    while (count < num_records && cur_rec != records + num_records) {
        sem_wait(&mutex);
        if (!is_unique_timestamp(cur_rec, records, count)) {
            sem_post(&mutex);
            continue;
        }
        init_record(cur_rec);
        cur_rec++;
        count++;
        sem_post(&mutex);
    }

    return records;
}

// Thread function for initializing record structures concurrently
void* thread_init_function(void* arg) {
    init_record_array((int)arg);
    pthread_exit(NULL);
}

// Main function to initialize record structures in a high-throughput environment
int main(int argc, char** argv) {
    // Initialize logging and synchronization
    log4cxx::PropertyConfigurator::configure("log4cxx.properties");
    sem_init(&mutex, 1, 1);

    // Parse command-line arguments for configuration
    if (argc < 5 || argc > 7) {
        fprintf(stderr, "Usage: %s <num_threads> <num_records> [min_offset] [max_offset] [min_key] [max_key]\n", argv[0]);
        exit(1);
    }
    max_records = atoi(argv[2]);
    min_offset = argc > 4 ? atol(argv[3]) : -1;
    max_offset = argc > 5 ? atol(argv[4]) : RAND_MAX / 2;
    min_key = argc > 6 ? atoi(argv[6]) : 0;
    max_key = argc > 7 ? atoi(argv[7]) : RAND_MAX;

    // Initialize record structures using concurrent threads
    pthread_t* threads = (pthread_t*)malloc((size_t)atoi(argv[1]) * sizeof(pthread_t));
    for (int i = 0; i < atoi(argv[1]); ++i) {
        int err = pthread_create(&threads[i], NULL, thread_init_function, (void*)atoi(argv[2]));
        if (err != 0) {
            log4cxx::LoggerPtr logger = log4cxx::Logger::getRootLogger();
            logger->error("Failed to create thread for initializing records.");
            exit(1);
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < atoi(argv[1]); ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

