#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <semaphore.h>
#include <sys/mman.h>

typedef struct record {
    long offset;
    int key;
    time_t timestamp;
} Record;

struct dataset {
    size_t capacity;
    size_t size;
    Record* data;
    pthread_mutex_t mutex;
    semaphore_t sem;
};

void init_dataset(struct dataset* ds, size_t initial_size) {
    ds->capacity = initial_size;
    ds->size = 0;
    ds->data = mmap(NULL, sizeof(Record) * initial_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ds->data == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    ds->mutex = PTHREAD_MUTEX_INITIALIZER;
    sem_init(&ds->sem, 0, initial_size);
}

Record* allocate_record(struct dataset* ds) {
    Record* record = (Record*) malloc(sizeof(Record));
    if (!record) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    return record;
}

void reallocate_dataset(struct dataset* ds, size_t new_capacity) {
    size_t old_capacity = ds->capacity;
    Record* old_data = ds->data;

    // Ensure that the new capacity is at least twice the current size to allow for growth.
    if (new_capacity < 2 * old_capacity) {
        new_capacity = 2 * old_capacity;
    }

    ds->capacity = new_capacity;
    Record* new_data = mmap(NULL, sizeof(Record) * new_capacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (new_data == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    // Copy data from old array to new array.
    for (size_t i = 0; i < old_capacity && i < ds->size; ++i) {
        memcpy((void*) ((char*)new_data + sizeof(Record)*i), (void*)((char*)old_data + sizeof(Record)*i), sizeof(Record));
    }

    // Free old data and update pointers.
    free(old_data);
    ds->data = new_data;
}

void populate_dataset(struct dataset* ds, int min_key, int max_key, long min_offset, long max_offset) {
    pthread_t threads[num_threads];
    Record* current_record = ds->data;
    for (int i = 0; i < num_threads; ++i) {
        int rc = pthread_create(&threads[i], NULL, populate_worker, (void*)ds);
        if (rc) {
            perror("pthread_create");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void* populate_worker(void* arg) {
    struct dataset* ds = arg;
    sem_t* sem = &ds->sem;
    Record* current_record = ds->data;

    while (ds->size < num_records) {
        timestampt_t timestamp;
        // Ensure unique timestamps.
        do {
            timestamp = time(NULL);
        } while (find_timestamp_collision(current_record, timestamp));

        current_record->offset = random_offset(min_offset, max_offset);
        current_record->key = random_int(min_key, max_key);
        current_record->timestamp = timestamp;

        // Increment the counter and release the semaphore to notify other threads that a record slot is available.
        pthread_mutex_lock(&ds->mutex);
        ds->size++;
        pthread_mutex_unlock(&ds->mutex);
        sem_post(sem);

        // Move to the next record slot, wrapping around if necessary.
        current_record = (Record*)((char*)current_record + sizeof(Record));
        if ((char*)current_record >= (char*)ds->data + sizeof(Record)*ds->capacity) {
            reallocate_dataset(ds, 2 * ds->capacity);
            current_record = ds->data;
        }
    }
    return NULL;
}

// Implement other helper functions such as random_offset(), find_timestamp_collision(), etc.
