struct CryptoPrimitive {
    const char* name;
    const EVP_CIPHER* cipher; // or any other relevant struct pointer for hash functions, etc.
    std::vector<unsigned char> params; // Initialization parameters
};

std::map<const char*, CryptoPrimitive*> loadPrimitives(const char* configFile) {
    std::ifstream config(configFile);
    if (!config.is_open()) {
        fprintf(stderr, "Error: Could not open configuration file.\n");
        exit(EXIT_FAILURE);
    }

    std::map<const char*, CryptoPrimitive*> primitives;

    while (true) {
        std::string line;
        std::getline(config, line);
        if (line.empty()) continue; // ignore empty lines

        std::istringstream ss(line);
        std::string primitiveName;
        ss >> primitiveName;

        if (ss.fail()) {
            fprintf(stderr, "Error: Malformed configuration line.\n");
            continue;
        }

        CryptoPrimitive* primitive = new CryptoPrimitive();
        primitive->name = primitiveName.c_str();

        std::getline(config, line); // get the next line for cipher details
        if (line.empty()) {
            fprintf(stderr, "Error: Missing cipher implementation for primitive %s.\n", primitiveName.c_str());
            delete primitive;
            continue;
        }

        std::istringstream ss2(line);
        EVP_CIPHER* cipher;
        const char* cipherName;
        ss2 >> cipherName;

        if (EVP_get_cipherbyname(cipherName) <= 0) {
            fprintf(stderr, "Error: Unknown cipher %s.\n", cipherName);
            delete primitive;
            continue;
        }

        cipher = EVP_get_cipherbyname(cipherName);
        primitive->cipher = cipher;

        // Parse initialization parameters from remaining lines in the configuration block
        // and populate params vector

        primitives[primitiveName] = primitive;
    }

    return primitives;
}

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
std::map<const char*, CryptoPrimitive*> loadCiphers(const char* configFile) {
    pthread_mutex_lock(&mutex);
    std::map<const char*, CryptoPrimitive*> primitives = loadPrimitives(configFile);
    pthread_mutex_unlock(&mutex);
    return primitives;
}
```

