#include <algorithm>
#include <vector>
#include <functional>
#include <mutex>
#include <stdexcept>

template<typename Iterator, typename Comparator>
Comparator get_comparator(Comparator comp) {
    // Create a thread-safe copy of the comparator if required.
    static std::mutex mutex;
    static Comparator threadSafeComp = comp;
    std::unique_lock<std::mutex> lock(mutex);
    if (!threadSafeComp) {
        threadSafeComp = [comp, &mutex] (const auto& lhs, const auto& rhs) { return comp(lhs, rhs); };
    }
    return threadSafeComp;
}

void insertAndSort(std::vector<int>& vec, int target, int value, std::function<bool(int, int)> comp) {
    auto compare = get_comparator([&](const int& lhs, const int& rhs) { return !comp(lhs, rhs); });
    auto it = std::find_if(vec.cbegin(), vec.cend(), [target](int x) { return !compare(x, target); });

    if (it == vec.cend()) {
        vec.push_back(value);
        std::sort(vec.begin(), vec.end(), compare);
    } else {
        vec.insert(it, value);
        std::nth_element(it, it+1, vec.end(), compare);
        std::sort(vec.begin(), it, compare);
        std::sort(it+1, vec.end(), compare);
    }
}
```

