typedef struct Record {
    char *key;
    long offset;
    float data;
} Record;

typedef struct MemPool {
    void *data;
    size_t size;
    struct MemPool *next;
} MemPool;

void init_mempool(MemPool **head, size_t size) {
    if (*head) mempool_free(*head);
    *head = malloc(sizeof(MemPool));
    (*head)->data = malloc(size);
    (*head)->size = size;
    (*head)->next = NULL;
}

void* mempool_alloc(MemPool **head, size_t size) {
    MemPool *pool = *head;
    void *mem;

    if (pool->size > 0) {
        mem = pool->data;
        pool->data += size;
        pool->size -= size;
    } else {
        MemPool *new_pool;
        new_pool = malloc(sizeof(MemPool));
        new_pool->data = malloc(size);
        new_pool->size = size;
        new_pool->next = *head;
        *head = new_pool;
        mem = new_pool->data;
    }

    return mem;
}

void mempool_free(MemPool *head) {
    if (!head) return;
    while (head != NULL) {
        MemPool *next = head->next;
        free(head->data);
        free(head);
        head = next;
    }
}

