    private static final OkHttpClient httpClient = new OkHttpClient();
    private static Map<String, Preference> cachedPreferences = new HashMap<>();
    private static ScheduledExecutorService cacheUpdateScheduler = Executors.newSingleThreadScheduledExecutor();

    public static class Preference {
