    private static Preference loadPreferencesFromService(URL url) throws Exception {
        try (Response response = httpClient.newCall(new Request.Builder().url(url).build()).execute()) {
            if (!response.isSuccessful()) {
                throw new RuntimeException("Failed to load preferences from remote configuration service");
            }
            return mapper.readValue(response.body().byteStream(), Preference.class);
        }
    }

    public static Preference getPreferences() {
