["```javascript
const axios = require('axios');
const { Readable } = require('stream');
const yaml = require('js-yaml');
const fs = require('fs');
const { promisify } = require('util');
const readFile = promisify(fs.readFile);

class CertificateGenerator {
  constructor() {
    this.lock = {};
  }

  async fetchData(url) {
    try {
      const response = await axios.get(url, { timeout: 10000 });
      return response.data;
    } catch (error) {
      console.error(`Error fetching data from ${url}:`, error);
    }
  }

  async processStream(request, stream, resolve) {
    let chunks = [];
    stream.on('data', (chunk) => {
      chunks.push(chunk);
    });
    stream.on('end', () => {
      const combinedChunks = Buffer.concat(chunks);
      try {
        const data = yaml.load(combinedChunks);
        resolve({ privateKey: data.privateKey, certificate: data.certificate });
      } catch (error) {
        console.error(`Error parsing data from stream:`, error);
      }
    });
  }

  async generateCertificate(req) {
    const { privateKeyUrl, certificateUrl } = req;

    const privateKeyStream = await this.fetchData(privateKeyUrl).then((data) => new Readable({ stream: () => ({
      read() {
        if (this.paused || !data) return this.push(null);
        let chunkSize = Math.min(1024, data.length);
        const chunk = data.slice(0, chunkSize);
        data = data.slice(chunkSize);
        this.push(Buffer.from(chunk));
      },
    })}));

    const certificateStream = await this.fetchData(certificateUrl).then((data) => new Readable({ stream: () => ({
      read() {
        if (this.paused || !data) return this.push(null);
        let chunkSize = Math.min(1024, data.length);
        const chunk = data.slice(0, chunkSize);
        data = data.slice(chunkSize);
        this.push(Buffer.from(chunk));
      },
    })}));

    let privateKeyData, certificateData;
    await new Promise((resolve) => {
      const privateKeyHandler = (data) => {
        if (!privateKeyData && !certificateData) {
          privateKeyData = data;
          this.lock[privateKeyUrl] = true;
          certificateStream.pause();
        } else if (!privateKeyData) {
          privateKeyData = data;
        }
        resolve();
      };
      const certificateHandler = (data) => {
        if (!privateKeyData && !certificateData) return;
        certificateData = data;
        this.lock[certificateUrl] = false;
        certificateStream.resume();
        const promise = new Promise((resolve) => this.processStream(req, privateKeyStream, (data) => {
          resolve(Object.assign({}, data, { certificate: certificateData }));
        }));
        return promise.then((result) => {
          const pemData = `${result.privateKey}\n---\n${result.certificate}`;
          return readFile('pemFormat.tpl', 'utf8').then((template) => {
            const formattedPemData = template.replace('{{pem}}', pemData);
            return fs.promises.writeFile('certificate.pem', formattedPemData);
          });
        }).catch((error) => {
          console.error(`Error generating certificate:`, error);
        });
      };
      privateKeyStream.on('data', privateKeyHandler);
      privateKeyStream.on('end', () => {
        if (privateKeyData && !certificateData) {
          privateKeyStream.unpipe(privateKeyHandler);
          certificateStream.resume();
        } else {
          privateKeyStream.unpipe();
          privateKeyStream.destroy();
        }
      });
      certificateStream.on('data', certificateHandler);
      certificateStream.on('end', () => {
        if (privateKeyData && certificateData) {
          certificateStream.unpipe(certificateHandler);
        } else {
          certificateStream.unpipe();
          certificateStream.destroy();
        }
      });
    });
  }
}

module.exports = CertificateGenerator;
```
In this code, the `CertificateGenerator` class generates a certificate from OAuth requests using an asynchronous pipeline. It uses axios for non-blocking HTTP requests and streams to handle data in chunks. The generated PEM format file is stored temporarily under 'certificate.pem'."]

