#include <netdb.h>
#include <pthread.h>
#include <map>

// Define a thread-safe cache for DNS lookups
std::map<std::string, addrinfo*> dns_cache;
pthread_mutex_t dns_cache_mutex = PTHREAD_MUTEX_INITIALIZER;

addrinfo* getaddrinfo_wrapper(const char *host, const char *service) {
    pthread_mutex_lock(&dns_cache_mutex);
    addrinfo *result = dns_cache.find(std::string(host))->second;
    if (result != nullptr) {
        // Cache hit, return the stored result
        pthread_mutex_unlock(&dns_cache_mutex);
        return result;
    }

    addrinfo hints = {};
    getaddrinfo_a(&hints, host, service, &result);
    if (result != nullptr) {
        // Cache miss, store the new result in the cache
        dns_cache[std::string(host)] = result;
    }

    pthread_mutex_unlock(&dns_cache_mutex);
    return result;
}
