#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/mman.h>

typedef struct {
    double value;
    char *data;
} record;

struct heap_buffer {
    void *ptr;
    size_t capacity;
};

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
long offset_array[1000001]; // Change 1000001 to desired maximum dataset size
int key_array[1000001];
record *record_array; // Will be dynamically allocated
struct heap_buffer string_buffer;

void init_heap_buffer(size_t capacity) {
    string_buffer.ptr = mmap(NULL, capacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (string_buffer.ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    string_buffer.capacity = capacity;
}

char *get_heap_buffer(size_t size) {
    void *tmp = NULL;
    if (string_buffer.ptr + string_buffer.capacity - tmp <= size) {
        init_heap_buffer((string_buffer.capacity + SIZE_MAX) / 2); // Adjust buffer size as needed
    }
    tmp = string_buffer.ptr + string_buffer.used;
    string_buffer.used += size + 1; // Account for null terminator
    return tmp;
}

void put_heap_buffer(char *str) {
    pthread_mutex_lock(&mutex);
    if (str - string_buffer.ptr <= string_buffer.capacity - string_buffer.used) {
        memmove(string_buffer.ptr + string_buffer.used, str + 1, strlen(str) + 1);
    } else {
        munmap(string_buffer.ptr, string_buffer.capacity);
        init_heap_buffer((string_buffer.capacity + SIZE_MAX) / 2);
        memmove(string_buffer.ptr + string_buffer.used, str + 1, strlen(str) + 1);
    }
    string_buffer.used += strlen(str) + 1;
    pthread_mutex_unlock(&mutex);
}

void update_record_string(size_t index, char *new_data) {
    pthread_mutex_lock(&mutex);
    free(record_array[index].data);
    record_array[index].data = get_heap_buffer(strlen(new_data) + 1);
    strcpy(record_array[index].data, new_data);
    pthread_mutex_unlock(&mutex);
}

void populate_arrays() {
    for (size_t i = 0; i < 1000001; ++i) {
        offset_array[i] = rand();
        key_array[i] = rand();
        record_array[i].value = rand();
        if (rand() % 2) { // Generate smaller strings with probability 1/2
            record_array[i].data = get_heap_buffer(rand() % 100);
            snprintf(record_array[i].data, rand() % 100, "%d", rand());
        } else {
            record_array[i].data = malloc(rand() % 500 + 1);
            sprintf(record_array[i].data, "%d", rand());
        }
    }
}

void cleanup() {
    for (size_t i = 0; i < 1000001; ++i) {
        free(record_array[i].data);
    }
    munmap(string_buffer.ptr, string_buffer.capacity);
}

// Function to manage dynamic memory allocation for three structures: offset_array, key_array, and record_array
void manage_memory() {
    record_array = (record*)malloc(1000001 * sizeof(record));
    if (!record_array) {
        perror("malloc");
        cleanup();
        exit(EXIT_FAILURE);
    }
    populate_arrays();
}
```

