2. Memory allocation function for arrays:

```cpp
#include <algorithm>
#include <new>
#include <vector>

template<typename T>
void allocateAndSort(size_t size, const std::function<T()>& constructor, size_t* offsets, int* keys, std::vector<Record>& records, size_t minKey = 0, size_t maxKey = std::numeric_limits<size_t>::max()) {
    // Allocate memory and initialize the arrays
    auto offsetArray = new (std::nothrow) size_t[size];
    if (!offsetArray) {
        std::cerr << "Failed to allocate memory for offsets." << std::endl;
        return;
    }
    auto keyArray = new (std::nothrow) int[size];
    if (!keyArray) {
        std::cerr << "Failed to allocate memory for keys." << std::endl;
        delete[] offsetArray;
        return;
    }
    // Allocate and initialize the records array
    auto recordArray = new (std::nothrow) Record[size];
    if (!recordArray) {
        std::cerr << "Failed to allocate memory for records." << std::endl;
        delete[] offsetArray;
        delete[] keyArray;
        return;
    }

    // Initialize the records and sort them based on their keys
    for (size_t i = 0; i < size; ++i) {
        recordArray[i] = Record(constructor(), i);
    }
    std::sort(recordArray, recordArray + size, [](const Record& lhs, const Record& rhs) {
        return lhs.key < rhs.key;
    });

    // Filter the records based on their key values
    auto it = recordArray.begin();
    for (size_t i = 0; i < size && it != recordArray.end() && it->key >= minKey && it->key <= maxKey; ++i, ++it) {
        offsets[i] = *offsetArray++;
        keys[i] = it->key;
    }

    // Free the allocated memory
    delete[] offsetArray;
    delete[] keyArray;
}
```

