    private static final Logger logger = Logger.getLogger(ConfigLoader.class.getName());
    private static final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors() * 2);
    private static final ScheduledExecutorService timer = Executors.newScheduledThreadPool(1);
    private static final ConcurrentMap<String, Future<ConfigState>> cache = new ConcurrentHashMap<>();
    private static final Yaml yaml = new Yaml();
    private static final int maxCacheSize;
    private static final long timeout = TimeUnit.SECONDS.toMillis(10);
    private static File configFile;

    static {
        Properties props = new Properties();
        try (InputStream input = ConfigLoader.class.getClassLoader().getResourceAsStream("config.properties")) {
            props.load(input);
            maxCacheSize = Integer.parseInt(props.getProperty("maxCacheSize"));
            configFile = new File(props.getProperty("configFile"));
        } catch (IOException e) {
            logger.severe("Error loading configuration properties: " + e.getMessage());
        }
    }

    public static ConfigState loadConfig() {
        String key = configFile.getAbsolutePath();
        Future<ConfigState> future = cache.get(key);
        if (future != null && !future.isDone()) {
            return future.getNow(null);
        }

        Runnable loadTask = () -> {
            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(configFile))) {
                ConfigState config = (ConfigState) ois.readObject();
                if (validateConfig(config)) {
                    return config;
                } else {
                    logger.warning("Invalid configuration object detected, discarding and reloading.");
                    return loadConfig();
                }
            } catch (IOException | ClassNotFoundException e) {
                logger.severe("Error loading configuration: " + e.getMessage());
                return null;
            } finally {
                if (!ois.equals(null)) {
                    try {
                        ois.close();
                    } catch (IOException ex) {
                        logger.warning("Failed to close ObjectInputStream.");
                    }
                }
            }
        };

        future = executor.submit(loadTask);
        cache.putIfAbsent(key, future);
        if (cache.size() > maxCacheSize) {
            Future<?> evictionTask = timer.scheduleWithFixedDelay(() -> {
                Future<?> oldestFuture = null;
                ConfigState oldestConfig = null;
                for (Map.Entry<String, Future<ConfigState>> entry : cache.entrySet()) {
                    if (oldestFuture == null || entry.getValue().compareTo(oldestFuture) < 0) {
                        oldestFuture = entry.getValue();
                        oldestConfig = entry.getKey();
                    }
                }
                if (oldestFuture != null && oldestFuture.isDone()) {
                    cache.remove(oldestConfig);
                    logger.info("Evicted configuration from cache.");
                }
            }, timeout, timeout, TimeUnit.MILLISECONDS);
            executor.execute(evictionTask);
        }

        return future.getNow(null);
    }

    private static boolean validateConfig(ConfigState config) {
