import java.lang.reflect.InvocationTargetException;
import java.text.SimpleDateFormat;

class UnionFind {
    private int[] parent;
    private int count;

    public UnionFind(int size) {
        this.parent = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
        }
        this.count = size;
    }

    public int find(int x) {
        while (x != parent[x]) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX == rootY) return;
        parent[rootX] = rootY;
        count--;
    }

    public int getCount() {
        return this.count;
    }
}

public class Processor {

    private static SimpleDateFormat dateFormatter = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");

    public void process(int[] intArray, byte[] byteArray) throws IOException, ClassNotFoundException, NoSuchMethodException, InstantiationException, IllegalAccessException, InvocationTargetException {
        UnionFind uf = new UnionFind(intArray.length);
        int pairsCount = 0;
        Map<String, Integer> pairMap = new HashMap<>();

        for (int i = 0; i < intArray.length; i++) {
            for (int j = i + 1; j < intArray.length; j++) {
                int rootX = uf.find(intArray[i]);
                int rootY = uf.find(intArray[j]);
                if (rootX != rootY) {
                    String key = Integer.toString(rootX) + "," + Integer.toString(rootY);
                    if (!pairMap.containsKey(key)) {
                        pairMap.put(key, pairsCount++);
                        System.out.println(dateFormatter.format(new Date()) + ": Pair found: " + intArray[i] + ", " + intArray[j]);
                    }
                    uf.union(rootX, rootY);
                }
            }
        }

        ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(byteArray));
        try {
            Object obj = ois.readObject();
            // Handle the deserialized object based on your application's requirements
        } catch (UnknownReloadingClassException | StreamCorruptedException e) {
            System.err.println(dateFormatter.format(new Date()) + ": Deserialization failed: " + e.getMessage());
        } catch (ClassNotFoundException | IOException e) {
            System.err.println(dateFormatter.format(new Date()) + ": Unexpected error during deserialization: " + e.getMessage());
        } finally {
            ois.close();
        }
    }
}
