    while (i >= 0 && isalnum(base[i])) --i;
    if (i < 0) {
        extension.data[extension.len++] = 'log';
        return extension;
    }
    if (strcasecmp(&base[i], "etc") == 0 || strcasecmp(&base[i], "bin") == 0 || strcasecmp(&base[i], "tmp") == 0) {
        extension.data[extension.len++] = 'l';
        extension.data[extension.len++] = 'o';
