typedef struct Sensor {
    DataPoint* dataPoints;
    int size;
    int capacity;
} Sensor;

Sensor* createSensor(int initialSize);
void destroySensor(Sensor* sensor);
int addDataPointToSensor(Sensor* sensor, double temperature, char* location);

#endif //SENSOR_H

#include "sensor.h"
#include <stdlib.h>
#include <time.h>
#include <string.h>

Sensor* createSensor(int initialSize) {
    Sensor* sensor = malloc(sizeof(Sensor));
    if (!sensor) return NULL;

    sensor->size = 0;
    sensor->capacity = initialSize;
    sensor->dataPoints = calloc(initialSize, sizeof(DataPoint));
    if (!sensor->dataPoints) {
        free(sensor);
        return NULL;
    }
    return sensor;
}

void destroySensor(Sensor* sensor) {
    for (int i = 0; i < sensor->size; ++i) {
        free(sensor->dataPoints[i].location);
    }
    free(sensor->dataPoints);
    free(sensor);
}

int addDataPointToSensor(Sensor* sensor, double temperature, char* location) {
    if (sensor->size >= sensor->capacity) {
        sensor->capacity *= 2;
        sensor->dataPoints = realloc(sensor->dataPoints, sensor->capacity * sizeof(DataPoint));
        if (!sensor->dataPoints) return -1;
    }

    sensor->dataPoints[sensor->size]->timestamp = time(NULL);
    sensor->dataPoints[sensor->size]->temperature = temperature;
    size_t len = strlen(location) + 1;
    sensor->dataPoints[sensor->size]->location = malloc(len);
    if (!sensor->dataPoints[sensor->size]->location) return -1;
    strcpy(sensor->dataPoints[sensor->size]->location, location);

    ++sensor->size;
    return 0;
}
