use std::sync::Arc;
use reqwest::{Client, Response};
use std::time::Duration;

type ClientRef = Arc<Client>;

struct HttpClient {
    client: ClientRef,
    timeout: Duration,
}

impl HttpClient {
    fn new(url: &str, timeout: u64) -> Self {
        let client = Arc::new(Client::builder()
            .timeout(Duration::from_secs(timeout))
            .build()
            .expect("Failed to create client"));

        HttpClient {
            client,
            timeout: Duration::from_secs(timeout),
        }
    }

    async fn send(&self, url: &str) -> Result<Response, reqwest::Error> {
        match self.client.get(url).send().await {
            Ok(response) => Ok(response),
            Err(_) => {
                self.exponential_backoff()
                    .map(|client| client.get(url).send().await)
                    .await
            }
        }
    }

    async fn exponential_backoff(&self) -> Box<dyn Future<Output = ClientRef>> {
        let mut delay = self.timeout;
        let mut retries = 5u8;

        async move {
            while retries > 0 {
                if let Ok(client) = Self::new(self.url(), self.timeout + delay).send().await {
                    return Arc::new(client);
                }
                retries -= 1;
                delay *= 2;
            }

            Err(reqwest::Error::new(reqwest::StatusCode::INTERNAL_SERVER_ERROR, "Too many failed attempts"))
        }
    }
}
