#define MAX_RECORDS 10000
#define MIN_RECORDS 100
#define RANGE 1000

typedef struct {
    int value;
} Record;

void processData(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    size_t numRecords = 0;
    Record *records = mmap(NULL, MAX_RECORDS * sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (records == MAP_FAILED) {
        perror("Error allocating memory");
        fclose(file);
        return;
    }

    Record tmpRecord;
    while (fscanf(file, "%d", &tmpRecord.value) == 1) {
        if (numRecords >= MAX_RECORDS) {
            size_t newSize = ((MAX_RECORDS * 2) > numRecords + MIN_RECORDS) ? (MAX_RECORDS * 2) : (numRecords + MIN_RECORDS);
            Record *newRecords = realloc(records, newSize * sizeof(Record));
            if (!newRecords) {
                perror("Error resizing memory");
                munmap(records, MAX_RECORDS * sizeof(Record));
                fclose(file);
                return;
            }
            records = newRecords;
        }

        records[numRecords].value = (rand() % RANGE) + 1; // Set the int field of the current record to a random value within the specified range.
        numRecords++;
    }

    fclose(file);

    if (munmap(records, MAX_RECORDS * sizeof(Record)) < 0) {
        perror("Error unmapping memory");
    }

    int maxValue = records[0].value;
    for (size_t i = 1; i < numRecords; i++) {
        if (records[i].value > maxValue) {
            maxValue = records[i].value;
        }
    }

    printf("Largest integer: %d\n", maxValue);
}
```

