#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

#define FIXED_RECORD_SIZE 100

typedef struct {
    int value;
} Record;

typedef struct Block {
    void *memory;
    size_t size;
    struct Block *next;
} Block;

Block *free_list = NULL;
pthread_mutex_t free_list_mutex = PTHREAD_MUTEX_INITIALIZER;

long *offsets;
int *keys;
Record records[FIXED_RECORD_SIZE];

void init_memory_manager() {
    pthread_mutex_lock(&free_list_mutex);
    if (free_list) free_list = NULL;
    pthread_mutex_unlock(&free_list_mutex);
}

void* mempool_alloc(size_t size) {
    void *memory;

    Block *current = free_list;
    Block *prev = NULL;

    if (free_list) {
        // Find the smallest block that can satisfy the request
        while (current->size >= size && current != NULL) {
            prev = current;
            current = current->next;
        }

        // If the current block can be split, create a new one from the excess memory and update the list accordingly
        if (prev && current && current->size > size + sizeof(Block)) {
            Block *new_block = (Block *)((char *)current + size + sizeof(Block));
            new_block->size = current->size - size - sizeof(Block);
            new_block->next = current->next;
            current->size -= size + sizeof(Block);
            current->next = new_block;
        }
    }

    // If no suitable block was found, allocate a new one and add it to the free list
    if (current == NULL) {
        memory = malloc(size + sizeof(Block));
        current = (Block *)memory;
        current->size = size;
        current->next = free_list;
        free_list = current;
    }

    return (char *)current + sizeof(Block);
}

void my_malloc_ wrapper(size_t size, void **ptr) {
    *ptr = mempool_alloc(size);
}

int main(int argc, char **argv) {
    srand(time(NULL));

    if (argc < 2) {
        printf("Usage: %s num_offsets\n", argv[0]);
        return -1;
    }

    int num_offsets = atoi(argv[1]);

    // Allocate memory for offsets
    if (num_offsets > 100) {
        printf("Error: num_offsets exceeds the limit of 100\n");
        return -1;
    }

    init_memory_manager();

    offsets = my_malloc(num_offsets * sizeof(long));
    memset(offsets, 0, num_offsets * sizeof(long));

    // Allocate memory for keys
    keys = my_malloc(num_offsets * sizeof(int));

    for (size_t i = 0; i < num_offsets; ++i) {
        keys[i] = i;
    }

    // Allocate memory and initialize records
