    Record *records_ptr = &records[0];
    for (size_t i = 0; i < FIXED_RECORD_SIZE; ++i) {
        int min_value = atoi(argv[2]);
        int max_value = atoi(argv[3]);

        records_ptr->value = rand() % (max_value - min_value + 1) + min_value;
        ++records_ptr;
    }

    // Use the allocated data structures...

    return 0;
}
