class Session {
public:
    explicit Session(int userID) : _userID(userID), _lastActive(std::chrono::steady_clock::now()), _expirationTime(std::numeric_limits<std::chrono::seconds>::max()) {}

    int getUserID() const { return _userID; }
    auto getLastActive() const { return _lastActive; }
