    void start(boost::asio::io_service& ioService, const std::chrono::seconds& sessionTimeout) {
        _timer = std::make_shared<boost::asio::deadline_timer>(ioService, sessionTimeout);
        _timer->async_wait([this](const boost::system::error_code& error) { if (!error) terminateInactiveSessions(); });
    }

    void addSession(std::unique_ptr<Session> session) {
        std::unique_lock<std::mutex> lock(_sessionsMutex);
        _sessions[session->getUserID()] = std::move(session);
        lock.unlock();
    }

    boost::optional<std::unique_ptr<Session>> getSession(int userID) {
        std::unique_lock<std::mutex> lock(_sessionsMutex);
        auto it = _sessions.find(userID);
        if (it != _sessions.end()) {
            Session* session = it->second.get();
            _sessions.erase(it);
            return std::unique_ptr<Session>(session);
        }
        return boost::none;
    }

private:
    void terminateInactiveSessions() {
        // Implement a mechanism to detect and terminate inactive sessions based on last active timestamp and session expiration time.
    }

    std::unordered_map<int, std::unique_ptr<Session>> _sessions;
    std::shared_ptr<boost::asio::deadline_timer> _timer;
    mutable std::mutex _sessionsMutex;
};
```

