#include <pthread.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>
#include <semaphore.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
} record;

typedef struct cache_node {
    record data;
    struct cache_node *next;
} cache_node;

typedef struct {
    sem_t mutex;
    size_t capacity;
    size_t num_elements;
    cache_node **cache_array;
    void *persistent_storage;
    size_t persistent_size;
} collection;

collection* create_collection(size_t initial_capacity) {
    collection *c = malloc(sizeof(collection));
    c->mutex = sem_init(0, 1, 1);
    c->capacity = initial_capacity;
    c->num_elements = 0;
    c->cache_array = calloc((size_t)initial_capacity, sizeof(cache_node*));
    return c;
}

void destroy_collection(collection *c) {
    free(c->cache_array);
    sem_destroy(&c->mutex);
    free(c);
}

static cache_node *find_in_cache(collection *c, const record* key_value) {
    size_t index = hash(key_value->key);
    for (cache_node *cn = c->cache_array[index]; cn != NULL; cn = cn->next) {
        if (cn->data.key == key_value->key && cn->data.offset == key_value->offset) {
            return cn;
        }
    }
    return NULL;
}

static void add_to_cache(collection *c, const record* key_value) {
    cache_node *cn = malloc(sizeof(cache_node));
    cn->data = *key_value;
    size_t index = hash(key_value->key);
    cn->next = c->cache_array[index];
    c->cache_array[index] = cn;
}

static record* find_record(collection *c, const int key) {
    sem_wait(&c->mutex);
    cache_node *cached_result = find_in_cache(c, &{(const record){key, 0}});
    if (cached_result != NULL) {
        sem_post(&c->mutex);
        return &cached_result->data;
    }

    size_t index = hash(key);
    for (size_t i = index; i < c->num_elements; ++i) {
        if (c->cache_array[i % c->capacity]->data.key == key) {
            record* result = &c->cache_array[i % c->capacity]->data;
            sem_post(&c->mutex);
            return result;
        }
    }

    for (size_t i = 0; i < c->num_elements; ++i) {
        if (c->cache_array[(i + index) % c->capacity]->data.key == key) {
            record* result = &c->cache_array[(i + index) % c->capacity]->data;
            sem_post(&c->mutex);
            return result;
        }
    }

    // Record not found, insert a new one
    size_t new_index = (c->num_elements % c->capacity == 0) ? 0 : (c->num_elements % c->capacity) + 1;
    record* new_record = malloc(sizeof(record));
    new_record->offset = -1; // Placeholder value for absent records
    new_record->key = key;
    c->cache_array[new_index] = new_record;
    c->num_elements++;

    if (c->num_elements > c->capacity * 0.75) {
        // Evict least recently used cache elements
        size_t least_recently_used_index = hash(key);
        for (size_t i = least_recently_used_index; i < c->num_elements; ++i) {
            if (c->cache_array[(i + least_recently_used_index) % c->capacity]->next == NULL) {
                break;
            }
        }
        for (size_t i = least_recently_used_index + 1; i < c->num_elements; ++i) {
            cache_node *cn = c->cache_array[(i + least_recently_used_index) % c->capacity];
            if (cn->next != NULL) {
                least_recently_used_index = (i + 1) % c->capacity;
            } else {
                break;
            }
        }
        free(c->cache_array[least_recently_used_index]);
        c->num_elements--;
    }

    add_to_cache(c, &{(const record){key, 0}});
    sem_post(&c->mutex);
    return &c->cache_array[(c->num_elements - 1) % c->capacity]->data;
}

// Periodic data updates and consistency handling should be implemented in external systems integrations.

// Implement serialization and deserialization functions as necessary, ensuring flexibility for future changes.
```

