        public:
            RandomGenerator(unsigned long seed, size_t range, size_t cacheSize) : _mt(seed), _range(range), _cacheSize(cacheSize) {}
            ~RandomGenerator() {}

            static RandomGenerator& getInstance() {
                static RandomGenerator generator{ std::random_device{}(), RAND_MAX, 1024 }; // Use a fixed seed and default values for cache size and range in the static instance.
                return generator;
