            std::vector<int> generate_random_numbers(int count) {
                std::unique_ptr<int[]> numbers{ new int[count] }; // Use unique_ptr with placement new to manage memory efficiently and avoid fragmentation.
                std::fill_n(numbers.get(), count, 0);

                std::mutex mtx;
                std::vector<std::thread> threads;
                size_t chunkSize = _cacheSize < count ? _cacheSize : count; // Adjust chunk size based on available cache.

                for (size_t i = 0; i < count; i += chunkSize) {
                    size_t endIndex = std::min(i + chunkSize, count);
                    threads.emplace_back([&, start = i, end = endIndex]() mutable {
                        for (size_t j = start; j < end; ++j)
                            new ((void*)&numbers[j]) int(_mt(j)); // Use placement new to initialize values in the array.
                    });
                }

                for (auto& thread : threads)
                    thread.join();

                for (size_t i = 0; i < count; ++i)
                    numbers[i] %= _range; // Ensure values are within the specified range.

                return {std::make_move_iterator(numbers.release())};
            }

        private:
