    int process_and_find_max(const std::vector<int>& numbers) {
        if (numbers.empty()) throw std::invalid_argument("Input vector cannot be empty.");

        int maxValue = *std::max_element(numbers.begin(), numbers.end());
        std::unique_ptr<int[]> localNumbers{ new int[numbers.size()] };
        std::copy(numbers.begin(), numbers.end(), localNumbers.get()); // Create a local copy to prevent concurrent access issues in multi-threaded scenarios.

        std::mutex mtx;
        std::vector<std::thread> threads;

        const size_t chunkSize = 1024;
        for (size_t i = 0; i < numbers.size(); i += chunkSize) {
            size_t endIndex = std::min(i + chunkSize, numbers.size());
            threads.emplace_back([&, start = i, end = endIndex]() mutable {
                for (size_t j = start; j < end; ++j)
                    if (localNumbers[j] > maxValue) maxValue = localNumbers[j]; // Update the maximum value.
            });
        }

        for (auto& thread : threads)
            thread.join();

        return maxValue;
    }
}

