typedef struct Connection {
    int socket_fd;
    sockaddr_in addr;
    double rtt; // Round-Trip Time (for metrics)
    pthread_mutex_t mutex;
} Connection;

// Custom compare function for qsort() to sort connections based on RTT
bool rttCompare(const void *a, const void *b) {
    return ((*(Connection*)a)->rtt > *(*(Connection*)b)->rtt);
}

void init_connection_manager(int max_sessions, int *session_ids, Connection ***connections) {
    *connections = malloc(max_sessions * sizeof(Connection*));

    for (int i = 0; i < max_sessions; ++i) {
        (*connections)[i] = malloc(sizeof(Connection));
        memset((*connections)[i], 0, sizeof(Connection));

        // Initialize socket descriptor
        if (((*connections)[i]->socket_fd = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP)) == -1) {
            perror("socket creation error");
            exit(EXIT_FAILURE);
        }

        // Set connection metrics and mutex for each session
        (*connections)[i]->rtt = -1.0;
        pthread_mutex_init(&((*connections)[i]->mutex), NULL);

        // Store session ID (for potential external monitoring service integration)
        if (session_ids != NULL) {
            (*connections)[i]->session_id = session_ids[i];
        } else {
            (*connections)[i]->session_id = -1;
        }
    }
}

void free_connection_manager(Connection **connections, int max_sessions) {
    for (int i = 0; i < max_sessions; ++i) {
        if ((*connections)[i] != NULL) {
            close((*connections)[i]->socket_fd);
            pthread_mutex_destroy(&((*connections)[i]->mutex));
            free(*connections[i]);
        }
    }
    free(*connections);
}
```

