// Multi-threaded transformation function
void* transform_multi_thread(void *arg) {
    ThreadData *data = (ThreadData *) arg;
    double sum = 0;

    for (int i = data->start; i < data->end; ++i) {
        sum += transform(data->records[i]);
    }

    return &sum;
}

