    }

    pthread_t threads[num_offsets];
    ThreadData thread_data[num_offsets];

    int chunk_size = (int) ceil((double) num_keys / num_offsets);

    for (int i = 0; i < num_offsets; ++i) {
        thread_data[i].start = i * chunk_size;
        thread_data[i].end = (i == num_offsets - 1 ? num_keys : (i + 1) * chunk_size);
        thread_data[i].records = records;
        pthread_create(&threads[i], NULL, transform_multi_thread, &thread_data[i]);
    }

    double total = 0;
    for (int i = 0; i < num_offsets; ++i) {
        void *result;
        pthread_join(threads[i], &result);
        total += *(double *) result;
    }

    printf("Total: %.2f\n", total);

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
