} MemoryBlock;

MemoryPool pool = {NULL, NULL}; // Initialize the memory pool as empty

// Function to find the largest integer in an array
void findLargest(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    printf("The largest integer is: %d\n", max);
}

void *allocate(size_t size) {
    if (!pool.next) {
        pool.memory = malloc(POOL_INITIAL_SIZE);
        pool.capacity = POOL_INITIAL_SIZE;
        pool.next = &pool.memory;
    }
    MemoryBlock *current = &pool.next;
    while (current->capacity <= size) {
        current->next = malloc(POOL_GROWTH_SIZE);
        current->next->capacity = POOL_GROWTH_SIZE;
        current = current->next;
    }
    void *result = current++;
    current->capacity -= size;
    return result;
}

void freeMemoryPool() {
    MemoryBlock *current = pool.next;
    while (current) {
        MemoryBlock *temp = current;
        current = current->next;
        free(temp);
    }
    pool.capacity = 0;
    pool.next = NULL;
}

// Custom malloc function that handles memory allocation failures gracefully
void *my_malloc(size_t size) {
    void *ptr = allocate(size);
    if (!ptr) {
        perror("Memory Allocation Error");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Custom free function that releases memory back to the pool
void my_free(void *ptr) {
    free(ptr);
    if (pool.next == &pool.memory) { // If the memory block is at the beginning of the pool
        pool.capacity -= sizeof(MemoryBlock);
        pool.next = NULL;
    } else {                         // Otherwise, update the current memory block's capacity
        MemoryBlock *current = &pool.memory;
        while (current->next != ptr) {
            current = current->next;
        }
        current->capacity += sizeof(void*) + size;
    }
}

