```c
#include <complex.h>
#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <math.h>

typedef struct {
    float value;
    unsigned short index;
    struct complex *number;
} data_point;

typedef struct {
    float real, imag;
} complex;

// Helper function to calculate mean and standard deviation of an array of floats
void mean_stddev(const float *arr, size_t length, float *mean, float *stddev) {
    // Calculate mean
    float sum = 0.0f;
    for (size_t i = 0; i < length; ++i)
        sum += arr[i];
    *mean = sum / length;

    // Calculate standard deviation
    float sq_sum = 0.0f;
    for (size_t i = 0; i < length; ++i)
        sq_sum += pow(arr[i] - *mean, 2);
    *stddev = sqrt(sq_sum / length);
}

// Function to dynamically allocate and initialize data_point array
data_point* data_point_array_init(size_t size) {
    // Allocate memory for data_point structures
    data_point *data_points = (data_point *) malloc(size * sizeof(data_point));
    if (!data_points) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for complex numbers and set to zero
    complex **complex_numbers = (complex**) calloc(size, sizeof(complex*));
    if (!complex_numbers) {
        free(data_points);
        perror("calloc");
        exit(EXIT_FAILURE);
    }

    // Initialize data points with zero values
    for (size_t i = 0; i < size; ++i) {
        data_points[i].value = 0.0f;
        data_points[i].index = 0;
        data_points[i].number = NULL;
        if (complex_numbers[i] = (complex*) calloc(1, sizeof(complex))) {
            complex_numbers[i]->real = 0.0f;
            complex_numbers[i]->imag = 0.0f;
        } else {
            perror("calloc");
            exit(EXIT_FAILURE);
        }
    }

    return data_points;
}

// Function to read integers from standard input, process them, and release resources at the end
void read_and_process_input() {
    int c;
    size_t num_data_points = 0, curr_index = 0;
    data_point *data_points = data_point_array_init(10_000_000);
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_t threads[NUM_THREADS];

    // Read integers from standard input, handle errors and non-numeric characters
    while ((c = getchar()) != EOF) {
        if (!isdigit(c)) continue;
        int num = c - '0';
        for (int i = NUM_THREADS - 1; i >= 0; --i) {
            if (threads[i] == THREAD_ID_INVALID) {
                threads[i] = thread_create(process_input, &num, &data_points[curr_index], &mutex);
                if (threads[i] != 0) break;
            }
        }
        num_data_points++;
        curr_index++;
    }

    // Wait for all threads to finish processing input and join them
    for (size_t i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Calculate mean and standard deviation of the indices
    float mean, stddev;
    mean_stddev((float*)data_points->index, num_data_points, &mean, &stddev);

    // Release resources
    for (size_t i = 0; i < num_data_points; ++i) {
        free(data_points[i].number);
    }
    free(complex_numbers);
    free(data_points);
}
