fn create_directory(dir_name: &str) -> Result<(), Box<dyn Error>> {
    if std::fs::create_dir_all(dir_name).is_err() {
        return Err(Box::new(std::io::Error::new(
            std::io::ErrorKind::NotFound,
            format!("Directory {} does not exist", dir_name),
        )));
    }
    Ok(())
}

fn set_env_var(var_name: &str, value: &str) -> Result<(), Box<dyn Error>> {
    if env::var_os(var_name).is_none() {
        env::set_var(var_name, value);
    }
    Ok(())
}

fn allocate_records(num_records: usize) -> Result<usize, Box<dyn Error>> {
    let mut count = 0;
    let mut records = Vec::with_capacity(num_records);
    let rng = thread_rng();
    for _ in 0..num_records {
        match records.try_resize(count + 1, Default::default) {
            Ok(_) => {
                let mut record: Value = serde_json::from_str("{\"key\": 0, \"timestamp\": 0, \"status\": \"pending\", \"value\": 0}").unwrap();
                record["key"] = num_records as i64;
                record["timestamp"] = SystemTime::now().duration_since(UNIX_EPOCH).expect("Time went backwards").as_secs() as f64;
                record["status"] = "pending".to_string();
                record["value"] = rng.gen_range(0, 100); // Adjust range as needed
                records[count] = record;
                count += 1;
            }
            Err(_) => {
                return Err(Box::new(std::alloc::SystemAllocErrorKind::OutOfMemory));
            }
        }
    }
    Ok(count)
}

fn main() -> Result<(), Box<dyn Error>> {
    let dir_name = "my_dir";
    create_directory(dir_name)?;
    set_env_var("MY_DIR", dir_name)?;

    let num_records = 1000;
    let count = allocate_records(num_records)?;
    println!("Successfully allocated {} records.", count);
    Ok(())
}
