void lcg(int* seed, int multiplier, int increment1, int increment2) {
    *seed = (*seed * multiplier + increment1) % 0x7FFFFFFF;
}

void init_network_device(struct network_device* dev, const char* protocol, size_t num_interfaces, unsigned long ip, unsigned long subnet_mask, unsigned long default_gateway) {
    // Dynamically allocate memory for ttl and metric keys
    dev->ttl = mmap(NULL, sizeof(unsigned long) * num_interfaces, PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    dev->metric_keys = calloc(num_interfaces, sizeof(int));

    // Initialize ttl values using a linear congruential generator
    for (size_t i = 0; i < num_interfaces; ++i) {
        dev->ttl[i] = 64;
        lcg(&dev->metric_keys[i], 16807, 0, 256);
    }

    // Set essential information
    strncpy(dev->protocol, protocol, sizeof(dev->protocol));
    dev->ip = ip;
    dev->subnet_mask = subnet_mask;
    dev->default_gateway = default_gateway;

    // Dynamically allocate and initialize interfaces array
    dev->interfaces = calloc(num_interfaces, sizeof(interface_record));
    for (size_t i = 0; i < num_interfaces; ++i) {
        interface_record* record = &dev->interfaces[i];
        pthread_mutex_init(&record->mutex, NULL);
        record->metric = dev->metric_keys[i];
    }
}

