        });
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);

        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Error in HTTP GET request: %s\n", curl_easy_strerror(res));
            readBuffer.clear();
