import java.io.IOException;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class WeatherApp {
    private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");
    private OkHttpClient client;
    private Gson gson;

    public WeatherApp() {
        this.client = new OkHttpClient();
        this.gson = new GsonBuilder().create();
    }

    public void sendPOSTRequest(String url, JsonObject jsonPayload, ExecutorService executor) throws IOException {
        RequestBody requestBody = RequestBody.create(JSON, gson.toJson(jsonPayload));
        Request request = new Request.Builder()
                .url(url)
                .post(requestBody)
                .build();

        Response response = client.newCall(request).execute();
        if (!response.isSuccessful()) {
            throw new IOException("Unexpected code " + response);
        }
    }

    public List<WeatherData> fetchWeatherDataForCities(List<String> cityEndpoints) throws IOException, InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(cityEndpoints.size());
        List<Future<Response>> futures = new ArrayList<>();
        List<WeatherData> weatherDataList = new ArrayList<>();

        for (String cityEndpoint : cityEndpoints) {
            Call call = client.newCall(new Request.Builder().url(cityEndpoint).build());
            Future<Response> future = executor.submit(() -> call.execute());
            futures.add(future);
        }

        for (Future<Response> future : futures) {
            Response response = future.get();
            if (!response.isSuccessful()) {
                continue;
            }
            jsonWeatherData = gson.fromJson(response.body().string(), WeatherData.class);
            weatherDataList.add(jsonWeatherData);
        }

        executor.shutdown();
        return weatherDataList;
    }

    public static class WeatherData {
        private String name;
        private double temperature;
        private int humidity;
        private double windSpeed;

        // Getters and setters for each property, as well as a toString method for printing the data.
    }
}
