class RandomGenerator {
  constructor(min, max) {
    this.min = Math.floor(min);
    this.max = Math.floor(max);
  }

  next() {
    return this.min + Math.random() * (this.max - this.min);
  }
}

function initializeAnalytics(tracking, config, options) {
  if (!Array.isArray(tracking) || !config || !options) {
    throw new Error("Invalid arguments passed to initializeAnalytics");
  }

  const { trustedEndpoints = [], compressRequests = false } = config;
  const { batchSize = 10, maxRetries = 5, intervalType = "fixed", interval, randomGenerator } = options || {};

  if (!Array.isArray(trustedEndpoints)) {
    throw new Error("trustedEndpoints must be an array");
  }

  let queue = [];
  let retryCount = 0;
  const analyticsRequest = (data) => new Promise((resolve, reject) => {
    // Add middleware functionality here
    const requestOptions = { /* Add headers and other options */ };
    const endpoint = data.endpoint;

    if (!trustedEndpoints.includes(endpoint)) {
      return reject(new Error("Endpoint not trusted"));
    }

    fetch(endpoint, { ...requestOptions, body: compressRequests ? JSON.stringify(data) : data, method: "POST" }) // Adjust this for different HTTP methods if necessary
      .then((response) => response.ok ? resolve(true) : reject(new Error("Request failed")))
      .catch(() => {
        if (retryCount < maxRetries) {
          retryCount++;
          setTimeout(() => analyticsRequest(data), Math.min(Math.pow(2, retryCount), interval * 2)); // Exponential backoff
        } else {
          throw new Error("Max retries exceeded");
        }
      });
  });

  function sendBatch() {
    if (queue.length < batchSize) return;

    const batchData = queue.splice(0, batchSize);
    Promise.all(batchData.map((data) => analyticsRequest(data)))
      .then(() => {
        if (intervalType === "fixed") {
          setTimeout(sendBatch, interval);
        } else if (randomGenerator && typeof randomGenerator.next === 'function') {
          setTimeout(sendBatch, Math.floor(interval * randomGenerator.next() + 1)); // Adjust the range as needed
        } else {
          throw new Error("Invalid intervalType provided");
        }
      })
      .catch((error) => console.error(error));
  }

  tracking.forEach(({ key, type, endpoint, interval: customInterval = 60000 }) => {
    queue.push({ key, type, endpoint, interval: customInterval || interval });
  });

  sendBatch();

  return new Promise((resolve) => {
    setTimeout(() => {
      if (queue.length === 0) resolve(true);
      else resolve(false);
    }, 10 * 60 * 1000); // Resolve after 10 minutes to ensure all data has been processed
  });
}
