use std::collections::HashSet;
use std::mem::{self, MaybeUninit};
use std::os::unix::io::AsRawFd;
use tokio::fs::File;
use tokio::io::{AsyncBufReadExt, BufStream};
use tokio::prelude::*;
use tokio::sync::RwLock;

#[derive(Debug)]
struct Record {
    key: i32,
    filename: String,
}

async fn read_filenames(file: AsRawFd) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    let mut lines = BufStream::from_fd(file).lines();
    let mut unique_filenames = HashSet::new();
    let mut filenames = Vec::new();

    loop {
        match lines.next_line().await {
            Ok(Some(line)) => {
                let line = line?;
                if !unique_filenames.insert(line) {
                    return Err(format!("Duplicate filename: {}", line).into());
                }
                filenames.push(line);
            }
            Ok(None) => break,
            Err(err) => return Err(err),
        }
    }

    Ok(filenames)
}

async fn allocate_memory(num_records: usize) -> Result<Vec<MaybeUninit<Record>>, Box<dyn std::error::Error>> {
    let mut memory = Vec::with_capacity(num_records);
    for _ in 0..num_records {
        let mut record = MaybeUninit::uninitialized();
        memory.push(record);
    }

    Ok(memory)
}

async fn populate_records(mut records: Vec<MaybeUninit<Record>>, num_records: usize, min_key: i32, max_key: i32) {
    let rng = rand::thread_rng();

    for (i, record) in records.into_iter().enumerate() {
        let key = rng.gen_range(min_key..=max_key);
        record.assume_init().key = key;
        records[i].assume_init().filename = format!("file_{}.txt", i); // Replace this with the actual filename read from the input file
    }
}

async fn run(file_path: String, num_records: usize, min_key: i32, max_key: i32) -> Result<(), Box<dyn std::error::Error> {
    let mut unique_filenames = HashSet::new();

    // Read filenames from the specified file and ensure they are unique.
    let input_file = File::open(&file_path).await?;
    let filenames = read_filenames(input_file.as_raw_fd()).await?;

    // Allocate memory for offsets, keys, and records.
    let num_offsets = num_records;
    let mut offsets = Vec::with_capacity(num_offsets);
    let mut keys = Vec::with_capacity(num_offsets);
    let mut records = allocate_memory(num_records)?;

    // Populate the records with random keys and filenames.
    populate_records(records, num_records, min_key, max_key)?;

    // Your implementation here to process the data as needed...

    // Free allocated memory when no longer needed.
    mem::drop(unique_filenames);
    mem::drop(input_file);
    mem::drop(filenames);
    mem::drop(offsets);
    mem::drop(keys);

    Ok(())
}
```

