2. Memory Pool:

```c
typedef struct MemoryPool {
    size_t capacity;
    Record** records;
    size_t allocated;
} MemoryPool;

MemoryPool* create_memory_pool(size_t capacity) {
    MemoryPool* pool = (MemoryPool*) malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->capacity = capacity;
    pool->records = (Record**) calloc(capacity, sizeof(Record*));
    if (!pool->records) {
        free(pool);
        return NULL;
    }

    pool->allocated = 0;

    return pool;
}

Record* get_record_from_pool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->capacity; ++i) {
        if (!pool->records[i]) {
            pool->records[i] = create_record();
            if (!pool->records[i]) return NULL;
            ++pool->allocated;
            break;
        }
    }

    return pool->records[0];
}

void release_record_to_pool(MemoryPool* pool, Record* record) {
    if (record) {
        record->key = NULL;
        record->offset = 0;
        record->value = 0;
        record->next = NULL;

        pool->records[0] = record;
        pool->records[0] = NULL;
    }
}
```

