4. Helper function to read integers and find the largest:

```c
int* read_integers(size_t* count) {
    *count = 0;

    int capacity = 16;
    int* numbers = (int*) malloc(capacity * sizeof(int));
    if (!numbers) return NULL;

    char input[256];
    while (1) {
        printf("Enter a number or type 'done' to finish: ");
        fgets(input, sizeof(input), stdin);

        if (strcmp(input, "done\n") == 0) break;

        int value = atoi(input);
        if (value < INT_MIN || value > INT_MAX) {
            printf("Invalid input. Please enter a valid integer.\n");
            continue;
        }

        if (*count >= capacity) {
            capacity *= 2;
            int* temp = (int*) realloc(numbers, capacity * sizeof(int));
            if (!temp) {
                printf("Memory allocation failed\n");
                return NULL;
            }
            numbers = temp;
        }

        numbers[*count] = value;
        ++(*count);
    }

    return numbers;
}

int find_largest(int* numbers, size_t count) {
    int largest = INT_MIN;
    for (size_t i = 0; i < count; ++i) {
        if (numbers[i] > largest) largest = numbers[i];
    }

    return largest;
}
```

