typedef struct {
    int value;
} record_t;

void process_large_dataset(size_t offsets_len, size_t keys_len, size_t records_len, size_t max_combined_len, size_t* offsets, int* keys, record_t* records, int* combined) {
    if (records_len < 2 || max_combined_len < 2) {
        return; // Invalid input parameters
    }

    // Allocate and initialize arrays
    int* even_results = malloc(max_combined_len * sizeof(int));
    int* odd_results = malloc(max_combined_len * sizeof(int));
    if (!even_results || !odd_results) {
        // Handle memory allocation errors here
    }

    // Initialize even_results and odd_results with zeros
    memset(even_results, 0, max_combined_len * sizeof(int));
    memset(odd_results, 0, max_combined_len * sizeof(int));

    // Populate records array with random integer values
    srand(time(NULL));
    for (size_t i = 0; i < records_len; ++i) {
        records[i].value = rand() % records_len;

        // Ensure no two consecutive records share the same value
        while (i > 1 && records[i - 2].value == records[i].value) {
            records[i].value = rand() % records_len;
        }
    }

    // Process the records based on their index
    for (size_t i = 0; i < records_len; ++i) {
        if (i % 2 == 0) {
            even_results[i / 2] += records[i].value + offsets[i / 2];
        } else {
            odd_results[i / 2] *= records[i].value * keys[i];
        }
    }

    // Combine the results of the even-indexed sums and odd-indexed products into a single array, ensuring the combined result does not exceed a specified maximum length.
    size_t combined_len = 0;
    for (size_t i = 0; i < max_combined_len && (i < combined_len || even_results[i] + odd_results[i] <= max_combined_len); ++i) {
        if (even_results[i] > 0 || odd_results[i] > 0) {
            combined[combined_len++] = i < combined_len ? even_results[i] + odd_results[i] : even_results[i];
        }
    }

    // Free unused resources
    free(even_results);
    free(odd_results);
}
