typedef struct Record {
    long offset;
    int key;
    struct Record *next_record;
    int value;
    char *string;
    long timestamp;
} Record;

Record* allocateAndInitializeRecords(size_t num_records) {
    if (num_records <= 0) return NULL;

    size_t offset_size = num_records * sizeof(long);
    size_t key_size = num_records * sizeof(int);
    size_t record_size = num_records * sizeof(Record);

    Record* records = (Record*)malloc(record_size);
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    long* offsets = (long*)((char*)records + key_size);
    int* keys = (int*)offsets + offset_size;
    Record* current_record = records + offset_size;

    for (size_t i = 0; i < num_records; ++i) {
        current_record->offset = i;
        current_record->key = keys[i] = i + 1;
        current_record->next_record = NULL;
        current_record->value = rand() % 1000 + 1; // Ensure no two records have the same integer value
        current_record->timestamp = time(NULL);
        size_t string_len = rand() % 100 + 1; // Generate random lengths between 1 and 100 characters
        current_record->string = (char*)malloc(string_len + 1);
        if (!current_record->string) {
            perror("Memory allocation failed");
            // Clean up memory for this record and previous ones
            while (current_record > records) {
                Record* temp = current_record;
                current_record = current_record->next_record;
                free(temp->string);
                free(temp);
            }
            return NULL;
        }
        for (size_t j = 0; j < string_len; ++j) {
            current_record->string[j] = isupper((unsigned char)rand() % 26 + 'A') ?
