```cpp
#include <vector>
#include <deque>
#include <iostream>
#include <numeric>
#include <thread>
#include <mutex>
#include <atomic>
#include <functional>
#include <algorithm>
#include <exception>
#include <future>

std::vector<float> values;
std::vector<unsigned short> indices;
std::vector<complex> complex_numbers;
std::vector<data_point> data_points;
std::vector<processing_task> processing_tasks;

constexpr int batchSize = 1000;
static std::mutex mtx;
static std::atomic<int> numDataPoints{ 0 };

void readNumbers(std::istream& in) {
    int number;
    while (std::cin >> number) {
        values.push_back(number);
        indices.push_back(numDataPoints.load());
        data_points[numDataPoints.load()].value = number;
        data_points[numDataPoints.load()].index = numDataPoints.load();
        ++numDataPoints;
    }
}

void processTask(const processing_task& task) {
    // Process the given data point in this thread
    // ...
}

void batchProcessTasks() {
    auto begin = std::next(std::begin(processing_tasks), 0u, batchSize);
    auto end   = std::min(std::end(processing_tasks), begin);

    if (begin != end) {
        std::vector<processing_task> batch;
        batch.insert(batch.end(), begin, end);

        std::packaged_task<void()> task = [&]() {
            for (auto& t : batch) processTask(t);
        };

        auto f = task.get_future();
        std::thread thread(std::move(task));
        thread.detach();

        // ... continue with more batches or other tasks ...
    }
}

void calculateStatistics() {
    double sum = 0;
    int count = 0;

    for (const auto& value : values) {
        ++count;
        sum += value;
    }

    if (count > 0) {
        double mean = sum / count;
        double varianceSum = 0;
        for (const auto& value : values) {
            varianceSum += pow(value - mean, 2);
        }
        double variance = varianceSum / count;
        std::cout << "Mean: " << mean << "\n";
        std::cout << "Standard Deviation: " << sqrt(variance) << "\n";
        std::cout << "Variance: " << variance << "\n";
    }
}

void releaseResources() {
    for (auto& dataPoint : data_points) {
        --dataPoint.referenceCount;
        if (dataPoint.referenceCount <= 0) {
            values.erase(std::remove(values.begin(), values.end(), dataPoint.value), values.end());
            indices.erase(std::remove(indices.begin(), indices.end(), dataPoint.index), indices.end());
            complex_numbers.erase(std::remove(complex_numbers.begin(), complex_numbers.end(), dataPoint.complexNumber), complex_numbers.end());
            data_points.erase(data_points.begin(), std::next(data_points.begin(), numDataPoints));
        }
    }
}

int main() {
    std::istream& in = std::cin; // or use a file stream for external API interaction

    std::thread readThread([&]() { readNumbers(in); });
    readThread.detach();

    while (true) {
        batchProcessTasks();
    }

    calculateStatistics();
    releaseResources();
}
```

